create temporary table import_summary (wikidata_id text primary key, summary text not null, source text not null);

insert into import_summary (wikidata_id, summary, source) values
  ('Q2110486', 'Mega Man III is a 1992 platform game developed by Minakuchi Engineering and published by Capcom for the Game Boy. It is the third game in the handheld series of the Mega Man franchise and the last to be published by Nintendo in Europe. The game follows the title character Mega Man as he fights the evil Dr. Wily. Along with foes from his past, Mega Man must contend with the next robot in Wily''s line of "Mega Man Killers", Punk.

Like its two consecutive predecessors on the Game Boy, the game combines elements from two previously released Nintendo Entertainment System (NES) titles: Mega Man 3 and Mega Man 4. The game received positive reviews from critics and was considered a notable improvement over its predecessors, though some criticized it for being too difficult, deeming its difficulty level overly frustrating.', 'https://en.wikipedia.org/wiki/Mega_Man_III_(1992_video_game)'),
  ('Q2041623', 'The Simpsons: Bart vs. the Juggernauts is a 1992 action-platform game developed by Imagineering and published by Acclaim Entertainment for the Game Boy. It stars Bart from The Simpsons in a game show based on American Gladiators, in which he has to compete in challenges to earn money. Critics gave Bart vs. the Juggernauts average reviews.', 'https://en.wikipedia.org/wiki/The_Simpsons:_Bart_vs._The_Juggernauts'),
  ('Q3519191', 'Tetris is a 1989 puzzle video game developed and published by Nintendo for the Game Boy. It is a portable version of Alexey Pajitnov''s original Tetris and it was bundled with the North American and European releases of the Game Boy itself. It is the first game to have been compatible with the Game Link Cable, a pack-in accessory that allows two Game Boy consoles to link for multiplayer purposes. A remaster, Tetris DX, was released on the Game Boy Color in 1998. It was released for the Nintendo 3DS'' Virtual Console in December 2011 without multiplayer functionality. The game was released on the Nintendo Classics service in February 2023.', 'https://en.wikipedia.org/wiki/Tetris_(Game_Boy_video_game)'),
  ('Q3504264', 'Super R.C. Pro-Am is a racing video game developed by Rare and published by Nintendo for the Game Boy. It was released in North America in June 1991 and in Europe on 23 April 1992; it was re-released in 1998 as part of Nintendo''s Player''s Choice series, which included all Game Boy titles which sold over one million copies. It is the follow-up to the Nintendo Entertainment System title R.C. Pro-Am, in which players race remote control cars from an out-of-vehicle perspective on a series of 24 tracks, avoiding obstacles and collecting items to improve performance in order to finish in the top three and qualify for the next track. The game can be played solo against three computer opponents, or two to four players can play simultaneously via the Game Link Cable or the Four Player Adapter.', 'https://en.wikipedia.org/wiki/Super_R.C._Pro-Am'),
  ('Q3538250', 'Trax is a 1991 shooter video game developed and published by HAL Laboratory for the Game Boy. Electro Brain published the game while being re-released outside Japan.', 'https://en.wikipedia.org/wiki/Trax_(video_game)'),
  ('Q3542368', 'Turok: Battle of the Bionosaurs is a 1997 platform game developed by Bit Managers and published by Acclaim Entertainment for the Game Boy. An entry in the Turok series of games, it was intended to be a companion to the Nintendo 64 game Turok: Dinosaur Hunter. The game includes eight stages, has a password system, and can be played in four different languages (English, French, Spanish, and German).', 'https://en.wikipedia.org/wiki/Turok:_Battle_of_the_Bionosaurs'),
  ('Q2273753', 'Kirby''s Dream Land 2 is a 1995 platform game developed by HAL Laboratory and published by Nintendo for the Game Boy handheld video game console. It was released in Japan on March 21, 1995, in North America on May 1, 1995, in Europe on July 31, 1995, and in Australia on November 22, 1995.

Kirby''s Dream Land 2 continues the adventures of Kirby from Kirby''s Dream Land and Kirby''s Adventure, adding three animal friends to aid Kirby in battle. It can be played on the Super Game Boy, and gives slight changes to the game, such as adding a custom color scheme, a special game border, and a few new sound effects.', 'https://en.wikipedia.org/wiki/Kirby%27s_Dream_Land_2'),
  ('Q2328923', 'Cool World is a 2D platform game released by Ocean Software in 1992 for the Commodore 64, Amiga, Atari ST, and MS-DOS. It was the first game based on the film of the same name. A version of the game for the Game Boy was released in 1993 alongside two entirely different games based on the film for the NES and SNES.', 'https://en.wikipedia.org/wiki/Cool_World_(1992_video_game)'),
  ('Q2164093', 'Wave Race is a 1992 racing video game developed and published by Nintendo for the Game Boy. It is the first game in the Wave Race series. The player controls a jet skier competing against AI opponents or up to three friends (using the GameBoy multiplayer link cable accessory) in two different racing modes across sixteen tracks.', 'https://en.wikipedia.org/wiki/Wave_Race'),
  ('Q2386992', 'The Simpsons: Bart & the Beanstalk is a platform game released in February 1994 for the hand-held console Game Boy. It was developed by Software Creations and published by Acclaim Entertainment, and is based on the animated television series The Simpsons. The game is a parody of the fairy tale "Jack and the Beanstalk"; a large beanstalk grows far up into the sky outside the home of Bart Simpson, whom the player controls. Bart climbs the beanstalk all the way to the top and adventure ensues. Bart & the Beanstalk has received mixed reviews from critics.', 'https://en.wikipedia.org/wiki/The_Simpsons:_Bart_%26_the_Beanstalk'),
  ('Q2389816', 'The Amazing Spider-Man is a platform action video game released for the Nintendo Game Boy in 1990, published by LJN and developed by Rare, based on the Marvel Comics superhero Spider-Man.', 'https://en.wikipedia.org/wiki/The_Amazing_Spider-Man_(handheld_video_game)'),
  ('Q2333557', 'Final Fantasy Adventure, known in Japan as Seiken Densetsu: Final Fantasy Gaiden or simply Seiken Densetsu, and later released in Europe as Mystic Quest, is a 1991 action role-playing game developed and published by Square for the Game Boy. It is a spin-off of the Final Fantasy series and the first game in the Mana series.

Originally developed under the name Gemma Knights, it features gameplay roughly similar to that of the original The Legend of Zelda, but with the addition of role-playing statistical elements. A remake, Sword of Mana, was released for the Game Boy Advance in 2003, changing the plot and many gameplay aspects. A second remake was released on mobile phones in Japan which improved the graphics and music of the original version. A third remake, Adventures of Mana, was released for iOS, Android, and PlayStation Vita on February 4, 2016.', 'https://en.wikipedia.org/wiki/Final_Fantasy_Adventure'),
  ('Q2381277', 'Timeball is a puzzle video game released by NEC for the TurboGrafx-16. The object of the game is to guide a ball along pieces of track by moving tiles like a sliding puzzle. The game''s name in Japan is Blodia, an anagram of Diablo, the title of a computer game upon which Blodia is based. Versions of Blodia were released exclusively in Japan for the original Game Boy and the X68000. A spin-off titled Blodia Land: Puzzle Quest was released for the Famicom, replacing the ball with cartoon dinosaur-like characters. These versions were developed by Tonkin House and published by Broderbund.', 'https://en.wikipedia.org/wiki/Timeball'),
  ('Q3570501', 'X is a 1992 space combat simulation video game developed by Nintendo and Argonaut Software and published by Nintendo for the Game Boy. It was only released in Japan. The player assumes the role of the VIXIV starship as it must protect the planet Tetamus II from a mysterious race of aliens. Gameplay involves completing missions assigned by the "Training Academy Coach", ranging from protecting bases from enemy fire or delivering cargo to a certain area.

Notable for being one of the few attempts at a 3D video game on the Game Boy alongside Faceball 2000, X was the creation of Dylan Cuthbert, who would later program the original Star Fox for the Super NES. Commissioned by Argonaut president Jez San after being impressed by the Game Boy at the 1991 Consumer Electronics Show, Cuthbert and a team of programmers were forced to reverse-engineer the system due to official development kits being hard to find. It was designed after Argonaut''s earlier game Starglider 2 for the Amiga. Nintendo grew interested in the game during production and convinced Cuthbert and Argonaut to make it a first-party title for the console. A planned North American release named Lunar Chase was cancelled as Nintendo of America felt a game of its type was too complicated for its audience at the time.', 'https://en.wikipedia.org/wiki/X_(1992_video_game)'),
  ('Q3634755', 'Barbie: Game Girl is a 2D platform game released in 1992 for the Game Boy based on the Barbie doll franchise.', 'https://en.wikipedia.org/wiki/Barbie:_Game_Girl'),
  ('Q3569533', 'Wizards & Warriors X: The Fortress of Fear is a 1990 video game developed by Rare and published by Acclaim Entertainment for the Game Boy. Taking place after the events of Ironsword: Wizards & Warriors II, the game follows the knight warrior Kuros as he sets out to the Fortress of Fear to defeat the evil wizard Malkil, who, after 17 years of dormancy, has captured Princess Elaine and has imprisoned her there.

Wizards & Warriors X consists of five "Chapters" that comprise 18 levels. In contrast to the previous games in the series, gameplay is more linear. Reviews were mainly negative and focused on the slow gameplay, lack of continues, and the blurring caused by scrolling on the Game Boy. Moreover, in response to the game''s title (Chapter X), some gaming magazines asked what happened to the intermediate chapters in the Wizards & Warriors series.', 'https://en.wikipedia.org/wiki/Wizards_%26_Warriors_X:_The_Fortress_of_Fear'),
  ('Q3748752', 'Fortified Zone is a 1991 top-down shooter video game developed and published by Jaleco for the Game Boy. The game is about the mercenaries Masato and Mizuki as they go through several environments to penetrate a military fortress. The game is set in a top-down point of view, where the characters shoot at various enemies while traverse four maze-like levels. The player can swap between each character who each have their own abilities ranging from being able to pick up enemy weapons to being able to jump to avoid traps.

It was first released in Japan on February 26, 1991, and later released in the United States in September 1991. A number of contemporary reviews were lukewarm, with some complimenting the game adding puzzle-solving and to its action-themed gameplay, while others found the game had too many frustrating elements and difficulty spikes. Some retrospective reviews of the game''s digital re-releases had similar complaints as well as finding the game to be too short.', 'https://en.wikipedia.org/wiki/Fortified_Zone'),
  ('Q3608223', 'Revenge of the ''Gator, known in Europe as Pinball: Revenge of the ''Gator, is a pinball video game developed and published by HAL Laboratory for the Game Boy. It was released in Japan in October 1989 and North America and Europe by Nintendo in March 1990. The objective of the game is to score as many points as possible without having the player''s pinball eaten by the alligator.', 'https://en.wikipedia.org/wiki/Revenge_of_the_%27Gator'),
  ('Q3772780', 'Godzilla is a video game developed by Compile based on the Godzilla franchise, and was first released for Game Boy in 1990. It is a port of the 1985 MSX game, Gojira-Kun. The game features character designs from the franchise''s Showa era films.', 'https://en.wikipedia.org/wiki/Godzilla_(1990_video_game)'),
  ('Q3564643', 'WCW: The Main Event is a professional wrestling video game released in 1994 by FCI, Inc. for the Nintendo Game Boy portable video game system. It was the second video game based on World Championship Wrestling (WCW), and the first of two released to a handheld console.', 'https://en.wikipedia.org/wiki/WCW:_The_Main_Event'),
  ('Q3905148', 'Pinball Mania is a 1995 video game developed by Spidersoft and published by 21st Century Entertainment. In addition to the Amiga release, ports were created for MS-DOS and Windows, with the Game Boy version published by GameTek.', 'https://en.wikipedia.org/wiki/Pinball_Mania'),
  ('Q3930487', 'Rats! is a 1998 2D platform video game developed by Tarantula Studios and published by Take-Two Interactive Software. The game was released in Europe for the Game Boy and Game Boy Color in 1998 under the title Reservoir Rat, and was released in the United States for only the Game Boy Color in 1998 under the title Rats!', 'https://en.wikipedia.org/wiki/Rats!'),
  ('Q3815154', 'Who Framed Roger Rabbit is a 1991 adventure game by Capcom for the Game Boy released in North America and Europe. Based on the 1988 film of the same title, it is one of the earliest games designed by Shinji Mikami.', 'https://en.wikipedia.org/wiki/Who_Framed_Roger_Rabbit_(1991_video_game)'),
  ('Q3812484', 'Kaijū-ō Godzilla is a 1993 action adventure game by Bandai for the Game Boy. It was released exclusively in Japan. The game is notable for featuring nearly every monster in the Godzilla franchise up until the time of its release.', 'https://en.wikipedia.org/wiki/Kaij%C5%AB-%C5%8D_Godzilla'),
  ('Q4353810', 'Blaster Master Boy in Europe and in Japan, is an action video game developed by Aicom and published by Sunsoft. The game was released in 1991 for the Game Boy.', 'https://en.wikipedia.org/wiki/Blaster_Master_Boy'),
  ('Q4390180', 'Gradius: The Interstellar Assault, released as Nemesis II: The Return of the Hero in Europe, and Nemesis II in Japan, is a 1991 horizontally scrolling shooter video game developed and published by Konami for the Game Boy. It is the second game in the Gradius series released for the console. The game was re-released via the Konami GB Collection series of Super Game Boy and Game Boy Color compilations; it can be found in the Japanese Vol.3 and the European Vol.4. Like Gradius before it, these versions were renamed Gradius II for the Japanese Vol.3 and Gradius II: The Return of the Hero for the European Vol.4. It was re-released on the Nintendo Classics service for the Nintendo Switch in May 2025.', 'https://en.wikipedia.org/wiki/Gradius:_The_Interstellar_Assault'),
  ('Q2454468', 'Castlevania Legends is a 1997 action-platform game developed and released by Konami for the Game Boy. The third Castlevania game released for the system, the story follows Sonia Belmont, a vampire hunter battling the first incarnation of Count Dracula. The game was conceived as a prequel to all other games in the Castlevania series; however, it was later retconned.

Castlevania Legends was released in Japan on November 27, 1997 and in Europe and North America on March 11, 1998. The game received mixed to negative reviews, with criticism directed towards its lack of difficulty, short length, technical issues, and unoriginality. The game received its first official re-release on the Nintendo Classics service on October 31, 2023.', 'https://en.wikipedia.org/wiki/Castlevania_Legends'),
  ('Q2619421', 'Kirby''s Star Stacker is a 1997 puzzle video game developed by HAL Laboratory and published by Nintendo for the Game Boy. It is a spin-off of the Kirby series with tile-matching gameplay. It was released for the Nintendo Classics service for the Nintendo Switch in May 2025.

It received a remake for the Super Famicom in Japan.', 'https://en.wikipedia.org/wiki/Kirby%27s_Star_Stacker'),
  ('Q4688470', 'Aerostar is a 1991 scrolling shooter video game developed by Sigma Pro-Tech and published by Vic Tokai in 1991 for the Nintendo Game Boy.', 'https://en.wikipedia.org/wiki/Aerostar_(video_game)'),
  ('Q3489226', 'Solar Striker is a vertically scrolling shooter video game developed by Nintendo and Minakuchi Engineering and published by Nintendo for the Game Boy. It was first published in Japan in January 1990, then released later in North America in February 1990 and in Europe in September 1990.', 'https://en.wikipedia.org/wiki/Solar_Striker'),
  ('Q2569337', 'Donkey Kong Land III is a 1997 platform game developed by Rare and published by Nintendo for the Game Boy. A port for the Game Boy Color was released only in Japan in 2000 under the name Donkey Kong GB: Dinky Kong & Dixie Kong. Like its predecessors, Donkey Kong Land III served as the portable version of and follow-up to its SNES counterpart, in this case Donkey Kong Country 3: Dixie Kong''s Double Trouble!, was enhanced for the Super Game Boy, and was packaged with a "banana yellow" cartridge.

The game has since been re-released via the Nintendo 3DS'' Virtual Console in 2014. The game was also later added to the Nintendo Classics service in early December 2024, following the re-releases of its two predecessors from late November.', 'https://en.wikipedia.org/wiki/Donkey_Kong_Land_III'),
  ('Q4690474', 'After Burst is a Japan-exclusive action video game released for the Game Boy in 1990.', 'https://en.wikipedia.org/wiki/After_Burst'),
  ('Q4736305', 'Altered Space is a 1991 video game produced for the Nintendo Game Boy.', 'https://en.wikipedia.org/wiki/Altered_Space'),
  ('Q2601198', 'Alleyway is a 1989 video game developed by Nintendo and Intelligent Systems and published by Nintendo for the Game Boy. It is a Breakout clone and one of the launch titles developed and released for the system. The game was released alongside the Game Boy, first in Japan in 1989, in North America later that year, and in Europe in 1990. It was later re-released for the Virtual Console on the Nintendo 3DS in June 2011, and on the Nintendo Switch Online service in May 2024.

The name Alleyway references the in-game gateway that the player''s spaceship (represented as a paddle) must pass through. While Alleyway is a portable clone of Breakout, it adds several features, including alternating stages, bonus rounds, and hazards for the player at later levels. While the game''s original box art featured an unidentifiable protagonist, later international releases of the game replaced the character with Mario. Alleyway was released with limited advertising, receiving moderate to low scores from reviewers who compared it to games like Arkanoid.', 'https://en.wikipedia.org/wiki/Alleyway_(video_game)'),
  ('Q4051775', 'Trip World is a 1992 platform video game developed and published by Sunsoft for the Game Boy. It was released in Japan in 1992. The game''s plot centers around the bunny-like being Yakopoo and his quest to retrieve the flower of peace so that peace will return to his disarranged world. The protagonist''s ability is to shapeshift into different forms.

Its reception was mixed; while it was praised for its graphics and music, it was criticized for its low difficulty and short length, with many comparing it to Gimmick!. It was re-released for the Nintendo 3DS''s Virtual Console in Japan in 2011, and in Europe in 2012. A remastered version, Trip World DX, was developed by Limited Run Games and released in 2023.', 'https://en.wikipedia.org/wiki/Trip_World'),
  ('Q278227', 'Amazing Tater is a video game for the Game Boy developed and published by Atlus.

Amazing Tater was released in Japan for the Game Boy on August 2, 1991 and is the sequel to Kwirk (1989) which was released as Pazuru Bōi. The English-language release of the game does not present any connection to the earlier game.', 'https://en.wikipedia.org/wiki/Amazing_Tater'),
  ('Q2565757', 'Kid Icarus: Of Myths and Monsters is a 1991 action-platform game developed and published by Nintendo for the Game Boy. It is a sequel to Kid Icarus (1986) for the Nintendo Entertainment System. It was released in North America on November 1991, and in Europe on May 21, 1992, but not in Japan where it was already developed until on February 8, 2012 through the 3DS Virtual Console; this project retained its original English localization and commemorated the release of the following month''s Kid Icarus: Uprising in the same region, followed by its re-release in Europe on March 8, and North America on July 19. The game was also re-released on the Nintendo Classics service on November 26, 2025. The story of Of Myths and Monsters is influenced by Greek and Roman mythology, and follows the angel soldier Pit on his quest for three sacred treasures. His objective is to defeat the demon Orcos, who has invaded the kingdom of Angel Land. The game features the core gameplay mechanics of its predecessor. Players explore two-dimensional environments while collecting items and fighting monsters. Of Myths and Monsters was named the 18th best Game Boy game by Nintendo Power, and commended by critics for its gameplay, graphics, and music.', 'https://en.wikipedia.org/wiki/Kid_Icarus:_Of_Myths_and_Monsters'),
  ('Q4353368', 'Yogi Bear''s Gold Rush is a 1994 2D platform game developed by British studio Twilight for the Game Boy.', 'https://en.wikipedia.org/wiki/Yogi_Bear%27s_Gold_Rush'),
  ('Q2484898', 'Tiny Toon Adventures: Montana''s Movie Madness (released in Japan as Tiny Toon Adventures 2: Buster Bunny no Kattobi Daibouken) is the second Tiny Toon Adventures game released on the Nintendo Game Boy. It was released in 1993 and was developed and published by Konami.', 'https://en.wikipedia.org/wiki/Tiny_Toon_Adventures_2:_Montana%27s_Movie_Madness'),
  ('Q2564684', 'Donkey Kong, commonly referred to as Donkey Kong ''94, is a 1994 puzzle-platform game developed by Nintendo and Pax Softnica for the Game Boy. The player controls the Italian plumber Mario, who must rescue his girlfriend Pauline from the gorilla Donkey Kong. It begins as a remake of the Donkey Kong (1981) arcade game before introducing 97 original levels, incorporating game mechanics from Donkey Kong Jr. (1982) and Super Mario Bros. 2 (1988), in which the player must locate a key to proceed.

The Donkey Kong franchise creator Shigeru Miyamoto led the development, which ended a decade-long hiatus after the unsuccessful Donkey Kong 3 (1983). The developers sought to reimagine the original game while maintaining the theme of Mario attempting to outwit the trickster Donkey Kong. They gave Mario many new abilities while focusing on puzzle-oriented gameplay to account for the Game Boy''s small display. Donkey Kong was the last game developed before Miyamoto shifted to an advisory role on the franchise.', 'https://en.wikipedia.org/wiki/Donkey_Kong_(1994_video_game)'),
  ('Q2636763', 'Kid Dracula is a 1993 platform game developed and published by Konami for the Game Boy. It is a spinoff of the Castlevania series and a sequel to the 1990 Famicom game also titled Kid Dracula. The game has the player control Kid Dracula who has forgotten most of his powers while the evil Garamoth is trying to take over his castle. As the player progresses through the games eight levels, Kid Dracula recalls his abilities which range from new ways to attack and traverse through levels.

Faith Johnson of Retro Gamer described the critical reception was generally positive about Kid Dracula. The game went on to be sell for high prices on the second hand market decades after its initial release.', 'https://en.wikipedia.org/wiki/Kid_Dracula_(1993_video_game)'),
  ('Q2626638', 'Itchy & Scratchy in Miniature Golf Madness is a side-scrolling action platform game and miniature golf game released on the Game Boy in 1994, featuring the cat and mouse pair Itchy & Scratchy from the American animated television series The Simpsons. Developed by Beam Software, it was the first game to feature these characters. In the game, the player controls Scratchy as he plays through a miniature golf course of nine holes while at the same time avoiding Itchy''s attacks. It received mixed reviews from critics.', 'https://en.wikipedia.org/wiki/The_Simpsons:_Itchy_%26_Scratchy_in_Miniature_Golf_Madness'),
  ('Q2471454', 'Metroid II: Return of Samus is a 1991 action-adventure game developed and published by Nintendo for the Game Boy. The first Metroid game for a handheld game console, it was released in North America in November 1991 and in Japan and Europe in 1992. It follows the bounty hunter Samus Aran on her mission to eradicate the Metroids from their home planet, SR388, before the Space Pirates can obtain them. Players must find and exterminate the Metroids to progress.

Like the original Metroid, released in 1986 for the Nintendo Entertainment System, Metroid II was developed by Nintendo Research & Development 1 and produced by Gunpei Yokoi. It introduced several features that became staples of the series, including Samus''s Space Jump, Spazer Beam and the Spider Ball, and round-shouldered Varia Suit.', 'https://en.wikipedia.org/wiki/Metroid_II:_Return_of_Samus'),
  ('Q2568036', 'Kirby''s Pinball Land is a 1993 pinball video game developed by HAL Laboratory and published by Nintendo for the Game Boy. It was HAL Laboratory''s third pinball video game after the MSX and NES title Rollerball and the Game Boy title Revenge of the ''Gator. It was also the first spin-off and second Game Boy title in the Kirby series, as well as the second pinball video game Nintendo published after the NES title Pinball. The game was rereleased on the Nintendo 3DS'' Virtual Console service in July 2012.

The game stars Kirby as the ball, and features three pinball tables, each owned by a classic boss of the Kirby series: Whispy Woods, Kracko, and Poppy Bros.', 'https://en.wikipedia.org/wiki/Kirby%27s_Pinball_Land'),
  ('Q2619366', 'Kirby’s Block Ball, known in Japan as Kirby no Block Ball, is a 1995 action video game developed by Tose and Nintendo and published by Nintendo for the Game Boy. It is a spin-off of the Kirby video game series. It is a Breakout clone; the player controls paddles along the screen''s edge to knock a bouncing ball, Kirby, into destructible bricks. The game''s 55 levels include power-ups, bonus rounds, and minigames. The team spent half a year revising the gameplay to match Kirby''s signature characteristics. Kirby''s Block Ball was released in Japan on December 14, 1995, later in North America in May 1996, and in Europe on August 29, 1996.', 'https://en.wikipedia.org/wiki/Kirby%27s_Block_Ball'),
  ('Q2639874', 'Operation C (released as Contra in Japan and as Probotector in the PAL region) is a 1991 run and gun video game by Konami released for the Game Boy. It is a sequel to Super Contra, and the first portable installment in the Contra series. Operation C features gameplay and graphics similar to the Nintendo Entertainment System versions of Contra and Super Contra.', 'https://en.wikipedia.org/wiki/Operation_C_(video_game)'),
  ('Q2718657', 'Donkey Kong Land, known in Japan as Super Donkey Kong GB, is a 1995 platform game developed by Rare and published by Nintendo for the Game Boy. It condenses the side-scrolling gameplay of the Super Nintendo Entertainment System (SNES) game Donkey Kong Country (1994) for the handheld Game Boy with different level design and boss fights. The player controls the gorilla Donkey Kong and his nephew Diddy Kong as they defeat enemies and collect items across 30 levels to recover their stolen banana hoard from the crocodile King K. Rool.

Development began in 1994, before Donkey Kong Country''s completion, and lasted a year. Rare''s Game Boy programmer, Paul Machacek, developed Land as an original game rather than as a port of Country after convincing the Rare co-founder Tim Stamper it would be a better use of resources. Like Country, Land features pre-rendered graphics converted to sprites through a compression technique. Rare retooled Country''s gameplay to account for the lower quality display, and David Wise and Graeme Norgate converted the soundtrack to the Game Boy''s sound chip.', 'https://en.wikipedia.org/wiki/Donkey_Kong_Land'),
  ('Q2704951', 'Teenage Mutant Ninja Turtles III: Radical Rescue is a 1993 Metroidvania video game developed and published by Konami for the Game Boy. Based on the Teenage Mutant Ninja Turtles (TMNT) franchise, the player controls a ninja turtle character as they battle enemies, rescue allies, and explore a non-linear maze-like environment. The game borrows plot elements, character design, and art styles from various forms of TMNT media of the era, such as the animated television series and the various comic series.

On the game''s release, some publications praised the game as one of the best games for the Game Boy, while others criticized the game''s difficulty and lack of originality. Years later, it has been recognized as an early example of the Metroidvania genre, pioneering design elements popularized in Konami''s later releases such as Castlevania: Symphony of the Night (1997).', 'https://en.wikipedia.org/wiki/Teenage_Mutant_Ninja_Turtles_III:_Radical_Rescue'),
  ('Q2710516', 'Bart Simpson''s Escape from Camp Deadly is a 1991 platform video game developed by Imagineering and published by Acclaim Entertainment for the Game Boy. Based on the animated television series The Simpsons, the player controls Bart as he escapes from an unpleasant summer camp run by ruthless counselors. The plot is similar to that of The Simpsons episode "Kamp Krusty", although the game was released nearly a year before that episode aired. Critics gave the game mixed reviews.', 'https://en.wikipedia.org/wiki/Bart_Simpson%27s_Escape_from_Camp_Deadly'),
  ('Q3958954', 'Ninja Gaiden Shadow, released in Japan as Ninja Ryūkenden GB: Matenrō Kessen and in Europe and Australia as Shadow Warriors, is a 1991 hack and slash platform game developed by Natsume Co., Ltd. and published by Tecmo for the Game Boy. It is a prequel to the NES Ninja Gaiden trilogy.', 'https://en.wikipedia.org/wiki/Ninja_Gaiden_Shadow'),
  ('Q3986142', 'The Bugs Bunny Crazy Castle 2 is a platform video game developed and published by Kemco for the Game Boy in 1991. It is the sequel to the 1989 Nintendo Entertainment System and Game Boy game The Bugs Bunny Crazy Castle.

This game was originally a Mickey Mouse game; it was released in Japan as Mickey Mouse II and in Europe as simply Mickey Mouse. A second reskin, themed around the Hugo franchise and simply titled Hugo, was released in Europe in 1996. This game''s Bugs Bunny version was released in Japan in 1997 through Bugs Bunny Collection, a Game Boy compilation containing this game and its predecessor.', 'https://en.wikipedia.org/wiki/The_Bugs_Bunny_Crazy_Castle_2'),
  ('Q2563041', 'Castlevania: The Adventure is a 1989 platform game developed and published by Konami for the Game Boy. The game is the first in the Castlevania series to be released on a handheld game console.

The game was re-released as part of the Konami GB Collection Vol.1 compilation in Japan and Europe, the latter version of which added color support. A remake titled Castlevania: The Adventure ReBirth was released as a WiiWare game for the Wii. The original game is included in the Castlevania Anniversary Collection, which was released in 2019.', 'https://en.wikipedia.org/wiki/Castlevania:_The_Adventure'),
  ('Q2562585', 'Castlevania II: Belmont''s Revenge is a 1991 platform game developed and published by Konami for the Game Boy. It is the second Castlevania title for the Game Boy and serves as a sequel to Castlevania: The Adventure. Belmont''s Revenge is included in color in the European Konami GB Collection Vol.4 compilation.

Set fifteen years after the events of Castlevania: The Adventure, Dracula returns and kidnaps Christopher Belmont''s son Soleil at his coming of age feast, and turns him into a demon. With Soleil''s mystical powers, Dracula retakes human form and rebuilds his castle, forcing Christopher to confront Dracula once again to save his son and Transylvania.', 'https://en.wikipedia.org/wiki/Castlevania_II:_Belmont%27s_Revenge'),
  ('Q3280776', 'The Amazing Spider-Man is a platform action video game released for the Nintendo Game Boy in 1990, published by LJN and developed by Rare, based on the Marvel Comics superhero Spider-Man.', 'https://en.wikipedia.org/wiki/The_Amazing_Spider-Man_(handheld_video_game)'),
  ('Q16266814', 'High Stakes Gambling is a Game Boy casino video game that takes place during the Great Depression in the 1930s. It was developed by Sculptured Software and published by Electro Brain in 1992.', 'https://en.wikipedia.org/wiki/High_Stakes_Gambling'),
  ('Q6412491', 'Kingdom Crusade (known as The Legend of Prince Valiant in Europe) is a Game Boy strategy video game released in 1991 in the PAL regions and 1992 in North America. The PAL version was based on the cartoon of the same name.', 'https://en.wikipedia.org/wiki/Kingdom_Crusade'),
  ('Q11544709', 'Boxing (known in North America as Heavyweight Championship Boxing) is a boxing video game, developed by Tose and published by Tonkin House which was released in 1990.

Once the player chooses a boxer, the other challengers must be defeated in order to gain the title. Points can be distributed and re-distributed on the fighter''s health meter, stamina, and how fast he moves around in the ring. Either uppercuts or normal punches can be used to wear down the opponent in the game.', 'https://en.wikipedia.org/wiki/Boxing_(1990_video_game)'),
  ('Q61880772', 'Ultima: Runes of Virtue a spin-off from the Ultima series released for the Game Boy in 1991. Runes of Virtue is Richard Garriott''s favorite non-PC Ultima game because it was built from the ground up as a Game Boy game, unlike previous console Ultima games which were ports from the PC. A sequel, Ultima: Runes of Virtue II, was released in 1993.', 'https://en.wikipedia.org/wiki/Ultima:_Runes_of_Virtue'),
  ('Q1276400', 'Popeye 2 is a 1991 2D platform game based on Popeye comic strip created by E. C. Segar, developed by Copya System and published by Sigma Enterprises for the Game Boy handheld. It was later published in North America (1993) and Europe (1994) by Activision.

It is a sequel to Popeye, released exclusively in Japan in 1990.', 'https://en.wikipedia.org/wiki/Popeye_2'),
  ('Q5097541', 'Chikyū Kaihō Gun ZAS is a vertical scrolling shooter video game developed and published by T&E Soft for the Nintendo Game Boy exclusively in Japan on December 18, 1992.', 'https://en.wikipedia.org/wiki/Chiky%C5%AB_Kaih%C5%8D_Gun_ZAS'),
  ('Q4907850', 'Bill & Ted''s Excellent Game Boy Adventure: A Bogus Journey! or Bill & Ted''s Excellent Portable Adventure is an action-puzzle video game based on the Bill & Ted films released by Acclaim Entertainment for the Game Boy in 1991.', 'https://en.wikipedia.org/wiki/Bill_%26_Ted%27s_Excellent_Game_Boy_Adventure:_A_Bogus_Journey!'),
  ('Q48987740', 'Megalit is a 1991 third party puzzle-solving strategy game developed by ASCII Corporation. It was published for the Nintendo Game Boy by Asmik Ace Entertainment in Japan and Takara in North America and Europe. Megalit was first released in Japan on August 9, 1991. It was not released until December 1992 in North America and Europe.', 'https://en.wikipedia.org/wiki/Megalit'),
  ('Q6346017', 'Kaeru no Tame ni Kane wa Naru (カエルの為に鐘は鳴る), officially translated as The Frog For Whom the Bell Tolls, is an action role-playing video game developed by Nintendo and Intelligent Systems and published by Nintendo for the Game Boy exclusively in Japan in 1992.

The title is a play on Ernest Hemingway''s novel For Whom the Bell Tolls, which is known in Japan as Ta ga Tame ni Kane wa Naru. This is in turn an allusion to John Donne''s famous Meditation XVII.', 'https://en.wikipedia.org/wiki/Kaeru_no_Tame_ni_Kane_wa_Naru'),
  ('Q5049072', 'Casper is a series of action-adventure games based on the 1995 film of the same name. Two different games were released in 1996 and 1997 for the Super Nintendo Entertainment System, by different publishers, in different regions. A third game was released for the 3DO (the final release for that system), Sega Saturn, PlayStation, and Game Boy Color, published by Interplay Productions. There was also a Game Boy game developed by Bonsai. A PC game, Casper: The Interactive Adventure, and a Game Boy Advance game, simply titled Casper, were released in 1997 and 2002 respectively serving as sequels.', 'https://en.wikipedia.org/wiki/Casper_(video_game)'),
  ('Q1154044', 'Kirby''s Dream Land is a 1992 platform game developed by HAL Laboratory and published by Nintendo for the Game Boy. It is the first game in the Kirby series and marks the debut of Kirby. It introduced many conventions that would appear in later games in the series. The game follows Kirby as he goes through five levels to retrieve the Sparkling Stars and food of Dream Land from King Dedede.

Kirby''s Dream Land was the debut game of designer Masahiro Sakurai. He intended it to be a simple game that could be easy to pick up and play by those unfamiliar with action games. For more advanced players, he offered additional optional challenges such as a hard mode and the ability to edit Kirby''s maximum HP and starting number of lives. Kirby''s Dream Land was re-released on the Nintendo 3DS via the Virtual Console in 2011; it is also one of the games included in the compilation game Kirby''s Dream Collection for the Wii, released to celebrate the series'' 20th anniversary. The game was included as part of the Nintendo Classics service in February 2023. The game was the highest grossing in the series, with 5,130,000 copies sold, until being beaten out 30 years later by Kirby and the Forgotten Land.', 'https://en.wikipedia.org/wiki/Kirby%27s_Dream_Land'),
  ('Q625278', 'Pocket Bomberman is a platform video game developed by Hudson Soft and originally released for the Game Boy in 1997. It was re-released as a launch title for the Game Boy Color in 1998.

The game received generally positive reviews for its gameplay.', 'https://en.wikipedia.org/wiki/Pocket_Bomberman'),
  ('Q4920327', 'Black Bass: Lure Fishing is a 1992 fishing video game for the Game Boy. It was ported to the North American and European Game Boy Color in 1999.', 'https://en.wikipedia.org/wiki/Black_Bass:_Lure_Fishing'),
  ('Q55639603', 'Dragon''s Lair: The Legend is a 1991 platform video game developed by Elite Systems and published by CSG Imagesoft for the Game Boy. The game is part of the Dragon''s Lair franchise and stars Dirk the Daring, who explores the world attempting to collect all 194 fragments of the mythical Life Stone. The gameplay is an extreme departure from other games in the series as it includes no enemies and aside from its protagonist, no other established characters. It does however retain the grueling difficulty that the series is known for.', 'https://en.wikipedia.org/wiki/Dragon%27s_Lair:_The_Legend'),
  ('Q4952015', 'Boxxle is a 1989 sokoban puzzle video game for the Game Boy developed by Atelier Double Co. and published by Pony Canyon in Japan and FCI in North America and Europe.

The game was one of the first licensed third-party titles for the Game Boy. released in Japan for the Game Boy on September 1, 1989. A sequel, Boxxle II, was released in 1990.', 'https://en.wikipedia.org/wiki/Boxxle'),
  ('Q643018', 'The Final Fantasy Legend, originally released in Japan as Makai Toushi Sa・Ga, is a 1989 role-playing video game developed and published by Square for the Game Boy. It was originally released in Japan in December 1989 and North America in September 1990. It is the first game in the SaGa series and the first role-playing game for the system. Square translated the game into English for worldwide release and renamed it, linking it with the Final Fantasy series to improve marketing. Sunsoft re-released it in North America during 1998; Square followed with a Japan-exclusive remake released for the WonderSwan Color and mobile phones in 2002 and 2007 respectively, it was also ported to the Nintendo Switch in 2020 and later ported to Android, iOS and Microsoft Windows in 2021.', 'https://en.wikipedia.org/wiki/The_Final_Fantasy_Legend'),
  ('Q6822673', 'Metal Masters is a 2D fighting video game first released in 1991 for the Atari ST, IBM PC, and Amiga. It was ported to the Nintendo Game Boy in 1993.', 'https://en.wikipedia.org/wiki/Metal_Masters'),
  ('Q30924186', 'Soldam is a 1992 tile-matching puzzle video game developed and published by Jaleco for arcades. It was only released in Japan in September 1992. It is a spin-off of Jaleco''s previous game Rod Land. A Game Boy port was only released in Japan in 1993. A Nintendo Entertainment System version was completed but cancelled before release; Jaleco''s successor City Connection released the game in 2025 in collaboration with Broke Studio and Omake Books.

City Connection released a remake, Soldam: Drop, Connect, Erase, for the Nintendo Switch in 2017 as a launch title for the console and the PlayStation 4 in 2019. Hamster Corporation released the arcade version as part of their Arcade Archives series for the Nintendo Switch and PlayStation 4 in September 2021.', 'https://en.wikipedia.org/wiki/Soldam'),
  ('Q7038892', 'Ninja Boy is a 1990 action video game that was developed and published by Culture Brain for the Game Boy.

The game is set in Kung-Fu World where the Yoma Clan have captured a princess. The player controls the ninja Jack, who seeks out across the various lands to rescue her.', 'https://en.wikipedia.org/wiki/Ninja_Boy'),
  ('Q4956075', 'Bram Stoker''s Dracula is a 1993 video game for the Game Boy developed by Probe Entertainment and released by Sony Imagesoft. It is a handheld port of the console video game of the same name, which is in turn based on the film Bram Stoker''s Dracula directed by Francis Ford Coppola.', 'https://en.wikipedia.org/wiki/Bram_Stoker%27s_Dracula_(handheld_video_game)'),
  ('Q14744083', 'Nemesis is a 1990 horizontally scrolling shooter video game developed and published by Konami for the Game Boy. It is part of the Gradius series. Similar to Taito''s Sagaia, this game uses a once-international title for an earlier game in the series to represent a mostly original project.

A sequel, Gradius: The Interstellar Assault, was released for the same platform in 1991. Both games were later rereleased through the Konami GB Collection series, where they are titled Gradius and Gradius II instead.', 'https://en.wikipedia.org/wiki/Nemesis_(video_game)'),
  ('Q11295705', 'Cave Noire is a Japanese roguelike video game developed and published by Konami and released on April 19, 1991, for the Nintendo Game Boy. It has never been officially released in the west.

In 2012, a fan translated English patch for the game was released online.

The player takes on the role of a hero, either male or female, who has recently arrived at the village of Karuzu, which consists of an Adventurer''s Guild and four distinct randomly generated dungeons. In order to be admitted to the guild, the player must challenge and conquer each dungeon multiple times, raising his or her level. Each dungeon consists of ten difficulty levels, with defeat of level six required to gain the Adventurer rank.', 'https://en.wikipedia.org/wiki/Cave_Noire'),
  ('Q6926041', 'Mouse Trap Hotel is an action video game for the Nintendo Game Boy. It is loosely based on Milton Bradley''s board game Mouse Trap.', 'https://en.wikipedia.org/wiki/Mouse_Trap_Hotel'),
  ('Q6928529', 'The Game Boy portable system has a library of games, which were released in plastic ROM cartridges. The Game Boy first launched in Japan on April 21, 1989, with Super Mario Land, Alleyway, Baseball, and Yakuman. For the North American launches, Tetris and Tennis were also featured, while Yakuman was never released outside of Japan. The last games to be published for the system were the Japan-only titles Shikakui Atama o Maruku Suru: Kanji no Tatsujin and Shikakui Atama o Maruku Suru: Keisan no Tatsujin, both released on March 30, 2001.

This list is initially organized alphabetically by their English titles, or, when Japan-exclusive, their rōmaji transliterations; however, it is also possible to sort each column individually by clicking the square icon at the top of each column. The Game Boy system is not region locked, meaning that software purchased in any region can be played on any region''s hardware. For Game Boy Color cartridges compatible with the original Game Boy, see those indicated in List of Game Boy Color games.', 'https://en.wikipedia.org/wiki/List_of_Game_Boy_games'),
  ('Q6917992', 'Motocross Maniacs is a 1989 platform racing video game developed by Konami and published by Konami under the Ultra Games label for the Game Boy. It was later re-released in color as part of the Konami GB Collection compilation series, under the name Bikers.', 'https://en.wikipedia.org/wiki/Motocross_Maniacs'),
  ('Q5104838', 'Choplifter II is a video game developed by Beam Software and released in 1991 exclusively for the Game Boy. It is a follow-up to the original Choplifter and the first entry in the series released for the Game Boy.', 'https://en.wikipedia.org/wiki/Choplifter_II'),
  ('Q6959577', 'Nail ''n'' Scale, known as Dragon Tail in Japan, is a puzzle video game for the Game Boy. A combination of the video game Jump''n Run and various puzzle games, it has a fast-paced side-scrolling gameplay.', 'https://en.wikipedia.org/wiki/Nail_%27n%27_Scale'),
  ('Q11301701', 'Tamagotchi is a 1997 simulation game for the Game Boy. It is based on the popular electronic toy Tamagotchi that was released in 1996 and became a popular toy in Japan. A similar wave of popularity for Tamagotchi entered the West on the toy''s release, but faded much faster than the toy''s popularity in Japan. During this wave of popularity, several spin-off items were created, including the Tom Create-developed Tamagotchi video game.

Like the original toy, Tamagotchi has the player raise a virtual pet. The game lets players raise up to three pets at a time and nurtures them through activities such as feeding, training, and cleaning up after their pets. The game adds more possible pets than the original toy and has more complex games with their pets and putting them into competitions.', 'https://en.wikipedia.org/wiki/Tamagotchi_(Game_Boy_video_game)'),
  ('Q4943468', 'Boomer''s Adventure in ASMIK World, known in Japan as Teke! Teke! Asmik-kun World is a 1989 puzzle video game developed and published by Asmik for the Game Boy. Asmik of America released its version in 1990 in North America. The game''s direct sequel, Asmik-kun World 2, was never released outside Japan.', 'https://en.wikipedia.org/wiki/Boomer%27s_Adventure_in_ASMIK_World'),
  ('Q6838736', 'Mickey Mouse: Magic Wands!, known in Japan as Mickey Mouse V: Mahou no Stick and known in Europe as Mickey Mouse V: Magic Wands!, is a puzzle/action game developed and published by Kemco in Japan on December 22, 1993. It was later released in Europe by Kemco in October 1995 and published in North America by Nintendo in May 1998 under the Player''s Choice label with the western versions featuring Super Game Boy support. It is the fifth installment in the Crazy Castle series.

It was the last of Kemco''s Mickey Mouse-based video games in their Crazy Castle series and the only title to be released in North America under its original title (although the Roman numeral was removed).', 'https://en.wikipedia.org/wiki/Mickey_Mouse:_Magic_Wands!'),
  ('Q6948790', 'Mysterium is a first person dungeon crawl game developed by Maxis and published by Asmik Ace Entertainment in February 1991 for the Nintendo Game Boy.', 'https://en.wikipedia.org/wiki/Mysterium_(video_game)'),
  ('Q5174274', 'Cosmo Tank is a video game published by Asuka Technologies and developed by Atlus. It was released in 1990 for the Game Boy; with most of the gameplay programmed as a 2D shooter with some levels resembling that of a 3D shooter video game.

All the 2D levels were designed by Masami Satō while all the 3D levels were designed by Hidehiko Harada.', 'https://en.wikipedia.org/wiki/Cosmo_Tank'),
  ('Q6731501', 'The Game Boy portable system has a library of games, which were released in plastic ROM cartridges. The Game Boy first launched in Japan on April 21, 1989, with Super Mario Land, Alleyway, Baseball, and Yakuman. For the North American launches, Tetris and Tennis were also featured, while Yakuman was never released outside of Japan. The last games to be published for the system were the Japan-only titles Shikakui Atama o Maruku Suru: Kanji no Tatsujin and Shikakui Atama o Maruku Suru: Keisan no Tatsujin, both released on March 30, 2001.

This list is initially organized alphabetically by their English titles, or, when Japan-exclusive, their rōmaji transliterations; however, it is also possible to sort each column individually by clicking the square icon at the top of each column. The Game Boy system is not region locked, meaning that software purchased in any region can be played on any region''s hardware. For Game Boy Color cartridges compatible with the original Game Boy, see those indicated in List of Game Boy Color games.', 'https://en.wikipedia.org/wiki/List_of_Game_Boy_games'),
  ('Q16248700', 'Star Trek Generations: Beyond the Nexus is a Star Trek video game released for the Nintendo Game Boy and Game Gear in 1994. It was developed and released by Absolute Entertainment, who back in 1993 released "Star Trek: The Next Generation - The Advanced Holodeck Tutorial". The space combat was adapted for the new game and further gameplay modes were added. The new game was developed for the film Star Trek Generations.', 'https://en.wikipedia.org/wiki/Star_Trek_Generations:_Beyond_the_Nexus'),
  ('Q647249', 'Super Mario Land is a 1989 platform game developed and published by Nintendo for the Game Boy, as one of four launch titles for the console. It was first released in Japan in April 1989, followed by North America in August of that year, and Europe and Australia in 1990. It is the first handheld entry in the Super Mario series, as well as the first mainline title not designed by series creator Shigeru Miyamoto. Modeled after the original Super Mario Bros. (1985), the game adapts side-scrolling gameplay for the Game Boy''s smaller screen, with the player guiding Mario through 12 levels to rescue Princess Daisy (in her debut appearance) from the alien Tatanga in the new setting of Sarasaland.', 'https://en.wikipedia.org/wiki/Super_Mario_Land'),
  ('Q4915184', 'Bionic Commando is a 1992 platform video game developed by Minakuchi Engineering and published by Capcom for the Game Boy. It is an adaptation of the Nintendo Entertainment System version of Bionic Commando, changing the present-day setting of the NES version into a futuristic science fiction one.

The game has been re-released via the Nintendo 3DS Virtual Console service in 2011 and the Nintendo Classics service in November 2025.', 'https://en.wikipedia.org/wiki/Bionic_Commando_(1992_video_game)'),
  ('Q627491', 'God Medicine: Fantasy Sekai no Tanjou is a role-playing video game released by Konami in 1993 for the Game Boy, only in Japan. An updated version of the game, God Medicine Fukkokuban, was re-released in 1998 through the Nintendo Power service, adding Super Game Boy support, a bestiary for encountered monsters and additional story elements.', 'https://en.wikipedia.org/wiki/God_Medicine'),
  ('Q97824006', 'Top Rank Tennis, released in some territories as Top Ranking Tennis, is a 1993 sports video game developed by Pax Softnica and published by Nintendo for the Game Boy. Players can play against each other by linking two Game Boys.', 'https://en.wikipedia.org/wiki/Top_Rank_Tennis'),
  ('Q25376969', 'Game & Watch Gallery is a 1997 video game compilation developed by Tose and published by Nintendo for the Game Boy. It is the second entry in the Game & Watch Gallery series, following Game Boy Gallery. The compilation includes updated versions of four titles from Nintendo''s Game & Watch line of handheld electronic games, originally released between 1980 and 1982. Each game is presented in two forms: a "Classic" mode that replicates the original gameplay and visuals, and a "Modern" mode with updated gameplay, enhanced graphics and music, and characters from the Mario franchise.', 'https://en.wikipedia.org/wiki/Game_%26_Watch_Gallery'),
  ('Q22019766', 'Skate or Die: Bad ''N Rad is a 2D action video game developed and published by Konami for the Nintendo Game Boy. A part of the Skate or Die series created by Electronic Arts, the game was released in North America in September 1990 and in Europe in June 1991.', 'https://en.wikipedia.org/wiki/Skate_or_Die:_Bad_%27N_Rad'),
  ('Q6129973', 'James Bond 007 is an action-adventure game featuring James Bond. The game was developed by Saffire and published by Nintendo for the Game Boy. Released in North America on February 9, 1998, the game features a story that includes characters from multiple James Bond films, such as Oddjob and Jaws.', 'https://en.wikipedia.org/wiki/James_Bond_007_(1998_video_game)'),
  ('Q97447238', 'Terminator 2: Judgment Day is a 1991 action-adventure game developed by Bits Studios and published by LJN. It is based on the 1991 film of the same name, and was released for the Game Boy. It was praised for its graphics, gameplay, and music.', 'https://en.wikipedia.org/wiki/Terminator_2_(Game_Boy_video_game)'),
  ('Q25403887', 'Tetris Blast, known in Japan as Super Bombliss is a 1995 puzzle video game released for the Game Boy. Developed by Bullet-Proof Software, Tetris Blast has its roots in a game called Bombliss, designed by a Japanese team and first released in Tetris 2 + Bombliss for the Famicom in Japan.

Tetris Blast follows the mechanics of Tetris with the addition of bombs to some of the blocks. When a full row of blocks is completed, any bombs within the blocks explode which has the potential to set off a chain reaction of other blocks nearby. The game has three modes: one for practice. The second is titled "Contest" where the goal is to clear an area of blocks in a chute already filled with blocks and bombs. The third is Fight mode which allows for the player to play the game while insect-like creatures cause problems on the playing board from adding blocks to eating bombs.', 'https://en.wikipedia.org/wiki/Tetris_Blast'),
  ('Q28126678', 'The Punisher: The Ultimate Payback! is a 1991 shoot ''em up video game for the Game Boy, based on the Marvel Comics antihero the Punisher. The game, developed by Beam Software and published by Acclaim Entertainment, is a revised version of the 1991 NES game The Punisher, featuring cameo appearances from Spider-Man and the final boss being switched from Kingpin to Jigsaw.', 'https://en.wikipedia.org/wiki/The_Punisher:_The_Ultimate_Payback!'),
  ('Q969612', 'Titus the Fox: To Marrakech and Back is a side-scrolling platform game developed by Titus France for the Amiga, Amstrad CPC, Atari ST, and MS-DOS. The game was originally released in 1991 under the name Lagaf'': Les Aventures de Moktar — Vol 1: La Zoubida, featuring French comedian Lagaf'' as a tie-in with his song "La Zoubida". For the international edition, Titus retooled the game to feature its mascot and released the game as Titus the Fox: To Marrakech and Back in 1992.', 'https://en.wikipedia.org/wiki/Titus_the_Fox'),
  ('Q936786', 'Teenage Mutant Ninja Turtles II: Back from the Sewers, released as Teenage Mutant Hero Turtles II: Back from the Sewers in Europe, and Teenage Mutant Ninja Turtles 2 in Japan, is a 1991 action-platform game developed and published by Konami for the Game Boy. It is the sequel to Teenage Mutant Ninja Turtles: Fall of the Foot Clan. The game was re-released as part of Teenage Mutant Ninja Turtles: The Cowabunga Collection in 2022.', 'https://en.wikipedia.org/wiki/Teenage_Mutant_Ninja_Turtles_II:_Back_from_the_Sewers'),
  ('Q971188', 'Gargoyle''s Quest is a 1990 platform game developed and published by Capcom for the Game Boy. It is a spin-off of the Ghosts ''n Goblins series, featuring the series antagonist character Firebrand as the main playable character. Gargoyle''s Quest was followed by the NES prequel Gargoyle''s Quest II in 1992 and the Super NES sequel Demon''s Crest in 1994.

Gargoyle''s Quest was released on the Nintendo 3DS Virtual Console in 2011. It was released for the Nintendo Classics service in February 2023.', 'https://en.wikipedia.org/wiki/Gargoyle%27s_Quest'),
  ('Q971338', 'Batman: The Animated Series is a platformer video game by Konami released for the Game Boy in 1993, based on the television series of the same title. In the game, the player controls either Batman or Robin as they thwart the villains of Gotham City such as Joker and Mr. Freeze.

The game was the third Batman game for the Game Boy following two titles from Sunsoft: Batman: The Video Game (1990) and Batman: Return of the Joker (1992). Reviewers praised the graphics of the game and complimented how it captured the look of the animated series. The game had mediocre reviews in terms of its gameplay, citing little variety and minimal challenge.', 'https://en.wikipedia.org/wiki/Batman:_The_Animated_Series_(video_game)'),
  ('Q7748782', 'The Lost World: Jurassic Park is the title of several different video games released for handheld video game consoles in 1997. Four versions, each with their own gameplay variations, were developed and published by various companies for the Sega Game Gear, Nintendo''s Game Boy, and Tiger Electronics'' game.com and R-Zone consoles. Each version is based on the 1997 film of the same name.', 'https://en.wikipedia.org/wiki/The_Lost_World:_Jurassic_Park_(handheld_game)'),
  ('Q7638008', 'Sumo Fighter: Tōkaidō Basho (known in North America only as Sumo Fighter) is a 2D sumo-based action game, developed by KID and published by I''Max, which was released in 1991. In North America, the game was released by DTMC.', 'https://en.wikipedia.org/wiki/Sumo_Fighter:_T%C5%8Dkaid%C5%8D_Basho'),
  ('Q7642252', 'Super Chinese Fighter GB is a 2D fighting video game for the Game Boy released by Culture Brain in 1996. It is part of the Super Chinese series.

Like Super Chinese Fighter for the SNES, Fighter GB allows players to participate in fighting game battles using characters from the Super Chinese games, including Jack and Ryu. The game has 12 different fighters. Players can use "super techniques" for their special attacks and block them using their "super defense". This game has a high level of animation and combat moves for a Game Boy game and it is possible to deliver combos that do more than 10 hits of damage.', 'https://en.wikipedia.org/wiki/Super_Chinese_Fighter_GB'),
  ('Q7642256', 'Super Chinese Land 3 is a 1995 video game for the Game Boy. It is the third game in the Game Boy series, which was a spin-off of the Super Chinese series which began in 1984.

In the game, the two ninjas must stop monsters that escaped when a magical seal was opened. As in the previous games, it is a role-playing video game that becomes an action game when the players enter battles. The game received poor reviews in Famicom Tsūshin who cited poor quality gameplay and controls during the fight scenes as well as low quality graphics.', 'https://en.wikipedia.org/wiki/Super_Chinese_Land_3'),
  ('Q7619766', 'Stop That Roach! is a Game Boy puzzle video game developed and published by Koei.', 'https://en.wikipedia.org/wiki/Stop_That_Roach!'),
  ('Q7712651', 'The Adventures of Star Saver, known in Japan as Rubble Saver, is a 2D platform game for the Game Boy. It is a quasi-sequel to the earlier Miracle Ropitt for Famicom.', 'https://en.wikipedia.org/wiki/The_Adventures_of_Star_Saver'),
  ('Q104840862', 'Baby T-Rex is a platform game developed by Beam Software for Game Boy. It was released in 1993 in Europe by Laser Beam Entertainment, Beam''s publishing arm. The same underlying game was released under alternate titles each adapting a different intellectual property: Agro Soar in Australia, Bamse in Sweden, and We''re Back! A Dinosaur''s Story in North America, where it was published by Hi Tech Expressions.

The following year Beam released a follow-up, Radical Rex, for Super NES, Sega Genesis and Sega CD, which in 2022 was bundled with the Game Boy game in a compilation for various platforms.', 'https://en.wikipedia.org/wiki/Baby_T-Rex'),
  ('Q7767759', 'The Sword of Hope, released in Japan as Selection: Erabareshi Mono, is a role-playing video game developed and published by Kemco for the Game Boy. It was released in 1989 in Japan and 1991 internationally.

In 1992, it received a sequel, The Sword of Hope II. These two games were rereleased in Japan as a single Game Boy cartridge, Selection I & II, on May 1, 1998. The Sword of Hope was also released for the Nintendo 3DS'' Virtual Console in Japan on December 7, 2011 and the Nintendo Classics service for the Nintendo Switch on May 23, 2025. Another sequel titled Selection was released for mobile phones on 2008.', 'https://en.wikipedia.org/wiki/The_Sword_of_Hope'),
  ('Q7600953', 'Star Trek: 25th Anniversary is a 1992 Game Boy video game developed by Visual Concepts and published by Ultra, based upon the Star Trek universe. The game chronicles a mission of James T. Kirk and his crew of the USS Enterprise. Despite having the same name, the Game Boy version is not a port of the NES game or computer versions, and is in fact a completely different game. It was succeeded by Star Trek: The Next Generation for Game Boy, developed and published by Absolute Entertainment the following year.', 'https://en.wikipedia.org/wiki/Star_Trek:_25th_Anniversary_(Game_Boy_video_game)'),
  ('Q1635462', 'Wario Land II, known in Japan as Wario Land 2: The Stolen Treasure, is a 1998 platform game developed and published by Nintendo for the Game Boy. Players control Wario as he sets out to recover his stolen treasure from Captain Syrup.

The gameplay retains the side-scrolling platforming of Wario Land: Super Mario Land 3, with the player guiding Wario through various levels with the goal of finishing with as many coins as possible. Wario Land II introduces an immortality game mechanic in which enemies cannot inflict damage, but instead cause Wario to lose coins or transform into forms with abilities that allow players to access new areas.', 'https://en.wikipedia.org/wiki/Wario_Land_II'),
  ('Q1634866', 'Wario Land: Super Mario Land 3, known in Japan as Super Mario Land 3: Wario Land, is a 1994 platform game developed and published by Nintendo for the Game Boy. A spin-off of the Mario series, it follows Wario, the antagonist of Super Mario Land 2: 6 Golden Coins (1992), as he travels around an island in an attempt to find the treasures necessary to purchase his own castle. The player traverses through side-scrolling levels, avoiding obstacles and jumping between platforms, while collecting coins and treasure in order to progress.

Wario Land received positive reviews from critics, lauding its length and aesthetic quality, though it garnered mixed opinions on the game''s difficulty. It sold more than five million copies and established the Wario series of spin-offs and sequels. The game was re-released for the Nintendo 3DS''s Virtual Console in 2012 and for the Nintendo Classics service in 2026.', 'https://en.wikipedia.org/wiki/Wario_Land:_Super_Mario_Land_3'),
  ('Q1621156', 'Mario''s Picross is a 1995 puzzle video game developed by Jupiter and Ape Inc. and published by Nintendo for the Game Boy. It is a compilation of nonogram logic puzzles, and is a part of Nintendo''s Picross video game franchise. The game stars Mario who chisels away at puzzle grids to form pictures. The game initially received positive reviews, with reviewers citing its length and addictive nature as a positive, but its grid sizes and absence of typical Mario elements as a negative.

Although the game sold well in Japan, it sold poorly in English-speaking regions. As a result of this, the game was followed by two sequels, Mario''s Super Picross and Picross 2, released only in Japan. The next game in the Picross franchise published by Nintendo to be released in English-speaking regions would be Picross DS in 2007, twelve years later. Due to its limited sales, the game is somewhat of a cult classic. The game was also available on the Nintendo 3DS through its Virtual Console service. The game was also later added to the Nintendo Classics service on March 7, 2025.', 'https://en.wikipedia.org/wiki/Mario%27s_Picross'),
  ('Q7426390', 'Satoru Nakajima F-1 Hero GB World Championship ''91 is a 1991 Japan-exclusive Game Boy Formula One video game published by Varie, endorsed by Satoru Nakajima, who was the first full-time Japanese racer in the history of Formula One. Apart from Nakajima, the actual names of the drivers are not used due to licensing arrangements.

There are sixteen rounds and eight difficulty levels. Each level has a special rival to beat. The game structure has few similarities with F-1 Race (Game Boy).', 'https://en.wikipedia.org/wiki/Nakajima_Satoru_F-1_Hero_GB_World_Championship_%2791'),
  ('Q1988120', 'Pokémon Red Version and Pokémon Blue Version are 1996 role-playing video games (RPGs) developed by Game Freak and published by Nintendo for the Game Boy. They are the first installments of the Pokémon video game series and were first released in Japan as Pocket Monsters Red and Pocket Monsters Green, followed by the special edition Pocket Monsters Blue later that year. The games were released internationally in 1998 and 1999 as Pokémon Red and Pokémon Blue, while an enhanced version, Pokémon Yellow Version: Special Pikachu Edition, was released in Japan in 1998 and in other regions in 1999 and 2000.', 'https://en.wikipedia.org/wiki/Pok%C3%A9mon_Red,_Blue,_and_Yellow'),
  ('Q2008875', 'TwinBee is a video game series composed primarily of cartoon-themed vertically scrolling shooter games produced by Konami that were released primarily in Japan. The series originated as an arcade video game simply titled TwinBee in 1985, followed by several home versions and sequels. The character designs of almost every game in the series since Detana!! TwinBee in 1991 were provided by Japanese animator Shuzilow HA (Jujiro Hamakawa), who also planned and supervised most of the subsequent installments in the TwinBee series. The series also inspired a radio drama adaptation that lasted three seasons in Japan, as well as an anime adaptation.', 'https://en.wikipedia.org/wiki/TwinBee_(series)'),
  ('Q7265384', 'QBillion is a puzzle video game for the Nintendo Game Boy. It was released by SETA Corporation in 1990.

In QBillion, you control a mouse that, for reasons that are left unclear, has to reduce stacks of blocks to units one block high. This is represented by a grid in which several squares have numbers, representing how many blocks are there. The player can move a single block around, or push a block down off a stack. However, to push a block the player must be standing on a block one level lower than the block - i.e. to push a block off the top of a three-block stack, the player must be standing on a two-block stack.', 'https://en.wikipedia.org/wiki/QBillion'),
  ('Q1929662', 'Turrican is a 1990 run and gun video game developed by Factor 5 and published by Rainbow Arts. Designed by Manfred Trenz, it was released for the Commodore 64, and was ported to other systems later. In addition to concept design and character creation, Trenz programmed Turrican on the Commodore 64. A sequel, Turrican II: The Final Fight, followed in 1991 for the Commodore 64 and other platforms.', 'https://en.wikipedia.org/wiki/Turrican'),
  ('Q7360136', 'Rolan''s Curse, known in Japan as Velious Roland no Majuu is an action adventure video game developed by NMK and published by Sammy for the Game Boy in 1990. Sammy released a follow-up to Rolan''s Curse for the Game Boy in 1992, entitled Rolan''s Curse II.', 'https://en.wikipedia.org/wiki/Rolan%27s_Curse'),
  ('Q7229280', 'Popeye is a Japan-exclusive Game Boy video game based on the comic strip of same name licensed from King Features Syndicate.

A cancelled US version was found in the 2020 Nintendo data leak, intended to be published by INTV Corporation.', 'https://en.wikipedia.org/wiki/Popeye_(1990_video_game)'),
  ('Q1937488', 'Double Dragon 3: The Rosetta Stone is a 1990 beat ''em up video game developed by East Technology and published by Technōs Japan for arcades. It is the third arcade game in the Double Dragon series and the first to not be developed by Technōs Japan.

As in the previous games of the series, players control twin martial artists Billy and Jimmy Lee, as they are approached by a mysterious fortune teller named Hiruko, who sends them on a worldwide journey to retrieve three mystical Rosetta Stones and uncover the mystery surrounding them in Egypt. Similar to The Combatribes, which ran on similar hardware, the game can be set for up to two or three players depending on the cabinet, with the third player controlling a new Lee sibling named Sonny. The U.S. version also features item shops where players could use additional credits to purchase in-game items such as weapons, additional moves and new playable characters in one of the earliest forms of microtransactions in a video game, although this system would end up being removed in the later-released Japanese version of the game in favor of a conventional character select feature similar to Golden Axe or Final Fight.', 'https://en.wikipedia.org/wiki/Double_Dragon_3:_The_Rosetta_Stone'),
  ('Q1527974', 'Bomberman GB 3 is the third and last game in the Bomberman GB series, developed and published by Hudson Soft. The game was released only in Japan on December 20, 1996.', 'https://en.wikipedia.org/wiki/Bomberman_GB_3'),
  ('Q7455087', 'Serpent is a snake video game developed by Dual and published by Naxat Soft in Japan and by Taxan in North America for the Game Boy. It was released in 1990 in North America and Japan.', 'https://en.wikipedia.org/wiki/Serpent_(video_game)'),
  ('Q1409043', 'Final Fantasy Legend III, known in Japan as SaGa 3: Jikuu no Hasha, is a role-playing video game developed and published by Square for the Game Boy. The third entry in the SaGa series, it was released in Japan in 1991 and in North America in 1993. A remake for the Nintendo DS was released in 2011 by Square Enix, remaining exclusive to Japan. The Game Boy version was later ported to the Nintendo Switch and released worldwide by Square Enix in 2020, with later ports to Android, iOS and Microsoft Windows in 2021.

The game''s narrative follows a group of warriors as they fight a god-like being in the past, present, and future. During gameplay, players explore the different time periods, fighting in turn-based battles and raising character power through a combination of experience points, skill leveling, and material-based character classes.', 'https://en.wikipedia.org/wiki/Final_Fantasy_Legend_III'),
  ('Q1835245', 'Bomberman GB 2 is the second game in the Bomberman GB series, developed and published by Hudson Soft in Japan, published by Nintendo in North America and by Virgin Interactive Entertainment in Europe.', 'https://en.wikipedia.org/wiki/Bomberman_GB_2'),
  ('Q7283083', 'Raging Fighter is a 1993 fighting video game developed and published by Konami for the Nintendo Game Boy. It was first released in Japan on March 26, 1993, and later released in North America and Europe in June 1993.', 'https://en.wikipedia.org/wiki/Raging_Fighter'),
  ('Q7278898', 'Race Days is a 1994 racing video game for the Game Boy. It is a compilation of Dirty Racing (Japan-exclusive) and Jeep Jamboree: Off Road Adventure (North America-exclusive) with a different name for the Jeep Jamboree game.', 'https://en.wikipedia.org/wiki/Race_Days'),
  ('Q7279677', 'Racing Damashii is a motorcycle racing video game from Irem for the Game Boy handheld and the PC Engine console, released in 1991 exclusively in Japan. The game features tracks all over Japan.', 'https://en.wikipedia.org/wiki/Racing_Damashii'),
  ('Q7360137', 'Rolan''s Curse II, known in Japan as Velious II: Fukushuu no Jashin is a video game developed by NMK and released for the Game Boy in 1992. It is the sequel to the original Rolan''s Curse.', 'https://en.wikipedia.org/wiki/Rolan%27s_Curse_II'),
  ('Q3281340', 'The Amazing Spider-Man is a platform action video game released for the Nintendo Game Boy in 1990, published by LJN and developed by Rare, based on the Marvel Comics superhero Spider-Man.', 'https://en.wikipedia.org/wiki/The_Amazing_Spider-Man_(handheld_video_game)'),
  ('Q2758069', 'Harvest Moon GB is the second game in the Story of Seasons series of video games, and was developed and published by Victor Interactive Software. Harvest Moon GB is the first portable Harvest Moon game, developed for the Game Boy. A Game Boy Color version was released later under the name Harvest Moon GBC. The Game Boy Color version was later released on the 3DS Virtual Console in 2013.', 'https://en.wikipedia.org/wiki/Harvest_Moon_GB'),
  ('Q735199', 'E-Motion (also known as Sphericule or The Game of Harmony) is a 1990 puzzle video game developed by The Assembly Line. It was available for Amiga, Amstrad CPC, Atari ST, Commodore 64, MS-DOS, ZX Spectrum, and Game Boy. The Spectrum and Game Boy versions were developed by The Code Monkeys.', 'https://en.wikipedia.org/wiki/E-Motion'),
  ('Q7111541', 'Fujisankei Communications International, Inc. (FCI) is the American arm of the Fujisankei Communications Group, a Japanese media conglomerate of television and radio channels, magazine, newspaper, record and video game companies. The Fujisankei Communications Group regroups more than 90 companies, like Fuji TV in Japan, among others. Founded in 1986 in New York City and owned by Fuji Media Holdings, FCI makes productions from the Fujisankei Communications Group available to the United States and the rest of the western world.

The company has always been based in Manhattan, but moved from its original offices at Pier 17 Pavilion to its current location on 52nd Street in 1988. FCI has contracts with television stations in New York City, Hawaii and California to air programming segments. FCI also has secondary offices in the United States and Europe.', 'https://en.wikipedia.org/wiki/Fujisankei_Communications_International'),
  ('Q3311823', 'Mickey''s Dangerous Chase, known in Japan as Mickey''s Chase, is a platform video game developed by Now Production for the Game Boy. It was released in North America in 1991 and Europe in 1992 by Capcom and Japan in December 1992 by Kemco; it was later re-released by Nintendo under the Player''s Choice brand, making it one of the first games to be sold under the brand.', 'https://en.wikipedia.org/wiki/Mickey%27s_Dangerous_Chase'),
  ('Q731612', 'Mega Man II is a 1991 platform game developed by Thinking Rabbit and published by Capcom for the Game Boy. It is the second handheld game in the original Mega Man franchise after Mega Man: Dr. Wily''s Revenge. The game follows Mega Man as he pursues his arch-enemy Dr. Wily, whose most recent ploy for world domination involves the theft of an experimental time machine. Mega Man confronts both Wily and a number of enemies from his past, including a new and mysterious robot named Quint. Just like other Game Boy games in the series, Mega Man II combines elements from two consecutive Nintendo Entertainment System (NES) titles, in this case, Mega Man 2 and Mega Man 3.', 'https://en.wikipedia.org/wiki/Mega_Man_II_(1991_video_game)'),
  ('Q650304', 'Ganbare Goemon: Sarawareta Ebisumaru! is a platform video game released by Konami for the Game Boy in 1991. The first game in the Ganbare Goemon series ever released for a portable system, it is the sixth mainline installment overall. Gameplay is similar to Ganbare Goemon! Karakuri Dōchū which was released on the Famicom. Only Goemon is playable, and the game consists of him rescuing Ebisumaru; Sasuke and Yae do not make appearances.', 'https://en.wikipedia.org/wiki/Ganbare_Goemon:_Sarawareta_Ebisumaru!'),
  ('Q2987019', 'Mega Man: Dr. Wily''s Revenge, also known as Mega Man in Dr. Wily''s Revenge or in Japan as Rockman World is a platform game developed by Minakuchi Engineering and published by Capcom for the Game Boy. It is the first game in the handheld series of the Mega Man franchise. It was released in Japan on July 26, 1991, and was localized in North America that December and in Europe the following year. The game continues the adventures of the android hero Mega Man as he once again confronts the evil Dr. Wily, who has dispatched his revived "Robot Masters" and a new "Mega Man Killer" named Enker.

Dr. Wily''s Revenge is an action and platform game in the same vein as the Nintendo Entertainment System (NES) Mega Man games. The player is tasked with completing a series of four stages in any order desired. Beating a stage''s boss will earn the player a special weapon that can be selected at will and used throughout the rest of the game. Dr. Wily''s Revenge specifically takes components of the original Mega Man and Mega Man 2, including their enemies, stage aesthetics, and Robot Masters.', 'https://en.wikipedia.org/wiki/Mega_Man:_Dr._Wily%27s_Revenge'),
  ('Q7038893', 'Ninja Boy 2 is an action role-playing game for the Game Boy released in 1991. In the game, the ninja Jack and Ryu find that aliens from outerspace have kidnapped all the dignitaries, which lead two the two take them on by creating a spaceship to chase after them.

Ninja Boy 2 was developed and published by Culture Brain. Unlike the previous Ninja Boy (1990) video game, Ninja Boy 2 is an action role-playing video game with battles being done in a beat ''em up style.

The game as first released in Japan on November 29, 1991, and released in the United States in April 1993. The game received poor reviews in Famitsu and GB Action who found its graphics weak.', 'https://en.wikipedia.org/wiki/Ninja_Boy_2'),
  ('Q3280849', 'WWF Superstars is a wrestling video game for the Game Boy handheld console developed by Rare and published by LJN, based on the WWF''s syndicated television show of the same name. This game was the first WWF game for the Game Boy system.

The game was succeeded by WWF Superstars 2, which was released in 1992 by LJN. A unique engine was built from the ground up; the developers never attempted to emulate the gaming engine found in the more advanced WWF games.', 'https://en.wikipedia.org/wiki/WWF_Superstars_(handheld_video_game)'),
  ('Q656503', 'The Rescue of Princess Blobette / Fushigi na Blobby: Princess Blob o Sukue! is a video game for the Game Boy and the sequel to the Nintendo Entertainment System (NES) game A Boy and His Blob: Trouble on Blobolonia. It was published in North America by Imagineering''s parent company Absolute Entertainment and in Japan by Jaleco. It was published by Nintendo in Europe.

The Rescue of Princess Blobette follows the two protagonists as they attempt to rescue Princess Blobette from her imprisonment from a castle tower. The game features the same puzzle-platforming gameplay mechanics as Trouble on Blobolonia. Controlling the boy, the player must feed the blob different flavored jelly beans to transform it into different tools to traverse the castle.', 'https://en.wikipedia.org/wiki/The_Rescue_of_Princess_Blobette'),
  ('Q7038949', 'Ninja Taro, released in Japan as Sengoku Ninja-kun, is an action-adventure video game for the Game Boy by NMK. It was released in 1991 in both Japan by UPL and North America by American Sammy and is part of the Ninja-kun series.', 'https://en.wikipedia.org/wiki/Ninja_Taro'),
  ('Q4869994', 'Battle Bull is a top-down action video game for the original Game Boy; released in 1990 in Japan and 1991 in North America.', 'https://en.wikipedia.org/wiki/Battle_Bull'),
  ('Q4870082', 'BATTLE PINGPONG is a Japanese table tennis video game developed and published by Quest for the Game Boy exclusively in Japan. It was released in Japan on August 31, 1990 and never saw a release in another territory, although the game was going to be published by Sammy in America. The game allows the player to either compete in a tournament or vs. mode against 8 nations.', 'https://en.wikipedia.org/wiki/Battle_Pingpong'),
  ('Q738698', 'Bomb Jack is a 1984 platform video game developed and published by Tehkan for arcades. It was released by Kitkorp in North America as its first arcade game. It was later ported to home systems and home computers. A commercial success, it was followed by several sequels: the console and computer game Mighty Bomb Jack, the arcade game Bomb Jack Twin, and Bomb Jack II, the last of which was licensed for home computers only.', 'https://en.wikipedia.org/wiki/Bomb_Jack'),
  ('Q4807434', 'Asmik-kun World 2 is a 1991 puzzle video game developed by Cyclone System and published by Asmik for the Game Boy. Unlike its predecessor, Boomer''s Adventure in ASMIK World (Teke! Teke! Asmik-kun World), this game was never released outside Japan. Like its predecessor, the game is an example of the trap-em-up genre, which also includes games like Heiankyo Alien and Space Panic.

In the game, Asmik-kun has to build a "road" from the entrance to the exit in each level. An enemy has come to kidnap the children on a certain world and the "roads" are intended for the children to be rescued and escorted safely back home.', 'https://en.wikipedia.org/wiki/Asmik-kun_World_2'),
  ('Q4880211', 'Three video games based on the 1988 American film Beetlejuice (as well its animated TV adaptation) were released in 1990, 1991, and 1992. In addition, a Beetlejuice expansion pack featuring maps, playable characters and missions was released in 2017 as part of the Lego Dimensions crossover video game "fun packs" line.', 'https://en.wikipedia.org/wiki/List_of_Beetlejuice_video_games'),
  ('Q860323', 'Jankenman is a children''s anime series that ran from April 4, 1991, to March 26, 1992. 51 episodes have been aired. The anime series uses the well-known game of Rock paper scissors as its theme. The concept of planning and production was "an anime series that mothers and children can watch with peace of mind".', 'https://en.wikipedia.org/wiki/Jankenman'),
  ('Q4811515', 'Astro Rabby is a 1990 action video game published by Information Global Service (IGS) for the original Game Boy exclusively in Japan on October 12, 1990. It is the first Game Boy title to be published by that company.', 'https://en.wikipedia.org/wiki/Astro_Rabby'),
  ('Q2913436', 'Battle Unit Zeoth is a scrolling shooter video game developed by Jaleco for the Nintendo Game Boy in 1990 which saw a release in North America and Europe one year later in 1991.', 'https://en.wikipedia.org/wiki/Battle_Unit_Zeoth'),
  ('Q4740815', 'Amazing Penguin, known in Japan as Osawagase! Penguin Boy, is a 1990 action game developed by Natsume Co., Ltd. for the Game Boy. The game sees the player controlling a penguin as they attempt to clear a set number of lines using switches and dots scattered through stages to do so.', 'https://en.wikipedia.org/wiki/Amazing_Penguin'),
  ('Q2947434', 'Maru''s Mission is a 1990 platform video game developed by Tose and published by Jaleco for the Game Boy. It was released in Japan as I''m Jajamaru! World Adventure on September 28, 1990. The game was released to the Japanese 3DS Virtual Console in January 2012 and later in North America in February.

It is the first game from the Jajamaru series, aside from the loosely related Ninja Taro, to be released in North America, until the release of Ninja JaJaMaru-kun through the Virtual Console. The soundtrack, as well as many sprites and some cut-scenes of the North American version are different from the original Japanese.', 'https://en.wikipedia.org/wiki/Maru%27s_Mission'),
  ('Q2733190', 'Donkey Kong Land 2 is a 1996 platform video game developed by Rare and published by Nintendo for the Game Boy. Part of the Donkey Kong video game series, it is the sequel to Donkey Kong Land. It was enhanced for the Super Game Boy with different shades of color, as well as a 16-bit banana border on the edges of the television screen. Like the original Donkey Kong Land, it came packaged in a banana-yellow cartridge. The game was followed by Donkey Kong Land III, which was released in 1997.

The game has since been re-released via the Nintendo 3DS'' Virtual Console and the Nintendo Classics service.', 'https://en.wikipedia.org/wiki/Donkey_Kong_Land_2'),
  ('Q3235095', 'The Rugrats Movie is a 1998 platform video game developed by Software Creations and published by THQ. It was released for Game Boy on November 24, 1998, and for Game Boy Color on April 1, 1999 in Europe and April 12, 1999 in North America. It is based on the movie of the same name and the 1991 TV series. Both versions of the game were re-released in 2026 as part of the Rugrats: Retro Rewind Collection compilation.', 'https://en.wikipedia.org/wiki/The_Rugrats_Movie_(video_game)'),
  ('Q7130811', 'Panel Action Bingo is a Game Boy action/adventure video game developed by Japanese studio Locus where the player controls a bird. It was released in November 1993 to an exclusively North American market.', 'https://en.wikipedia.org/wiki/Panel_Action_Bingo'),
  ('Q3321552', 'Monster Max is a 1994 action-adventure puzzle video game developed by Rare and published by Titus France in Europe for the Game Boy. The player is the titular aspiring rock star, who, in an attempt to fight King Krond who bans all music, traverses nine floors of the Mega Hero Academy. Floors consist of diversely-designed rooms of puzzles to solve, the player having to figure out the order of actions to take.

The game was specifically developed by a three-member team, which consisted of Jon Ritman for programming and design, Bernie Drummond for graphics, and David Wise for music. Ritman and Drummond, before joining Rare, developed isometric games for Ocean Software, including Batman (1986) and Head over Heels (1987). As a result of the failure of an arcade football game to be completed for the company, Ritman and Drummond did not have any publicity with their work for seven years. Ritman decided to work on an isometric Game Boy title with a £1,200 Global Language Assembler Monitor software development kit he created by himself, noticing the handheld console''s absence of the genre.', 'https://en.wikipedia.org/wiki/Monster_Max'),
  ('Q3011788', 'Daedalian Opus is a puzzle video game for the Game Boy that was released in 1990. It was developed and published by Vic Tokai.', 'https://en.wikipedia.org/wiki/Daedalian_Opus'),
  ('Q3285664', 'WWF Superstars 2 is a video game based on the World Wrestling Federation (WWF), released in 1992 for the Game Boy by Acclaim Entertainment. It is the sequel to WWF Superstars and the second WWF game for the Game Boy system. The game is similar to WWF WrestleMania: Steel Cage Challenge for the Nintendo Entertainment System, although it runs much faster.

The game features six wrestlers: Hulk Hogan, "Macho Man" Randy Savage, The Undertaker, Sid Justice, Jake "The Snake" Roberts, and The Mountie.', 'https://en.wikipedia.org/wiki/WWF_Superstars_2'),
  ('Q3304395', 'Atomic Punk is a maze video game developed and published by Hudson Soft for the Game Boy. Part of the Bomberman series, it was first released in Japan on August 31, 1990. It was later published in North America in October 1991 and Europe in 1991.

There are three game modes in Atomic Punk, all of which share a top-down perspective and the gameplay utilizing bombs to demolish obstacles and defeat opponents. The first one is a single-player campaign where the player controls the titular character, embarking on an adventure across eight levels filled with environmental hazards while getting equipped with power-ups to upgrade his abilities. The second is a port of Bomberman (1985) on the Nintendo Entertainment System. The third is a multiplayer battle mode that requires the Game Link Cable accessory, pitting two players against each other.', 'https://en.wikipedia.org/wiki/Atomic_Punk'),
  ('Q7198990', 'Catrap, known as Pitman in Japan and Power Paws in the United Kingdom, is a 1985 puzzle-platform game developed by Yutaka Isokawa for the Sharp MZ-700 computer. A port to the Game Boy developed by ASK Kodansha was released in Japan in June 1990 and North America in October 1990 by Asmik. ASK retained the rights to the game after splitting from Kodansha, re-releasing the game on the Nintendo 3DS Virtual Console in October 2011.

The word Catrap refers to the frequent number of times the player is trapped and needs to reverse their movements and the two anthropomorphic cats the player must maneuver to advance through the levels.', 'https://en.wikipedia.org/wiki/Catrap'),
  ('Q19598913', 'Battletoads is a 1991 action game originally released by Rare in 1991 exclusively for the Nintendo Game Boy. Despite having the same title as the original Battletoads game, Battletoads for Game Boy is a completely different game with unique levels. It was never ported to any other systems. A more faithful port of the NES game for the Game Boy was released later, in 1993 as Battletoads in Ragnarok''s World.', 'https://en.wikipedia.org/wiki/Battletoads_(Game_Boy_video_game)'),
  ('Q7705666', 'Tesserae is a single-player video game developed by Nicholas Schlott based on Kent Brewster''s DOS game Stained Glass and published by Inline Design in 1990 for the Macintosh. The game was also released for the Game Boy and Game Gear handhelds published by GameTek, developed by Eurocom.', 'https://en.wikipedia.org/wiki/Tesserae_(video_game)'),
  ('Q7548011', 'Snoopy''s Magic Show, is a 1990 action puzzle video game, developed and published by Kemco for the Game Boy. The game stars Snoopy, who is tasked with saving four Woodstocks in a set time limit, solving puzzles and dodging enemies to do so.', 'https://en.wikipedia.org/wiki/Snoopy%27s_Magic_Show'),
  ('Q5299747', 'Double Dragon II is a 1990 beat ''em up video game developed by Technōs Japan for the Game Boy. Although it is the second Double Dragon game released for the Game Boy, it is unrelated to the arcade and NES game Double Dragon II: The Revenge. The game is a localization of the 1990 Japanese Game Boy game Nekketsu Kōha Kunio-kun: Bangai Rantō Hen, which was part of Technōs Japan''s Kunio-kun series. The graphics, music, and storyline were changed for the English version of the game. In Japan, it was re-released for the Nintendo 3DS Virtual Console on August 8, 2012.', 'https://en.wikipedia.org/wiki/Double_Dragon_II_(Game_Boy)'),
  ('Q16267513', 'Top Gun: Guts and Glory is a modern jet flight simulation that was released in 1993 for the original Nintendo Game Boy in Europe and North America.', 'https://en.wikipedia.org/wiki/Top_Gun:_Guts_and_Glory'),
  ('Q5304099', 'Dr. Franken is a platform game released in 1992 for the Game Boy and in 1993 for the Super Nintendo Entertainment System by Elite Systems. It was titled The Adventures of Dr. Franken for the SNES in the United States. The game features Franky, a Frankenstein''s monster on a mission to collect the scattered body parts of his girlfriend, Bitsy.

A Mega Drive version was planned but never released. Versions for the Nintendo Entertainment System and Game Gear reached prototype stage, but were also not released. A Game Boy sequel, Dr. Franken II, was published in 1993.', 'https://en.wikipedia.org/wiki/Dr._Franken'),
  ('Q5872800', 'GB Genjin Land: Viva! Chikkun Kingdom is an action video game that was released by Hudson Soft for Game Boy on April 22, 1994 in Japan. It is a unique entry in the Bonk series as it consists of multiple mini-games rather than being a standard side-scrolling platformer.', 'https://en.wikipedia.org/wiki/GB_Genjin_Land:_Viva!_Chikkun_%C5%8Ckoku'),
  ('Q5574532', 'Go! Go! Tank is an action-oriented strategy video game released in 1990.', 'https://en.wikipedia.org/wiki/Go!_Go!_Tank'),
  ('Q7534117', 'Skate or Die: Tour de Thrash is a 1991 skateboarding video game for the Game Boy that was released only in North America. It was sponsored by Santa Cruz Skateboards.', 'https://en.wikipedia.org/wiki/Skate_or_Die:_Tour_de_Thrash'),
  ('Q7558528', 'Solomon''s Key is a 1986 puzzle video game developed and published by Tecmo for arcades. It was ported to multiple systems, including the Nintendo Entertainment System and Commodore 64. The PC Engine version was known as Zipang and the Game Boy version as Solomon''s Club. A prequel, Solomon''s Key 2, was released in 1992 for the NES. The NES version of the game was also released in emulated form on Virtual Console for the Wii in 2006, Nintendo 3DS and Wii U in 2013 and later to the Nintendo Classics service in 2018.', 'https://en.wikipedia.org/wiki/Solomon%27s_Key'),
  ('Q11443252', 'Mercenary Force is a 1990 shoot ''em up video game developed for the Game Boy. The video game is set in the Shogunate-era of Japan where the player must choose five of six possible mercenaries with different abilities and skills for each level.

On its release in 1990, some reviewers complimented the game''s unique setup of choosing characters with different skills in a shooter game; others found it ultimately did not change a game that was very difficult.', 'https://en.wikipedia.org/wiki/Mercenary_Force'),
  ('Q7581468', 'Spud''s Adventure is an adventure video game with role-playing video game elements published by Atlus in 1991. This game stars a cast of mostly vegetables; Spud, a cap-wearing potato, is the hero and must save Princess Mato from the evil clutches of Devi.

Spud''s Adventure is one of the rarest Game Boy games.', 'https://en.wikipedia.org/wiki/Spud%27s_Adventure'),
  ('Q10328213', 'Mega Man V is a video game developed by Minakuchi Engineering and published by Capcom for the Game Boy. It is the fifth game in the handheld series of the Mega Man franchise. The game follows the adventures of the protagonist Mega Man as he must defend the Earth from a group of powerful robots from outer space called the Stardroids. Mega Man V is unique among the Game Boy Mega Man games as it features original bosses rather than recycling those from the Nintendo Entertainment System (NES) Mega Man games.

Mega Man V is an action platformer in which the player selects stages in a non-linear fashion and acquires the weapon of each boss defeated to use as their own. Although it plays nearly identical to other games in the series, Mega Man V features a new default weapon (the powerful "Mega Arm") and introduces Tango, a new assistant character. Mega Man V received a positive critical reception, with critics considering it to be one of the best games in the series and praising its relative ambition with its original content, but it also received criticism for the lack of innovation in the series'' core gameplay.', 'https://en.wikipedia.org/wiki/Mega_Man_V_(1994_video_game)'),
  ('Q554247', 'Ayakashi no Shiro is a 1990 role-playing video game for the Game Boy manufactured by SETA Corporation. It was never published outside Japan.', 'https://en.wikipedia.org/wiki/Ayakashi_no_Shiro'),
  ('Q1053648', 'Centipede is a 1981 fixed shooter video game developed and published by Atari, Inc. for arcades. Designed by Dona Bailey and Ed Logg, it was one of the most commercially successful games from the golden age of arcade video games, and one of the first widely played by women and girls. The primary objective is to shoot all the segments of a centipede that winds down the playing field.

Centipede was ported to Atari''s own 2600, 5200, 7800, and 8-bit computers. Under the Atarisoft label, the game was sold for the Apple II, Commodore 64, ColecoVision, VIC-20, IBM PC (as a self-booting disk), Intellivision, and TI-99/4A. Superior Software published the port for the BBC Micro. Versions for the Game Boy and Game Boy Color were also produced, as well as a version for the short-lived Game.com. Other developers released more than 25 Centipede clones for home computers. It was followed by the arcade sequel Millipede in 1982. In 1998, a 3D remake for Windows, Mac, PlayStation, and Dreamcast was published by Hasbro Interactive.', 'https://en.wikipedia.org/wiki/Centipede_(video_game)'),
  ('Q1343411', 'Teenage Mutant Ninja Turtles: Fall of the Foot Clan is a 1990 action-platform game developed and published by Konami for the Game Boy. The game is based on the 1987 Teenage Mutant Ninja Turtles television series. The Turtles'' first Game Boy game is a platforming-style game, where Leonardo, Michelangelo, Donatello, and Raphael must battle against Krang and Shredder and save their friend April O''Neil in the process. The game was re-released as part of Teenage Mutant Ninja Turtles: The Cowabunga Collection in 2022.', 'https://en.wikipedia.org/wiki/Teenage_Mutant_Ninja_Turtles:_Fall_of_the_Foot_Clan'),
  ('Q596392', 'Super Mario Land 2: 6 Golden Coins is a 1992 platform game developed and published by Nintendo for the Game Boy. It is the sequel to Super Mario Land. In Super Mario Land 2, the player assumes the role of the protagonist Mario, whose main objective is to reclaim his personal island, Mario Land, from the clutches of his greedy rival Wario. The gameplay builds and expands on that of its precursor with innovations carried over from Super Mario World and Super Mario Bros. 3.

Super Mario Land 2 received critical acclaim upon release and sold over 11 million copies, becoming one of the most successful and highest-rated titles on the Game Boy. Reviewers emphasized that the game surpassed its predecessor in all aspects. Super Mario Land 2 marks the debut appearance of Wario, who would become a prominent character in the Super Mario series as the antihero of several games, the first being this game''s sequel Wario Land: Super Mario Land 3. Super Mario Land 2 was re-released in 2011 as a downloadable title for the Nintendo 3DS, and the Nintendo Switch in 2023, as part of the Nintendo Classics service.', 'https://en.wikipedia.org/wiki/Super_Mario_Land_2:_6_Golden_Coins'),
  ('Q8047229', 'Yakuman is a 1989 Japanese mahjong game developed by Intelligent Systems and published by Nintendo as a launch title for the Game Boy, exclusive to Japan. One of the first four games released for the system, it was also the first to utilize the Game Link Cable for multiplayer functionality.', 'https://en.wikipedia.org/wiki/Yakuman_(video_game)'),
  ('Q7687006', 'Tarzan: Lord of the Jungle is a 1994 video game for the Game Boy and Game Gear video game systems.', 'https://en.wikipedia.org/wiki/Tarzan:_Lord_of_the_Jungle'),
  ('Q605032', 'Mega Man IV is a 1993 platform game developed by Minakuchi Engineering and published by Capcom for the Game Boy. It is the fourth game in the handheld series of the Mega Man franchise. The game continues the quest of the protagonist Mega Man in the struggle with his long-time nemesis Dr. Wily, who sends out a disruptive radio signal to cause a rampage, citywide destruction from dormant robots.

Mega Man IV features the traditional action platforming gameplay of the prior games while introducing one new feature, the ability to purchase items with power-ups found throughout each stage. As with previous Game Boy releases, the game incorporates gameplay elements and bosses from two sequential Nintendo Entertainment System (NES) games: Mega Man 4 and Mega Man 5. The game received positive reviews from critics, with significant praise for its improvements from its predecessors, though its low level of innovation was criticized.', 'https://en.wikipedia.org/wiki/Mega_Man_IV_(1993_video_game)'),
  ('Q5957619', 'Hyper Lode Runner is a video game for the Game Boy from Bandai released in 1989 in Japan and 1990 in North America. It is based on the 1983 game Lode Runner from Broderbund. While each level in the original fit on a single screen, Hyper Lode Runner has a scrolling playfield.', 'https://en.wikipedia.org/wiki/Hyper_Lode_Runner'),
  ('Q1408991', 'Final Fantasy Legend II, known in Japan as SaGa 2: Hihou Densetsu, is a role-playing video game developed and published by Square for the Game Boy. The second entry in the SaGa series, it was released in 1990 in Japan, and in 1991 in North America. A remake for the Nintendo DS was released in 2009 by Square Enix, remaining exclusive to Japan. The Game Boy version was later ported to the Nintendo Switch and released worldwide by Square Enix in 2020, with later ports to Android, iOS and Microsoft Windows in 2021.

The game''s narrative follows the protagonist as they search for their father, who left them one of the seventy-seven magical MAGI stones, going on to explore the worlds connected by the Pillar of Sky. During gameplay, players explore and fight in turn-based battles, with character attributes randomly increased upon victory. The DS remake uses a system of ability and statistical increases based on battle actions, and incorporates a multiplayer boss arena.', 'https://en.wikipedia.org/wiki/Final_Fantasy_Legend_II'),
  ('Q5454512', 'Towa Chiki Corporation was a Japanese toy company responsible for many Famicom games in the late 1980s and 1990s.', 'https://en.wikipedia.org/wiki/Towa_Chiki'),
  ('Q499021', 'Miner 2049er is a platform game developed by Big Five Software and published in December 1982 for the Atari 8-bit computers. The player controls Mountie Bounty Bob through multiple levels of a mine, with the goal of traversing all of the platforms in each level all while avoiding enemies and within a set amount of time. Miner 2049er was widely ported, being released on a total of 22 different systems. Video magazine''s editors commented on the game''s popularity in January 1984, declaring it "the most widely played home electronic game of all time" and that "no home-arcade title has had the impact" that Miner 2049er had.', 'https://en.wikipedia.org/wiki/Miner_2049er'),
  ('Q7767760', 'The Sword of Hope II, known in Japan as Selection II: Ankoku no Fuuin, is a 1992 role-playing video game developed and published by Kemco for the Game Boy. It is the sequel to the 1989 The Sword of Hope. A "dungeon crawler"-type game, the player must retrieve the Sword of Hope, which has been stolen, and find the evil Zakdos who has been set free after being imprisoned.

In 1998, both Sword of Hope games were rereleased in Japan as a single Game Boy cartridge, Selection I & II. The Sword of Hope II was released for the 3DS Virtual Console in 2012, and the Nintendo Classics service in 2026.', 'https://en.wikipedia.org/wiki/The_Sword_of_Hope_II'),
  ('Q7676056', 'Tail ''Gator, known in Japan as Shippo de Bun!, is a Game Boy video game released in 1991. In the game, the player plays a small alligator known as ''Charly'' who whips his tail forward to attack.', 'https://en.wikipedia.org/wiki/Tail_%27Gator'),
  ('Q5599268', 'Great Greed is a 1992 role-playing video game developed and published by Namco for the Game Boy. The player controls Sierra Sam who is warped from his own world to the Greene Kingdom, where he attempts to stop Biohaz from causing havoc.

As a role-playing game (RPG), the player does various tasks such as wandering a world map, battling monsters and exploring towns. Battles in the game are fought in real-time, with magic spells being set to each direction of the d-pad, and attacking and dodging options being used by the other Game Boy buttons. It was released in Japan in 1992 and in 1993 in the United States, being one of the few RPGs Namco would publish in the United States until the genres popularity grew later in the decade.', 'https://en.wikipedia.org/wiki/Great_Greed'),
  ('Q7855740', 'Turn and Burn: The F-14 Dogfight Simulator is a flight simulation video game developed by Imagineering Inc. and released in 1992 for the Game Boy in Europe and North America. In Europe, the game was released as the Game Boy adaptation of Phantom Air Mission, the European version of Imagineering''s previous flight simulator Flight of the Intruder. A sequel, Turn and Burn: No-Fly Zone, was later released for the Super NES.', 'https://en.wikipedia.org/wiki/Turn_and_Burn:_The_F-14_Dogfight_Simulator'),
  ('Q7883516', 'Undercover Cops: Hakaishin Garumaa, sometimes referred to with or without subtitle as Undercover Cops Gaiden, is a 1993 turn-based traditional game developed and published by Irem exclusively in Japan for the Nintendo Game Boy on December 10, 1993. It is a spin-off of Irem''s 1992 beat ''em up arcade game simply titled Undercover Cops. It is also the second-to-last game Irem released for the Game Boy, with Daiku no Gen-san - Robot Teikoku no Yabō being the last.', 'https://en.wikipedia.org/wiki/Undercover_Cops:_Hakaishin_Garumaa'),
  ('Q5519823', 'Game Boy Wars is a 1991 turn-based strategy video game developed by Nintendo and Intelligent Systems and published by Nintendo for the Game Boy. Released only in Japan, it is a portable follow-up to the 1988 Family Computer war game Famicom Wars, making it the second game in Nintendo''s Wars series. A series of sequels to the original Game Boy Wars were developed and released by Hudson Soft.', 'https://en.wikipedia.org/wiki/Game_Boy_Wars'),
  ('Q7831483', 'Track Meet, known in Japan as Track Meet: Mezase! Barcelona, is a sports video game that was released for the original Game Boy. In Germany the game was released as Litti''s Summer Sports (endorsed by Pierre Littbarski).', 'https://en.wikipedia.org/wiki/Track_Meet'),
  ('Q5268471', 'Dexterity, known as Funny Field in Japan, is a puzzle video game released by SNK for the Game Boy in 1990. The game consists of a square-shaped floor covered in seven rows and eight columns of tiles (56 tiles in total). The goal of the game is to flip all of the light tiles into dark tiles. There are several enemies as the level advances. The game has a total of 30 rounds.', 'https://en.wikipedia.org/wiki/Dexterity_(video_game)'),
  ('Q7642440', 'Super Hunchback, known in France as Le Bossu: Super Hunchback Quasimodo, is platform video game released for the Game Boy in 1992 by Ocean Software in North America and Europe and Imagineer in Japan. It is a sequel to their 1984 conversion of the 1983 Century Electronics arcade game Hunchback. The title screen bears a 1991 copyright, the cartridge label records the year as 1992.

On June 2, 2021, the game was released on Windows PCs via Steam by Piko Interactive.', 'https://en.wikipedia.org/wiki/Super_Hunchback'),
  ('Q16267429', 'Athena Co. Ltd. was a Japanese video game developer, founded in July 1987.', 'https://en.wikipedia.org/wiki/Athena_(game_developer)'),
  ('Q5215786', 'Ultra Golf, known in Europe as Konami Golf and in Japan as Konamic Golf, is a golf video game developed by Konami for the Game Boy system. It was released by Konami on November 1, 1991 in Japan, later being released in North America in March 1992, and in the PAL region in 1994.', 'https://en.wikipedia.org/wiki/Ultra_Golf'),
  ('Q5245215', 'Dead Heat Scramble is a 1990 arcade racing game developed by Copya System and published by Electro Brain in North America and Copya System in Japan for the Game Boy.', 'https://en.wikipedia.org/wiki/Dead_Heat_Scramble'),
  ('Q7580026', 'Spot: The Cool Adventure is a 1992 platform game developed by Visual Concepts and published by Virgin Games for the Game Boy. It is a port of the NES game, M.C. Kids. The Game Boy version was released outside of Europe and was localized with the 7 Up mascot Spot as Spot: The Cool Adventure.

The game structure is based on M.C. Kids, although the map screen closely resembles Super Mario Bros. 3. Getting hit causes players to lose health. In addition to avoiding enemies, Spot can jump or collect blocks to help him reach hearts in other locations.', 'https://en.wikipedia.org/wiki/Spot:_The_Cool_Adventure'),
  ('Q5304097', 'Dr. Franken is a platform game released in 1992 for the Game Boy and in 1993 for the Super Nintendo Entertainment System by Elite Systems. It was titled The Adventures of Dr. Franken for the SNES in the United States. The game features Franky, a Frankenstein''s monster on a mission to collect the scattered body parts of his girlfriend, Bitsy.

A Mega Drive version was planned but never released. Versions for the Nintendo Entertainment System and Game Gear reached prototype stage, but were also not released. A Game Boy sequel, Dr. Franken II, was published in 1993.', 'https://en.wikipedia.org/wiki/Dr._Franken'),
  ('Q973660', 'The Real Ghostbusters, known in Europe as Garfield Labyrinth and in Japan as Mickey Mouse IV: Mahō no Labyrinth, is a 1993 action-puzzle video game developed by Kemco and published in Japan and Europe by Kemco and in North America by Activision.

The Japanese version is based on Mickey Mouse and is part of the Mickey Mouse side of Kemco''s Crazy Castle series, while the European version is based on Jim Davis''s Garfield comic strips and the animated series Garfield and Friends. The North American version is based on the animated series The Real Ghostbusters and contains ten more stages than the previous incarnations.', 'https://en.wikipedia.org/wiki/The_Real_Ghostbusters_(1993_video_game)'),
  ('Q7712362', 'The Addams Family is a 1992 action-adventure platform game based on the 1991 film of the same name. Developed and published by Ocean Software, it was released for home consoles such as the Super Nintendo Entertainment System, computers such as the Amiga, and handheld consoles such as the Game Boy.

The player assumes the role of Gomez Addams. His mission is to rescue other members of the Addams family from the clutches of Abigail Craven, who, alongside The Judge and the family attorney Tully Alford, is attempting to seize the Addams'' wealth. The game is non-linear, with the player moving throughout the mansion''s many inside and outside areas, some of which are hidden. Enemies include bosses each holding a member of the Addams Family hostage, making them necessary to defeat. Power-ups, extra lives, and money are also obtainable.', 'https://en.wikipedia.org/wiki/The_Addams_Family_(video_game)');

insert into import_summary (wikidata_id, summary, source) values
  ('Q7672313', 'TV Champion is a Game Boy game based on the game show of the same name, broadcast on TV Tokyo. It includes support for the Super Game Boy, and was released only in Japan.', 'https://en.wikipedia.org/wiki/TV_Champion_(video_game)'),
  ('Q5305280', 'Dragon Slayer is an action role-playing game developed by Nihon Falcom and designed by Yoshio Kiya. It was originally released in 1984 for the PC-8801, PC-9801, X1 and FM-7, and became a major success in Japan.

It was followed by an MSX port published by Square in 1985 (making it one of the first titles to be published by Square), a Super Cassette Vision by Epoch in 1986 and a Game Boy port by the same company in 1990. A version for PC-6001mkII was in development but was never released. A remake of Dragon Slayer is included in the Falcom Classics collection for the Sega Saturn.

Dragon Slayer began the Dragon Slayer series, a banner which encompasses a number of popular Falcom titles, such as Dragon Slayer II: Xanadu, Sorcerian, and Legacy of the Wizard. It also includes Dragon Slayer: The Legend of Heroes, which would later spawn over a dozen entries across multiple subseries.', 'https://en.wikipedia.org/wiki/Dragon_Slayer_(video_game)'),
  ('Q11167437', 'Looney Tunes is a platform video game developed and published by Sunsoft released for Game Boy in 1992. The game was re-released for Game Boy Color seven years later.

It features Daffy Duck, Tweety, Porky Pig, Taz, Speedy Gonzales, Road Runner and Bugs Bunny as playable characters. Other Looney Tunes characters include Elmer Fudd, Marvin the Martian, Wile E. Coyote and Sylvester.', 'https://en.wikipedia.org/wiki/Looney_Tunes_(video_game)'),
  ('Q7550314', 'Soccer Mania, known in Japan as Soccer Boy, is a soccer-themed sports simulation video game for the Nintendo Game Boy. It was released in 1990 in Japan and two years later in North America. The two releases differ slightly: in Soccer Mania, the player plays as the USA team, while in Soccer Boy, the player plays as the Japan team.', 'https://en.wikipedia.org/wiki/Soccer_Mania'),
  ('Q7550286', 'Soccer (known in Europe as Football International) is a football video game with top-down perspective, developed by Tose for the Game Boy handheld, which was released in 1991.', 'https://en.wikipedia.org/wiki/Soccer_(1991_video_game)'),
  ('Q6141895', 'Mole Mania is a 1996 video game developed and published by Nintendo for the Game Boy. It was released in Japan in July 1996, North America in February 1997 and Europe in May 1997. The game was re-released for the Nintendo 3DS Virtual Console in all major regions throughout 2012, and on Nintendo Classics in 2026.', 'https://en.wikipedia.org/wiki/Mole_Mania'),
  ('Q6148204', 'Mystical Ninja Starring Goemon (がんばれゴエモン〜黒船党の謎〜, Ganbare Goemon: Kurofune Tō no Nazo; lit. "Go Goemon: Mystery of the Black Ship Gang") is an action-adventure video game released by Konami for the Game Boy in 1998. It is the thirteenth mainline installment in the Ganbare Goemon series overall. Featuring gameplay similar to the Super Famicom title Ganbare Goemon 3: Shishijūrokubē no Karakuri Manji Gatame, the game presents a story where Yae has been kidnapped by the Black Ship Gang. Its release immediately followed the Nintendo 64 game of the same name. The game was re-released in 2012 on the Nintendo 3DS Virtual Console, and in 2026 via the Ganbare Goemon! Daishūgō compilation.', 'https://en.wikipedia.org/wiki/Mystical_Ninja_Starring_Goemon_(Game_Boy_video_game)'),
  ('Q6172914', 'Jeep Jamboree: Off Road Adventure is a Game Boy racing video game that involves Jeep Wrangler vehicles. This game was later recycled for use in the video game Race Days (also for the Game Boy).', 'https://en.wikipedia.org/wiki/Jeep_Jamboree:_Off_Road_Adventure'),
  ('Q141192208', 'Aretha II is a 1991 role-playing video game developed by Japan Art Media for the Game Boy. It was a sequel to the company''s previous game Aretha (1990), and is set a year after Materia Weathers discovers that an evil being named Warick is stealing a powerful artifact. This leads to her partnering with her old friends to recover the item and save the world.

While having a similar battle system to the previous game, Aretha adds new battle mechanics such as weapons having the ability to break and a new "technical attack" system. Some towns in the game are now explored in a 2D side-scrolling style instead of the previous top-view form.', 'https://en.wikipedia.org/wiki/Aretha_II'),
  ('Q11477459', 'Legend of the River King is a 1997 fishing and role-playing game originally released for the Game Boy in 1997. It is part of the River King series and has the player controlling an avid young boy who must seek out the Guardian Fish to cure his sick sister. To do so, the player must collect fish and other items to traverse to newer areas to find the Guardian Fish.

Originally released in 1997 in Japan, it became the first Western release of any game in the River King series on its release for the Game Boy in 1998 in North America. It was released for the Game Boy Color in 1999 with some small extra features added to the game.', 'https://en.wikipedia.org/wiki/Legend_of_the_River_King'),
  ('Q123196063', 'Batman: The Video Game is a 1990 action video game developed and published by Sunsoft for the Game Boy. Based on the DC Comics superhero Batman, it is inspired by the Warner Bros.''s 1989 film of the same name. In the main storyline, Batman must face the Joker. The Game Boy version was developed by most of the same staff at Sunsoft which had previously worked on the Nintendo Entertainment System adaptation based on the 1989 film. It was produced by Cho Musou, while soundtrack was composed by Naoki Kodaka, Nobuyuki Hara, and Shinichi Seya. The game garnered a generally favorable reception from critics and retrospective commentators.', 'https://en.wikipedia.org/wiki/Batman:_The_Video_Game_(Game_Boy_video_game)'),
  ('Q138787471', 'Battle Arena Toshinden is a 1996 fighting video game for the Game Boy. It is a version of Battle Arena Toshinden (1995) with the same choice of characters, but done in a two-dimensional playfield instead of the original 3D game. Like the original, the game is set during a secret fighting tournament, with each character having unique motives to enter the tournament. Some new characters are added to this game, while some others are given different motives to battle. This stylized version of the game was part of the Nettō series, which featured more light-hearted versions of the characters.

As a fighting game, players battle each other with kicks, punches and special moves while dodging their opponents'' attacks to drain their power meter. Each character has unique abilities. The game also features an invisible barrier on the sides of the screen, which, when breached three times, results in the player losing the battle.', 'https://en.wikipedia.org/wiki/Battle_Arena_Toshinden_(Game_Boy_video_game)'),
  ('Q11356117', 'Mikeneko Homuzu no Kishido is a 1991 mystery-themed adventure game for the Game Boy. It is based on a novel by Japanese mystery writer Jiro Akagawa in his Calico Cat series. The game involves the detective Yoshitaro Katayamam, his sister and their cat Holmes as they travel to Germany to solve a mystery that occurred in a castle three years earlier.

Mikeneko Homuzu no Kishido was released on February 15, 1991 and was the first adventure game for the Game Boy. Reviewers in Japanese video game magazines Famicom Tsūshin and Hippon Super! complimented the story and background graphics in the game, with some reviewers in the former magazine suggesting that the designs of the characters were not on the same level. One reviewer from each magazine found trouble with the play control and password system in the game.', 'https://en.wikipedia.org/wiki/Mikeneko_Homuzu_no_Kishido'),
  ('Q7579711', 'Sports Collection is a 1996 Japan-exclusive sports video game released by Tonkin House for the Game Boy handheld.', 'https://en.wikipedia.org/wiki/Sports_Collection'),
  ('Q4726454', 'Alien Olympics is a video game for MS-DOS developed by Dark Technologies and published by Mindscape in Europe in 1994. The game is a sports video game that imitates a range of track and field Olympic sports competed by aliens. A Europe-only Game Boy version, Alien Olympics 2044 AD, was published by Ocean Software for the Game Boy in the same year. Upon release, critics praised the game for its variety of events, although critiqued some of them for their challenge and reliance on repeated button presses.', 'https://en.wikipedia.org/wiki/Alien_Olympics'),
  ('Q65038242', 'All-Star Baseball 99 is a video game developed by Iguana Entertainment and Realtime Associates Seattle Division and published by Acclaim Entertainment for the Game Boy and the Nintendo 64 in 1998. The game''s cover features Colorado Rockies outfielder Larry Walker.

All-Star Baseball 99 was the first game to use Acclaim''s Quagmire engine. The game also marked the debut of play-by-play commentary for the series. This is done by two New York Yankees broadcasters: John Sterling and Michael Kay.', 'https://en.wikipedia.org/wiki/All-Star_Baseball_99'),
  ('Q1182593', 'Defender is a horizontally scrolling shooter video game developed and published by Williams Electronics for arcades in 1981. Set on a mountainous planet, the player pilots a space ship to defeat waves of invading aliens that vary in appearance and behavior. While attacking enemies, the player must protect and rescue astronauts on the surface from aliens.

A pinball developer at the time, Williams aimed to expand into video games and selected Eugene Jarvis to lead development. The development team initially focused on designing the game''s arcade hardware, aiming to portray Williams as a technologically advanced developer. When creating early prototypes, Jarvis drew inspiration from Space Invaders and Asteroids. He progressively added offensive and defensive action to the game design, which culminated in gameplay that was more complex and challenging than contemporary video games.', 'https://en.wikipedia.org/wiki/Defender_(video_game)'),
  ('Q4789098', 'Aretha is a 1990 role-playing game developed by Japan Art Media for the Game Boy. It has a fantasy-themed story about the Princess of Aretha named Materia, who seeks out to free her land after it was taken over long ago by a Demon King.

The game was published by Yanoman and received positive reviews scores in Famicom Tsūshin, while a reviewer in Hardcore Gaming 101 felt it was a higher quality game than contemporary home console RPGs for the Family Computer. Both publications commented on the games high difficulty level. The game spawned five follow-ups, with two on the Game Boy and three on the Super Famicom, while none of the game in the Aretha series were officially released in English.', 'https://en.wikipedia.org/wiki/Aretha_(video_game)'),
  ('Q4828099', 'Avenging Spirit, released in Japan as Phantasm, is a 1991 platform video game developed by C.P.Brain and published by Jaleco for arcades. It was released in Japan in May 1991 and in North America in October 1991.', 'https://en.wikipedia.org/wiki/Avenging_Spirit'),
  ('Q3018952', 'Bonk''s Revenge, known as PC-Genjin 2 in Japan and PC Kid 2 in Europe, is a 2D platformer set in prehistory, originally for the PC Engine/TurboGrafx-16 console, created in 1991 by the Red Company for Hudson Soft, and licensed by NEC. This is the second title in the Bonk series, and was re-released for the TurboGrafx-16 in 1992 on the Gate of Thunder 4-in-1 game CD-ROM. A completely different game with the same name appeared on the Game Boy, whereas the original version was re-released for Wii Virtual Console. It was released in Japan on Windows Store on December 13, 2013, and on Wii U Virtual Console on March 12, 2014. The title is also playable on the Turbografx-16/PC Engine Mini Console.', 'https://en.wikipedia.org/wiki/Bonk%27s_Revenge'),
  ('Q137771797', 'Boxxle II is a 1990 sokoban puzzle video game for the Game Boy developed by Atelier Double Co.. It was published by Pony Canyon in Japan and FCI in the United States. It is the sequel to the 1989 Game Boy title Boxxle.', 'https://en.wikipedia.org/wiki/Boxxle_II'),
  ('Q2927389', 'Bubble Ghost is a puzzle video game created by Christophe Andréani for the Atari ST in 1987. The player controls a ghost who, by blowing, guides a floating bubble throughout a number of halls in a haunted house, while avoiding obstacles that can make the bubble pop.

A remake by Nakama Game Studio was released in March 2025 for Windows, PlayStation 5 and Nintendo Switch.', 'https://en.wikipedia.org/wiki/Bubble_Ghost'),
  ('Q6492533', 'Las Vegas Cool Hand, known as Cool Hand in Europe, is a casino game developed by Tarantula Studios and published by Take-Two Interactive for the Game Boy Color. It was released on December 1, 1998 in North America and Europe. The game was ported exclusively in Europe on 1998 for the Game Boy.', 'https://en.wikipedia.org/wiki/Las_Vegas_Cool_Hand'),
  ('Q5191327', 'Crystal Quest is an action game written by Patrick Buckland for the Macintosh and published by Casady & Greene in 1987. It was ported to the Apple IIGS in 1989 by Rebecca Heineman. Ports were also made to the Amiga, Game Boy, iOS, and Palm. It was the first game to support the color displays of the Macintosh II.

The game was based on the original shareware game Crystal Raider, one of the supporters of which had been Michael Greene, founder of Greene, Inc. (later to merge with CasadyWare to become Casady & Greene). A sequel, similar to the original game, Crystal Crazy, was released in 1993.

On February 7, 2006 Crystal Quest was released on Xbox 360 via Xbox Live Arcade and in 2008 for iPhone and iPod touch.', 'https://en.wikipedia.org/wiki/Crystal_Quest'),
  ('Q137772025', 'The Fidgetts is a 1993 video game for the Game Boy developed by Game Over Production and published by Elite Systems. The game was later published by GX Media Co in Japan in 1994 and Jaleco in North America in 1997. The game is a platform video game in which players alternate between two mice, Frankie and Freddie, to navigate mazelike levels to help both reach the end. Upon release, The Fidgetts received average reviews, with praise for its visual design and backgrounds, and criticism of its difficulty and time limits.', 'https://en.wikipedia.org/wiki/The_Fidgetts'),
  ('Q139854994', 'Fist of the North Star: 10 Big Brawls for the King of Universe is a 1989 video game for the Game Boy. It is based on the Fist of the North Star series, which debuted as a serialized manga in Japan in 1983. The game involves characters from the series battling after the events of a nuclear war, with each trying to defeat the others to decide the fate of what was left of the Earth.

Fist of the North Star was the first fighting game released for the Game Boy. It features a normal mode where different characters fight each other one-on-one, exchanging blows until one character''s power meter is drained. Players can gain experience points to boost their chosen characters defencsive and attack stats to use in the other modes, such as two-player versus modes.', 'https://en.wikipedia.org/wiki/Fist_of_the_North_Star:_10_Big_Brawls_for_the_King_of_the_Universe'),
  ('Q2722404', 'Game & Watch Gallery 2, known in Japan as Game Boy Gallery 2, is a video game compilation developed by Tose and published by Nintendo. It was released for the Game Boy in Japan in 1997, and for the Game Boy Color in North America and Europe in November 1998. It is the third entry in the Game & Watch Gallery series, and includes updated versions of six titles from Nintendo''s Game & Watch line of handheld electronic games, originally released between 1980 and 1982.. Each game is presented in two forms: a "Classic" mode that replicates the original gameplay and visuals, and a "Modern" mode with updated gameplay, enhanced graphics and music, and characters from the Mario franchise.', 'https://en.wikipedia.org/wiki/Game_%26_Watch_Gallery_2'),
  ('Q140611111', 'Fortified Zone 2 is a 1992 top-down shooter video game developed and published by Jaleco for the Game Boy. A direct sequel to Fortified Zone (1991), it follows the two mercenaries, Masato Kanzaki and Mizuki Makimura, on a new mission to take down a new weapon that their enemies have. The game features similar gameplay to the original game, with players going through four levels, all while dealing with enemies and traps.

Initially only released in Japan on February 21, 1992, the game was published by the French-based Broke Studio for an English-language release on June 3, 2025. Original reviews were lukewarm, with reviewers complimenting the graphics, but finding that the only thing improved upon the original was the graphics; it was hurt by slow-paced character movement and a lack of innovation from the original.', 'https://en.wikipedia.org/wiki/Fortified_Zone_2'),
  ('Q3322683', 'Montezuma''s Return! is a 1997 action/adventure video game and the sequel to the original Parker Brothers game Montezuma''s Revenge. While the original game was a 2D platform game, the sequel was a 3D first-person puzzle platformer. According to Steve Bergenholtz, the Utopia Technologies spokesperson, the musical score was written by a TV and film veteran. A port for Nintendo 64 was in the works but was cancelled.', 'https://en.wikipedia.org/wiki/Montezuma%27s_Return!'),
  ('Q3327486', 'Muhammad Ali Heavyweight Boxing is a boxing video game that was developed by Park Place Productions and published by Virgin Games in 1992. It was released for the Sega Genesis console.', 'https://en.wikipedia.org/wiki/Muhammad_Ali_Heavyweight_Boxing'),
  ('Q18636716', 'Mulan is a 1998 action game developed by Tiertex and published by THQ for the Game Boy. It is based on the 1998 animated film of the same name. It was released on 16 October 1998, two days before the release of the Game Boy Color.', 'https://en.wikipedia.org/wiki/Mulan_(video_game)'),
  ('Q2686321', 'Navy SEALs is a shoot ''em up platform video game developed and published by Ocean Software. It was first released in the United Kingdom for the Amstrad CPC, GX4000 and Commodore 64 in 1990. It was later re-released in the rest of Europe for the ZX Spectrum, Atari ST and Amiga home computers in the following year. It was then ported to the Game Boy on 1 September 1991 in the United States. The game is based on the film of the same name and follows the protagonist, Lieutenant Dale Hawkins, progressing through five side-scrolling levels.

The game was developed by Ocean Software, renowned for creating video games based on films and other licensed properties. Navy SEALs focuses on Hawkins recovering caches of Stinger missiles from Arab soldiers in the Middle East. The game received positive reviews upon release, with critics mainly praising the graphics, presentation and challenging gameplay, but the criticism was directed at the ZX Spectrum port, which received disapproval over its monochrome graphics.', 'https://en.wikipedia.org/wiki/Navy_SEALs_(video_game)'),
  ('Q1974863', 'Penguin Land, known as Doki Doki Penguin Land Uchū Daibōken in Japan, is a 1987 puzzle-platform game published and developed by Sega for the Master System. It is the second game in the Doki Doki Penguin Land series. The player controls a penguin to guide an egg around polar bears, rocks and other hazards. There are 50 stages and a level editor which can save up to 15 additional levels. The level editor data is stored on the game''s battery back-up RAM. Penguin Land was the first home console video game to include a battery backup save feature, its original Japanese version being released four days prior to The Legend of Zelda''s US release.', 'https://en.wikipedia.org/wiki/Penguin_Land'),
  ('Q1592239', 'Head On is an arcade video game developed by Sega/Gremlin and released by Sega in 1979. It was the first maze video game where the goal is to run over dots. Designed by Lane Hauck at Sega/Gremlin in the United States, it was the fourth highest-grossing arcade game of 1979 in both Japan and the US.

Sega released a sequel, Head On Part II, later the same year. The original inspired a number of clones, as well as Namco''s Rally-X (1980).', 'https://en.wikipedia.org/wiki/Head_On_(video_game)'),
  ('Q7929454', 'Prophecy I: The Viking Child (shortened to Viking Child on some systems) is an action video game released by Imagitec Design Limited for the Atari ST, Amiga, Atari Lynx, Game Boy, and MS-DOS compatible operating systems in 1991. The Atari ST original was programmed by Mark Fisherwith with graphics by Anthony Rosbottom and music by Barry Leitch and Ian Howe.

Ports to the Game Gear, Master System, and Commodore 64 were cancelled. A planned sequel, Viking Child 2, was not released.', 'https://en.wikipedia.org/wiki/Viking_Child'),
  ('Q55673', 'R-Type is a 1987 horizontally scrolling shooter developed and published by Irem as an arcade video game. The player controls the R-9 "Arrowhead" starship in its efforts to destroy the Bydo, a powerful alien race bent on wiping out all of mankind. The R-9 can acquire a glowing orb called a "Force", giving limited protection from enemy fire and providing additional firepower.

R-Type was the first game to run on Irem''s 16-bit M72 arcade system. The development team drew inspiration from Gradius, Aliens, and works by H.R. Giger. The music was composed by Masato Ishizaki, while character designs were by Akio Oyabu. The arcade version was distributed in North America by Nintendo, and was the last arcade title to be released by the company.', 'https://en.wikipedia.org/wiki/R-Type'),
  ('Q622124', 'R-Type II is a 1989 horizontally scrolling shooter video game developed and published by Irem for arcades. It is the sequel to 1987''s R-Type, and the second game in the R-Type series.', 'https://en.wikipedia.org/wiki/R-Type_II'),
  ('Q7279973', 'Radar Mission is a turn-based strategy video game developed and published by Nintendo for the Game Boy. It was released in 1990 in Japan and North America and Europe in 1991. In June 2011, the game was re-released on the Nintendo 3DS'' Virtual Console.', 'https://en.wikipedia.org/wiki/Radar_Mission'),
  ('Q11346350', 'Ray-Thunder is a 1991 3D shooter game published by Nichibutsu for the Game Boy. The game is set in the future, where security robots have gone berserk and begin attacking people in Tokyo, which leads the player to choose a craft to track them down in various mazes.

Ray-Thunder was Nichibutsu''s first Game Boy video game. It was released for the Game Boy in Japan on February 8, 1991. It received mixed reviews in Famicom Tsūshin with comments being split on its visuals and gameplay.', 'https://en.wikipedia.org/wiki/Ray-Thunder'),
  ('Q2742946', 'Darius II, released outside Japan as Sagaia, is a 1989 horizontally scrolling shooter video game developed and published by Taito for arcades. It is a direct sequel to the 1987 title Darius. It was later released in Japan in 1991 for the Game Boy as well as non-Japanese ports. A remake was released for the PC Engine Super CD-ROM² as Super Darius II in 1993.', 'https://en.wikipedia.org/wiki/Darius_II_(video_game)'),
  ('Q1150903', 'Ninja Spirit is a 1988 hack and slash platform video game developed and published by Irem for arcades. Although praised by gamers for detailed graphics, serious themes, solid controls and gameplay, the game also was criticized for its harsh difficulty.', 'https://en.wikipedia.org/wiki/Ninja_Spirit'),
  ('Q224905', 'SameGame is a tile-matching puzzle video game originally released under the name CHAIN SHOT in 1985 by Kuniaki "Morisuke" Moribe. It has since been ported to numerous computer platforms, handheld devices, and even TiVo, with new versions as of 2016.', 'https://en.wikipedia.org/wiki/SameGame'),
  ('Q7439840', 'Sea Battle is a real-time strategy game released by Mattel for its Intellivision system in 1980. In the game, players command fleets of naval vessels attempting to invade the harbor of their opponent.', 'https://en.wikipedia.org/wiki/Sea_Battle'),
  ('Q13580398', 'Bugs Bunny: Crazy Castle 3 is a platform game developed by Kemco as part of the Crazy Castle series. It was originally released in Japan as a Game Boy title in July 1997 called Soreyuke!! Kid: Go! Go! Kid starring the character Kid Klown. The title was later remade on the Game Boy Color to include colorized graphics and characters from the Looney Tunes series, which was released in Japan in January 1999 by Kemco, and later that year in North America and Europe by Nintendo. It replaces Honey Bunny with Lola Bunny as Bugs'' love interest to be rescued. It was followed by a sequel, Bugs Bunny in Crazy Castle 4, in 2000.', 'https://en.wikipedia.org/wiki/Bugs_Bunny:_Crazy_Castle_3'),
  ('Q55641905', 'Super Breakout is a 1978 action video game developed and published by Atari, Inc. for arcades. It was released by Namco and Esco Trading in Japan. The game, originally designed by Ed Rotberg and Ed Logg, is a sequel to Atari''s 1976 game Breakout, and uses the same mechanics while also allowing the selection of three distinct game modes, two of which involve multiple, simultaneous balls in play. As with its predecessor, the arcade version of Super Breakout is displayed in black and white, with monitor overlays to add color.

The arcade game was commercially successful in Japan and the United States. Atari published home versions of the game–in color–for most of its consoles and computers, and the game was the pack-in title for the Atari 5200 console when it was released in 1982.', 'https://en.wikipedia.org/wiki/Super_Breakout'),
  ('Q933967', 'Tumblepop is a 1991 platform video game developed and published by Data East for arcades. It was released in North America by Leprechaun Inc. and in Europe by Mitchell Corporation. Starring two ghosthunters, players are tasked with travelling across different countries, capturing enemies and throwing them as bouncing ball, jumping on and off platforms to navigate level obstacles while dodging and defeating monsters in order to save the world.

Designed by Makoto Kikuchi, Tumblepop was developed by most of the same team that worked on several projects at Data East. The game was later ported to the Game Boy with several changes or additions from the original version. The game was met with mostly positive reception from critics and players alike, gaining a cult following since its initial release. However, other versions were met with a more mixed response from reviewers.', 'https://en.wikipedia.org/wiki/Tumblepop'),
  ('Q19850827', 'Wario Blast: Featuring Bomberman! is a video game developed and published by Hudson Soft in Japan, and published by Nintendo in North America and Europe. It was released on August 10, 1994 in Japan and later in November 1994 in North America, and on June 29, 1995 in Europe. It was released in Japan as Bomberman GB.', 'https://en.wikipedia.org/wiki/Wario_Blast:_Featuring_Bomberman!'),
  ('Q8034284', 'WordZap is a puzzle video game designed by Michael F.C. Crick, son of scientist Francis Crick. In 1991, it was included with Volume 3 of the Microsoft Entertainment Pack and was later released by Jaleco for the Game Boy in 1992. An updated version for newer editions of Microsoft Windows is available on the game''s official website as shareware. The game has been compared with Scrabble and Boggle; in WordZap, players race to make proper English words to fill their rack of words, but when one player makes a word already found by the other player, the word is "zapped" from both players'' racks. Each round ends when either one player fills the word rack, or time runs out without either player being able to make another word.', 'https://en.wikipedia.org/wiki/WordZap'),
  ('Q4020897', 'World Heroes 2 Jet is a 1994 fighting video game developed by ADK and published by SNK for the Neo Geo arcade and home platforms. It is the sequel and update to the 1993 fighting arcade game World Heroes 2, as well as the third title of the World Heroes series.

It was followed by a sequel released over a year later titled World Heroes Perfect.', 'https://en.wikipedia.org/wiki/World_Heroes_2_Jet'),
  ('Q1738113', 'Xenon 2: Megablast is a 1989 shoot ''em up video game developed by The Bitmap Brothers and published by Image Works for the Amiga and Atari ST. It was later converted to the Master System, PC-98, X68000, Mega Drive, Commodore CDTV, Game Boy, Acorn Archimedes and Atari Jaguar platforms. The game is a sequel to Xenon and takes place a millennium after the previous title. The goal of the game is to destroy a series of bombs planted throughout history by the Xenites, the vengeful antagonists of the first game.

Xenon 2: Megablast is the third major video game release by The Bitmap Brothers. Its subtitle is derived from the Bomb the Bass track "Megablast (Hip Hop on Precinct 13)", which serves as the game''s theme music. The original release of Xenon 2: Megablast was met with critical acclaim and commercial success, with reviewers praising the detailed visuals, addictive gameplay, variety of weapons and innovative soundtrack.', 'https://en.wikipedia.org/wiki/Xenon_2:_Megablast'),
  ('Q3084347', 'Mega Man Xtreme 2 is a 2001 platform game developed and published by Capcom for the Game Boy Color. It is a spin-off title in the Mega Man X series and a follow-up to Mega Man Xtreme, which was released the previous year. Mega Man Xtreme 2 is set in the 22nd century between the events of Mega Man X3 and Mega Man X4. The DNA souls of robots known as "Reploids" are being stolen and used to create an army of undead "Mavericks". The "Maverick Hunters" X and Zero quickly spring into action with the help of their young ally Iris.

Gameplay in Mega Man Xtreme 2 is similar to that of earlier Mega Man games, retaining most elements from the home-console versions of the series, but adding the ability to switch between characters, use unique abilities and obtain upgrades through "DNA Souls" collected from fallen enemies. Each character has a different set of stages and bosses; defeating the stage''s boss will earn the character a special weapon.', 'https://en.wikipedia.org/wiki/Mega_Man_Xtreme_2'),
  ('Q3005559', 'Cruis''n Exotica is a 1999 racing game developed and published by Midway Games for arcades. The game is a sequel to Cruis''n World and is the third entry in Nintendo''s Cruis''n series. A port to the Nintendo 64 developed by Gratuitous Games was released in 2000, along with a Game Boy Color version developed by Crawfish Interactive.', 'https://en.wikipedia.org/wiki/Cruis%27n_Exotica'),
  ('Q3133955', 'Hercules: The Legendary Journeys is a 2000 action-adventure game based on the television series of the same name, released by Titus Interactive for the Nintendo 64 and Game Boy Color. The player controls Hercules and his friends, Iolaus and Serena, on a quest to free Zeus from the forces of Ares and Hera.

The gameplay differs depending on the version played; the N64 version is a 3D game with elements of platforming and role playing games while the Game Boy Color version is a side-scrolling adventure game with shifting view perspectives.

The Nintendo 64 version has received mixed to positive reviews, with it being praised for its variety in content, but criticized for feeling too similar to The Legend of Zelda: Ocarina of Time. Meanwhile, the Game Boy Color version has received mixed to negative reviews with it being criticized for its gameplay and challenges, along with conflicting reactions for the game''s blend of formulas.', 'https://en.wikipedia.org/wiki/Hercules:_The_Legendary_Journeys_(video_game)'),
  ('Q3038722', 'Dragon Ball Z: Legendary Super Warriors is a turn-based fighting game released for the Game Boy Color. It is played with the use of in-game cards for attacks, techniques and support items. The game''s story takes place from the start of Dragon Ball Z, the Saiyan Saga, and runs until the end of the Buu Saga. The game includes two extra stories involving Future Trunks''s timeline.

Once the game has been completed, the player can replay the story mode or battle modes the game has with the freedom to use any characters and forms they choose in any of the given battles. During the player''s second playthrough, they may be able to unlock additional characters if certain criteria are met.', 'https://en.wikipedia.org/wiki/Dragon_Ball_Z:_Legendary_Super_Warriors'),
  ('Q3038754', 'Dragon Warrior Monsters 2, known in Japan as Dragon Quest Monsters 2, is a role-playing video game published by Enix for the Game Boy Color. It is the second Dragon Warrior Monsters game for the Game Boy Color and features two different versions of the same game, Cobi''s Journey (released as Dragon Quest Monsters 2 - Maruta No Fushigi Na Kagi - Ruka no Tabidachi in Japan) and Tara''s Adventure (released as Dragon Quest Monsters 2: Maruta No Fushigi Na Kagi - Iru no Bouken in Japan). Both games were remade in 2002 for the PlayStation in a compilation game called Dragon Quest Monsters 1+2 and released only in Japan. The Nintendo 3DS version combined both games into one and was released only in Japan in 2014 with the title Dragon Quest Monsters 2: Iru and Luca''s Marvelous Mysterious Key. The 3DS version was later brought to iOS, Android on August 6, 2020, in Japan.', 'https://en.wikipedia.org/wiki/Dragon_Warrior_Monsters_2'),
  ('Q7489029', 'Shantae is a 2002 platform video game developed by WayForward and originally published by Capcom for the Game Boy Color. The video game follows the adventures of the titular half-genie Shantae as she travels across Sequin Land to thwart the domination plans of the evil lady pirate Risky Boots. During her quest, she learns various dances and acquires items which make her progressively stronger as well as unlocking new abilities and locations, culminating in a final showdown with Risky at her hideout.

Upon its release, Shantae received favorable reviews but struggled to find an audience due to its launch a year after the Game Boy Color was succeeded by the Game Boy Advance. Despite this, it has since been recognized as a "cult classic" and is frequently included in lists of the best Game Boy Color games. The game later spawned a successful series of sequels. Shantae was re-released for the Nintendo 3DS in 2013 via the Virtual Console emulator, marking its debut in Europe. The original version was re-released for the Nintendo Switch in April 2021, with PlayStation 4 and PlayStation 5 versions released in June 2023.', 'https://en.wikipedia.org/wiki/Shantae_(video_game)'),
  ('Q7572413', 'Burai Fighter is a shoot ''em up video game developed by KID for the Nintendo Entertainment System. The game was released in North America by Taxan in March 1990, PAL regions by Nintendo in 1990, and Japan by Taito on July 20, 1990. The game was ported to the Game Boy and retitled as Burai Fighter Deluxe, and was released in Japan on June 27, 1990, in North America in January 1991 and in Europe in 1991; this port was released for the Game Boy Color as Space Marauder, originally released in Japan as Burai Fighter Color, as the original Game Boy version is not compatible with the later models.

The setting for Burai Fighter is to fend off seven bases of Burai, super-intelligent cyborgs. The player starts out with a relatively weak cannon, but can upgrade to ring, laser, and missile weapons, which are much more powerful. The player can initially choose from three difficulty settings: Eagle, Albatross, and Ace; the fourth difficulty setting, Ultimate, must be unlocked. The character can be moved in 8 directions and can shoot in a different direction from the direction he is moving towards.', 'https://en.wikipedia.org/wiki/Burai_Fighter'),
  ('Q7642251', 'Super Chinese Fighter EX is a fighting video game for the Game Boy Color released by Culture Brain in 1999. It is part of the Super Chinese series and is the final Fighter game in the series.

Unlike most of the Super Chinese games, Fighter EX is not an action game or role-playing video game. This game includes many characters of the Super Chinese series, like the main characters Jack and Ryu.', 'https://en.wikipedia.org/wiki/Super_Chinese_Fighter_EX'),
  ('Q7578979', 'SpongeBob SquarePants: Legend of the Lost Spatula is a 2001 platform action video game developed by Vicarious Visions and published by THQ for the Game Boy Color handheld game console. It is the first video game to be based on SpongeBob SquarePants. The game''s story centers on SpongeBob SquarePants, a sea sponge who lives in the undersea town of Bikini Bottom and works for Mr. Krabs as the fry cook of the Krusty Krab fast food restaurant. SpongeBob is destined to become the ocean''s greatest fry cook, and must embark on a quest to retrieve a golden spatula from the Flying Dutchman, a pirate ghost. The game features platforming-style gameplay, as well as many characters from the television series.', 'https://en.wikipedia.org/wiki/SpongeBob_SquarePants:_Legend_of_the_Lost_Spatula'),
  ('Q7600814', 'Star Ocean: Blue Sphere is an action role-playing video game developed by tri-Ace and published by Enix for the Game Boy Color handheld video game console in June 2001. It is a spin-off entry in the Star Ocean series, acting as a direct sequel to the 1998 PlayStation title Star Ocean: The Second Story. It was later remade for mobile devices, releasing in 2009.

Blue Sphere is set two years after the events of The Second Story on the planet Edifice, a world currently in a pre-space flight state but holding remnants of an advance civilization. Protagonists from the events of The Second Story are brought down onto the planet by an unknown force, and must work to discover its source and leave. The gameplay carries over multiple Star Ocean elements, including real-time combat and optional side conversations between party members. New elements include item creation tied to the skill system, and local multiplayer options unlock through the Game Link Cable.', 'https://en.wikipedia.org/wiki/Star_Ocean:_Blue_Sphere'),
  ('Q7548028', 'Snoopy Tennis is a sports video game developed by the British company Mermaid Studios and published by Infogrames. It was released for the Game Boy Color in 2001. It was the first Peanuts video game released after Charles M. Schultz''s death the year prior in 2000.', 'https://en.wikipedia.org/wiki/Snoopy_Tennis'),
  ('Q2909725', 'Bomberman Max: Blue Champion and Bomberman Max: Red Challenger are video games released for the Game Boy Color on May 9, 2000. The game was followed by Bomberman Max 2 which was released for the Game Boy Advance on June 4, 2002. There are two versions called Bomberman Max: Blue Champion and Bomberman Max: Red Challenger. In Blue Champion the playable character is Bomberman where in Red Challenger the playable character is Max.

A third version of the game, Bomberman Max: Ain Version, was a Japan-exclusive limited edition. Limited to 2,000 copies, it was only available through a lucky draw contest by the Pentel Ain ad campaign.', 'https://en.wikipedia.org/wiki/Bomberman_Max'),
  ('Q2928773', 'Bust-A-Move Millennium, also known as Puzzle Bobble Millennium in Japan, is a 2000 puzzle video game developed and published by Altron for the Game Boy Color.', 'https://en.wikipedia.org/wiki/Bust-a-Move_Millennium'),
  ('Q2891437', 'Batman: Chaos in Gotham is a 2001 action video game developed by Digital Eclipse Software and published by Ubisoft for the Game Boy Color. It is based on The New Batman Adventures.', 'https://en.wikipedia.org/wiki/Batman:_Chaos_in_Gotham'),
  ('Q2891778', 'BattleTanx is a 1998 vehicular combat game released for the Nintendo 64, produced by The 3DO Company. Set in a post-apocalyptic world where a virus has wiped out nearly all women, the player controls a tank and must fight across the former United States against other tank-armed gangs. The game was followed by a 1999 sequel, titled BattleTanx: Global Assault.', 'https://en.wikipedia.org/wiki/BattleTanx'),
  ('Q120146328', 'NASCAR Challenge is a 1999 video game for the Game Boy Color, developed by Morning Star Multimedia and published by Hasbro Interactive. The game is a NASCAR-licensed racing video game featuring three tracks from the NASCAR circuit. Upon release, the game received negative reviews, with publications criticizing the game''s limited tracks, features, and poor attention to detail.', 'https://en.wikipedia.org/wiki/NASCAR_Challenge'),
  ('Q122782003', 'Maya the Bee & Her Friends is a 1999 platformer video game developed by British studio Crawfish Interactive for the Game Boy and the Game Boy Color. It is the first game based on Maya the Bee.

The game reuses the engine sourced from a cancelled South Park game which Crawfish Interactive were developing for Acclaim in 1998. The game was also reskinned and released as The New Adventures of Mary Kate & Ashley in North America to tie in with the Mary-Kate and Ashley Olsen media franchise.', 'https://en.wikipedia.org/wiki/Maya_the_Bee_%26_Her_Friends'),
  ('Q55217', 'Star Wars Episode I: Racer is a 1999 racing video game developed and published by LucasArts. It is based on the podracing sequence in the film Star Wars: Episode I – The Phantom Menace. The game features all of the racers and race course on Tatooine from The Phantom Menace. It adds several courses, on Tatooine and various planets. The game has several single-player modes, including a tournament mode. The format of multiplayer mode varies by platform. Jake Lloyd and Lewis MacLeod, who portrayed Anakin Skywalker and Sebulba in The Phantom Menace, reprise their roles in the game.

Episode I: Racer received generally positive reviews from critics. Several major media outlets listed it as one of the top Star Wars video games. As of 2011, the game holds the Guinness record as the best-selling sci-fi racing game, with worldwide sales of 3.12 million units, followed by series like Wipeout and F-Zero. Two podracing games were released later. Star Wars: Racer Arcade, an arcade game featuring many similar tracks and characters, was released in 2000. A sequel, Star Wars Racer Revenge was released in 2002 for the PlayStation 2.', 'https://en.wikipedia.org/wiki/Star_Wars_Episode_I:_Racer'),
  ('Q120177389', 'Carl Lewis Athletics 2000 is a 2000 video game developed by Planet Interactive Development and published in Europe by Ubi Soft for the Game Boy Color. Based on the brand of American athlete Carl Lewis, the game is a track and field sports game in which players compete in various decathlon events.', 'https://en.wikipedia.org/wiki/Carl_Lewis_Athletics_2000'),
  ('Q120252967', 'Supercross Freestyle is a 2000 motorbike racing game developed by Fernando Velez and Guillaume Dubail, and published by Infogrames Europe for the Game Boy Color. The game features three modes, including a conventional supercross racing mode, a freestyle trick mode, and an arcade racing mode. Supercross Freestyle received praise upon release for the diversity of game modes and controls.', 'https://en.wikipedia.org/wiki/Supercross_Freestyle'),
  ('Q54842', 'Star Wars Episode I: Obi-Wan''s Adventures is a 2000 action-adventure game developed by HotGen and published by THQ and LucasArts for the Game Boy Color. The game, which is based on the 1999 film Star Wars: Episode I – The Phantom Menace, follows Jedi apprentice Obi-Wan Kenobi as he fights the forces of the evil Trade Federation, which culminates in a battle against the Sith Lord Darth Maul.

Obi-Wan''s Adventures was the result of an agreement made between LucasArts and THQ, which allowed THQ to publish games based on LucasArts licenses for the Game Boy Color. Since its release, the game has received mixed reviews, with praise for its level and sound design and criticism for its visuals and controls.', 'https://en.wikipedia.org/wiki/Star_Wars_Episode_I:_Obi-Wan%27s_Adventures'),
  ('Q3493444', 'Spider-Man 2: The Sinister Six (or Spider-Man 2: Enter the Sinister Six in Europe) is a 2001 platform video game based on the Marvel Comics character Spider-Man. It was developed by Torus Games and published by Activision for the Game Boy Color. It was released on May 18, 2001, and is a sequel to Spider-Man (2000).

A canonical sequel to the first game, Spider-Man 2: Enter: Electro, was eventually released on October 19, 2001 as a PlayStation exclusive, followed by a standalone sequel, Spider-Man: Mysterio''s Menace, released on September 19, 2001 for the Game Boy Advance.', 'https://en.wikipedia.org/wiki/Spider-Man_2:_The_Sinister_Six'),
  ('Q3375307', 'Perfect Dark is a 2000 action-adventure stealth game developed and published by Rare for the Game Boy Color. As a direct prequel to its Nintendo 64 counterpart, the game follows agent Joanna Dark as she completes her training at the Carrington Institute research centre and uncovers information against rival corporation dataDyne. The gameplay revolves around shooting opponents and completing objectives such as rescuing hostages or recovering items. The game also includes a multiplayer mode where two players may compete against each other in several deathmatch modes.

Perfect Dark was developed simultaneously with the Game Boy Color version of Donkey Kong Country. It supports the Game Boy Printer and Game Link Cable accessories, and includes a built-in rumble functionality into the game cartridge. The Transfer Pak allows players to alternatively unlock cheat modes in the Nintendo 64 game. The game received generally mixed reviews from critics, who criticised its difficult and superficial gameplay, but highlighted its technical aspects such as graphics and compatibility features.', 'https://en.wikipedia.org/wiki/Perfect_Dark_(GBC_video_game)'),
  ('Q3283766', 'WWF Betrayal is a beat ''em up on the Game Boy Color based on the World Wrestling Federation (WWF). It was the third and last WWF game released to the Game Boy Color and one of a few games based on the promotion that was of a different genre than the regular professional wrestling games usually produced.

The game''s plot was roughly based on a storyline in 1999 where Stephanie McMahon gets kidnapped. Her father Vince McMahon promises to grant the player a shot at the WWF Championship if they manage to save her. The player must then fight through a series of side-scrolling levels to rescue Stephanie. The player can play as Stone Cold Steve Austin, The Rock, Triple H, or The Undertaker.', 'https://en.wikipedia.org/wiki/WWF_Betrayal'),
  ('Q3284542', 'Tiny Toon Adventures: Buster Saves the Day is the first Tiny Toon Adventures game released on the Nintendo Game Boy Color. It was released on June 29, 2001 in Europe and July 27, 2001 in United States and was developed by Warthog and published by Conspiracy Games in North America and Swing! Entertainment in Europe.', 'https://en.wikipedia.org/wiki/Tiny_Toon_Adventures:_Buster_Saves_the_Day'),
  ('Q3311829', 'Mickey''s Racing Adventure is a 1999 racing video game developed by Rare and published by Nintendo for the Game Boy Color. It was followed by Mickey''s Speedway USA in 2001.', 'https://en.wikipedia.org/wiki/Mickey%27s_Racing_Adventure'),
  ('Q108810308', 'Qix Adventure is a 1999 video game developed by Coconuts Japan Entertainment and published by Taito for the Game Boy Color. An English port was developed by Evolution Entertainment for the United Kingdom in 2000. It is a puzzle game based on the 1981 Taito title Qix, with additional story elements.', 'https://en.wikipedia.org/wiki/Qix_Adventure'),
  ('Q124372291', 'International Rally (released in Europe as Cross Country Racing and Japan as It''s a World Rally) is a 1999 racing video game developed by Konami for the Game Boy Color. The game features rally races across 20 tracks set in international countries including France, Italy, Egypt and Japan. Upon release, International Rally received mixed to negative reviews, with critics praising the attempt to integrate racing simulation elements into a handheld game, but faulting its lack of variety, slow gameplay, and lacklustre visuals.', 'https://en.wikipedia.org/wiki/International_Rally'),
  ('Q7885948', 'Game & Watch Gallery 3, known in Japan as Game Boy Gallery 3, is a 1999 video game compilation developed by Tose and published by Nintendo for the Game Boy Color, with backward compatibility for the Game Boy. It is the fourth entry in the Game & Watch Gallery series. The compilation includes updated versions of five games from Nintendo''s Game & Watch line of handheld electronic titles, originally released between 1981 and 1983. Each game is presented in two modes: a "Classic" mode that replicates the original gameplay and visuals, and a "Modern" mode that features updated mechanics, enhanced graphics and music, and characters from the Mario franchise. As players progress, six additional "Classic" mode games also become available for play.', 'https://en.wikipedia.org/wiki/Game_%26_Watch_Gallery_3'),
  ('Q7969514', 'Warlocked is a real-time strategy video game developed by Bits Studios and published by Nintendo for the Game Boy Color. It was solely released in North America on July 24, 2000. Choosing between human and beast factions, the player plays through twelve scenarios from each faction, gathering resources, building fortresses, and managing troops to defeat the opposing force.

The music for Warlocked was composed by Jeroen Tel. Critical reception towards the game was positive, with some critics noting its status as the only real-time strategy game for the handheld. It received IGN''s "Best Game Boy Strategy" award in 2000. Despite the accolades, sales were low. A sequel was planned for the Game Boy Advance titled Wizards but it was cancelled.', 'https://en.wikipedia.org/wiki/Warlocked'),
  ('Q109413037', 'Bugs Bunny in Crazy Castle 4 is a platform game developed and published by Kemco as part of the Crazy Castle series. This is the first game in the series to feature the Bugs Bunny character in all of its versions, and the last one to be published under that license.', 'https://en.wikipedia.org/wiki/Bugs_Bunny_in_Crazy_Castle_4'),
  ('Q10268706', 'Dragon Tales is an animated educational fantasy children''s television series created by Jim Coane and Ron Rodecker, developed by Coane, Wesley Eure, Jeffrey Scott, Cliff Ruby and Elana Lesser, and produced by Sesame Workshop (formerly known as the Children''s Television Workshop), Sony Pictures Television (formerly known as Columbia TriStar Television) and Adelaide Productions. The series focuses on the adventures of two siblings, Emmy and Max, and their dragon friends Cassie, Ord, and Zak and Wheezie.

The series began broadcasting on PBS on their newly-renamed PBS Kids block on September 6, 1999, with its final episode airing on April 11, 2005. Yearim Productions was responsible for the animation for all seasons (Sunwoo Entertainment and Wang Film Productions only did animation for season 1 and Rough Draft Korea only did animation for seasons 2 and 3), with the exception of Koko Enterprises, which recorded the show along with BLT Productions. The Corporation for Public Broadcasting, the United States Department of Education, cereal company Kellogg''s and greeting card manufacturer, American Greetings were responsible for funding. The show is available to stream for free on Tubi and The Roku Channel.', 'https://en.wikipedia.org/wiki/Dragon_Tales'),
  ('Q115244932', 'Hands of Time is a 2001 action game for the Game Boy Color developed by Mirage Media S.C. and published by Titus Interactive SA. The game''s story features time travel, in which the player travels to the past to destroy a time machine that has led to events creating a world war.', 'https://en.wikipedia.org/wiki/Hands_of_Time_(video_game)'),
  ('Q97930369', 'International Karate 2000 is a 2000 video game developed by Studio 3 Interactive Entertainment. The game is a handheld sequel to the original title, International Karate. Upon release, the game received generally positive reviews.', 'https://en.wikipedia.org/wiki/International_Karate_2000'),
  ('Q97930726', 'Towers: Lord Baniff''s Deceit is a first-person role-playing video game originally developed and published by JV Enterprises for the Atari ST in 1993. It is the first entry in the Towers series. In the game, players assume the role of adventurers tasked with finding Lord Baniff in his Tower, who has not been heard from by the people of Lamini. The title was later ported to both MS-DOS and Game Boy Color, each featuring various differences compared to the original release. It was met with mixed reception from critics across all platforms. A sequel, Towers II: Plight of the Stargazer, was released in 1995 for the Atari Falcon.', 'https://en.wikipedia.org/wiki/Towers:_Lord_Baniff%27s_Deceit'),
  ('Q67388656', 'Top Gear Pocket, known in Europe as Top Gear Rally, is a racing video game developed by Kemco and released for the Game Boy Color handheld console in 1999. A sequel, Top Gear Pocket 2, was released in 2000.', 'https://en.wikipedia.org/wiki/Top_Gear_Pocket'),
  ('Q445295', 'Wings of Fury is a scrolling shooter, with some combat flight simulator elements, originally written for the Apple II by Steve Waldo and released in 1987 by Broderbund. The player assumes the role of a pilot of an American F6F Hellcat plane aboard the USS Wasp in the Pacific during World War II. It was also released in 1989 for the X68000 and in 1990 for Amstrad CPC, Commodore 64, Amiga, and MS-DOS compatible operating systems. A Game Boy Color version was published in 1999.', 'https://en.wikipedia.org/wiki/Wings_of_Fury'),
  ('Q106548367', 'Zebco Fishing (stylised as Zebco Fishing!) is a 1999 video game developed by Vicarious Visions and published by Vatical Entertainment for the Game Boy Color. It is a ZEBCO licensed fishing video game. Upon release, the game received mixed reviews.', 'https://en.wikipedia.org/wiki/Zebco_Fishing'),
  ('Q100930299', 'Millennium Winter Sports, known in Japan as Hyper Olympic Winter 2000, and in Europe as Konami Winter Games, is a video game developed and published by Konami for Game Boy Color in 2000.', 'https://en.wikipedia.org/wiki/Millennium_Winter_Sports'),
  ('Q115287465', 'Hexcite: The Shapes of Victory is a 1998 Game Boy Color game developed by Gu Inc. in Japan and Landwarf in North America, and published by Ubi Soft. The game was a launch title for the Japanese release of the Game Boy Color.', 'https://en.wikipedia.org/wiki/Hexcite'),
  ('Q113793937', 'Toy Story 2 is a 1999 side-scrolling platform game for Game Boy Color based on the film of the same name developed by Tiertex Design Studios. It was released in November 1999 in North America with the European version releasing the following year. The premise of the game loosely follows the original film with players taking control of Buzz Lightyear on a mission to rescue Woody by traversing through stages.', 'https://en.wikipedia.org/wiki/Toy_Story_2_(video_game)'),
  ('Q7750522', 'The Mask of Zorro is a 1999 Game Boy Color platform game developed by Saffire and published by Sunsoft, based upon and following the plot of the 1998 movie of the same name.', 'https://en.wikipedia.org/wiki/The_Mask_of_Zorro_(video_game)'),
  ('Q776134', 'Tonic Trouble is a 1999 action-adventure game developed by Ubi Soft Montreal and published by Ubi Soft. The game follows janitor Ed, who drops a container of unidentified fluid from his spaceship to Earth, transforming the planet into a mutated version of itself. Drunkard Grögh drinks from the container and is granted powers that lead him to conquer Earth. Assuming the role of Ed, the player is tasked with solving puzzles and defeating enemies to acquire the tools to conquer Grögh and repossess the container to create an antidote.

Tonic Trouble was conceptualized by Michel Ancel and developed by a team of around 120 people, starting pre-production in June 1996. After multiple delays, the game was released for Nintendo 64 in August 1999, with a Windows version following that December. A Game Boy Color adaptation was made by RFX Interactive and released in Europe in 2000. Tonic Trouble received a mixed response from critics, who approved of the controls, score, level design, and graphics, but criticized the camera system, gameplay, visuals, and its derivative nature. The game sold 1.1 million copies by 2001 and was re-released with Nintendo Classics in 2025.', 'https://en.wikipedia.org/wiki/Tonic_Trouble'),
  ('Q113540736', 'Mary-Kate and Ashley: Get A Clue! is a 2000 video game developed by Crawfish Interactive and published by Acclaim Entertainment. Mary-Kate and Ashley: Get a Clue! was released for the Game Boy Color on May 31, 2000, and represented part of Club Acclaim, a push by Acclaim to attract more girls and families to video games.', 'https://en.wikipedia.org/wiki/Mary-Kate_and_Ashley:_Get_A_Clue'),
  ('Q115325121', 'Tweety''s High-Flying Adventure is a 2000 Game Boy Color game developed and published by Kemco, and is a platform game based on the 2000 Looney Tunes film of the same name.', 'https://en.wikipedia.org/wiki/Tweety%27s_High-Flying_Adventure_(video_game)'),
  ('Q115325093', 'Jim Henson''s Muppets is a 2000 platform game, based on The Muppets franchise, developed by Tarantula Studios and published by Take-Two Interactive for Game Boy Color.', 'https://en.wikipedia.org/wiki/Jim_Henson%27s_Muppets_(video_game)'),
  ('Q113288909', 'Evel Knievel is an action-adventure racing video game for the Game Boy Color developed by Tarantula Studios.', 'https://en.wikipedia.org/wiki/Evel_Knievel_(video_game)'),
  ('Q98893724', 'Pro Pool is a video game developed by Blade Interactive and published by Codemasters in 2000.

The game had been scheduled to be released in May 2000, but it was delayed for unknown reasons.', 'https://en.wikipedia.org/wiki/Pro_Pool'),
  ('Q738725', 'Pokémon Puzzle Challenge is a puzzle video game developed by Intelligent Systems and published by Nintendo for the Game Boy Color. It was released in Japan on September 21, 2000; in North America on December 4, 2000; and in PAL regions on June 15, 2001, it is the second Pokémon-themed entry in the Puzzle League series. While its Nintendo 64 counterpart Pokémon Puzzle League is visually based on the Pokemon anime, Puzzle Challenge instead draws inspiration from the Pokémon Gold and Silver games. The game features multiple modes of play and support for competitive play between two players. Puzzle Challenge was later digitally re-released via the Nintendo 3DS''s Virtual Console line on November 6, 2014.', 'https://en.wikipedia.org/wiki/Pok%C3%A9mon_Puzzle_Challenge'),
  ('Q67388756', 'Top Gear Pocket 2, known in Europe as Top Gear Rally 2, is a racing video game developed by Kemco and released for the Game Boy Color handheld console, released on December 17, 1999 in Japan and in 2000 across other regions. It is a sequel to Top Gear Pocket.', 'https://en.wikipedia.org/wiki/Top_Gear_Pocket_2'),
  ('Q7808639', 'Tiny Toon Adventures: Dizzy''s Candy Quest is the second Tiny Toon Adventures-related game released on the Game Boy Color, published in October 2001 by Swing! Entertainment. It was developed by Formula, a handheld division of Lost Boys Games.', 'https://en.wikipedia.org/wiki/Tiny_Toon_Adventures:_Dizzy%27s_Candy_Quest'),
  ('Q7857517', 'Tweenies is a British live action puppet children''s television series created by Will Brenton and Iain Lauchlan, and produced by Tell-Tale Productions for the BBC. The programme was focused on four preschool-aged characters, known as the "Tweenies"; Jake, Fizz, Milo & Bella, whilst playing, singing, dancing and learning in a fictional playgroup in England. They are cared for by two adult Tweenies; Judy & Max and his dog; Doodles, and later another dog, Izzles who belongs to Judy.

Tweenies first premiered on 6 September 1999 on the BBC''s children''s block and consisted of a total of 390 episodes, with the final production airing in April 2002. Repeated episodes of the series aired on CBeebies from 2002 to 2016. In 2000, the show won a British Academy Television Award for Best Pre-school Live Action Series, and singles featuring exclusive songs spent several weeks in the charts during the early 2000s.', 'https://en.wikipedia.org/wiki/Tweenies'),
  ('Q7687444', 'Tasmanian Devil: Munching Madness is a video game developed by the British studio M4 Ltd. and released by Sunsoft in 1999 for the Game Boy Color. The game stars the Looney Tunes character Tasmanian Devil.', 'https://en.wikipedia.org/wiki/Tasmanian_Devil:_Munching_Madness'),
  ('Q7861437', 'Tyrannosaurus Tex is a cancelled first-person shooter video game for the Nintendo Game Boy Color portable console developed by Slitherine Software and planned to be released in March 2000. The game generated high expectations, as it would have been one of only two first-person shooters released for the Game Boy Color, alongside Ultimate Paintball.

In January 2013, a 30 minutes gameplay footage video was released to the Internet, after the prototype cartridge was sold at auction.

On March 8, 2016, Piko Interactive announced that they had acquired the rights to this game, and it was later released officially in May 2018. They are also planning to port this game to PC and "other" platforms.', 'https://en.wikipedia.org/wiki/Tyrannosaurus_Tex'),
  ('Q64711789', 'The World Is Not Enough is a 2001 action-adventure video game developed by 2n Productions and published by Electronic Arts for the Game Boy Color. The game was the final release of the video games based on the 1999 James Bond film The World Is Not Enough starring Pierce Brosnan, following the Nintendo 64 and PlayStation versions of the game. The game was released in North America on September 17, 2001 and in Europe on September 28, 2001.', 'https://en.wikipedia.org/wiki/The_World_Is_Not_Enough_(GBC_video_game)'),
  ('Q63228536', 'Tonka Raceway is a 1999 video game developed by Media Station and published by Hasbro Interactive. The game is for ages 5 and up.', 'https://en.wikipedia.org/wiki/Tonka_Raceway'),
  ('Q124322369', 'Trick Boarder (released in Japan as Trickboarder GP) is a 2000 video game developed by Act Studio and published by Natsume for the Game Boy Color. The game is a snowboard racing video game in which player select one of eight characters to compete with other racers through nine downhill courses. Natsume adapted the engine of the game from the Game Boy Color version of Tony Hawk''s Pro Skater, and showcased the game at E3 2000. Upon release, Trick Boarder received mixed to negative reviews, with criticism directed at the game''s lack of variety and faulting its visual presentation and flow of gameplay.', 'https://en.wikipedia.org/wiki/Trick_Boarder'),
  ('Q74014645', 'Daikatana is a 2000 action-adventure game developed by Will and published by Kemco for the Game Boy Color. It is based on the first-person shooter of the same name, which was released earlier in 2000. Players control a swordsmaster who travels through various time periods in an effort to obtain the eponymous Daikatana, a powerful sword tied to the fate of the world.

Developed separately from the original game, the Game Boy Color version of Daikatana was designed as an adventure game at the request of creator John Romero. It was released in Europe in September 2000 and in Japan as a download for the Nintendo Power peripheral in May 2001; a planned North American release was cancelled due to the original version''s negative reputation. The game received generally positive reviews, with critics regarding it as superior to the original Daikatana.', 'https://en.wikipedia.org/wiki/Daikatana_(GBC_video_game)'),
  ('Q9359604', 'Inspector Gadget: Operation Madkactus is a video game based on the television show of the same name.', 'https://en.wikipedia.org/wiki/Inspector_Gadget:_Operation_Madkactus'),
  ('Q63225525', 'Oddworld Adventures 2 is a Game Boy Color platform game developed by Saffire and published by GT Interactive in 2000. It is a spin-off off the Oddworld series based upon the title Oddworld: Abe''s Exoddus, released in 1998.', 'https://en.wikipedia.org/wiki/Oddworld_Adventures_2'),
  ('Q124333359', 'Speedy Gonzales: Aztec Adventure is a 2000 video game developed and published by Sunsoft for the Game Boy Color. The game is a licensed platformer depicting the Looney Tunes animated cartoon character Speedy Gonzales, who the player controls across six stages set in Mexico. Upon release, Speedy Gonzales received average to mixed reviews, with critics praising the visual presentation of the game but faulting its platform gameplay mechanics, difficulty, and performance.', 'https://en.wikipedia.org/wiki/Speedy_Gonzales:_Aztec_Adventure'),
  ('Q115109288', 'Tech Deck Skateboarding is a Game Boy Color game developed by Handheld Games and released in 2001, based upon the Tech Deck brand of fingerboard skateboard toys.', 'https://en.wikipedia.org/wiki/Tech_Deck_Skateboarding'),
  ('Q115137359', 'Dragon Dance (released in Japan in 1998 as Pocket Color Block) is a 2000 action game for the Game Boy Color developed by Natsume Co., Ltd. and published in the United States by Crave Entertainment. The game is a paddle-and-ball game similar to the arcade video game Breakout.', 'https://en.wikipedia.org/wiki/Dragon_Dance_(video_game)'),
  ('Q67766220', 'Billy Bob''s Huntin''-n-Fishin is a 1999 video game developed by Saffire and published by Midway Games for the Game Boy Color. As Billy Bob, players undertake a range of activities including hunting, fishing and shooting, supported by several minigames. Upon release, the game received mixed reviews, with critics faulting the simplistic gameplay and the redneck theme of the title.', 'https://en.wikipedia.org/wiki/Billy_Bob%27s_Huntin%27-n-Fishin%27'),
  ('Q125869204', 'Enix was a Japanese video game publishing company founded in September 1975 by Yasuhiro Fukushima. Initially a tabloid publisher named Eidansha Boshu Service Center, it ventured in 1982 into video game publishing for Japanese home computers such as the PC-8800 series, the X1 series, and the FM-7. Enix initially found games to release by holding contests for programming hobbyists and publishing the winners, with the first titles appearing in February 1983. Enix continued to hold contests and publish the winners through 1993. When Enix moved into traditional publishing for video game consoles in 1985, it began with ports of two of its more successful games, Door Door (1983) and The Portopia Serial Murder Case (1983). From that point onward, Enix served as a publisher for both video games developed independently by other companies as well as for titles in franchises owned by Enix and created by licensed developers. Enix''s flagship franchise was the Dragon Quest series of console games, developed primarily by Chunsoft; some of the games, such as Dragon Quest VII (2000), have sold millions of copies, and the series as a whole has sold over 85 million copies as of March 2022.', 'https://en.wikipedia.org/wiki/List_of_Enix_games'),
  ('Q7897206', 'Uno is a 1999 video game developed by HotGen and published by Mattel for the Game Boy Color. It is based on the card game of the same name.', 'https://en.wikipedia.org/wiki/Uno_(1999_video_game)'),
  ('Q115428248', 'Pocket Bowling is a bowling video game developed by Athena and published by Jaleco for the Game Boy Color. The game was a launch title for the Japanese release of the Game Boy Color and the first bowling game for the platform.', 'https://en.wikipedia.org/wiki/Pocket_Bowling'),
  ('Q785735', 'Test Drive 2001 is a racing video game developed by American studio Xantera and published by Infogrames exclusively for Game Boy Color. It is the last game in the series to be available on Game Boy Color, and the last on a Nintendo platform in general.', 'https://en.wikipedia.org/wiki/Test_Drive_2001'),
  ('Q16262935', 'Denki Blocks! is a puzzle video game developed by Denki and originally released in 2001 by Rage Games for Sky Gamestar and the Game Boy Color and Game Boy Advance. In the game, players manoeuvre different coloured blocks around a grid to join those of the same colour together. The game features versus modes for multiple players. Denki Blocks! was ported to the PlayStation Portable in 2011 by Tiger Games, and to Android the same year and iOS in 2010.

Many features had to be added to meet price requirements. Denki Blocks! was released in the United States in 2002 by Majesco. The game received positive reviews, with critics praising the gaily coloured graphics, but a major criticism of the iOS version was the lack of an online leaderboard.', 'https://en.wikipedia.org/wiki/Denki_Blocks!'),
  ('Q16267583', 'Dinosaur''us is a platform and role-playing video game developed by RFX Interactive and co-published by Light & Shadow Production and Electronic Arts. It was released for Nintendo''s Game Boy Color on 2 February 2001 in the United Kingdom. However, its release was cancelled in the United States.

The gameplay involved the player taking control of a newly hatched baby dinosaur and controlling it around the game, avoiding hazards and pits like in platform games. However, in addition, enemies were fought in turn-based fashion like on the Pokémon games which were popular on the same console at the same time. Health lost in battles with enemies could be regained in the platform play.', 'https://en.wikipedia.org/wiki/Dinosaur%27us'),
  ('Q16267716', 'Robot Wars: Metal Mayhem is the first video game based on the British game show Robot Wars. It was released exclusively for Game Boy Color on 7 December 2000. It was the first of four games based on the show, with the first three selling over 250,000 copies. The game was based on the third series of the show, and competitors such as its champion Chaos 2 feature in the game.

In the game, a competitor robot from the series, or a robot created by the player, is entered into combat against a robot controlled by the game. A bout finishes when one robot''s health bar is fully depleted. In the Tournament Mode, the first robot to win two bouts advances. The game features the arena obstacles and House Robots of the series, and in other modes, a selection of mini-games based on the show''s side events.', 'https://en.wikipedia.org/wiki/Robot_Wars:_Metal_Mayhem'),
  ('Q11271773', 'Chee-Chai Alien is a video game developed by Creatures, Inc. and released on the Game Boy Color in Japan on February 27, 2001. It was designed and developed by Hirokazu Tanaka.

It utilizes the Game Boy Color''s infrared port and has a built-in rumble feature. It is compatible with the Game Boy Printer. Because the game must use the Game Boy Color''s IR sensor, the game will display an error screen when inserted in a Game Boy or a Game Boy Advance, being one of the only Game Boy Color games that the GBA does not support.

Players use the infrared sensor on the Game Boy Color to find artificial light sources, to which the Game Pak responds by rumbling. The game comes with a "spectrum communicator", a plastic device that can be attached to the Game Boy Color to enhance the sensitivity of the infrared sensor. However, even with the attachment, the game still struggled to detect light sources.', 'https://en.wikipedia.org/wiki/Chee-Chai_Alien'),
  ('Q134301071', 'Woody Woodpecker Racing is a 2000 kart racing game developed and published by Konami for the Game Boy Color. It features characters from the Woody Woodpecker franchise and offers a variety of gameplay modes and tracks. The game, as well as its PlayStation and PC counterpart, was the result of a partnership between Konami and Universal Interactive that allowed Konami to distribute and market video games based on Universal Studios franchises. It received mixed reviews, with some praise going to its depth and polish, mixed assessments of its difficulty and criticism toward its slow pace.', 'https://en.wikipedia.org/wiki/Woody_Woodpecker_Racing_(GBC_video_game)'),
  ('Q134718795', 'NBA 3 on 3 featuring Kobe Bryant is a 1999 basketball video game developed by Left Field Productions and published by Nintendo. The game simulates play of 3x3 basketball with NBA licensed teams and players. The game was a handheld successor to the Nintendo 64 title Kobe Bryant in NBA Courtside, also by Left Field Productions. Upon release, NBA 3 on 3 received average reviews, with critics praising the customisation options but critiquing the graphics and sound.', 'https://en.wikipedia.org/wiki/NBA_3_on_3_featuring_Kobe_Bryant'),
  ('Q11322148', 'Trade & Battle: Card Hero is a card battle role-playing game developed by Nintendo and Intelligent Systems and published by Nintendo for the Game Boy Color. It was released in Japan on February 21, 2000. A sequel, Kousoku Card Battle: Card Hero, was released in 2007.', 'https://en.wikipedia.org/wiki/Trade_%26_Battle:_Card_Hero'),
  ('Q136772665', 'The Powerpuff Girls games are a series of three 2D platform game developed by Los Angeles-based studio Sennari Interactive and published by BAM! Entertainment for the Game Boy Color. They are based on The Powerpuff Girls animated series on Cartoon Network. The series includes The Powerpuff Girls: Bad Mojo Jojo, The Powerpuff Girls: Paint the Townsville Green, and The Powerpuff Girls: Battle Him. Players can trade character cards across versions when linked together with the Game Boy Color''s Game Link Cable accessory.', 'https://en.wikipedia.org/wiki/The_Powerpuff_Girls_(Sennari_Interactive_games)'),
  ('Q130341191', 'Croc 2 is a 2001 platformer video game developed by Natsume Co., Ltd. and published by THQ for the Game Boy Color (GBC). It is part of the Croc series and the second game in the series for the GBC after Croc (2000). It is an adaptation of Croc 2 (1999) for the PlayStation and Windows. The game utilizes 2D sprite graphics, in contrast to the 3D polygon graphics featured in the 1999 game.', 'https://en.wikipedia.org/wiki/Croc_2_(2001_video_game)'),
  ('Q134605558', 'The Grinch is a 2000 video game developed and published by Konami for the Game Boy Color. A maze video game with stealth elements, the player controls the Grinch and his dog Max, who must navigate mazes and steal presents while avoiding detection from citizens. The game, as well as its console and PC counterpart, was the result of a partnership between Konami and Universal Interactive that allowed Konami to distribute and market video games based on Universal Studios franchises. The game received mixed reviews from critics, who widely noted its similarities to Pac-Man and Metal Gear Solid and approved of its premise and presentation, with individual criticisms directed at its short length, repetitive gameplay, low difficulty, and lack of features.', 'https://en.wikipedia.org/wiki/The_Grinch_(GBC_video_game)'),
  ('Q137506886', 'Matchbox: Emergency Patrol is a 2001 racing video game for Microsoft Windows and the Game Boy Color developed by Sandbox Studios and published by THQ. The game is a Mattel-licensed title for the Matchbox series of toy cars, allowing the player to respond to emergencies whilst driving police cars, ambulance trucks and fire engines. Upon release, the game received mixed reviews, with critics finding the game fun but critiquing its gameplay as simplistic and repetitive.', 'https://en.wikipedia.org/wiki/Matchbox:_Emergency_Patrol'),
  ('Q137580001', 'Road Champs: BXS Stunt Biking is a 2000 video game developed by London-based studio HotGen and published by Activision for the Game Boy Color.', 'https://en.wikipedia.org/wiki/Road_Champs:_BXS_Stunt_Biking'),
  ('Q137580145', 'Quest: Fantasy Challenge is a 1999 video game for the Game Boy Color developed by C-Lab and published by Virgin Interactive Entertainment in Europe and Sun Corporation in the United States. The game is a spinoff of the Nintendo 64 title Quest 64, featuring arcade gameplay similar to Dig Dug and Mr. Do!. Upon release, Fantasy Challenge received mixed reviews.', 'https://en.wikipedia.org/wiki/Quest:_Fantasy_Challenge'),
  ('Q137609287', 'Gex: Enter the Gecko is a 1998 platformer video game by David A. Palmer IMS Productions for the Game Boy Color. It takes its themes for levels from the 3D platform game Gex: Enter the Gecko (1998) while maintaining some abilities from the 2D game Gex (1995).

The game was published by Crave Entertainment in November 1998. Along with Virtual Pool 64 (1998), Milo''s Astro Lanes (1998) for the Nintendo 64 and Pitfall: Beyond the Jungle (1998) and Men in Black: The Series for the Game Boy Color, the games gave Crave a $40 million proft in the fourth quarter of 1998.

The game received positive reviews from Game Informer and Total Games while IGN and the Los Angeles Times found it to be too simple of a game to hold a player''s attention for extended periods of play.', 'https://en.wikipedia.org/wiki/Gex:_Enter_the_Gecko_(GBC_video_game)'),
  ('Q137636614', 'Gex 3: Deep Pocket Gecko is a 1999 platformer video game developed by David A. Palmer IMS Productions and published by Eidos Interactive for the Game Boy Color. It is part of the Gex of games, where the player controls a gecko named Gex through a series of television and film-themed 2D side-scrolling levels where he collects various items to progress through the game. In the game, Gex is trying to reach Agent Xtra who has been kidnapped and must reach his long-standing enemy Rez-Raker to do so.

Gex 3: Deep Pocket Gecko follows Gex: Enter the Gecko (1998) as the second game in the series for the Game Boy Color. It follows a similar plot and level scheme as the earlier console game Gex 3: Deep Cover Gecko (1999). Reviewers complimented the animation of Gex in the game with some reviewers finding the large levels in it to be positive while others found it detracted from its overall quality. While IGN and Video Games  found it superior to the previous Gex game on the system, reviewers in Computer and Video Games and Player One  found it inferior to the many platforming titles available on the Game Boy Color.', 'https://en.wikipedia.org/wiki/Gex_3:_Deep_Pocket_Gecko'),
  ('Q138803408', 'Rip-Tide Racer is a 2000 video game developed and published by Cryo Interactive for the Game Boy Color. Players race futuristic hoverbikes named waterpods across eight courses. Upon release, the game received negative reviews, with most critics finding the game was difficult to control, and competing racers were too slow to be challenging.', 'https://en.wikipedia.org/wiki/Rip-Tide_Racer'),
  ('Q130760918', 'Toonsylvania is a 2000 video game developed by RFX Interactive and published by Ubi Soft for the Game Boy Color. It is based on the Toonsylvania television series.', 'https://en.wikipedia.org/wiki/Toonsylvania_(video_game)'),
  ('Q96377174', 'There have been a variety of Sesame Street video games released for video game platforms. Most of the Sesame Street video games were published and developed by NewKidCo.', 'https://en.wikipedia.org/wiki/Sesame_Street_video_games'),
  ('Q96603710', 'Shrek: Fairy Tale Freakdown is an action fighting video game developed by Prolific and published by TDK Mediactive for the Game Boy Color. Based on the 2001 animated film, it released in North America on May 29, 2001, and in the United Kingdom on July 6, 2001.', 'https://en.wikipedia.org/wiki/Shrek:_Fairy_Tale_Freakdown'),
  ('Q16267750', 'The Adventures of Elmo in Grouchland was published by NewKidCo for Game Boy Color and Mattel Media for Windows in 1999. This game is a platforming side scroller based on the movie of the same name.', 'https://en.wikipedia.org/wiki/The_Adventures_of_Elmo_in_Grouchland_(video_game)'),
  ('Q16259740', 'The Little Mermaid II: Pinball Frenzy is a 2000 pinball video game developed by Left Field Productions and published by Nintendo for the Game Boy Color. First released in North America on September 24, 2000, it was later made available in PAL regions on March 16, 2001.

The Little Mermaid II: Pinball Frenzy is based on the 1989 film The Little Mermaid and its 2000 sequel The Little Mermaid II: Return to the Sea. In it, the player interacts with two pinball tables based on the mermaid Ariel and her daughter Melody. It features 16 minigames, which were identified as a primary part of the game. The Little Mermaid II: Pinball Frenzy supports up to four players through alternating tables.', 'https://en.wikipedia.org/wiki/The_Little_Mermaid_II:_Pinball_Frenzy'),
  ('Q29867432', 'Motocross Maniacs 2 (released as Crazy Bikers in Europe) is a 1999 racing game for the Game Boy Color, developed and published by Konami. A sequel to the 1989 Game Boy title Motocross Maniacs, the game is a racing game in which the player drives across a side-scrolling motocross course.', 'https://en.wikipedia.org/wiki/Motocross_Maniacs_2'),
  ('Q972268', 'Resident Evil Gaiden is a 2001 action-adventure game developed by M4 for the Game Boy Color. It was published by Capcom in Japan and North America, and by Virgin Interactive in Europe. Receiving generally mixed reviews by critics, the game marks a departure from other entries in the series, insofar as areas are explored with the playable character seen from a top-down perspective and with battles fought in first-person view. The story revolves around a viral outbreak on a passenger ship and has Leon S. Kennedy and Barry Burton return as protagonists. This game is non-canon, as its plot is contradicted by the main series in key parts, and its events are ignored.', 'https://en.wikipedia.org/wiki/Resident_Evil_Gaiden'),
  ('Q39070413', 'Croc is a scrolling platform game for the Game Boy Color (GBC) developed by British studio Virtucraft with assistance from Argonaut Games and published by THQ under license from Fox Interactive. Released on 6 June 2000, it is a 2D remake of the 1997 3D platform game Croc: Legend of the Gobbos with similar gameplay. The game follows Croc, a crocodile, on a quest to save a race of furry creatures called Gobbos from the evil Baron Dante. The game received mixed reviews from critics. A second game for the GBC, Croc 2, was released in 2001, based on the 1999 game of the same title.', 'https://en.wikipedia.org/wiki/Croc_(2000_video_game)'),
  ('Q39058559', 'Men in Black 2: The Series is an action video game developed by David A. Palmer Productions and published by Crave Entertainment for the Game Boy Color. It is based on the animated television series, Men in Black: The Series, and is a sequel to the 1999 video game of the same name. Crave Entertainment announced the game in March 2000, and released it in the United States in July 2000.', 'https://en.wikipedia.org/wiki/Men_in_Black_2:_The_Series'),
  ('Q28127215', 'The Powerpuff Girls games are a series of three 2D platform game developed by Los Angeles-based studio Sennari Interactive and published by BAM! Entertainment for the Game Boy Color. They are based on The Powerpuff Girls animated series on Cartoon Network. The series includes The Powerpuff Girls: Bad Mojo Jojo, The Powerpuff Girls: Paint the Townsville Green, and The Powerpuff Girls: Battle Him. Players can trade character cards across versions when linked together with the Game Boy Color''s Game Link Cable accessory.', 'https://en.wikipedia.org/wiki/The_Powerpuff_Girls_(Sennari_Interactive_games)'),
  ('Q30591282', 'Hollywood Pinball is a 1999 pinball video game developed by Tarantula Studios, first published by Take-Two Interactive Software in the EU for Game Boy Color in April 1999. Hollywood Pinball was unreleased within the United States.

Hollywood Pinball is a pinball game with several different themed tables taking inspiration from popular movies of the time.', 'https://en.wikipedia.org/wiki/Hollywood_Pinball'),
  ('Q33890877', 'Trouballs is a 2001 Game Boy Color puzzle video game developed by Paragon Five and published by Capcom Entertainment. The game was developed out of Paragon Five''s studio in Wrocław, Poland, founded and led by Paul Bragiel.', 'https://en.wikipedia.org/wiki/Trouballs'),
  ('Q28127368', 'Wendy: Every Witch Way is an action platform video game published by TDK Mediactive and developed by WayForward Technologies for the Game Boy Color in 2001. The game centers on Wendy the Good Little Witch from the Casper the Friendly Ghost series. Wendy accidentally opens her aunts'' chest containing magical stones, which upset the gravity of a floating castle that crashes onto her house. The player controls Wendy through four worlds with sixteen levels, with each world having three side-scrolling levels and one horizontal shooter stage. Inserting the game in the Game Boy Advance unlocks a new world exclusive to the console.', 'https://en.wikipedia.org/wiki/Wendy:_Every_Witch_Way'),
  ('Q39073874', 'Men in Black: The Series is an action platform video game developed by Tiertex Design Studios and published by Crave Entertainment for the Game Boy Color (GBC) on December 14, 1998. The game is based on the animated television series of the same name, and was followed by a sequel titled Men in Black 2: The Series, released for the Game Boy Color in 2000.

In May 2001, Crave announced plans for another game, also titled Men in Black: The Series, to be released on the Game Boy Advance (GBA). The game, developed by David A. Palmer Productions, was released in the US on September 11, 2001, while a European version was released on September 28, 2001.', 'https://en.wikipedia.org/wiki/Men_in_Black:_The_Series_(video_game)'),
  ('Q28452472', 'Turok 2: Seeds of Evil is an action-platform video game developed by Bit Managers and published by Acclaim Entertainment. It was released for the Game Boy Color handheld game console in 1998 alongside its Nintendo 64 counterpart. The game is backward compatible with the original Game Boy in monochrome mode. Although the game is set in the same world as its counterpart, it features a different storyline.', 'https://en.wikipedia.org/wiki/Turok_2:_Seeds_of_Evil_(GBC_video_game)'),
  ('Q28452572', 'Turok 3: Shadow of Oblivion is an action video game developed by Bit Managers and published by Acclaim Entertainment. It was released for the Game Boy Color handheld game console in 2000 alongside its Nintendo 64 counterpart. Although the game is set in the same universe as its counterpart, it features a different storyline.', 'https://en.wikipedia.org/wiki/Turok_3:_Shadow_of_Oblivion_(GBC_video_game)'),
  ('Q28452644', 'Turok: Rage Wars is an action video game developed by Bit Managers and published by Acclaim Entertainment for the Game Boy Color handheld console in 1999. Although the game is set in the same universe as its Nintendo 64 counterpart, it is a different game. The game received generally favorable reviews from critics.', 'https://en.wikipedia.org/wiki/Turok:_Rage_Wars_(GBC_video_game)'),
  ('Q30591082', 'Austin Powers: Oh, Behave! and Austin Powers: Welcome to My Underground Lair! are minigame-based action games based on the Austin Powers franchise. They were developed by Tarantula Studios, and published by Rockstar Games. Both games were released simultaneously for Game Boy Color, on September 18, 2000, in North America and November 3, 2000, in Europe. The two games are able to connect to one another, with Oh, Behave starring Austin Powers and Welcome to My Underground Lair! starring Dr. Evil.

The games were poorly received by critics.', 'https://en.wikipedia.org/wiki/Austin_Powers:_Oh,_Behave!_and_Welcome_to_My_Underground_Lair!'),
  ('Q117706379', 'Harry Potter and the Philosopher''s Stone (released in the United States as Harry Potter and the Sorcerer''s Stone) is a 2001 role-playing video game developed by Griptonite Games and published by Electronic Arts for the Game Boy Color. Based on the 1997 novel of the same name, the player controls Harry Potter, who must navigate his first year in the Hogwarts School of Witchcraft and Wizardry and eventually confront the villainous Lord Voldemort.

The Game Boy Color version was released simultaneously with the PlayStation and Game Boy Advance versions, and had the longest development cycle of the three versions. The game received mixed reviews from critics, who praised the visuals and faithfulness to the novel, but had lukewarm reactions to the audio and criticized the standard battle system and lack of a map function.', 'https://en.wikipedia.org/wiki/Harry_Potter_and_the_Philosopher%27s_Stone_(GBC_video_game)'),
  ('Q25991443', 'Pokémon Gold Version and Pokémon Silver Version are 1999 role-playing video games developed by Game Freak and published by Nintendo for the Game Boy Color. They are the first installments in the second generation of the Pokémon video game series. They were released in Japan on November 21st, 1999, Australia and North America on October 15th, 2000, and Europe on April 6th, 2001.

The games introduce 100 new species of Pokémon and follow the progress of the player character in their quest to master Pokémon battling. Both games are independent of each other but feature largely the same plot and, while both can be played separately, it is necessary to trade between these games and their predecessors in order to fully complete each game''s Pokédex. The Johto Saga of the Pokémon anime is based on the new region introduced in the games.', 'https://en.wikipedia.org/wiki/Pok%C3%A9mon_Gold_and_Silver'),
  ('Q25991446', 'Pokémon Gold Version and Pokémon Silver Version are 1999 role-playing video games developed by Game Freak and published by Nintendo for the Game Boy Color. They are the first installments in the second generation of the Pokémon video game series. They were released in Japan on November 21st, 1999, Australia and North America on October 15th, 2000, and Europe on April 6th, 2001.

The games introduce 100 new species of Pokémon and follow the progress of the player character in their quest to master Pokémon battling. Both games are independent of each other but feature largely the same plot and, while both can be played separately, it is necessary to trade between these games and their predecessors in order to fully complete each game''s Pokédex. The Johto Saga of the Pokémon anime is based on the new region introduced in the games.', 'https://en.wikipedia.org/wiki/Pok%C3%A9mon_Gold_and_Silver'),
  ('Q116969227', 'The Legend of Zelda: Link''s Awakening DX is a 1998 action-adventure game developed and published by Nintendo for the Game Boy Color. The game is a colorized version of the 1993 Game Boy title The Legend of Zelda: Link''s Awakening, in which protagonist Link must fight monsters, explore dungeons and solve puzzles to escape from Koholint Island. The DX version of Link''s Awakening features gameplay additions including a color-themed dungeon and support for the Game Boy Printer.

Upon release, Link''s Awakening DX was critically acclaimed, with reviewers commending the game on the strengths of the original title and welcoming the addition of color graphics and new features, although noting the additions were largely insubstantial compared to the original game. The DX version of Link''s Awakening has retrospectively been cited by critics as one of the best games for the Game Boy and Game Boy Color systems. It was subsequently re-released on the Nintendo 3DS via the Virtual Console and the Nintendo Switch via the Nintendo Classics service.', 'https://en.wikipedia.org/wiki/The_Legend_of_Zelda:_Link%27s_Awakening_DX'),
  ('Q115767427', 'Armada F/X Racers is a 2000 video game for the Game Boy Color, developed by Metropolis Digital and published by Metro3D. The game is a futuristic-themed racing game based on the 1999 Dreamcast game Armada.', 'https://en.wikipedia.org/wiki/Armada_F/X_Racers'),
  ('Q115778105', 'Dracula: Crazy Vampire is a 2001 action game for the Game Boy Color developed by Planet Interactive Development and published by DreamCatcher Interactive. The game was licensed as part of the Universal Studios Monsters franchise used for Universal Studios books and toys featuring Count Dracula.', 'https://en.wikipedia.org/wiki/Dracula:_Crazy_Vampire'),
  ('Q115804311', 'F-18 Thunder Strike is a 2000 action game for the Game Boy Color developed by Morning Star Multimedia and published by Majesco. The game is a simplified first-person combat flight simulator in which the player operates a F-18 Hornet for the United States Air Force, who have has confirmed reports of renewed hostile activity in the Balkans and order an aerial assault on the region.', 'https://en.wikipedia.org/wiki/F-18_Thunder_Strike'),
  ('Q115804442', 'Cool Bricks is a 1999 block breaker game developed by Pukka Games and published by SCi Games. The game is an adaptation of the arcade game Breakout for the Game Boy Color.', 'https://en.wikipedia.org/wiki/Cool_Bricks'),
  ('Q115804850', '3D Pocket Pool is a 2001 pool game for the Game Boy Color, developed by Aardvark Software and published by Virgin Interactive.', 'https://en.wikipedia.org/wiki/3D_Pocket_Pool'),
  ('Q115804942', 'Babe and Friends is a 1999 Game Boy Color game developed by Aqua Pacific Ltd, based upon the 1995 film Babe.', 'https://en.wikipedia.org/wiki/Babe_and_Friends'),
  ('Q115805561', 'Chase H.Q.: Secret Police is a 1999 vehicular combat game developed by Dreams Co. Ltd and ITL Co. Ltd and published by Metro3D for the Game Boy Color. The game is an installment in the Chase H.Q. series, which began with a 1988 arcade game by Taito.', 'https://en.wikipedia.org/wiki/Chase_H.Q.:_Secret_Police'),
  ('Q115805460', 'Xtreme Wheels is a 2001 racing game developed by Spike and published by BAM! Entertainment for the Game Boy Color. Compared to Excitebike, the game is a BMX racing game in which the player competes with other riders to finish a motocross course.', 'https://en.wikipedia.org/wiki/Xtreme_Wheels'),
  ('Q115811406', 'Klustar is a 1999 Game Boy Color game developed by Rebellion Developments and published by Infogrames. Similar to Tetris, the game is a puzzle game requiring the player to manipulate and match patterns on a grid of blocks.', 'https://en.wikipedia.org/wiki/Klustar'),
  ('Q48703014', 'Stuart Little: The Journey Home is a 2001 platform game developed by Tiertex Design Studios and published by Activision for the Game Boy Color, and is a licensed game based upon the 1999 film of the same name.', 'https://en.wikipedia.org/wiki/Stuart_Little:_The_Journey_Home'),
  ('Q18754123', 'Rugrats: Time Travelers (spelled as Rugrats: Time Travellers in PAL regions) is a 1999 platform game developed by Software Creations Limited and published by THQ, Inc. for the Game Boy Color. It was released on October 27, 1999, in North America. It is the second game based on the Nickelodeon animated television series Rugrats to release for the system and the first Game Boy Color-exclusive title. Its plot follows the Rugrats characters traversing over 10 levels via a time machine found in a toy store. The game was re-released in 2026 as part of the Rugrats: Retro Rewind Collection compilation.', 'https://en.wikipedia.org/wiki/Rugrats:_Time_Travelers'),
  ('Q16677736', 'Spirou: The Robot Invasion (released in French-speaking countries as Spirou: La Panique mécanique) is a 2000 Game Boy Color game developed by Planet Interactive Development and produced by Ubi Soft. The game is based upon the eponymous character of the Belgian comic strip magazine Spirou, and is a follow-up to the 1996 Game Boy title of the same name.', 'https://en.wikipedia.org/wiki/Spirou:_The_Robot_Invasion'),
  ('Q4021193', 'X-Men: Mutant Wars is a side-scrolling beat ''em up game for Game Boy Color released in 2000. It is the second X-Men titled released for the system. It was released to coincide with the release of the X-Men film on DVD.

X-Men: Mutant Wars was followed by a sequel in 2001 titled X-Men: Wolverine''s Rage.', 'https://en.wikipedia.org/wiki/X-Men:_Mutant_Wars'),
  ('Q4021199', 'X-Men: Wolverine''s Rage is a side-scrolling video game for the Game Boy Color. A sequel to X-Men: Mutant Wars (2000), Wolverine''s Rage follows the story of Wolverine as he chases down Lady Deathstrike, Sabretooth, and Cyber.', 'https://en.wikipedia.org/wiki/X-Men:_Wolverine%27s_Rage'),
  ('Q16555066', 'Daffy Duck: Fowl Play (japanese: Daffy Duck: Subette Koron de Oogane Mochi) is a 2D platform video game featuring the Looney Tunes character Daffy Duck. It was released for the Game Boy Color in 1999 in North America and 2000 in Japan and Europe. The game is compatible with the original Game Boy.', 'https://en.wikipedia.org/wiki/Daffy_Duck:_Fowl_Play'),
  ('Q117886626', 'Dragon''s Lair is a 2001 action video game developed by Digital Eclipse and published by Capcom for the Game Boy Color handheld game console. An adaptation of the 1983 arcade title, players control protagonist Dirk the Daring who is tasked with rescuing Princess Daphne from the dragon Singe. In doing so, players must avoid various obstacles and foes using quick reaction inputs to get from one scene to another. If an action command is failed, Dirk loses a life. A new feature introduced into this game was the tutorial, which allowed players to practice certain parts of the game.

The Game Boy Color version originated as a demonstration of Digital Eclipse''s full-motion video compression technology, displayed at the Classic Gaming Expo. It was later presented to Dragon''s Lair creators Rick Dyer and Don Bluth, and gained Dyer''s approval. Designers Jeremy Mika and Mike Mika brought on programmer Cathryn Mataga to help with development, who scrapped much of what they had done. Capcom USA was ultimately chosen as the publisher for this game due to their prior history with both Digital Eclipse and the Dragon''s Lair franchise with Dragon''s Lair 3D: Return to the Lair.', 'https://en.wikipedia.org/wiki/Dragon%27s_Lair_(GBC_video_game)'),
  ('Q4677120', 'Action Man: Search for Base X is an action video game developed by Natsume Co., Ltd. and published by THQ under license from Hasbro Interactive for the Game Boy Color. It was released in North America on January 30, 2001, and is based on the Action Man TV series.', 'https://en.wikipedia.org/wiki/Action_Man:_Search_for_Base_X'),
  ('Q116265550', 'Gobs of Games, released in Europe as Games Frenzy, is a 2000 video game for the Game Boy Color developed by 2N Productions and published by The 3DO Company, who showcased the game at E3 2000. The game is a compilation of compilation of puzzle games, including simplified iterations of traditional games, including peg solitaire, checkers and tic tac toe.', 'https://en.wikipedia.org/wiki/Gobs_of_Games'),
  ('Q933822', 'This is a list of video games based on the Transformers television series and movies, or featuring any of the characters.

Transformers games have been released for the ZX Spectrum, Commodore 64, Family Computer, Family Computer Disk System, Microsoft Windows, Mac OS, PlayStation, Game Boy Color, Nintendo 64, PlayStation 2, Mobile, iOS, Android, webOS, BlackBerry OS, and Virtual Console. Hasbro sold the digital gaming rights of various properties, including My Little Pony, Magic: The Gathering, Tonka, Playskool, and The Transformers, to Infogrames for $100 million USD in 2000, and then it bought back the rights for $65 million USD in June 2005.', 'https://en.wikipedia.org/wiki/List_of_Transformers_video_games'),
  ('Q21563313', 'Ultimate Paintball is a video game for the Game Boy Color which was released in 2000.

It was developed by Morning Star Multimedia and published by Majesco. It was released in September 2000 in North America and in 2000 in Europe for the Game Boy Color.

The game was planned to be released on the Game Boy Advance at some point, but it was ultimately cancelled. The developer was supposed to be Pipe Dream Interactive, Majesco''s in-house development company.

The game was distributed by Take-Two Interactive in Europe.', 'https://en.wikipedia.org/wiki/Ultimate_Paintball'),
  ('Q58864649', 'Rhino Rumble is a 2002 game for the Game Boy Color developed by Lost Boys Games and published by Telegames. The game is a side-scrolling platformer set in the jungle.', 'https://en.wikipedia.org/wiki/Rhino_Rumble'),
  ('Q4049863', 'Spawn is a 1999 action-adventure game developed and published by Konami for the Game Boy Color, based on the Spawn comic book character. The game was noted for its extensive use of digitized speech in cutscenes, a largely uncommon feature in games for the system.', 'https://en.wikipedia.org/wiki/Spawn_(1999_video_game)'),
  ('Q115776460', 'Merlin is a 2000 action game for the Game Boy Color developed by French company RFX Interactive, published in Europe by Light & Shadow Production and Electronic Arts. The game is a platformer that takes place in a fantasy setting inspired by the mythical figure Merlin.', 'https://en.wikipedia.org/wiki/Merlin_(video_game)'),
  ('Q55622305', 'Mary-Kate and Ashley: Pocket Planner is a digital planner and video game developed by American studio Powerhead Games and published by Acclaim Entertainment. It was released on November 21, 2000, for the Game Boy Color. It is part of the Mary-Kate and Ashley video game series. The user can keep track of the time and take notes while also playing through a number of minigames. Mary-Kate and Ashley are featured extensively throughout the planner. Reception was mixed, with criticism focused on the shortcomings of the game and its gendered focus and content while praising its clever features.', 'https://en.wikipedia.org/wiki/Mary-Kate_and_Ashley:_Pocket_Planner'),
  ('Q21039925', 'Winnie the Pooh: Adventures in the 100 Acre Wood is an adventure game developed by NewKidCo and TOSE and published by NewKidCo and Disney Interactive. It was released in North America in March 2000 and in Japan on July 7, 2000 for the Game Boy Color.

The game follows Winnie the Pooh as he interacts with other characters in the wood. Most of the game uses a board game structure, where the player rolls a dice and draws cards to move around on the map in an attempt to explore the wood. The game is aimed at a younger demographic and was designed to be simple. It was the first Winnie the Pooh game to be released on a video game console.', 'https://en.wikipedia.org/wiki/Winnie_the_Pooh:_Adventures_in_the_100_Acre_Wood'),
  ('Q51000295', 'Asteroids is a 1979 multidirectional shooter video game developed and published by Atari, Inc. for arcades. It was released by Taito and Sega in Japan. The player controls a spaceship in an asteroid field which is periodically traversed by flying saucers. The object of the game is to shoot and destroy the asteroids and saucers while avoiding colliding with either or being hit by the saucers'' counterfire. The game becomes more difficult as the number of asteroids increases.

Asteroids was conceived and designed by Lyle Rains and Ed Logg, who decided to use hardware developed by Wendi Allen (then known as Howard Delman) that was previously used for Lunar Lander. Asteroids was based on an unfinished game titled Cosmos; its physics model, control scheme, and gameplay elements were derived from Spacewar!, Computer Space, and Space Invaders and refined through trial and error. The game is rendered on a vector display in a two-dimensional view that wraps around both screen axes.', 'https://en.wikipedia.org/wiki/Asteroids_(video_game)'),
  ('Q4035127', 'Bionic Commando: Elite Forces is a 2000 platform video game developed by Nintendo Software Technology and published by Nintendo for the Game Boy Color. Part of Capcom''s Bionic Commando series developed under license by Nintendo, it was the first title to be developed by its Redmond-based first-party studio Nintendo Software Technology. It is the sequel to the Game Boy version of Bionic Commando. It was not released in Europe until November 2014, when it was finally released for the Nintendo 3DS Virtual Console there.', 'https://en.wikipedia.org/wiki/Bionic_Commando:_Elite_Forces'),
  ('Q115452165', 'The Land Before Time is a 2001 Game Boy Color platform game developed by Eclipse Entertainment Ltd and published by Swing! Entertainment in Europe and Conspiracy Entertainment in North America, based upon the 1988 film of the same name. A separate game featuring the same name was released for the Game Boy Advance by Full Fat in 2002.', 'https://en.wikipedia.org/wiki/The_Land_Before_Time_(2001_video_game)'),
  ('Q22019737', 'Return of the Ninja is a platform game with stealth elements developed by Act Japan and published by Natsume Inc. for the Game Boy Color in 2001 as a spiritual successor to 1990''s Shadow of the Ninja.', 'https://en.wikipedia.org/wiki/Return_of_the_Ninja'),
  ('Q4035488', 'Buffy the Vampire Slayer is a 2000 beat ''em up game developed by GameBrains and published by THQ for the Game Boy Color. Based on the television show Buffy the Vampire Slayer, the game features Buffy Summers, who fights vampires, demons, and other supernatural entities as the Slayer. The player controls Buffy through eight side-scrolling levels, and gameplay centers on one-on-one fights with vampires. The game received negative reviews, with reviewers criticizing its gameplay and graphics.', 'https://en.wikipedia.org/wiki/Buffy_the_Vampire_Slayer_(2000_video_game)'),
  ('Q19707296', 'The Moomins or Moomintrolls (Swedish: Mumintrollen, pronounced [ˈmʉːmɪnˌtrɔlːɛn]) are the central characters in a series of novels, short stories, picture books, and a comic strip by the Finnish writer and illustrator Tove Jansson, originally published in Swedish by the Finnish publisher Schildts. They are a family of white, round fairy-tale characters with large snouts that make them resemble the hippopotamus. However, despite this resemblance, the Moomin family are trolls who live in a house in Moominvalley.

Between 1945 and 1993, Jansson wrote a series of nine books, and created five picture books and a long-running comic strip. The Moomins have inspired numerous television series, films, music, theatre productions, video games, and theme parks. In popular culture, the Moomins have appeared on a wide range of merchandise, sold in shops around the world, and as a livery for some Finnair aircraft.', 'https://en.wikipedia.org/wiki/Moomins'),
  ('Q723623', 'Blaster Master: Enemy Below, known in Japan as Metafight EX, is a 2000 run and gun video game released by Sunsoft for the Game Boy Color. It was also re-released for the Virtual Console on the Nintendo 3DS system in 2011, and on the Nintendo Classics service in 2023.', 'https://en.wikipedia.org/wiki/Blaster_Master:_Enemy_Below'),
  ('Q39306034', 'The Fish Files is a 2001 adventure game developed by the Italian team 7th Sense and published by MC2-Microïds on the Game Boy Color.', 'https://en.wikipedia.org/wiki/The_Fish_Files'),
  ('Q18087995', 'Mario Golf is a 1999 sports video game developed by Camelot Software Planning and published by Nintendo for the Game Boy Color. It is a companion to the Nintendo 64 game of the same, and sees players competing in golf on various themed courses. The game features a story mode with role-playing elements where the player selects a character and improves their golfing abilities by winning matches with the goal to eventually compete against Mario.

The game was received positively by critics. A sequel, Mario Golf Advance Tour, would release in 2004.', 'https://en.wikipedia.org/wiki/Mario_Golf_(GBC_video_game)'),
  ('Q938360', 'Commander Keen is a 2001 platform video game developed by David A. Palmer Productions and published by Activision for the Game Boy Color. Part of the Commander Keen series, it was released ten years after the first seven episodes in 1990–91. The game follows the titular Commander Keen, an eight-year-old child genius, as he journeys through three alien worlds to collect three plasma crystals to prevent the weapon they power, built by several enemies from previous games, from destroying the universe. The game features Keen running, jumping, and shooting through various levels while opposed by aliens, robots, and other hazards.', 'https://en.wikipedia.org/wiki/Commander_Keen_(video_game)'),
  ('Q28126588', 'The Powerpuff Girls games are a series of three 2D platform game developed by Los Angeles-based studio Sennari Interactive and published by BAM! Entertainment for the Game Boy Color. They are based on The Powerpuff Girls animated series on Cartoon Network. The series includes The Powerpuff Girls: Bad Mojo Jojo, The Powerpuff Girls: Paint the Townsville Green, and The Powerpuff Girls: Battle Him. Players can trade character cards across versions when linked together with the Game Boy Color''s Game Link Cable accessory.', 'https://en.wikipedia.org/wiki/The_Powerpuff_Girls_(Sennari_Interactive_games)'),
  ('Q3978766', 'Sweet Ange is a Game Boy Color game from the Angelique series by KOEI. It is a cooking (confection making) simulation with some dating sim elements. The player is given a choice of four protagonists: Angelique Limoges, Rosalia de Catargena, Angelique Collet, or Rachel Hart.

The story takes place several years before the events in the first Angelique game and all the characters are correspondingly younger. The Guardians are known as the Sweet Knights, each of them associated with a confection/drink category. The goal of this game is to win the Rose Contest - the Smallney Academy cooking contest and become friends with the Sweet Knights along the way. As it is in an alternate universe setting, it is generally not considered to be part of a story arc in the series.', 'https://en.wikipedia.org/wiki/Sweet_Ange'),
  ('Q4037876', 'Earthworm Jim: Menace 2 the Galaxy is a 1999 platform video game developed by David A. Palmer Productions and published by Crave Entertainment for the Game Boy Color. It is the fourth and final installment in the Earthworm Jim series. The game received mixed reviews, with critics considering it inferior to the first two games in the series.', 'https://en.wikipedia.org/wiki/Earthworm_Jim:_Menace_2_the_Galaxy'),
  ('Q17985733', 'Barbie: Magic Genie Adventure is a single-player adventure/action game developed by Vicarious Visions and published by Mattel Interactive. It was released on the Game Boy Color on November 1, 2000.', 'https://en.wikipedia.org/wiki/Barbie:_Magic_Genie_Adventure'),
  ('Q4546897', '10-Pin Bowling is a bowling video game developed by Morning Star Multimedia and published by Majesco for the Game Boy Color. Originally announced for Game Boy before shifting development to the newer system, 10-Pin Bowling is one of few Game Boy Color games to support rumble, which is achieved by utilizing a rumble pak built directly into the cartridge.', 'https://en.wikipedia.org/wiki/10-Pin_Bowling_(video_game)'),
  ('Q115816544', 'Pocket Music is a 2002 video game developed by Jester Interactive and published by Rage Games for the Game Boy Color and Game Boy Advance. The game is a handheld adaptation of the Music series of games released by the developer, and allows players to create tracks of music from pre-recorded samples using a grid-based interface.', 'https://en.wikipedia.org/wiki/Pocket_Music'),
  ('Q47473836', 'Noddy and the Birthday Party is a children''s video game released only in Europe for the Game Boy Color in 2000. It was developed by Tiertex Design Studios and published by BBC Multimedia. The game is based on the character Noddy by Enid Blyton (specifically the TV series Noddy''s Toyland Adventures), as well as the fictional universe in which he resides. The focus of the plot and gameplay is the preparation of the character Big-Ears'' upcoming birthday party. The game received mixed to negative reviews from critics.', 'https://en.wikipedia.org/wiki/Noddy_and_the_Birthday_Party'),
  ('Q914334', 'Toki Tori is a puzzle-platform video game developed by Two Tribes and published by Capcom for the Game Boy Color. The game follows a young chick, Toki Tori, and his quest to rescue his younger siblings, still in their eggs. To progress through the game, the player must pick up each egg on a level using a set number of tools, with new tools being introduced as the player progresses through the four worlds. This usually involves careful planning and creative thinking.

Toki Tori was later released for Windows Mobile and an enhanced remake was released for Nintendo''s Wii via WiiWare after Two Tribes acquired the rights to the game. In the Summer of 2009, Chillingo published another enhanced remake of the game for the iOS. In 2010, Two Tribes released a Windows remake on Steam. A DRM-free version of the game was released in January 2012 as part of the Humble Bundle for Android. This marked a simultaneous release of the game on OS X, Linux and Android. The original version of the game was re-released on the Nintendo 3DS''s eShop as a Virtual Console title on 31 August 2012, and an HD remake of the game was released for the Wii U eShop on 7 November 2013. An updated version of Toki Tori was released on the Nintendo 3DS eShop on 5 November 2015. A release for the Nintendo Switch eShop followed on 30 March 2018.', 'https://en.wikipedia.org/wiki/Toki_Tori'),
  ('Q4039658', 'Grandia: Parallel Trippers is a role-playing video game developed by Game Arts for the Game Boy Color handheld system as part of their Grandia series. Published by Hudson Soft and released exclusively in Japan in December 2000, the game is a spin-off of the first Grandia title, and features characters, music, and a similar battle system to the original. Unlike its predecessor, Parallel Trippers is presented using entirely two-dimensional graphics and character sprites, with combat sequences that take place from first-person perspective that utilize "Synthesis Cards" instead of direct actions. New features include a database of all possible combat actions, as well a monster and character catalog that fills as the player progresses through the game.', 'https://en.wikipedia.org/wiki/Grandia:_Parallel_Trippers');

insert into import_summary (wikidata_id, summary, source) values
  ('Q18149321', 'Disney''s Beauty and the Beast: A Board Game Adventure is a 1999 party video game developed by Left Field Productions and published by Nintendo for the Game Boy Color.', 'https://en.wikipedia.org/wiki/Disney%27s_Beauty_and_the_Beast:_A_Board_Game_Adventure'),
  ('Q6406209', 'Whilst merchandise for The Railway Series books by Wilbert Awdry was produced alongside the books, since the original broadcast of its television adaptation Thomas & Friends in 1984 in the United Kingdom, much more merchandise was produced for the television series. Large numbers of manufacturers have sought to produce items based on the Thomas & Friends franchise after the original television series was broadcast in the United States and Japan.

The most popular and wide-ranging merchandise are models of the characters, some including accompanying railway systems. Other popular products include videos, books and magazines, computer and video games, audiobooks, annuals, colouring and activity books, jigsaw puzzles, board games, stationery, clothing, cutlery, household items such as curtains, duvet covers and lampshades and soft drinks.', 'https://en.wikipedia.org/wiki/The_Railway_Series_and_Thomas_%26_Friends_merchandise'),
  ('Q6547375', 'Lil'' Monster, known as Gem Gem Monster in Japan, is a video game for the Game Boy Color handheld, published by Agetec. The game entailed players to train small monsters used for training and battling, and collect sixty kinds of gem and six gem chips, while defeating Cool Joe who has become infamous for his evil deeds and cheating all across the land, in gem battles which his brother, Hot Joe, invented.', 'https://en.wikipedia.org/wiki/Lil%27_Monster'),
  ('Q6434143', 'Koto Battle: Tengai no Moribito is a role-playing video game developed and published by AlphaDream for the Game Boy Color. It was released only in Japan on March 9, 2001.', 'https://en.wikipedia.org/wiki/Koto_Battle:_Tengai_no_Moribito'),
  ('Q6349722', 'This list of Game Boy Color games includes 915 licensed releases from the Game Boy Color''s launch in 1998 to the final release in 2003. The last official release for the system was Doraemon no Study Boy: Kanji Yomikaki Master, which was released in Japan on July 18, 2003. However, multiple unlicensed games (many of which are developed and distributed by fans) have been released since then. Additionally, there were several games which were developed and officially licensed, but were cancelled before release.

Games were released under two classes of cartridges. "Dual Mode" cartridges are compatible with Game Boy systems that predate the Game Boy Color, and feature both Game Boy and Game Boy Color versions of the game on the cartridges. Their boxes are labeled "Compatible with Game Boy" and the cartridges are typically molded in black to distinguish them from original Game Boy cartridges. Many of them also support features of the Super Game Boy peripheral for the Super Nintendo Entertainment System. Cartridges compatible only with the Game Boy Color, Game Boy Advance, Game Boy Advance SP, and the Game Boy Player peripheral for the GameCube typically feature the disclaimers "Only for Game Boy Color" and "Not compatible with other Game Boy systems!" on their box art and sometimes on the cartridge, with the cartridge typically made of clear plastic.', 'https://en.wikipedia.org/wiki/List_of_Game_Boy_Color_games'),
  ('Q6699624', 'Lufia: The Legend Returns is a role-playing video game for the Game Boy Color developed by Neverland and published by Taito, Natsume Inc., and Ubi Soft in Japan, North America, and Europe, respectively, in 2001. It is the third game in the Lufia series and the first one to appear on a handheld gaming system.', 'https://en.wikipedia.org/wiki/Lufia:_The_Legend_Returns'),
  ('Q6341335', 'The Legend of Zelda: Oracle of Seasons and The Legend of Zelda: Oracle of Ages are 2001 action-adventure games developed by Flagship and published by Nintendo for the Game Boy Color. They are the seventh and eighth installments in the Legend of Zelda series.

The gameplay and graphics are similar to that of Link''s Awakening (1993) for the Game Boy. The player controls Link from an overhead perspective. Oracle of Ages focuses on puzzles, while Oracle of Seasons focuses on action. The games can interact with one other via passwords or a Game Link Cable. In Seasons, Link uses the Rod of Seasons to controls the seasons and change the environment. In Ages, he uses the Harp of Ages to travel between the past and the present.', 'https://en.wikipedia.org/wiki/The_Legend_of_Zelda:_Oracle_of_Seasons_and_Oracle_of_Ages'),
  ('Q6498545', 'Laura''s Happy Adventures is a 1998 adventure game developed by Ubi Soft Montreal and published by Ubi Soft, released as part of the Playmobil Interactive series of products. The setting is based on Playmobil''s Victorian dollhouse line. The game''s storyline revolves around a good-natured young girl named Laura as she solves the mystery of a magic diamond by helping the people around her. A Game Boy Color-exclusive version, simply re-titled Laura, was produced and released in 2000.', 'https://en.wikipedia.org/wiki/Laura%27s_Happy_Adventures'),
  ('Q6675663', 'Looney Tunes Collector: Martian Revenge! (Known as simply Looney Tunes: Marvin Strikes Back! in North America) is a Looney Tunes game developed and published by Infogrames for the Game Boy Color in 2000. It is a sequel to Looney Tunes Collector: Martian Alert!, as both share near-identical gameplay.', 'https://en.wikipedia.org/wiki/Looney_Tunes_Collector:_Martian_Revenge!'),
  ('Q6675674', 'Looney Tunes Collector: Martian Alert! (Known as simply Looney Tunes Collector: Alert! in North America) is a Looney Tunes game developed and published by Infogrames for the Game Boy Color in 2000.

A sequel: Looney Tunes Collector: Martian Revenge!, was released a few months later, and shares near-identical gameplay, except it is played from Marvin the Martian''s perspective.', 'https://en.wikipedia.org/wiki/Looney_Tunes_Collector:_Martian_Alert!'),
  ('Q6651158', 'Little Nicky is a 2000 licensed platform game developed by Digital Eclipse and published by Ubi Soft for the Game Boy Color. Based on the comedy film of the same name, the game was released exclusively in North America. The player controls the half-demon/angel Nicky and utilizes his demonic powers in order to traverse 24 levels inspired by events from the titular film. Outside of the main game, the player can also partake in five different minigames. Critical reception towards the game was mixed, with many reviewers praising its visuals and risqué elements, while a myriad of reactions were given towards the game''s audio and gameplay.', 'https://en.wikipedia.org/wiki/Little_Nicky_(video_game)'),
  ('Q3611777', 'Aliens: Thanatos Encounter is a 2001 shooter video game developed by Crawfish Interactive and based on the Alien science-fiction horror film series. It was published by THQ and released for the Game Boy Color handheld game console. The game takes place aboard Thanatos, an abandoned freighter that has been infested with Alien creatures.', 'https://en.wikipedia.org/wiki/Aliens:_Thanatos_Encounter'),
  ('Q1860996', 'Scooby-Doo! Classic Creep Capers is an adventure game published by THQ for the Nintendo 64 and Game Boy Color, based on the Hanna-Barbera cartoon Scooby-Doo, Where Are You!. The Nintendo 64 version, developed by Terraglyph Interactive Studios, was released in November 2000, while the Game Boy Color version was developed by Digital Eclipse Software, and released in February 2001. A PlayStation version, identical to the Nintendo 64 version, had been in development by Terraglyph Interactive Studios but was later cancelled.', 'https://en.wikipedia.org/wiki/Scooby-Doo!_Classic_Creep_Capers'),
  ('Q7271470', 'Quest for Camelot is a 1998 action role-playing game developed by Titus Interactive and published by Nintendo for the Game Boy Color. It is based on the film of the same title under license from Warner Bros. The game is compatible with Game Boy, Super Game Boy, and Game Boy Printer. A Nintendo 64 version was planned but was canceled due to the film''s poor performance at the box office.

The game was added to the Nintendo Classics service on September 6, 2023.', 'https://en.wikipedia.org/wiki/Quest_for_Camelot_(1998_video_game)'),
  ('Q4777508', 'Antz Racing is a 2001 video game for the Game Boy Color, developed by RFX Interactive and published by Light and Shadow Production with Acclaim Entertainment co-publishing in North America and Electronic Arts co-publishing in Europe. The game is a kart racing game based on the 1998 film Antz.', 'https://en.wikipedia.org/wiki/Antz_Racing'),
  ('Q4823238', 'Austin Powers: Oh, Behave! and Austin Powers: Welcome to My Underground Lair! are minigame-based action games based on the Austin Powers franchise. They were developed by Tarantula Studios, and published by Rockstar Games. Both games were released simultaneously for Game Boy Color, on September 18, 2000, in North America and November 3, 2000, in Europe. The two games are able to connect to one another, with Oh, Behave starring Austin Powers and Welcome to My Underground Lair! starring Dr. Evil.

The games were poorly received by critics.', 'https://en.wikipedia.org/wiki/Austin_Powers:_Oh,_Behave!_and_Welcome_to_My_Underground_Lair!'),
  ('Q3933909', 'Revelations: The Demon Slayer is a role-playing video game developed by Access and Multimedia Intelligence Transfer, and published by Atlus, Index and Sega, initially released on Game Boy on December 25, 1992 in Japan under the name ‘''Megami Tensei Gaiden: Last Bible’''. It is the first color RPG for Game Boy Color released in North America.', 'https://en.wikipedia.org/wiki/Revelations:_The_Demon_Slayer'),
  ('Q3551619', 'Yu-Gi-Oh! Dark Duel Stories is a 2000 digital collectible card game of the Yu-Gi-Oh! universe for the Game Boy Color, developed and published by Konami. The game was Konami''s first attempt at a Yu-Gi-Oh! game released in English and the third game in the Japanese Duel Monsters series. This game uses the rules of the previous Duel Monsters games, as opposed to the rules for the Yu-Gi-Oh! Trading Card Game. Players of the game can trade and battle with other players using a link cable.', 'https://en.wikipedia.org/wiki/Yu-Gi-Oh!_Dark_Duel_Stories'),
  ('Q1126115', 'Conker''s Pocket Tales is a 1999 action-adventure game developed and published by Rare for the Game Boy Color. It is the first game in the Conker series and follows the story of Conker the Squirrel as he retrieves his stolen birthday presents and rescues his girlfriend Berri, who has been kidnapped by the Evil Acorn. The cartridge is dual-format, allowing it to also run on the original Game Boy and the Super Game Boy with some gameplay differences.', 'https://en.wikipedia.org/wiki/Conker%27s_Pocket_Tales'),
  ('Q5520530', 'Ganbare Goemon: Seikūshi Dynamites Arawaru!! is the eighteenth Ganbare Goemon game, released for the Game Boy Color on December 21, 2000. The game was re-released in 2026 via the Ganbare Goemon! Daishūgō compilation.', 'https://en.wikipedia.org/wiki/Ganbare_Goemon:_Seik%C5%ABshi_Dynamites_Arawaru!!'),
  ('Q5520534', 'Ganbare Goemon: Mononoke Dōchū Tobidase Nabe-Bugyō! is a role-playing video game developed by Konami Computer Entertainment Kobe and released by Konami for the Game Boy Color on December 16, 1999. It is the seventeenth installment in the Ganbare Goemon series overall.', 'https://en.wikipedia.org/wiki/Ganbare_Goemon:_Mononoke_D%C5%8Dch%C5%AB_Tobidase_Nabe-Bugy%C5%8D!'),
  ('Q5922850', 'Hoyle Card Games is a Game Boy Color-only video game that was developed by Sandbox Studios and published by Sierra On-Line under their Sierra Attractions label.', 'https://en.wikipedia.org/wiki/Hoyle_Card_Games'),
  ('Q4797710', 'The Arthur video games franchise was a series of learning and interactive story video games based on the American-Canadian children''s TV show Arthur. The games were released in the 1990s and 2000s for PlayStation and Game Boy Color alongside Windows and Mac OS computers.', 'https://en.wikipedia.org/wiki/Arthur_video_games'),
  ('Q4777509', 'Antz is a video game developed by French studio Planet Interactive and released in 1999 by Infogrames for the Game Boy Color. It is based on the film of the same name.', 'https://en.wikipedia.org/wiki/Antz_(video_game)'),
  ('Q1149174', 'There have been numerous sports games featuring Mario characters, based, among others, on tennis, golf, baseball, soccer, and various sports featured in the Olympic Games.

The Mario Kart and F1 series are not included in this list.', 'https://en.wikipedia.org/wiki/List_of_sports_video_games_featuring_Mario'),
  ('Q7353296', 'Robot Ponkottsu, commonly abbreviated as Robopon, is a role-playing video game for the Game Boy Color. It focuses on a boy and his adventures on an island with his robotic Robopon friends, while collecting and battling other Robopon. Players could exchange data wirelessly over infrared using "GB Kiss" features built into the cartridge.

The game was initially split between two versions, Robot Ponkottsu Sun Version and Robot Ponkottsu Star Version, which were published by Hudson Soft in 1998. An expanded version with additional features, Robot Ponkottsu Moon Version, was released the following year, alongside the limited edition Robot Ponkottsu Comic BomBom Special Version, which features art based on the concurrently-running Robopon manga. Only Robopon Sun Version was localized into English, being published by Atlus in North America in December 2000.', 'https://en.wikipedia.org/wiki/Robopon'),
  ('Q2310820', 'Mega Man Xtreme is a 2000 platform game developed and published by Capcom for the Game Boy Color. It is a spin-off title in the Mega Man X series of video games that originated on the Super Nintendo Entertainment System. Mega Man Xtreme takes place within the series timeline during the 22nd century, in which a group of "Maverick" androids called the "Shadow Hunters" hack into the world''s "Mother Computer" system, destabilize all of the networks, and allow other Mavericks to cause rampant destruction all over the world. The heroic "Maverick Hunter" X is tasked with going into cyberspace to relive his past missions and put a stop to the group''s plans.', 'https://en.wikipedia.org/wiki/Mega_Man_Xtreme'),
  ('Q5288724', 'Dokapon?! Millennium Quest is a 2000 role-playing game developed and published by Asmik Ace Entertainment in Japan on July 14, 2000.', 'https://en.wikipedia.org/wiki/Dokapon_MillenniumQuest'),
  ('Q3646676', 'Bugs Bunny & Lola Bunny: Operation Carrot Patch is a 1998 Game Boy Color video game starring Bugs Bunny and Lola Bunny.', 'https://en.wikipedia.org/wiki/Bugs_Bunny_%26_Lola_Bunny:_Operation_Carrot_Patch'),
  ('Q5445318', 'Ferret Monogatari: Watashi no Okini Iri (Ferret Story: My Dear Ferret) is a Japan-only digital pet video game for Game Boy Color created by Culture Brain. Ferret Monogatari is a simulation style game in which the players take care of a ferret.

At the start the players choose one of three different coloured ferrets. The colours are randomly chosen.

The ferret is kept in the cage much of the time. The players have to keep its water and food topped up, and clean its litter box. They can take own ferret out for walks or to play with. They can even play minigames. One is a race, one is putting together a picture and the other is dancing.', 'https://en.wikipedia.org/wiki/Ferret_Monogatari:_Watashi_no_Okini_Iri'),
  ('Q5359710', 'Elevator Action EX is an update to the Game Boy version of Elevator Action published by Altron in 2000. In addition to colour, players can choose between three characters: Mike, an all rounded character, Guy, a slower yet more durable character, and Sarah, a faster yet weaker character.

This game was redesigned and published by BAM! Entertainment as Dexter''s Laboratory: Robot Rampage in the US, which uses Dexter''s Laboratory characters.', 'https://en.wikipedia.org/wiki/Elevator_Action_EX'),
  ('Q1632811', 'San Francisco Rush 2049 is a 1999 racing video game developed and published by Atari Games for arcades. It was later ported to home systems. It is the third game in the Rush series as the sequel to San Francisco Rush: Extreme Racing and Rush 2: Extreme Racing USA as well as the last to be set in the city of San Francisco. An updated version with fixes and more tracks was later released subtitled Tournament Edition.

The game was ported to the Nintendo 64, Game Boy Color, and Dreamcast starting in September 2000 under the Midway Games West label, which Midway Games had replaced the Atari Games name with. The Dreamcast version was later re-released as part of Midway Arcade Treasures 3 for the PlayStation 2, Xbox, and GameCube and later for Microsoft Windows as part of Midway Arcade Treasures Deluxe Edition. A sequel, Hot Rod Rebels, was under development but cancelled. The next entry in the series would be L.A. Rush in 2005, which would not be set in the city of San Francisco.', 'https://en.wikipedia.org/wiki/San_Francisco_Rush_2049'),
  ('Q2201706', 'The Simpsons: Night of the Living Treehouse of Horror is a platform game published by THQ on March 19, 2001, for the Game Boy Color. Developed by Software Creations, it is based on the Treehouse of Horror episodes of the animated television series The Simpsons. The game features seven side-scrolling levels in which the player controls the members of the Simpson family. Night of the Living Treehouse of Horror has received average reviews from critics, with praise directed at the design.', 'https://en.wikipedia.org/wiki/The_Simpsons:_Night_of_the_Living_Treehouse_of_Horror'),
  ('Q3782923', 'Hamtaro: Ham-Hams Unite! is an action video game developed by Pax Softnica and Nintendo and published by for the Game Boy Color handheld video game console. It is based on the Hamtaro anime and features much of the same characters. It launched in Japan in 2001, and later came to North America and Europe in 2002 and 2003 respectively. It was the final video game published on the Game Boy Color by Nintendo. Players control the hamster Hamtaro, who is tasked with gathering his friends and returning them to the clubhouse as well as collecting words missing from the Hamchat dictionary.

The game received generally positive reception, with reviewers such as IGN and Eurogamer noting its success as both a game for children and a game that could appeal to older audiences. It was the seventh best-selling game for the Game Boy Color in Japan. The successor of the 2000 Game Boy Color game Tottoko Hamtaro: Tomodachi Daisakusen Dechu, it was followed by Hamtaro: Ham-Ham Heartbreak in 2003 for the Game Boy Advance which featured similar gameplay mechanics.', 'https://en.wikipedia.org/wiki/Hamtaro:_Ham-Hams_Unite!'),
  ('Q5268360', 'Dexter''s Laboratory: Robot Rampage is an action video game published by Bay Area Multimedia for the Game Boy Color and released in the United States on November 28, 2000. It is a graphically redesigned version of the game Elevator Action EX, also developed by Altron, with characters from the American animated television series Dexter''s Laboratory from Cartoon Network.', 'https://en.wikipedia.org/wiki/Dexter%27s_Laboratory:_Robot_Rampage'),
  ('Q4765202', 'Animorphs is a 2000 game for the Game Boy Color. It is based upon the Scholastic book series Animorphs by K. A. Applegate.', 'https://en.wikipedia.org/wiki/Animorphs_(GBC_video_game)'),
  ('Q5283792', 'Diva Starz: Mall Mania (released as Diva Starz in Europe) is an action video game developed by Digital Illusions Canada and published by Vivendi Universal Interactive Publishing for the Game Boy Color. It was released in North America on November 1, 2001, Europe in 2002, and is based on Mattel''s Diva Starz dolls.

The game follows four playable dolls from the Diva Starz line as they play through six different stages. As the player completes each stage with one doll, it subsequently gets harder through subsequent levels. The game received negative reviews from critics.', 'https://en.wikipedia.org/wiki/Diva_Starz:_Mall_Mania'),
  ('Q5743244', 'Heroes of Might and Magic is a series of games that were remade for the Game Boy Color. They are based on early games in the original Heroes of Might and Magic series. The remakes were developed by KnowWonder and published by The 3DO Company.', 'https://en.wikipedia.org/wiki/Heroes_of_Might_and_Magic_(GBC_video_game)'),
  ('Q5300226', 'Doug is an American animated sitcom created by Jim Jinkins and produced by Jumbo Pictures. It originally aired on Nickelodeon from August 11, 1991, to January 2, 1994. The Disney seasons would air on ABC from September 7, 1996, to March 20, 1999, with several episodes airing in syndication from October 19, 1998, to April 12, 1999. The show focuses on the early adolescent life and zany hijinks of its eponymous character, Doug Funnie, who experiences common predicaments while attending school in his new hometown of Bluffington. Doug narrates each story in his journal, and the show incorporates many imagination sequences. The series addresses numerous topics, including trying to fit in, platonic and romantic relationships, self-esteem, bullying, and rumors. Many episodes center on Doug''s attempts to impress his classmate and crush, Patti Mayonnaise.', 'https://en.wikipedia.org/wiki/Doug_(TV_series)'),
  ('Q5399203', 'NBA Jam 2001 is a sports Game Boy Color game made by Acclaim Entertainment as licensed basketball simulation for the 2001-2002 NBA season. It was the follow-up to NBA Jam 2000. It featured Karl Malone, Jason Williams, Reggie Miller, Jason Kidd, Latrell Sprewell, and Scottie Pippen on the cover.', 'https://en.wikipedia.org/wiki/NBA_Jam_2001'),
  ('Q5422374', 'The Berenstain Bears is a children''s literature franchise created by Stan and Jan Berenstain and continued by their son, Mike Berenstain. The books feature a family of anthropomorphic grizzly bears who generally learn a moral or safety-related lesson in the course of each story.

Since the 1962 debut of the first Berenstain Bears book, The Big Honey Hunt, the series has grown to over 400 titles, which have sold approximately 260 million copies in 23 languages. The Berenstain Bears franchise has also expanded well beyond the books, encompassing television series and a wide variety of other products and licenses. While enjoying decades of popularity and receiving numerous awards, the series has been criticized for its perceived saccharine tone and formulaic storytelling.', 'https://en.wikipedia.org/wiki/Berenstain_Bears'),
  ('Q2135136', 'Wario Land 3, known in Japan as Wario Land 3: Mysterious Music Box, is a 2000 platform game developed by Nintendo R&D1 and published by Nintendo for the Game Boy Color. The game''s plot centers around Wario who must free a mysterious figure who is trapped inside a music box. The game was released in Japan on March 21, 2000, Europe on April 14, 2000, and North America on May 30, 2000.

The game was later re-released for the Nintendo 3DS Virtual Console in 2013, and as part of the Nintendo Classics service on February 8, 2023.', 'https://en.wikipedia.org/wiki/Wario_Land_3'),
  ('Q2078596', 'The Legend of Zelda: Oracle of Seasons and The Legend of Zelda: Oracle of Ages are 2001 action-adventure games developed by Flagship and published by Nintendo for the Game Boy Color. They are the seventh and eighth installments in the Legend of Zelda series.

The gameplay and graphics are similar to that of Link''s Awakening (1993) for the Game Boy. The player controls Link from an overhead perspective. Oracle of Ages focuses on puzzles, while Oracle of Seasons focuses on action. The games can interact with one other via passwords or a Game Link Cable. In Seasons, Link uses the Rod of Seasons to controls the seasons and change the environment. In Ages, he uses the Harp of Ages to travel between the past and the present.', 'https://en.wikipedia.org/wiki/The_Legend_of_Zelda:_Oracle_of_Seasons_and_Oracle_of_Ages'),
  ('Q2351151', 'Dragon Quest Monsters, released in North America as Dragon Warrior Monsters, is the first video game in the Dragon Quest Monsters series. It was released in Japan by Enix on September 25, 1998, and co-published by Eidos Interactive in Europe and North America in 2000. It was the first Dragon Quest game to be released in Europe. The game cartridge is compatible with both the black-and-white Game Boy and the Game Boy Color; a second printing of the game was made after the Game Boy Color itself was released. The game was remade for the PlayStation in a compilation Dragon Quest Monsters 1+2 Hoshi Furi no Yūsha to Bokujō no Nakamatachi. A mobile phone incarnation titled Dragon Quest Monsters i was released in Japan on January 28, 2002.', 'https://en.wikipedia.org/wiki/Dragon_Warrior_Monsters'),
  ('Q2029195', 'Pokémon Pinball is a pinball-based Pokémon spin-off video game for the Game Boy Color. It was released in Japan on April 14, 1999, and in North America on June 29, 1999. In it, the ball is a Poké Ball, and most of the objects on the table are Pokémon-related.

Like any pinball game, the main objective is to get points, using the different modes of advances to score them at a higher rate. Pokémon Pinball has a secondary objective, which is to collect all 151 Pokémon to fill your Pokédex. The Pokédex is saved between individual games, so it can be built up over time.', 'https://en.wikipedia.org/wiki/Pok%C3%A9mon_Pinball'),
  ('Q2019427', 'Tales of Phantasia: Narikiri Dungeon is a role-playing video game for the Game Boy Color released by Namco on November 10, 2000, selling 136,000 copies. Tales of Phantasia: Narikiri Dungeon''s characteristic genre name is Dungeon RPG. It is the third main title and the first sequel in the Tales series, which normally does not have connected storylines. The story begins 205 years after the beginning of Tales of Phantasia.

Due to the limits of the Game Boy, the game uses a battle system called Petit LMBS, a turn-based variation on the Linear Motion Battle System used by the rest of the series. As in normal LMBS, the player controls only one character and does so via button combinations instead of a dialog choice, while party members are computer-controlled. A remake of the game was later released on PlayStation Portable called Tales of Phantasia: Narikiri Dungeon X.', 'https://en.wikipedia.org/wiki/Tales_of_Phantasia:_Narikiri_Dungeon'),
  ('Q2560049', 'Pokémon Trading Card Game, known in Japan as Pokémon Card GB, is a 1998 digital collectible card video game developed by Hudson Soft and Creatures and published by Nintendo for the Game Boy Color. It is an adaptation of the card game of the same name. It was initially released in Japan in December 1998 and internationally in 2000. The game includes the first three sets of the trading card game, as well as exclusive cards not available elsewhere.

A second Game Boy Color game, Pokémon Card GB2: Great Rocket-Dan Sanjo! (Pokémon Card GB2: Here Comes Team Great Rocket!), was released in Japan in 2001, having a centered storyline. Although this sequel was not released in North America or Europe, several enthusiasts have released unofficial English translations.', 'https://en.wikipedia.org/wiki/Pok%C3%A9mon_Trading_Card_Game_(video_game)'),
  ('Q2451909', 'Super Mario Bros. Deluxe (also known as Super Mario Bros. DX) is a 1999 platform game developed and published by Nintendo for the Game Boy Color. It is a largely unaltered port of the 1985 Super Mario Bros., originally released for the Nintendo Entertainment System (NES), with an unlockable version of its 1986 Japanese sequel, Super Mario Bros.: The Lost Levels. The game also introduces several new features, including a single-player and two-player race mode, a challenge mode for individual levels, and various toys and collectibles, some of which utilize the functionality of the Game Boy Printer.', 'https://en.wikipedia.org/wiki/Super_Mario_Bros._Deluxe'),
  ('Q6878465', 'Mission: Impossible is an adventure video game based upon the Mission: Impossible film series. It was developed by Rebellion Developments and published by Infogrames for the Game Boy Color in 1999.', 'https://en.wikipedia.org/wiki/Mission:_Impossible_(1999_video_game)'),
  ('Q6902808', 'Monster Rancher Battle Card GB, known in Japan as Monster Farm Battle Card GB is a strategy video game developed by Graphic Research and released in 1999 by Tecmo for the Game Boy Color. It is the first game in Tecmo''s Monster Rancher Battle Card series, featuring a card game incorporating the popular characters from the Monster Rancher series. It was followed by a 2000 sequel Monster Rancher Battle Card Episode II for the PlayStation which featured additional monsters.', 'https://en.wikipedia.org/wiki/Monster_Rancher_Battle_Card_GB'),
  ('Q6902811', 'Monster Rancher Explorer (known as Solomon in Japan) is a 2000 puzzle game developed by Graphic Research and published by Tecmo for the Game Boy Color. It features the same gameplay elements as Solomon''s Key but includes Monster Rancher characters.', 'https://en.wikipedia.org/wiki/Monster_Rancher_Explorer'),
  ('Q6822711', 'Metal Walker, known as Bakusou Senki Metal Walker GB: Kotetsu no Yuujou in Japan, is a role-playing video game for the Game Boy Color, developed and published by Capcom. Many critics likened the game to the Pokémon series, but praised the game''s unique qualities. In Japan, the game inspired merchandise based on the Metal Walker robots.

Metal Walker''s battles are unique from other games in the genre due to their billiard-style nature. Players move their Metal Walkers across the battlefield by hitting them into items, walls, or enemy Metal Walkers.

The 2013 mobile game Monster Strike has a similar concept and gameplay mechanics but is otherwise unconnected to Metal Walker.', 'https://en.wikipedia.org/wiki/Metal_Walker'),
  ('Q6900797', 'Monkey Puncher is a video game for the Game Boy Color, developed by Atelier Double, and released in December 2000. The game''s goal is to train a monkey to fight in organised boxing matches in order to save the main character''s father and sibling.', 'https://en.wikipedia.org/wiki/Monkey_Puncher'),
  ('Q2591858', 'Tomb Raider (also known as Tomb Raider: The Nightmare Stone) is a 2000 action-adventure video game developed by Core Design and published by THQ for the Game Boy Color under license from series owner Eidos Interactive. Following series protagonist Lara Croft as she searches ruins in South America for a powerful artefact, the gameplay features platforming and puzzle-solving on a 2D side-scrolling environment.

Tomb Raider was the debut entry for the series on Nintendo platforms, with it being described by developers and journalists as technically impressive for the platform. It sold well for THQ, and was praised by critics for its technical achievements and emulation of the main series gameplay in portable form. Two sequels were released: Curse of the Sword in 2001 and The Prophecy in 2002.', 'https://en.wikipedia.org/wiki/Tomb_Raider_(GBC_video_game)'),
  ('Q7071857', 'O''Leary Manager 2000 is a football player-manager game developed by LiveMedia and published by Ubi Soft released in 2000 for the Game Boy Color. The player can choose whether they want to focus on the management side of football, play the matches themselves on the game''s 2D match engine, or combine the two features for a more in-depth experience. It is endorsed by Irish football manager David O''Leary, who was managing English Premier League side Leeds United at the time of the game''s release. The game was released as Guy Roux Manager 2000 in France, DSF Fußball Manager in Germany, Co Adriaanse Football Manager in the Netherlands and Barça Manager 2000 in Spain.', 'https://en.wikipedia.org/wiki/O%27Leary_Manager_2000'),
  ('Q2356104', 'Kirby Tilt ''n'' Tumble is an action puzzle video game developed and published by Nintendo for the Game Boy Color handheld video game console. It was released in Japan on August 23, 2000 and in North America on April 9, 2001. Due to the cartridge having a built-in Accelerometer, it has a unique shape, as well as a unique translucent pink color in reference to Kirby. The game received its first official re-release on the Nintendo Classics service on June 5, 2023.', 'https://en.wikipedia.org/wiki/Kirby_Tilt_%27n%27_Tumble'),
  ('Q2351827', 'Pokémon Crystal Version is a role-playing video game developed by Game Freak and published by Nintendo for the Game Boy Color, released in Japan in December 2000 and internationally throughout 2001. Serving as an enhanced edition of the 1999 titles Pokémon Gold and Silver, it is the final entry in the second generation of the Pokémon game series. The game introduced several new features, including additional story elements, a Battle Tower area, the option to play as a female protagonist, animated Pokémon sprites during battles, and various minor improvements. The Japanese version of the game also utilized the capabilities of the Mobile Adapter GB, a peripheral that allowed players to trade and battle over cell phones and a paid subscription service called "Mobile System GB". These enhancements were made possible by the Game Boy Color''s improved hardware, making Crystal the first game in the series to be incompatible with the original Game Boy.', 'https://en.wikipedia.org/wiki/Pok%C3%A9mon_Crystal'),
  ('Q7249303', 'Project S-11 is a game developed by Paragon 5 and published by Sunsoft for the Game Boy Color. It was released exclusively in North America on January 3, 2001.', 'https://en.wikipedia.org/wiki/Project_S-11'),
  ('Q7271465', 'Quest: Brian''s Journey is a 2000 role-playing video game published in North America by Sunsoft for the Game Boy Color. The game''s title screen instead displays the title as Quest RPG: Brian''s Journey.

The original Japanese version was published by Imagineer under the title Elemental Tale - Jack''s Great Adventure: Satan''s Counterattack. This game is a demake of another Imagineer product, the Nintendo 64 game Quest 64.', 'https://en.wikipedia.org/wiki/Quest:_Brian%27s_Journey'),
  ('Q2600361', 'Metal Gear: Ghost Babel, released in North America and Europe as Metal Gear Solid, is a 2000 action-adventure stealth game developed and published by Konami for the Game Boy Color. Development began after Konami Computer Entertainment Japan were commissioned by Konami''s European branch to develop a portable version of their 1998 PlayStation game Metal Gear Solid. However, Ghost Babel is not a port of Metal Gear Solid, but instead takes place in an alternative continuity set three years after the events of the MSX2 game Metal Gear 2: Solid Snake. Tose assisted on the development. The game was re-released in 2026 for the first time via Metal Gear Solid: Master Collection Vol. 2 under its Japanese name.', 'https://en.wikipedia.org/wiki/Metal_Gear:_Ghost_Babel'),
  ('Q7236403', 'Power Quest, known in Japan as Gekitō Power Modeler (Japanese: 激闘パワーモデラー), is a role-playing-based fighting video game developed by Japan System Supply for the Game Boy Color. It was published in Japan by Capcom on November 27, 1998, and published in North America by Sunsoft in December 1998. It later received a limited European release in July 1999.

In the game, a new craze has hit the town: fighting with model robots. The player walks around the town as the main character, but takes control of the model robot during fights. There are six robot models available, each with different stats and special moves. The models are Max, Gong, Axe, Speed, Lon and Borot. Over time, the player earns credits and buys parts to improve their model. In addition to the story mode, there is a versus mode that allows the player to fight immediately.', 'https://en.wikipedia.org/wiki/Power_Quest_(video_game)'),
  ('Q2758074', 'Harvest Moon 2 GBC, released in Japan as Bokujō Monogatari GB2, is a farming simulation video game for the Game Boy Color developed and published by Victor Interactive Software, and the second portable game in the Story of Seasons series. The object of the game is to cultivate a farm to prevent the land from being used to build an amusement park. As with the previous game, the player may choose to play as a boy or a girl.', 'https://en.wikipedia.org/wiki/Harvest_Moon_2_GBC'),
  ('Q2758082', 'Harvest Moon 3 GBC is a farm simulation video game for the Game Boy Color developed and published by Victor Interactive Software, part of the long-running Story of Seasons series of video games. The game was released for the Nintendo 3DS via Virtual Console in North America on December 11, 2014.', 'https://en.wikipedia.org/wiki/Harvest_Moon_3_GBC'),
  ('Q2745604', 'Tetris DX is a 1998 video game developed and published by Nintendo for the Game Boy Color. It is a version of the game Tetris and unlike the 1989 port of the game, it introduces color, new gameplay modes, save games, and multiplayer using the Game Link Cable. DX was released as a launch title for the Game Boy Color in October 1998. Upon release, the game received a positive reception, with praise directed towards its gameplay additions. Following release, critics praised the game as one of the best titles for the Game Boy Color.', 'https://en.wikipedia.org/wiki/Tetris_DX'),
  ('Q2710825', 'Bomberman Quest is an action role-playing game. The player takes the role of Bomberman, who has to defeat monsters and collect items to defeat the Commander bosses of each area. Bomberman Quest marks the departure of veteran composer, Jun Chikuma.', 'https://en.wikipedia.org/wiki/Bomberman_Quest'),
  ('Q2836700', 'Alice in Wonderland is a 2000 platform video game developed by Digital Eclipse and published by Nintendo for the Game Boy Color. It was released in North America on October 4, 2000. The game follows the plot of the 1951 animated film of the same name.', 'https://en.wikipedia.org/wiki/Alice_in_Wonderland_(2000_video_game)'),
  ('Q2706771', 'Tomb Raider: Curse of the Sword is an action-adventure video game, part of the Tomb Raider series, developed by Core Design and published by Activision under license from Eidos Interactive. It was released for the Game Boy Color in 2001, and is a sequel to the first Tomb Raider for the same system. The next Tomb Raider game for a handheld system was Tomb Raider: The Prophecy for the Game Boy Advance.', 'https://en.wikipedia.org/wiki/Tomb_Raider:_Curse_of_the_Sword'),
  ('Q110662911', 'R-Type is a science-fiction themed horizontally scrolling shooter franchise developed and published by Irem for arcade systems and home game platforms. The first entry in the series, R-Type, was released in 1987 and was followed by several sequels for other platforms. Ten games in total have been released in the series. Other pieces of media, such as plastic-resin model kits, soundtrack albums and literature, were also produced. The series centers on an intergalactic war between humans and the Bydo, a powerful extraterrestrial race that are made from both biological lifeforms and mechanical structures. Most games have the player controlling the R-9 "Arrowhead" star vessel, although other entries have slightly altered versions of the ship instead.', 'https://en.wikipedia.org/wiki/List_of_R-Type_video_games'),
  ('Q107665151', 'Antz is a 1998 American animated comedy film directed by Eric Darnell and Tim Johnson, and written by Todd Alcott, Chris Weitz and Paul Weitz, with additional sequences directed by Lawrence Guterman. Produced by DreamWorks Animation and PDI, the film stars the voices of Woody Allen, Sharon Stone, Jennifer Lopez, Sylvester Stallone, Christopher Walken, Dan Aykroyd, Anne Bancroft, Danny Glover and Gene Hackman. Some of the main characters share facial similarities with the actors who voice them. The film involves an anxious worker ant, Z, who falls in love with Princess Bala. When the arrogant General Mandible attempts to seize control of the ant colony, Z must combine his desire for purpose with his inner strength to save everyone.', 'https://en.wikipedia.org/wiki/Antz'),
  ('Q137690626', 'Pitfall: Beyond the Jungle is a 1998 platformer video game developed by David A. Palmer IMS Productions and published by Crave Entertainment for the Game Boy Color. The game features Pitfall Harry''s son, Pitfall Harry Jr. as he enters an interdimensional rift to help a band of rebels led by a woman named Mira. The game features side-scrolling gameplay with the player controlling Pitfall Harry Jr. through various levels themed around areas like jungles and volcanoes.

Pitfall: Beyond the Jungle was part of a series in Pitfall games that were released in 1982 to 1986. During the 1990s, Activision would resurrect the series with games like Pitfall: The Mayan Adventure (1994) and Pitfall 3D: Beyond the Jungle (1998). Following the 3D games release in early 1998, Pitfall: Beyond the Jungle was released in December 1998. Along with Virtual Pool 64 (1998), Milo''s Astro Lanes (1998) for the Nintendo 64 and Gex: Enter the Gecko (1998), Men in Black: The Series for the Game Boy Color, the games gave Crave a $40 million proft in the fourth quarter of 1998.', 'https://en.wikipedia.org/wiki/Pitfall:_Beyond_the_Jungle'),
  ('Q65038106', 'All-Star Baseball 2000 is a video game developed by Iguana Entertainment and Realtime Associates and published by Acclaim Entertainment for the Game Boy Color and the Nintendo 64 in 1999.', 'https://en.wikipedia.org/wiki/All-Star_Baseball_2000'),
  ('Q55375355', 'All-Star Baseball 2001 is a video game developed by High Voltage Software and KnowWonder and published by Acclaim Entertainment for the Game Boy Color and the Nintendo 64 in 2000.', 'https://en.wikipedia.org/wiki/All-Star_Baseball_2001'),
  ('Q107306095', 'Adventures with Barbie: Ocean Discovery is a 1997 video game developed by Gorilla Systems Corporation and published by Mattel Media for Windows. A version for the Game Boy Color developed by Realtime Associates was released in 1999, simply titled Barbie: Ocean Discovery.

The game was Mattel Media''s first adventure game featuring the character Barbie. Its financial success led to Mattel Media producing further girl''s games over the next few years.', 'https://en.wikipedia.org/wiki/Adventures_with_Barbie:_Ocean_Discovery'),
  ('Q3504942', 'Supreme Snowboarding (known as Boarder Zone in the United States) is a snowboarding video game created by Housemarque for Microsoft Windows with a Game Boy Color version by Software Creations in 1999. It was one of the first snowboarding games for Windows to take full advantage of 3D graphics cards that were becoming the norm in the late 1990s. Over 1.5 million units were sold worldwide, allowing Supreme Snowboarding to become the first hit title in Finnish game development. The game received positive critical reception, as well as acclaim for having one of the best visuals of its time, though its lack of content and replay value was sometimes criticized.', 'https://en.wikipedia.org/wiki/Supreme_Snowboarding'),
  ('Q114853982', 'Deer Hunter, also known as Deer Hunter: Interactive Hunting Experience, is a 1997 video game developed by Sunstorm Interactive and published by WizardWorks.', 'https://en.wikipedia.org/wiki/Deer_Hunter_(1997_video_game)'),
  ('Q743841', 'F-1 World Grand Prix II is a Formula One racing game for the Nintendo 64, Sega Dreamcast and Game Boy Color. The Nintendo 64 version was released only in Europe in 1999, with other formats following in 2000. The game is a sequel to F-1 World Grand Prix, and is based on the 1998 Formula One season (Nintendo 64 version) and the 1999 Formula One season (Game Boy Color and Dreamcast versions).', 'https://en.wikipedia.org/wiki/F-1_World_Grand_Prix_II'),
  ('Q5467428', 'Force 21 is a real-time strategy game made by Red Storm Entertainment.', 'https://en.wikipedia.org/wiki/Force_21_(video_game)'),
  ('Q5520537', 'Ganbare Goemon: Tengu-tō no Gyakushū! is a Japanese role-playing video game developed by TOSE and published by Konami for the Game Boy Color. It is the sixteenth main entry in the Ganbare Goemon series. Unlike most games in the series, this game is actually a role-playing game, a genre which was used first in the Ganbare Goemon Gaiden games for the Famicom. The game also borrows some concepts from the franchise''s anime series. The game was re-released in 2026 via the Ganbare Goemon! Daishūgō compilation.

The protagonist in the game is a boy named Hajime, who somehow gets transported into a Ganbare Goemon game and teams with Goemon in order to save Japan from the Tengu Party.', 'https://en.wikipedia.org/wiki/Ganbare_Goemon:_Tengu-t%C5%8D_no_Gyakush%C5%AB!'),
  ('Q3105443', 'Gift is a platform game developed by French studio Eko Software that parodies elements of popular adventure games. It was created by Cryo Interactive''s creative director Philippe Ulrich (creator of the Dune video game) and by author, cartoonist and illustrator Régis Loisel. The game is set over ten levels in a fully three-dimensional world.', 'https://en.wikipedia.org/wiki/Gift_(2000_video_game)'),
  ('Q39054775', 'Harley-Davidson: Race Across America is a racing game developed by Canopy Games and G2M Games, and published by WizardWorks in 1999. The game centers on racing Harley-Davidson motorcycles across different locales in the United States, with the ultimate goal being to reach the Sturgis Motorcycle Rally.

A version of the game was developed for the Game Boy Color by Running Dog and Xantera, released in 2000. Race Across America was later followed by Harley-Davidson: Wheels of Freedom, released in 2000.', 'https://en.wikipedia.org/wiki/Harley-Davidson:_Race_Across_America'),
  ('Q16259669', 'Hot Wheels Stunt Track Driver is a racing video game developed by Semi Logic Entertainments and published by Mattel Media for Microsoft Windows. It is based on the Hot Wheels toy franchise, and was released on October 15, 1998. A Game Boy Color version, developed by Lucky Chicken Games, was released in 2000.', 'https://en.wikipedia.org/wiki/Hot_Wheels_Stunt_Track_Driver'),
  ('Q16958109', 'Hoyle Casino is a virtual casino video game series released from 1996 to 2016 as a spin-off of the Hoyle''s Official Book of Games series developed and published by Sierra Entertainment. After 2005, publication of the series moved to Encore, Inc.

Set in a virtual Las Vegas casino, players create profiles and are given a set amount of virtual money. A player can then visit any part of the virtual casino and wager their virtual money as they could in a real casino. A related business simulation game called Hoyle Casino Empire was released in 2002.', 'https://en.wikipedia.org/wiki/Hoyle_Casino'),
  ('Q6173917', 'Jeff Gordon XS Racing is a 1999 racing video game for Microsoft Windows and Game Boy Color. The game features then three time NASCAR Winston Cup Series champion Jeff Gordon. The game''s Game Boy version has link cable support.', 'https://en.wikipedia.org/wiki/Jeff_Gordon_XS_Racing'),
  ('Q3195037', 'Ken Griffey Jr.''s Slugfest is a 1999 baseball video game developed by Angel Studios and published by Nintendo for the Nintendo 64. It was released in May 1999 only in North America. A Game Boy Color port developed by Software Creations was released in June 1999. Featuring real-life player Ken Griffey Jr., it is a sequel to Major League Baseball Featuring Ken Griffey Jr., released for the Nintendo 64, which itself was preceded by Software Creation''s Ken Griffey Jr. Presents Major League Baseball and Rare''s Ken Griffey Jr.''s Winning Run, both released for the Super NES.

This version of the game contains actual player names, unlike the original. It contains Season, Exhibition, World Series and Home Run Derby modes.', 'https://en.wikipedia.org/wiki/Ken_Griffey_Jr.%27s_Slugfest'),
  ('Q2276180', 'Lego Alpha Team is a 2000 puzzle video game developed by Digital Domain and published by Lego Media in September 2000 for Windows. A Game Boy Color adaptation of the game was developed by Climax Studios and published in November 2000. It was originally known by its working title Lego Action Team.

The game follows Agent Dash, who has to rescue the other Alpha Team members from Ogel and stop production of the mind control orbs. After rescuing an agent, they are playable in some levels as well. During development, the game held the working title Lego Logic and the team''s name was "TILT" (Trans-International Lego Team).', 'https://en.wikipedia.org/wiki/Lego_Alpha_Team_(video_game)'),
  ('Q67433277', 'Sylvester & Tweety: Breakfast on the Run, known as Looney Tunes: Twouble! in North America, is a 2D and isometric, pseudo-3D platform video game developed by Bit Managers and published by Infogrames for the Game Boy Color in 1998. It features the Looney Tunes characters Sylvester and Tweety. Other Looney Tunes include Bugs Bunny, Daffy Duck, Granny, Hector the Bulldog, Taz, Pepé Le Pew and Marvin the Martian.', 'https://en.wikipedia.org/wiki/Sylvester_%26_Tweety:_Breakfast_on_the_Run'),
  ('Q6730466', 'Magi Nation is a 2001 video game for the Game Boy Color developed by American studio Interactive Imagination. It is based on the collectible card game Magi-Nation Duel.', 'https://en.wikipedia.org/wiki/Magi_Nation_(video_game)'),
  ('Q3517288', 'Michael Owen''s WLS 2000 is an association football video game developed by Silicon Dreams Studio and published by THQ for the Nintendo 64. Released on 24 September 1999, the game stars English footballer Michael Owen. It is the third and final game in the World League Soccer series after World League Soccer ''98 and Michael Owen''s World League Soccer ''99.

Michael Owen''s WLS 2000 received reskinned versions for releases outside the United Kingdom; RTL World League Soccer 2000 in Germany and Telefoot Soccer 2000 in France. The only licensed players included in these versions are Premier League players. Most notably it was reskinned as Mia Hamm Soccer 64, starring Mia Hamm and was published in North America by SouthPeak Interactive.', 'https://en.wikipedia.org/wiki/Michael_Owen%27s_WLS_2000'),
  ('Q3048043', 'Mickey''s Speedway USA is a kart racing game developed by Rare and published by Nintendo for the Nintendo 64 and Game Boy Color. It is Rare and Nintendo''s second collaboration with Disney Interactive following Mickey''s Racing Adventure (1999), and features characters from the Mickey Mouse universe racing across the United States. The Nintendo 64 game released in November 2000 to mixed reception, while the Game Boy Color version followed in March 2001.', 'https://en.wikipedia.org/wiki/Mickey%27s_Speedway_USA'),
  ('Q3312024', 'Micro Machines V3 is a racing video game developed by Codemasters, the third title of the Micro Machines series following Micro Machines 2: Turbo Tournament (1994) and the first set in a 3D game environment. It was originally released for PlayStation in 1997 followed by ports to Microsoft Windows, Nintendo 64 (as Micro Machines 64 Turbo) in 1999, and a 2D version for Game Boy Color in 2000.', 'https://en.wikipedia.org/wiki/Micro_Machines_V3'),
  ('Q6840122', 'Microsoft Entertainment Pack: The Puzzle Collection is a collection of 10 puzzle computer games developed by Mir - Dialogue and published by Microsoft Games. The creator of Tetris, Alexey Pajitnov, designed some of the games featured in the pack. It was released on CD-ROM for Windows 95. It was also bundled as part of the Microsoft Plus! Game Pack which was released after Windows Me.

A version was made for the Game Boy Color. It features six of the games from the PC version; Fringer, Charmer, Mixed Genetics, and Muddled Casino have been omitted.', 'https://en.wikipedia.org/wiki/Microsoft_Entertainment_Pack:_The_Puzzle_Collection'),
  ('Q6840187', 'Microsoft Pinball Arcade is a pinball video game from Microsoft. It was released on December 15, 1998, for Microsoft Windows and in 2001 for the Game Boy Color. The game is a collection of seven real pinball tables licensed from Gottlieb. These include one from each decade: Baffle Ball (1931), Humpty Dumpty (1947), Knock Out (1950), Slick Chick (1963), Spirit of 76 (1975), Haunted House (1982), and Cue Ball Wizard (1992).

This game was designed for Windows 9x and Windows NT 4.0. The resolution of the PC version could be set up to 1024x768.

A free trial PC version was released, with Haunted House as the only playable table up to a limited score.', 'https://en.wikipedia.org/wiki/Microsoft_Pinball_Arcade'),
  ('Q16266958', 'NBA Jam 99 is a basketball game for the Nintendo 64 and Game Boy Color, released in 1998 by Acclaim Entertainment''s Acclaim Sports label and developed by Iguana West. New Jersey Nets forward Keith Van Horn appeared on the cover. Acclaim was unable to secure the license to use Michael Jordan''s name or likeness, and as such he was not available as a player for the Chicago Bulls. A player named Roster Guard is available in his place. Rosters are accurate as of July 1, 1998. The game also features Kevin Harlan on play-by-play with Bill Walton as the color commentator. The Utah Jazz'' Dan Roberts provides the arena announcing.', 'https://en.wikipedia.org/wiki/NBA_Jam_99'),
  ('Q131735990', 'Papyrus is a 2000 platform video game developed by Planet Interactive Development and published by Ubi Soft for the Game Boy Color. The game is based upon the Belgian comic book series Papyrus by Lucien De Gieter, with the player completing levels set in ancient Egypt as the titular character. Upon release, Papyrus was generally well received by critics, with praise directed to the game''s visuals and animations, and criticism to its limited gameplay features and longevity.', 'https://en.wikipedia.org/wiki/Papyrus_(video_game)'),
  ('Q122923349', 'Puzzle Master is a 1999 video game developed by Metropolis Digital and published by Metro3D. It is a puzzle video game in which players must arrange falling blocks in a row to clear levels with fantasy elements. Upon release, the game received average reviews.', 'https://en.wikipedia.org/wiki/Puzzle_Master'),
  ('Q2276756', 'Shamus is a shooter with light action-adventure game elements written by Cathryn Mataga (credited as William Mataga) and published by Synapse Software. The original Atari 8-bit computer version was released on disk and tape in 1982. According to Synapse co-founder Ihor Wolosenko, Shamus made the company famous by giving it a reputation for quality. "Funeral March of a Marionette", the theme song from Alfred Hitchcock Presents, plays on the title screen.

The player moves through four flip-screen levels, each containing 32 rooms, shooting attackers and collecting keys for locked areas while searching for the exit. Shamus was inspired by the 1980 Berzerk arcade video game.', 'https://en.wikipedia.org/wiki/Shamus_(video_game)'),
  ('Q106472398', 'Space Invaders (released as Space Invaders X in Japan) is a 1999 fixed shooter video game developed by Z-Axis and published by Activision for Microsoft Windows and video game consoles. It is the seventh entry in the Space Invaders series, the first to feature three-dimensional graphics, and the first entry not published by series creator Taito. It was originally released for the Nintendo 64, Game Boy Color, PlayStation, and Microsoft Windows in 1999, and ported to the Game Boy Advance in 2002. The action occurs on a two-dimensional playfield, similar to earlier entries in the series, but all moving objects including the player, enemies, weapons, and power-ups are rendered in 3D, except for the portable versions, which use pre-rendered 2D sprites. Although the Game Boy Color version is single-player only, all others support either one or two simultaneous players, with the Game Boy Advance edition using the Game Link Cable for multiplayer. Reviews varied by platform, ranging from positive to negative.', 'https://en.wikipedia.org/wiki/Space_Invaders_(1999_video_game)'),
  ('Q55265', 'Star Wars: Yoda Stories is a 1997 adventure video game based on the Star Wars franchise, developed by LucasArts. The game is the second and last title in LucasArts'' Desktop Adventures series, preceded by Indiana Jones and His Desktop Adventures. The game was released in March 1997 for Microsoft Windows and ported to Game Boy Color by Torus Games in December 1999.', 'https://en.wikipedia.org/wiki/Star_Wars:_Yoda_Stories'),
  ('Q3284150', 'Survival Kids, known as Stranded Kids in Europe, is a 1999 survival video game developed and published by Konami for the Game Boy Color. The gameplay revolves around surviving on a deserted island, and features an open-ended structure that presents the player with multiple ways to progress. It is the first in the Survival Kids series in Japan, which goes under the name Lost in Blue in North America and Europe.

Survival Kids received its first official re-release on the Nintendo Classics service on May 23, 2025.', 'https://en.wikipedia.org/wiki/Survival_Kids'),
  ('Q1421188', 'SWIV is a 1991 vertically scrolling shooter video game developed and published by The Sales Curve. It was released for the Amiga, Atari ST, Commodore 64, MSX, ZX Spectrum, and Amstrad CPC computers. A Game Boy Color conversion was published in 2001.

The game was considered a spiritual successor to Tecmo''s arcade game Silkworm, which The Sales Curve had previously converted to home computer formats in 1989. The game''s heritage is evident from the game design whereby one player pilots a helicopter, and the other an armoured Jeep. SWIV is not an official sequel, as noted by ex-Sales Curve producer Dan Marchant: "SWIV wasn''t really a sequel to Silkworm, but it was certainly inspired by it and several other shoot-''em-ups that we had played and loved."', 'https://en.wikipedia.org/wiki/SWIV'),
  ('Q124415641', 'Tyco R/C Racin'' Ratz is a 2000 video game developed by American studio KnowWonder and published by Mattel Interactive for the Game Boy Color. The game is a licensed title based upon remote control toy cars of the same name produced by Mattel, and was announced at E3 2000. Upon release, Racin'' Ratz received average reviews, with critics noting that the game''s design had greater similarities to a puzzle title than a racing title, and critiquing the graphics.', 'https://en.wikipedia.org/wiki/Tyco_R/C_Racin%27_Ratz'),
  ('Q18216019', 'The Wild Thornberrys: Rambler is an action adventure game based on Nickelodeon''s The Wild Thornberrys animated television series, published by Mattel Interactive. It was released for Microsoft Windows in August 2000 and Game Boy Color in November 2000.', 'https://en.wikipedia.org/wiki/The_Wild_Thornberrys:_Rambler'),
  ('Q2016181', 'WWF WrestleMania 2000 is a professional wrestling video game released in 1999 on the Nintendo 64 (N64) console. It was based on the World Wrestling Federation''s (WWF, now WWE) annual pay-per-view, WrestleMania. Despite the fact that this game is based upon WrestleMania 2000, the game was released five months prior (and four months prior on the Game Boy Color) to the actual PPV itself, therefore resulting in the game using the stage design from the 1999 event, WrestleMania XV, instead. Released at the height of the WWF''s Attitude Era, WrestleMania 2000 was the first WWF game released by THQ. The WWF ended its long relationship with Acclaim Entertainment after witnessing the video game success of its competitor, World Championship Wrestling (WCW), on behalf of THQ. WrestleMania 2000 shares its game engine with the Japan-only release Virtual Pro Wrestling 2: Ōdō Keishō.', 'https://en.wikipedia.org/wiki/WWF_WrestleMania_2000_(video_game)'),
  ('Q67988590', 'Xtreme Sports is a sports video game developed by WayForward Technologies for the Game Boy Color. It was initially published by Infogrames North America, and first released in North America on June 29, 2000. The game is similar to one of WayForward''s PC games, Xtreme Sports Arcade: Summer Edition (1999). The artist of Xtreme Sports would later go on to continue work with the Shantae series. A port for Nintendo Switch was released on August 15, 2023.', 'https://en.wikipedia.org/wiki/Xtreme_Sports_(video_game)'),
  ('Q1507926', 'Yars'' Revenge is a 1982 fixed shooter video game developed by and published by Atari, Inc. for the Atari Video Computer System. Set in the Razak solar system, it focuses on the conflict between the Yars, a fly-like humanoid alien race, and the Qotile, who have destroyed their habitable planets. The player controls a Yar tasked with destroying the Qotile''s energy shield, and finishing off the enemy with the Zorlon cannon.

Initially tasked with developing a port of the arcade game Star Castle, designer Howard Scott Warshaw focused on graphics and taking in feedback from co-workers to develop its gameplay. He was also responsible for the backstory of the game, which was adapted as a comic book included with the game.', 'https://en.wikipedia.org/wiki/Yars%27_Revenge'),
  ('Q120702619', 'Grimace''s Birthday is a 2023 browser-based platformer game developed by Krool Toys and published by McDonald''s. The game was a promotional title released to coincide with the launch of the Grimace Shake on 12 June 2023. Development of Grimace''s Birthday used GB Studio, a tool to create games compatible with use on Game Boy hardware, although the game was not a Nintendo-licensed title and did not receive a physical release. Grimace''s Birthday was positively received, with several critics directing attention to the unexpected theme and medium for a promotional game and the strong likeness of the game''s visual presentation to Game Boy titles.', 'https://en.wikipedia.org/wiki/Grimace%27s_Birthday'),
  ('Q979582', 'Mega Man: The Wily Wars is a 1994 platform game compilation developed by Minakuchi Engineering and published by Capcom for the Sega Genesis; the compilation features remakes of the first three Mega Man games which were originally released on the Nintendo Entertainment System, alongside a new game called Wily Tower, only unlockable with a completed save file.

The Wily Wars saw a physical release in Japan and Europe, while the physical North American release was cancelled, with it only releasing as part of the Sega Channel service. In 2019, The Wily Wars was one of 42 games included in the Sega Genesis Mini and in 2021 got a physical re-release on cartridge, North America included, by the company Retro-Bit. On June 30, 2022, The Wily Wars was added to the Nintendo Classics service. Reviews have been generally positive.', 'https://en.wikipedia.org/wiki/Mega_Man:_The_Wily_Wars'),
  ('Q164067', 'Herzog Zwei (pronounced [ˈhɛʁtsoːk ˈtsvaɪ]; German for ''Duke Two'') is a real-time strategy video game developed by Technosoft and published by Sega for the Mega Drive/Genesis. An early real-time strategy game, it predates the genre-popularizing Dune II. It was released first in Japan in 1989 and worldwide in 1990. It is the sequel to Herzog, which was available on the Japanese MSX and PC-8801 personal computers.

Herzog Zwei combines the arcade-style play of Technosoft''s own Thunder Force series with a simple, easy-to-grasp level of strategy. It has been cited as an inspiration to the developers of Warcraft, StarCraft, Dune II, and Command & Conquer and is also considered a precursor to the MOBA genre.', 'https://en.wikipedia.org/wiki/Herzog_Zwei'),
  ('Q113106', 'Crusader of Centy, known as Soleil in PAL regions, is an action-adventure video game developed by Nextech for the Sega Genesis and Mega Drive. The story centers on the player character Corona, a boy who has just turned 14 years of age and must inherit his late father''s sword to fight the monsters that threaten the human race''s existence. Gameplay uses an overhead perspective and focuses on exploring, battling enemies with a sword, and solving puzzles. As the story progresses, numerous animals join the hero and aid him with special abilities, often granting the player passage to previously inaccessible areas.', 'https://en.wikipedia.org/wiki/Crusader_of_Centy'),
  ('Q911619', 'James Bond 007: The Duel is an action video game featuring the fictional British intelligence agent James Bond. It was developed by The Kremlin and published by Domark in 1992 for Sega''s Mega Drive/Genesis, and then the following years for the Master System video game consoles, and the Game Gear handheld game console. The Mega Drive version was also released in Japan by Tengen on 14 May 1993, under the title known as 007: Shitō (００７・死闘, Daburu Ō Sebun: Shitō).', 'https://en.wikipedia.org/wiki/James_Bond_007:_The_Duel'),
  ('Q912708', 'Thunder Force IV, known in North America as Lightening Force: Quest for the Darkstar, is a 1992 shoot ''em up video game developed and published by Technosoft for the Mega Drive/Genesis. It is the fourth installment in Technosoft''s Thunder Force series, and the third and final one created for the Mega Drive. It was developed by the team at Technosoft that ported Devil''s Crush to the Mega Drive rather than the team that developed the previous Thunder Force games. Like its predecessors, it is a horizontally scrolling shooter, but it also features extensive vertical scrolling with large playing fields.', 'https://en.wikipedia.org/wiki/Thunder_Force_IV'),
  ('Q1069752', 'Gunstar Heroes is a 1993 run and gun video game developed by Treasure and published by Sega for the Sega Genesis. It was Treasure''s first developed video game. The premise is centered around a pair of characters, the Gunstars, in their efforts to stop an evil empire from recovering four powerful gems. The characters can fire guns and perform a series of acrobatic maneuvers to fight enemies across each stage. There are four weapons which can be combined with one another to create different shot types.

Development on Gunstar Heroes began among a team of staff working at Konami in 1991. Following an unwillingness of Konami to embrace their original game ideas, the team quit in 1992 and formed Treasure to see their project through. The team wanted to develop their game for the Genesis because of the system''s powerful Motorola 68000 microprocessor. Sega initially rejected their proposal, but later granted approval after they worked for Sega for several months on McDonald''s Treasure Land Adventure (1993). Treasure worked on both games in parallel, and released Gunstar Heroes as their first game in 1993.', 'https://en.wikipedia.org/wiki/Gunstar_Heroes'),
  ('Q2893330', 'Beauty and the Beast is a Disney media franchise comprising a film series and additional merchandise. The success of the original 1991 American animated feature, Beauty and the Beast, directed by Gary Trousdale and Kirk Wise, led to three direct-to-video follow-up films, a live-action spin-off television series, a Disney World stage show, a Disney World restaurant, a trackless dark ride, several video games, merchandise, and the 10th longest-running musical in Broadway history, which was nominated for nine Tony Awards, winning for Best Costume Design. In March 2017, Disney released a live-action remake of the film.', 'https://en.wikipedia.org/wiki/Beauty_and_the_Beast_(franchise)'),
  ('Q441629', 'The Faery Tale Adventure is a 1987 action role-playing video game designed by David Joiner and published by MicroIllusions for the Amiga, and later ported to the Commodore 64, MS-DOS, and Sega Genesis. The MS-DOS version is titled The Faery Tale Adventure: Book I. Microillusions also released a "Book 1" version for the Amiga which was going to be the start of a series of games, according to Talin, but bankruptcy prevented it. The initial version was produced for the Amiga 1000 and featured the largest game world to that date. A sequel, Faery Tale Adventure II: Halls of the Dead, was released in 1997.', 'https://en.wikipedia.org/wiki/The_Faery_Tale_Adventure'),
  ('Q1989029', 'Warsong, known as Langrisser in Japan, is a tactical role-playing game. The first in the Langrisser series, it blended tactical warfare with RPG elements, similar to the Fire Emblem series. It was initially released for the Sega Genesis console and later the PC Engine CD (in Super CD-ROM² format), the former version being published by Treco in America. The PC Engine version was released under the title Langrisser: The Descendants of Light. It was re-released alongside Der Langrisser (a remake of Langrisser II) in a compilation for the Sega Saturn and PlayStation. That compilation was released for the PlayStation Network in 2009. A full remake of Langrisser I & II was also released in 2019 on both Sony PlayStation 4 and Nintendo Switch and on PC in 2020, featuring new graphics and BGM and also new playable characters and multiple paths through the game for Langrisser I.', 'https://en.wikipedia.org/wiki/Warsong'),
  ('Q2891804', 'Battle Mania Daiginjō is a 1993 horizontally scrolling shooter developed and published by Vic Tokai for the Mega Drive. It serves as a sequel to the original Battle Mania, which was released in North America under the title Trouble Shooter. Unlike the original Battle Mania, Daginjō was released exclusively for the Japanese and South Korean markets.

Battle Mania Daiginjō had a limited print run and is consequently one of the most expensive Sega Mega Drive games today.', 'https://en.wikipedia.org/wiki/Battle_Mania_Daiginj%C5%8D'),
  ('Q2891805', 'Battle Golfer Yui is a 1991 video game developed by Santos and published by Sega for the Mega Drive. It is a golf video game where the player must stop a mad scientist. Upon release the game did not receive good reviews.', 'https://en.wikipedia.org/wiki/Battle_Golfer_Yui'),
  ('Q2413475', 'Galaxy Force is a 1988 rail shooter video game developed and published by Sega for arcades. The player assumes control of a starship named the TRY-Z, as it must prevent the Fourth Empire from taking over the entire galaxy. Gameplay involves shooting down enemies using either a laser shot or a limited supply of heat-seeking missiles, all while avoiding collision with projectiles or obstacles and making sure the ship''s energy meter doesn''t fully deplete. It ran on the Sega Y Board arcade system, and was released with a motion simulator cockpit arcade cabinet like previous Sega Super Scaler games (Space Harrier, After Burner and Thunder Blade).', 'https://en.wikipedia.org/wiki/Galaxy_Force'),
  ('Q2892894', 'Beast Wrestler is a 1991 fighting game published for the Mega Drive in Japan and North America. The cover art was made by Yasushi Nirasawa, in his position as a model-builder for Hobby Japan magazine.', 'https://en.wikipedia.org/wiki/Beast_Wrestler'),
  ('Q2413642', 'Party Quiz Mega Q is a quiz video game developed and published by Sega, which released for the Mega Drive in Japan in 1993. Players participate in a television quiz programme, answering questions in rounds of differing rules, earning or losing points along the way. Up to five players are supported, and the game was released on the Wii''s Virtual Console in 2007. In 2014, the soundtrack was released on the Mega Drive 25th Anniversary Album Vol.1 album.', 'https://en.wikipedia.org/wiki/Party_Quiz_Mega_Q'),
  ('Q2891476', 'Batman is a 1990 beat ''em up video game developed and published by Sunsoft for the Sega Genesis, based on the 1989 film of the same name. The game is more faithful to the film''s plot than the NES game of the same name, and includes levels in which the player controls Batman''s vehicles.', 'https://en.wikipedia.org/wiki/Batman_(Genesis_video_game)'),
  ('Q2076925', 'Thunder Fox is a 1990 run and gun video game developed and published by Taito for arcades. It was released in North America in June 1990 and in Japan in July 1990. It was ported to the Sega Genesis in 1991.', 'https://en.wikipedia.org/wiki/Thunder_Fox'),
  ('Q2072787', 'Fighting Masters is a 1991 fighting video game developed by Aicom and ALU, and published by Treco for the Sega Genesis. In the game, players assume the role of a hero to fight against an assortment of opponents on an apocalyptic setting to face against an entity known as Lord Valgasu. Co-directed by Hajime Kusano and Ramō Kobayashi, the title was created by some of the same team that would later work on various projects at Almanic Corporation such as E.V.O.: Search for Eden. It was met with mixed reception from critics since its release.', 'https://en.wikipedia.org/wiki/Fighting_Masters'),
  ('Q392948', 'HardBall! is a baseball video game published by Accolade. Initially released for the Commodore 64 in 1985, it was ported to other computers over the next several years. A Sega Genesis cartridge was published in 1991. HardBall! was followed by HardBall II, HardBall III, HardBall IV, HardBall 5, and HardBall 6.', 'https://en.wikipedia.org/wiki/HardBall!'),
  ('Q2442543', 'Asterix and the Great Rescue is a video game released by Sega for the Genesis/Mega Drive in 1993 and for the Game Gear and Master System in 1994.', 'https://en.wikipedia.org/wiki/Asterix_and_the_Great_Rescue'),
  ('Q2067756', 'F-15 Strike Eagle II is an F-15E Strike Eagle combat flight simulator released in 1989 by MicroProse and is the sequel of F-15 Strike Eagle. It was followed in 1992 by F-15 Strike Eagle III, the final game of the series.

The fighter is equipped with a M61 Vulcan and three different kinds of missiles, Sidewinders, AMRAAMs and Mavericks. F-15 Strike Eagle II comes with four scenarios: Libya, Persian Gulf, Vietnam and Middle East. In a mission the player has to fight a variety of enemy aircraft, missile boats, satellite stations and other ground targets, to take out one primary and one secondary target, making sure to not attack friendly targets. Promotions and medals are based on the mission score.', 'https://en.wikipedia.org/wiki/F-15_Strike_Eagle_II'),
  ('Q2889334', 'Kid Chameleon is a 1992 platform game developed and published by Sega for the Sega Genesis. The player controls the "Kid Chameleon" and attempts to save his peers from a virtual reality video game''s rogue artificial intelligence. The gameplay involves the player going through a series of levels, in which the goal is to reach a flag at the end. The central mechanic revolves around different forms, obtained from masks, which are used to progress through levels.

The game has been ported to several platforms via game compilations and digital distribution services.', 'https://en.wikipedia.org/wiki/Kid_Chameleon'),
  ('Q2471057', 'Garfield: Caught in the Act is a 1995 side-scrolling platform game developed and published by Sega for the Genesis and Game Gear; a Microsoft Windows version was also released. It is based upon Jim Davis'' comic strip character, Garfield, and draws inspiration from Davis'' 1984 book Garfield: His 9 Lives. The story follows Garfield, who is watching television when Odie scares him, causing him to fall onto the television and break it; they both attempt to repair it before Jon catches them. However, some leftover parts become an electronic monster known as the Glitch, who transports Garfield inside the TV, where he must defeat it in order to escape.', 'https://en.wikipedia.org/wiki/Garfield:_Caught_in_the_Act'),
  ('Q1967427', 'Ecco: The Tides of Time (Japanese: Ecco the Dolphin 2) is an action-adventure video game developed by Novotrade International, published by Sega, and released for most of Sega''s then-supported gaming consoles in 1994. It is the second game in the Ecco the Dolphin series. The Tides of Time continued the story of the first game and featured similar gameplay with a few new additions.', 'https://en.wikipedia.org/wiki/Ecco:_The_Tides_of_Time'),
  ('Q1971610', 'Ecco the Dolphin is an action-adventure game developed by Ed Annunziata and Novotrade International and published by Sega for the Mega Drive/Genesis in 1992. Versions for the Sega CD, Master System, and Game Gear were released the following years. It is the first installment in the Ecco the Dolphin video game franchise. The player character is a bottlenose dolphin who travels through time to combat hostile extraterrestrials in Earth''s oceans and on an alien spacecraft.

Ecco the Dolphin received favourable reviews and became a bestseller on the Genesis. It has been re-released several times, including on the Nintendo Virtual Console, Xbox Live Arcade, Steam, iOS, Nintendo 3DS, and the Nintendo Classics service. A sequel, Ecco: The Tides of Time, was released in 1994.', 'https://en.wikipedia.org/wiki/Ecco_the_Dolphin_(video_game)'),
  ('Q1970728', 'Rings of Power is a 1992 role-playing video game developed by Naughty Dog and published by Electronic Arts (EA) for the Sega Genesis. The player takes on the role of an apprentice sorcerer named Buc, whose quest is to assemble a team of adventurers and collect eleven rings to defeat the evil god Void.

The game was pitched under the working title Buccaneer by Naughty Dog founders Andy Gavin and Jason Rubin following the release of their previous title Keef the Thief, and was developed while the pair attended college in separate states. It was originally intended for an MS-DOS and Amiga release until Gavin and Rubin happened upon – and decided to invest in – EA''s secret operation of using makeshift development kits to create Genesis games without Sega''s permission; as a result, Rings of Power became Naughty Dog''s first console video game.', 'https://en.wikipedia.org/wiki/Rings_of_Power_(video_game)'),
  ('Q339571', 'X-Men 2: Clone Wars is a 1995 2D action-platformer video game developed by HeadGames and released by Sega for the Mega Drive/Genesis as a sequel to the 1993''s X-Men. The game is based on the adventures of the Marvel Comics superhero team, the X-Men. A sequel, titled X-Women, was cancelled.', 'https://en.wikipedia.org/wiki/X-Men_2:_Clone_Wars'),
  ('Q379017', 'Castle of Illusion Starring Mickey Mouse is a 1990 platform game developed and published by Sega and released for the Sega Genesis. An 8-bit version of the game was later released for the Master System and Game Gear. The game follows Mickey Mouse on a quest to save Minnie Mouse from the evil witch Mizrabel. It is the first game in Sega''s Illusion video game series starring Mickey.

Castle of Illusion was very well received by critics, especially the original 16-bit version. It was re-released in 1998 in Japan as part of Sega Ages: Mickey Mouse & Donald Duck for the Sega Saturn, which features both Castle of Illusion and QuackShot. A remake of the game by Sega Studios Australia was released for PlayStation Network, Windows, and Xbox Live Arcade in September 2013. The game was also included on the Sega Genesis Mini in 2019.', 'https://en.wikipedia.org/wiki/Castle_of_Illusion_Starring_Mickey_Mouse'),
  ('Q2963209', 'Chi Chi''s Pro Challenge Golf is a 1993 golf video game that was released for the Sega Genesis featuring Chi-Chi Rodríguez.', 'https://en.wikipedia.org/wiki/Chi_Chi%27s_Pro_Challenge_Golf'),
  ('Q2972124', 'Chōkyūkai Miracle Nine is an arcade-style baseball video game for the Sega Mega Drive released exclusively in Japan.', 'https://en.wikipedia.org/wiki/Ch%C5%8Dky%C5%ABkai_Miracle_Nine'),
  ('Q2961958', 'Cheese Cat-Astrophe Starring Speedy Gonzales is a 1995 platform game developed by Cryo Interactive and published by Sega for the Game Gear, Master System, and Mega Drive. Only the Game Gear version was released in North America.', 'https://en.wikipedia.org/wiki/Cheese_Cat-Astrophe_Starring_Speedy_Gonzales'),
  ('Q1997363', 'Haunting Starring Polterguy is a comedy-horror video game released for the Mega Drive/Genesis by Electronic Arts in 1993. Taking control of a ghost named ''Polterguy'', the player must bring various household items to life in order to frighten a family away from their home. A port for the PlayStation Portable was released in 2006 on EA Replay.', 'https://en.wikipedia.org/wiki/Haunting_(video_game)'),
  ('Q2745596', 'Monster World IV is an action-adventure platform game developed by Westone and released in Japan by Sega for the Mega Drive in April 1994.

It is the sixth game in the Wonder Boy series and the fourth game in the Monster World subseries, the other three of which can be identified by their Japanese names: Super Wonder Boy: Monster World for the Sega Mark III (a port of Wonder Boy in Monster Land), Monster World II: Dragon no Wana for the Game Gear (a port of Wonder Boy: The Dragon''s Trap), and Wonder Boy V: Monster World III for the Mega Drive (released overseas as Wonder Boy in Monster World).', 'https://en.wikipedia.org/wiki/Monster_World_IV'),
  ('Q2745925', 'The Revenge of Shinobi, released in Japan as The Super Shinobi, is a hack-and-slash action video game developed and published by Sega in 1989. It was the first Shinobi game developed for the Sega Genesis, and was later released on the coin-operated version of that console, the Mega-Tech.

Alongside Shadow Dancer, the game is a sequel to Shinobi, and features an original score by Yuzo Koshiro. The game was included in the compilations: Mega Games 2, Mega Drive 6 Pak, Sega Classics Arcade Collection (for the Sega CD), and Sega Smash Pack (for the PC and Dreamcast). It was also re-released for the Wii Virtual Console in 2009, on the PlayStation 3 via PlayStation Network and Xbox 360 via Xbox Live Arcade download services in 2012, for iOS and Android devices in 2017 via Sega Forever, and on the Nintendo Classics service in 2023. The game also appears on the Sega Genesis Classics (released as Sega Mega Drive Classics in PAL regions) for Windows, Linux, macOS, PlayStation 4, Xbox One, and Nintendo Switch.', 'https://en.wikipedia.org/wiki/The_Revenge_of_Shinobi_(1989_video_game)'),
  ('Q2746704', 'Sorcerian is a 1987 action role-playing game developed by Nihon Falcom as the fifth installment in the Dragon Slayer line of games. Originally released for the NEC PC-8801, it has since been released on a wide variety of platforms.', 'https://en.wikipedia.org/wiki/Sorcerian'),
  ('Q2746118', 'Jewel Master is a 1991 action-adventure game developed and published by Sega for the Genesis. It follows a mage who can cast spells using elemental rings as they attempt to thwart the conquest of a demonic king. The player traverses five side-scrolling levels with the aid of their rings to progress through platforming challenges and to defeat enemies and bosses.

The game originally began development by Amusement on the Japanese X68000 computer under the title Blade of the Great Elements, but due to complicated circumstances the game shifted its focus to the Sega Genesis and as a result certain things were changed about the game. The game was composed by Motoaki Takenouchi.', 'https://en.wikipedia.org/wiki/Jewel_Master'),
  ('Q2747178', 'Rolling Thunder 2 is a 1991 run and gun video game developed and published by Namco for arcades. It is the sequel to 1986''s Rolling Thunder, retaining the same gameplay of its predecessor while adding cooperative gameplay for two players and improved graphics. Unlike the original, which was set in 1968, Rolling Thunder 2 has a more contemporary setting to go with its more futuristic design, as well as an optionally playable female character.', 'https://en.wikipedia.org/wiki/Rolling_Thunder_2'),
  ('Q2756215', 'Pro Moves Soccer is a soccer video game developed by Danish studios BGS Developments and ZAT Productions and published by ASCII Entertainment for the Sega Genesis in North America. The game was released in 1993, and was based on the fictional Asciiware World Sports league.', 'https://en.wikipedia.org/wiki/Pro_Moves_Soccer'),
  ('Q2819551', 'ATP Tour Championship Tennis is a 1995 tennis video game developed by SIMS Co., Ltd. and published by Sega for the Sega Genesis.', 'https://en.wikipedia.org/wiki/ATP_Tour_Championship_Tennis'),
  ('Q191965', 'Zero Wing is a 1989 horizontally scrolling shooter video game developed by Toaplan and published by Namco for arcades. It was released in North America by Williams Electronics. Controlling the ZIG space fighter craft, players assume the role of protagonist Trent in a last-ditch effort to overthrow the alien space pirate organization CATS (Abigor in the PC Engine version). It was the eighth shoot ''em up game from Toaplan, and their fourteenth video game overall.

Headed by development chief Toshiaki Ōta, Zero Wing was created by most of the same team that previously worked on several projects at Toaplan, initially starting as a project not intended for commercial release but to train new recruits before being ultimately released to the market. The game was later ported to other platforms, each one featuring several changes or additions compared with the original version.', 'https://en.wikipedia.org/wiki/Zero_Wing'),
  ('Q2747557', 'Sol-Feace is a 1990 horizontally scrolling shooter video game developed by Wolf Team and published by Telenet Japan for the X68000. Versions for the Sega CD and Sega Genesis were released later on, with the latter version renaming the game Sol-Deace. The player takes control of the titular starship as it must prevent a malfunctioning supercomputer from enslaving all of mankind. Gameplay involves shooting down enemies and avoiding projectiles, while collecting power capsules to increase the Sol-Feace''s abilities. The Sol-Feace also has dual cannons that can fire shots diagonally.

The game''s soundtrack was composed by Motoi Sakuraba, who would later work on the Tales series for Namco. Alongside Micronet''s Heavy Nova, it was also one of the first launch titles for Sega CD in Japan, and was made as the console pack-in game in North America. Sol-Feace was met with mixed reviews from critics, who praised its fast-paced action, graphics and soundtrack but criticized its lack of originality and subpar quality compared to other similar games on the market. Sunsoft owns the rights to Sol-Feace after their acquisition of Telenet Japan''s intellectual properties in 2009.', 'https://en.wikipedia.org/wiki/Sol-Feace'),
  ('Q2819724', 'We''re Back! A Dinosaur''s Story is a 1993 animated adventure comedy film directed by Dick Zondag, Ralph Zondag, Phil Nibbelink, and Simon Wells from a screenplay by John Patrick Shanley. Loosely based on the 1987 Hudson Talbott children''s book of the same name, its plot follows three dinosaurs and one pterosaur who travel to the present day and become intelligent by eating a "Brain Grain" cereal invented by scientist Captain Neweyes. The film was produced by Steven Spielberg''s Amblimation studio and features the voices of John Goodman, Felicity Kendal, Charles Fleischer, Walter Cronkite, Jay Leno, Julia Child, Kenneth Mars, Yeardley Smith, and Martin Short.', 'https://en.wikipedia.org/wiki/We%27re_Back!_A_Dinosaur%27s_Story_(film)'),
  ('Q2748187', 'Ranger X is a side-scrolling run and gun video game developed for the Genesis by GAU Entertainment and published by Sega in 1993.', 'https://en.wikipedia.org/wiki/Ranger_X'),
  ('Q2785213', 'Streets of Rage 3 is a 1994 beat ''em up game developed and published by Sega for the Genesis. It is the third installment of the Streets of Rage series and the last game in the original trilogy. The game includes several changes over Streets of Rage and Streets of Rage 2, such as a more complex plot, inclusion of character dialogue, longer levels, more in-depth scenarios and faster gameplay. Weapons can be integrated with unique moves with certain characters, hidden characters were added, and a few cutscenes were included to give the story greater depth.

It was later released for the Japanese version of Sonic Gems Collection for the GameCube, PlayStation 2 and the Wii Virtual Console in September 2007. The game also appeared in Sonic''s Ultimate Genesis Collection for Xbox 360 and PlayStation 3. The game also appeared in Sega Genesis Classics for PlayStation 4, Xbox One, and Nintendo Switch.', 'https://en.wikipedia.org/wiki/Streets_of_Rage_3'),
  ('Q2747613', 'Sparkster: Rocket Knight Adventures 2 (known simply as Sparkster in North America and Europe), is a 1994 side-scrolling platform game developed and published by Konami for the Sega Genesis. A sequel to Rocket Knight Adventures, the game involves the character named Sparkster attempting to save Princess Cherry and to stop the evil plans of King Gedol, who plans to take over the kingdom of Zephyrus. The game largely follows the same format as its precursor, with changes to the game''s mechanics.

Sparkster: Rocket Knight Adventures 2 is the second game in the Rocket Knight Adventures series. Another game under the same title, Sparkster, but without the Rocket Knight Adventures subtitle and not continuing the plot of the first game, was released on the SNES in the same year. A direct sequel, Rocket Knight, was released in 2010.', 'https://en.wikipedia.org/wiki/Sparkster:_Rocket_Knight_Adventures_2'),
  ('Q2378952', 'Vectorman is a 2D action platformer video game developed by BlueSky Software and published by Sega. The game was released for the Sega Genesis in late 1995 in North America and Europe. It was considered a critical and commercial success, achieving its dual goal of retaining interest in the aging Sega Genesis platform in face of the increasingly popular new technology of the next generation of video game consoles and providing competition to industry competitor Nintendo''s popular Donkey Kong Country video game. In subsequent decades, the game was re-released across many Sega-themed video game compilations, and on its own across the Wii Virtual Console, Steam, Sega Forever, and Nintendo Classics digital platforms. A sequel, Vectorman 2, was released in 1996, but despite several abandoned attempts at making a Vectorman 3, no further games have been released.', 'https://en.wikipedia.org/wiki/Vectorman'),
  ('Q2863368', 'Arnold Palmer Tournament Golf (JP: Ozaki Naomichi no Super Masters is a golf video game for the Sega Mega Drive/Genesis.

Although Arnold Palmer appears on the box cover and title screen, he is not referenced in the game itself. Palmer''s name was only added in the localised release, a practice common among early Sega sports titles (other games in this vein include Tommy Lasorda Baseball and Pat Riley Basketball). The original Japanese release bore the name of Japanese golfer Naomichi Ozaki.', 'https://en.wikipedia.org/wiki/Arnold_Palmer_Tournament_Golf'),
  ('Q2421926', 'Castlevania: Bloodlines, known in PAL regions as Castlevania: The New Generation, is a 1994 platform game developed and published by Konami for the Sega Genesis as part of the Castlevania series. A vampire named Elizabeth Bartley is orchestrating the beginning of World War I to serve as the catalyst for the resurrection of her uncle, Dracula. Players take on the role of Quincey Morris'' son, John, and his friend Eric Lecarde to take up the fight against evil.

The development team approached Bloodlines as a unique Castlevania experience tailor-made for the Genesis. In this sense, the gameplay was made more fast and action-oriented. Writer Toshiki Yamamura was focused on crafting what he viewed as a new chapter in the Castlevania continuity. The game was the first Castlevania title for which Michiru Yamane composed music. She used her Bach influences to compose the soundtrack, leading to her becoming a recurring series composer.', 'https://en.wikipedia.org/wiki/Castlevania:_Bloodlines'),
  ('Q2872177', 'Australian Rugby League is a 1995 rugby league video game developed by I-Space Interactive and published by EA''s EA Sports label for the Mega Drive only in European and Australian markets. It was adapted from the Mega Drive version of ''''Rugby World Cup ''95'''', replacing rugby union rules with rugby league gameplay.

In addition to the league that names the game, the Australian Rugby League, the game also includes the State of Origin, Super League (eleven English teams plus one French) and international mode. While the ARL has all correct team names, player names are fictitious.', 'https://en.wikipedia.org/wiki/Australian_Rugby_League_(video_game)'),
  ('Q960337', 'James Pond: Underwater Agent is a 1990 platform video game developed by Vectordean and published by British company Millennium Interactive for the Amiga, Atari ST and Acorn Archimedes. A port to the Sega Genesis was released by Electronic Arts the following year. It was the first in the James Pond series of games.', 'https://en.wikipedia.org/wiki/James_Pond:_Underwater_Agent'),
  ('Q2419838', 'Blue Almanac is a futuristic role-playing video game for the Sega Mega Drive.

It was released only for Japan on June 22, 1991 and had a US release as Star Odyssey planned and advertised but it was cancelled at the time. North American publisher Super Fighter Team acquired the official rights to publish an English version of the game with alterations to the translation and the programming, based on an as-yet-unreleased prototype of the US version, and released it exactly twenty years after the game''s original release as Star Odyssey.', 'https://en.wikipedia.org/wiki/Blue_Almanac'),
  ('Q2373154', 'Taz in Escape from Mars is a video game developed by HeadGames and Al Baker & Associates and released by Sega in 1994 for the Genesis/Mega Drive and Game Gear respectively featuring Taz, the Looney Tunes Tasmanian devil cartoon character. The Game Gear version was ported by TecToy to the Master System and released in 1997 only in Brazil. Taz must escape from Mars, where he was brought by Marvin the Martian. The game includes six worlds with two or three levels in each world.', 'https://en.wikipedia.org/wiki/Taz_in_Escape_from_Mars'),
  ('Q1001540', 'Budokan: The Martial Spirit is a fighting game published by Electronic Arts in 1989 for the Amiga and MS-DOS compatible operating systems. The game pits the player against other martial artists in a tournament known as the Budokan at the Nippon Budokan in Tokyo. A port for the Sega Genesis was released in 1990, followed by Commodore 64, ZX Spectrum, and Amstrad CPC releasing in 1991.', 'https://en.wikipedia.org/wiki/Budokan:_The_Martial_Spirit'),
  ('Q2864226', 'Arrow Flash is a horizontally scrolling shooter video game developed by Imaginative Technology Land (I.T.L.) and published by Sega in Japan and Europe and by Renovation Products in the United States for the Sega Genesis in 1990. The game''s main character pilots a prototype transformable fighter-mecha left from her grandfather to fight against an alien attack on humankind. The game is mostly a horizontal shooter, with one down scrolling stage.', 'https://en.wikipedia.org/wiki/Arrow_Flash'),
  ('Q2884600', 'Barkley Shut Up and Jam 2 is a 1995 basketball video game developed and published by Accolade for the Sega Genesis. The game is a sequel to 1994''s Barkley Shut Up and Jam!

Piko Interactive acquired the rights to the game and re-released it in a compilation cartridge for the Evercade handheld under the name Hoops Shut Up and Jam 2 in 2021.', 'https://en.wikipedia.org/wiki/Barkley_Shut_Up_and_Jam_2'),
  ('Q2884690', 'Barney''s Hide & Seek Game is a 1993 licensed edutainment video game developed by Realtime Associates and published by Sega for the Sega Genesis exclusively in North America. It was based on the children''s television series Barney & Friends. Educational concepts taught in the game include counting, matching, and problem solving. There is a self-play feature that guides the player to the objective without input from the player.

The voice of Barney was recorded by his original voice actor Bob West, who also did it on the television show. There are more than one hundred words and two hundred phrases spoken by Barney the Dinosaur.', 'https://en.wikipedia.org/wiki/Barney%27s_Hide_%26_Seek_Game'),
  ('Q2864518', 'Art Alive! is a paint video game released by Sega for the Sega Genesis in 1991.', 'https://en.wikipedia.org/wiki/Art_Alive!'),
  ('Q2868651', 'Asterix and the Power of the Gods is a 1995 platform game for the Sega Mega Drive based on the comic book series Asterix, most notably Asterix and the Chieftain''s Shield.', 'https://en.wikipedia.org/wiki/Asterix_and_the_Power_of_the_Gods'),
  ('Q1046574', 'Golden Axe is a 1989 beat ''em up video game developed and published by Sega for arcades on the Sega System 16B hardware. Players control one of three warriors who must free the fantasy land of Yuria from the tyrannical rule of Death Adder, who wields the titular Golden Axe. The lead designer was Makoto Uchida, who was also responsible for the creation of Sega''s earlier Altered Beast (1988).

Golden Axe was well received at the time of release, and was later ported to several home systems, including Sega''s own Mega Drive/Genesis and Master System. The game''s success spawned a franchise with several sequels and spin-offs, beginning with Golden Axe II in 1991.', 'https://en.wikipedia.org/wiki/Golden_Axe_(video_game)'),
  ('Q998293', 'Midnight Resistance is a 1989 run and gun video game developed and published by Data East for arcades. It was ported to the Sega Genesis in 1991 as Data East''s first video game for the console. The game was also adapted by Ocean Software to home computers.', 'https://en.wikipedia.org/wiki/Midnight_Resistance'),
  ('Q2874684', 'Awesome Possum... Kicks Dr. Machino''s Butt is a video game created and published by Tengen for the Sega Mega Drive/Genesis that was released in late 1993. It also had many lines of digitized speech, unusual for its time, a feature with which the game was marketed. The box also states, "it is an excellent educational game for all ages".', 'https://en.wikipedia.org/wiki/Awesome_Possum..._Kicks_Dr._Machino%27s_Butt'),
  ('Q2869574', 'Atomic Robo-Kid is a 1988 horizontally scrolling shooter video game developed and published by UPL for arcades. The game was published in North America in February 1989 by Nikom as its only released arcade title. The PC Engine version is an adaptation of the arcade original and published as Atomic Robo-Kid Special.', 'https://en.wikipedia.org/wiki/Atomic_Robo-Kid'),
  ('Q2536351', 'In 1990, several video games based on the 1988 Michael Jackson film Moonwalker, all named Michael Jackson''s Moonwalker, were released. Sega developed two beat ''em ups, one released in arcades and another released for the Sega Genesis and Master System consoles. U.S. Gold also published various games for home computers. Each of the games'' plots loosely follows the "Smooth Criminal" segment of the film, in which Jackson rescues kidnapped children from the evil Mr. Big, and incorporates synthesized versions of some of the musician''s songs. Following Moonwalker, Jackson collaborated with Sega on several other video games.', 'https://en.wikipedia.org/wiki/Michael_Jackson%27s_Moonwalker'),
  ('Q2197533', 'El Viento is a 1991 platform game developed and published by Wolf Team for the Sega Genesis. It is the first in a trilogy of games, which includes Earnest Evans and Annet Returns, despite taking place after the former.', 'https://en.wikipedia.org/wiki/El_Viento'),
  ('Q257540', '688 Attack Sub is a submarine simulator video game designed by John W. Ratcliff and Paul Grace and published in 1989 for MS-DOS and in 1990 for Amiga by Electronic Arts. A Sega Genesis version developed by MicroProse was released in 1991 by Sega.

The player takes command of a US Los Angeles-class or Soviet Alfa-class nuclear-powered attack submarine, and plays ten missions ranging from Cold War scenarios to combat missions in a hypothetical global conflict. As modeled in the game, the American submarine has more sophisticated electronics and more weapons. The Soviet boat has fewer weapons but higher sustained speeds. Two people can play against each other over a modem (or null modem cable).', 'https://en.wikipedia.org/wiki/688_Attack_Sub'),
  ('Q2039855', 'Air Buster is a 1990 horizontally scrolling shooter arcade video game developed by Kaneko. It was published by Namco in Japan and Sharp Image Electronics in North America (licensed from Namco). Two players control the "Blaster Fighter" star ships in their efforts to destroy a mysterious mechanical fortress orbiting Earth, with plans to take control of the planet. The Blaster Fighters can equip one of seven available weapons, which will change the ship''s firepower and abilities, such as diagonal shots, homing missiles and small drones that follow the player''s ship.

Air Buster received a favorable reception for its visuals, sound effects and gameplay, although complaints were directed at the difficulty, which was deemed "too easy" by numerous publications. Ports of the game were released for both the TurboGrafx-16 and Sega Genesis, the former being renamed to Aero Blasters for international releases. The Sega Genesis release was ported over to the "Project EGG" digital storefront in 2014, which remained exclusive to Japan. A version for the X68000 was in development but never released.', 'https://en.wikipedia.org/wiki/Air_Buster'),
  ('Q2154888', 'Ristar is a 1995 platform game developed and published by Sega for the Sega Genesis. The game stars an anthropomorphic cartoon star who uses his hands and long, stretchable arms to both move and fight enemies. Reception for the game was generally positive, but the game''s initial release was overshadowed due to the imminent ending of the Genesis''s lifecycle and the succession of the Sega Saturn and other fifth generation video game consoles.

While never receiving any sequels, Sega has re-released Ristar several times digitally and on Sega-themed compilations, including the Sega Forever line of releases for mobile devices. The character has additionally received various cameos in other Sega properties as well. A Game Gear version of Ristar featured different level design and gameplay mechanics.', 'https://en.wikipedia.org/wiki/Ristar'),
  ('Q2933402', 'Caliber.50 is a 1989 scrolling shooter arcade game developed by SETA Corporation. A port of the game was released for the Sega Genesis in 1991.', 'https://en.wikipedia.org/wiki/Caliber_.50'),
  ('Q2924940', 'Brian Lara Cricket ''96, known as Lara ''96 and Shane Warne Cricket in Australia and New Zealand, is the sequel to Brian Lara Cricket and the second game in the Brian Lara-endorsed series of cricket video games. It was developed by Audiogenic for Codemasters and released in 1996 for the Sega Mega Drive, Amiga and PC systems.', 'https://en.wikipedia.org/wiki/Brian_Lara_Cricket_%2796'),
  ('Q2927458', 'Buck Rogers: Countdown to Doomsday is a role-playing video game set in the Buck Rogers XXVC universe. It was published in 1990 by Strategic Simulations for MS-DOS, Commodore 64, and Amiga. A Sega Genesis version was released in 1991. Buck Rogers: Matrix Cubed is the 1992 sequel.', 'https://en.wikipedia.org/wiki/Buck_Rogers:_Countdown_to_Doomsday'),
  ('Q2034608', 'Zero Tolerance is a first-person shooter video game developed by Technopop and published in 1994 by Accolade for the Sega Genesis. It was one of the few first-person shooters for the console, along with Bloodshot, Duke Nukem 3D, and Corporation.', 'https://en.wikipedia.org/wiki/Zero_Tolerance_(video_game)'),
  ('Q2947736', 'Chakan: The Forever Man is a Sega Genesis and Game Gear video game published by Sega in 1992.

It is based upon a comic book of the same name, written by Robert A. Kraus, and was produced by Ed Annunziata, who met Chakan''s creator at a convention and was impressed. In addition to composing, Chakan is also Mark Miller''s only work as a gameplay and level designer.', 'https://en.wikipedia.org/wiki/Chakan:_The_Forever_Man'),
  ('Q285065', 'Growl, released in Japan as Runark, is a 1991 beat ''em up video game developed and published by Taito for arcades. It was released in Japan and North America in February 1991. Set in the early 20th century, the player controls a forest ranger who must protect the local wildlife from a group of evil poachers who are driving the animals to extinction. A home version was released for the Sega Genesis (Mega Drive) in November 1991. A censored version was also included in the arcade game compilation Taito Legends 2 for the PlayStation 2, Xbox, and Microsoft Windows. Hamster Corporation released the game as part of their Arcade Archives series for the Nintendo Switch and PlayStation 4 in July 2023.', 'https://en.wikipedia.org/wiki/Growl_(video_game)'),
  ('Q2189424', 'Corporation (released as Cyber-Cop in North America) is a video game for Amiga, Atari ST and MS-DOS, later ported to the Mega Drive/Genesis. It was developed for Core Design by Dimension Creative Designs by Bill Allen with graphics and design by Kevin Bulmer.

The PC and Sega versions were published by Virgin Games. Originally released for Amiga in 1990, it is one of the earliest 3D first-person shooter games, predating id Software''s Wolfenstein 3D (1992). It was also the first of its kind to utilize dynamic lighting. Gameplay was very complex for its time, featuring role-playing, stealth and hacking elements, similar to the later immersive sims System Shock and Deus Ex series of games.', 'https://en.wikipedia.org/wiki/Corporation_(video_game)'),
  ('Q2928561', 'Burning Force is a 1989 third-person shooter video game developed and published by Namco for arcades. It was initially released only in Japan in November 1989. A port for the Sega Genesis was released worldwide a year later. The player assumes control of the woman space cadet Hiromi Tengenji, a pilot training to become a member of the Space Force, who must complete each level by shooting down enemies with her airbike and avoiding projectiles. Gameplay is similar to Space Harrier, featuring a fixed camera position behind the player and having similar mechanics. It runs on the Namco System 2 arcade hardware.', 'https://en.wikipedia.org/wiki/Burning_Force'),
  ('Q2927391', 'Bubble and Squeak is a platform game published for the Amiga in 1994 by Audiogenic Software. It was developed by Fox Williams under the name Barney & Clyde, and they ported it to the Sega Genesis for which it was published by Sunsoft under license from Audiogenic. The game is a childlike sci-fi fantasy platform game in which players control a little human boy named Bubble along with recent alien acquaintance Squeak. The platform levels are separated by brief underwater scrolling shooter bonus segments.', 'https://en.wikipedia.org/wiki/Bubble_and_Squeak_(video_game)'),
  ('Q2036643', 'Fire Shark is a 1989 vertically scrolling shooter arcade video game developed and published by Toaplan in Japan and Europe, and by Romstar in North America. It is the sequel to Flying Shark, a game released in 1987 on multiple platforms. Set in the year 1991, the game focuses on a mysterious armada launching a worldwide attack from a small island in the Mediterranean Sea. Players take control of the titular biplane to counterattack the enemy''s forces.

Fire Shark was ported in-house to the Mega Drive/Genesis and published worldwide by DreamWorks, Toaplan and Sega between 1990 and 1992. The console launch featured various changes compared with the original release. A conversion for the X68000 was developed but never released. The game was well received in arcades across Western regions where reviewers commended its graphics, sound and gameplay, but it proved to be less popular in Japan due to the high difficulty level. The Mega Drive/Genesis version was also met with mostly positive reviews from critics across multiple regions.', 'https://en.wikipedia.org/wiki/Fire_Shark'),
  ('Q2924939', 'Brian Lara Cricket is a cricket video game, the first in the Brian Lara Cricket series. It is endorsed by Brian Lara. Brian Lara Cricket was released for MS-DOS in 1994 and in 1995 for the Mega Drive and Amiga by Codemasters. The game was rereleased in 1999 under the Codemaster Classics brand for Windows. It was developed by Audiogenic. The game is a rebranded version of Graham Gooch World Class Cricket.', 'https://en.wikipedia.org/wiki/Brian_Lara_Cricket'),
  ('Q2928114', 'Bulls vs Lakers and the NBA Playoffs is a 1992 basketball video game developed and published by Electronic Arts for the Sega Genesis. It is the second game in the NBA Playoffs series, following 1989''s Lakers versus Celtics and the NBA Playoffs. The game features the previous season''s NBA championship series, the 1991 NBA Finals matchup between the Chicago Bulls and Los Angeles Lakers.

Bulls vs Lakers introduced a television broadcast-style presentation on the fictional Electronic Arts Sports Network. EA chief creative officer Bing Gordon was featured as the game announcer. This was also the first game to depict NBA team logos on the courts.', 'https://en.wikipedia.org/wiki/Bulls_vs_Lakers_and_the_NBA_Playoffs'),
  ('Q2110427', 'Super Monaco GP is a Formula One racing simulation video game released by Sega, originally as a Sega X Board arcade game in 1989, followed by ports for multiple video game consoles and home computers in the early 1990s. It is the sequel to the 1979 arcade game Monaco GP. The arcade game consists of one race, the Monaco Grand Prix, but later ports added more courses and game modes based on the 1989 Formula One World Championship.

The original concept for Super Monaco GP came from Hisao Oguchi, who was at the time a game planner with Sega. The arcade game contained parodies of actual brands that were sponsors in Formula One, which led to a lawsuit from Philip Morris over advertising of tobacco products. Shortly after the arcade game launch, Super Monaco GP was ported to Sega''s video game consoles, the Genesis, Master System, and Game Gear. British developer U.S. Gold published ports for home computers.', 'https://en.wikipedia.org/wiki/Super_Monaco_GP'),
  ('Q2160091', 'Alien Storm is a beat ''em up shooter released as an arcade video game by Sega in 1990. It was ported to the Genesis/Mega Drive and Master System. The Mega Drive version was re-released on Wii''s Virtual Console in 2007 and was also included on Sonic''s Ultimate Genesis Collection for Xbox 360 and PlayStation 3. The game was also re-released on the Nintendo Classics service in 2022.', 'https://en.wikipedia.org/wiki/Alien_Storm'),
  ('Q546623', 'Generations Lost is a 1994 platform game developed by Pacific Softscape and published by Time Warner Interactive for the Sega Genesis. Designer Bruce Straley described the game as a clone of the 1993 game X-Men (which he and other Pacific Softscape employees had worked on), after Pacific Softscape was unable to secure the rights to the X-Men franchise to develop a sequel.', 'https://en.wikipedia.org/wiki/Generations_Lost'),
  ('Q2893809', 'Beggar Prince, originally known as Xin Qigai Wangzi is a Taiwanese role-playing adventure game for the Sega Mega Drive/Genesis and PC. It was originally released in 1996 for the Sega Mega Drive/Genesis by C&E Inc. and later ported and released in 1998 on the PC.

An English translation of the Sega Genesis version was produced by the North American company Super Fighter Team. A prototype version was first shown to the public on August 20, 2005, at the Classic Gaming Expo in Burlingame, California. The completed game began shipping to pre-order customers on May 22, 2006, at the price of US$40 per copy. Beggar Prince was the first game for the Sega Genesis to be commercially released in North America since 1998.', 'https://en.wikipedia.org/wiki/Beggar_Prince'),
  ('Q2904002', 'Bio-ship Paladin, known in Japan as Space Battleship Gomora, is a 1990 horizontally scrolling shooter video game developed and published by UPL for arcades. It was released in Japan in November 1990 and in North America by Sammy Corporation in North America in April 1991. It was later ported to the Sega Mega Drive. Hamster Corporation released the game as part of their Arcade Archives series for the Nintendo Switch and PlayStation 4 in August 2021.', 'https://en.wikipedia.org/wiki/Bio-ship_Paladin'),
  ('Q2904000', 'Bio-Hazard Battle, released in Japan as Crying: Aseimei Sensou, is a 1992 scrolling shooter released for the Sega Genesis and Sega Mega Play arcade platform. It was made available on the Wii''s Virtual Console in February 2007. The game was also re-released on the Steam platform in October 2010. An unreleased X68000 version exists currently under ownership of M2 CEO Naoki Horii.', 'https://en.wikipedia.org/wiki/Bio-Hazard_Battle'),
  ('Q2566266', 'Tiny Toon Adventures: ACME All-Stars is a Tiny Toon Adventures-based sports video game released on the Sega Genesis video game console. The game was developed and published by Konami in 1994.', 'https://en.wikipedia.org/wiki/Tiny_Toon_Adventures:_ACME_All-Stars'),
  ('Q2332380', 'F-22 Interceptor is a 1991 combat flight simulator created by Ned Lerner and Gene Kusmiak. It was released by Electronic Arts for the Sega Genesis.

The player controls one aircraft, the F-22 Raptor, throughout the game. At that time, the prototype of the F-22, the Lockheed YF-22, had only first flown in 1990. Like LHX Attack Chopper, another flight simulator by EA, the playable aircraft had not yet been developed.', 'https://en.wikipedia.org/wiki/F-22_Interceptor'),
  ('Q2712291', 'FIFA Soccer 95 is a 1994 football video game published by EA Sports. The game was released for the Sega Mega Drive in 1994. It is a sequel to FIFA International Soccer and the second game in the FIFA series.', 'https://en.wikipedia.org/wiki/FIFA_Soccer_95'),
  ('Q2633916', 'The Punisher is a 1993 beat ''em up video game developed and published by Capcom for arcades. It stars the Marvel Comics antihero the Punisher and co-stars S.H.I.E.L.D. agent Nick Fury as the second player''s character as they embark on a mission to kill the crime lord the Kingpin and bring down his organization. While following the same general formula as Capcom''s previous beat ''em ups, the game has a range of usable weapons and a comic book-style presentation.

The Punisher gained significant popularity in arcades and is widely regarded as one of the best titles in the beat ''em up genre as well as one of the best video game adaptations of comic books. A Sega Genesis port was developed by Sculptured Software and published by Capcom to mixed reviews and commercial failure.', 'https://en.wikipedia.org/wiki/The_Punisher_(1993_video_game)'),
  ('Q1979142', 'Light Crusader is a 1995 action-adventure game developed by Treasure and published by Sega for the Sega Genesis. The game''s plot follows a knight named Sir David as he attempts to rescue the kidnapped people of Greenrow. Played from an isometric perspective, the game sees the player, assuming the role of David, descending through a large dungeon by fighting enemies, solving puzzles, and traversing the environment in order to find the missing townsfolk.

The final title developed by Treasure for the Genesis, the game was first announced in the spring of 1994 under the working title of Relayer. During development, the dev team sought to improve the operability and enjoyment of previous pseudo-3D titles by implementing an isometric viewpoint. However, due to programming difficulties stemming from the perspective, the game was delayed for over a year in order for the development team to fix the issues.', 'https://en.wikipedia.org/wiki/Light_Crusader'),
  ('Q2039873', 'MUSHA is a vertically scrolling shooter video game developed by Compile for the Sega Genesis. An entry in Compile''s shooter series, Aleste, MUSHA places the player in the role of a flying mecha pilot who must destroy a large super intelligent computer threatening planet Earth. The game had a working title of Aleste 2 and originally featured a style similar to the first game, but this was changed to a more original Japanese aesthetic and speed metal soundtrack.

Initial reception for MUSHA was mixed. Critics generally agreed the game was enjoyable with great graphics, but found themselves overwhelmed by the number of scrolling shooters on the Genesis and felt the title was unremarkable and lacked challenge. The game was re-released on the Wii Virtual Console by Naxat Soft in Japan in 2008 and the West in 2009. It was re-released again on the Nintendo Classics service in 2021 by Sega. MUSHA has been more well-received in retrospective reviews, where it is cited for its challenging gameplay, strong soundtrack, and graphics that were ahead of its time.', 'https://en.wikipedia.org/wiki/MUSHA'),
  ('Q2569030', 'Streets of Rage 2, known as Bare Knuckle II in Japan, is a 1992 beat ''em up video game developed by Ancient and published by Sega for the Sega Genesis. The sequel to Streets of Rage (1991), the characters Axel Stone and Blaze Fielding return while the game also introduces two new characters: Max Thunder, and Eddie "Skate" Hunter, the younger brother of Adam Hunter from the first game.

Streets of Rage 2 was developed by an ad hoc team of several companies: Ancient, Shout! Design Works, M.N.M Software, and H.I.C. Ancient''s Ayano Koshiro was the lead graphic designer and one of the game design planners, while her brother Yuzo Koshiro composed the music.', 'https://en.wikipedia.org/wiki/Streets_of_Rage_2'),
  ('Q2903811', 'Bimini Run is a third-person shooter video game for the Sega Genesis. It was developed by Microsmiths and published by Nuvision Entertainment in 1991. Bimini Run allows two players to traverse a wide scrolling environment on objective based missions.', 'https://en.wikipedia.org/wiki/Bimini_Run'),
  ('Q2332147', 'Blades of Vengeance is a 1993 platform game developed by Beam Software and published by Electronic Arts for the Mega Drive/Genesis. One or two players can select one of three fantasy warriors to fight through a large range of platform levels in order to defeat the forces of darkness.', 'https://en.wikipedia.org/wiki/Blades_of_Vengeance'),
  ('Q2333312', 'Goofy''s Hysterical History Tour is a 1994 platform game, based on Disney''s Mickey Mouse series, developed and published by Absolute Entertainment for Sega Genesis. The player controls Goofy as he daydreams about what it would be like to live in the past.', 'https://en.wikipedia.org/wiki/Goofy%27s_Hysterical_History_Tour');

insert into import_summary (wikidata_id, summary, source) values
  ('Q3007744', 'Curse is a 1989 scrolling shooter video game developed by Micronet for the Mega Drive. Although an American release was planned, it was never officially released outside Japan.', 'https://en.wikipedia.org/wiki/Curse_(video_game)'),
  ('Q2721797', 'Double Dragon II: The Revenge is a 1988 beat ''em up video game developed and published by Technōs Japan for arcades. It is the first sequel to Double Dragon, released during the previous year. The sequel involves Billy and Jimmy Lee in a mission to avenge Billy''s girlfriend Marian after she is shot to death by the Black Warriors leader Willy, who is retaliating against the Lee brothers after his defeat at the end of the previous game.

Double Dragon II was initially developed as an upgrade kit for the original Double Dragon, but evolved into a stand-alone game due to an increase in memory size, resulting in the developers reusing assets for both games. A distinct version of the same name was released for the Nintendo Entertainment System.', 'https://en.wikipedia.org/wiki/Double_Dragon_II:_The_Revenge'),
  ('Q2264526', 'Centurion: Defender of Rome is a turn-based strategy video game with real-time battle sequences, designed by Kellyn Beck and Bits of Magic and published by Electronic Arts. Originally released for MS-DOS in 1990, the game was later ported to the Amiga and the Sega Genesis in 1991. Centurion shares much of the concept and feel with Beck''s earlier game Defender of the Crown (1987).', 'https://en.wikipedia.org/wiki/Centurion:_Defender_of_Rome'),
  ('Q596631', 'Dune II: The Building of a Dynasty (titled Dune II: Battle for Arrakis in Europe and Dune: The Battle for Arrakis in North America for the Mega Drive/Genesis port, respectively) is a 1992 real-time strategy game developed by Westwood Studios and published by Virgin Games. It serves as the sequel to Dune (a more traditional adventure game), which came out earlier that same year.

While not the first real-time strategy (RTS) video game, Dune II established the format that would be followed for years to come. As such, Dune II is the archetypal real-time strategy game. Striking a balance between complexity and innovation, it was a huge success and laid the foundation for Age of Empires, Warcraft, Westwood Studios'' subsequent strategy game Command & Conquer, and many other RTS games that followed.', 'https://en.wikipedia.org/wiki/Dune_II'),
  ('Q626822', 'Phantasy Star IV: The End of the Millennium is a 1993 role-playing video game developed and published by Sega for the Sega Genesis. The fourth main installment in the Phantasy Star series, it is the final title in the original tetralogy and is currently the last traditional role-playing game in the franchise. The game''s plot follows the hunters Alys and Chaz, as well as their traveling party, attempting to stop an ecological crisis from destroying their solar system. Phantasy Star IV kept many of the gameplay elements of the previous game, including turn-based battles, overhead exploration, and magic spells. It received positive reviews and has been listed among the greatest video games of all time.', 'https://en.wikipedia.org/wiki/Phantasy_Star_IV'),
  ('Q2287101', 'QuackShot Starring Donald Duck, known in Japan as I Love Donald Duck: The Treasure of King Garuzia, is a 1991 platform game developed and published by Sega for the Sega Genesis. The player controls Donald Duck as he, alongside his three nephews Huey, Dewey and Louie, tries to track down a lost artifact treasured by King Garuzia. The game was influenced by the Indiana Jones film series.

QuackShot was released with a positive response from video game publications. The game was universally lauded for its graphics, with magazines like Sega Pro describing them as "some of the best graphics around". It was also praised for its music and puzzles. Conversely, the game was criticized for its overall difficulty and controls in certain situations. Retrospectively, QuackShot was also criticized for its lack of speech samples by IGN.', 'https://en.wikipedia.org/wiki/QuackShot'),
  ('Q2501831', 'Bubba ''n'' Stix is a side-scrolling platform game for the Sega Genesis, Amiga and CD32 developed and released by Core Design. The Genesis version was released in the United States and featured a promotional tie-in with the Bubblicious bubble gum brand.

The player controls Bubba, a redneck character, who is accompanied by a sentient stick named Stix. Stix can be used in various ways to help Bubba defeat enemies and get past obstacles: for instance, Stix can be thrust into a hole in the side of a platform so that Bubba can climb higher.', 'https://en.wikipedia.org/wiki/Bubba_%27n%27_Stix'),
  ('Q1114985', 'Comix Zone is a 1995 beat ''em up game developed by Sega Technical Institute (S.T.I.) and published by Sega for the Sega Genesis. Set within the panels of a comic book, it follows the comic writer/artist Sketch Turner who, after being transported into the comic by one of his creations, attempts to escape while contending with various threats. The game sees players traversing six levels, where they interact with the comic world and must defeat enemies, or occasionally solve puzzles, to progress.

Conceived by S.T.I. programmer Peter Morawiec, the concept for the game was originally shown off in 1992 via a demonstration video, entitled Joe Pencil Trapped In The Comix Zone. The concept was greenlit by Sega of America C.E.O. Tom Kalinske and development began on the game in late 1993. After repeated delays in order to implement more features, the game was released in July 1995 in North America, in Japan on September, and Europe in October of the same year.', 'https://en.wikipedia.org/wiki/Comix_Zone'),
  ('Q2060608', 'OutRun 2019 is a 1993 racing video game for the Sega Genesis, developed by Hertz and published by SIMS. It is a sequel to Out Run (1986) that takes place a futuristic 2019. The object is to race against a time limit in a rocket-boosted car across four different stages around the world.', 'https://en.wikipedia.org/wiki/OutRun_2019'),
  ('Q2908426', 'Body Count is a 1994 rail shooter for the Mega Drive. It is one of the few games that make use of the Menacer light gun and the Mega Mouse.', 'https://en.wikipedia.org/wiki/Body_Count_(video_game)'),
  ('Q2342898', 'Alisia Dragoon is a 1992 platform game developed by Game Arts and published by Sega for the Sega Genesis. The player controls Alisia, a young woman who is on a quest to avenge her father and save the world. She can fire lightning from her hands and summon four faithful beasts to aid her. The game was later made available on the Sega Genesis Mini and Nintendo Classics service.', 'https://en.wikipedia.org/wiki/Alisia_Dragoon'),
  ('Q625305', 'Golden Axe III is a 1993 beat ''em up game developed and published by Sega for the Sega Genesis. Originally exclusive to Japan, it was made available in North America via the Sega Channel online service in 1995. In this sequel to Golden Axe II, the player controls one of four warriors as they attempt to defeat the evil Damud Hellstrike, who has stolen the Golden Axe and kidnapped the princess of Yuria. Much like its predecessors, the game is based around side-scrolling levels where the player defeats enemies with their melee weapon or fists, while riding creatures known as Bizarrians, or through elemental magic. Several new offensive and defensive moves, like blocking and projectile attacks, can also be used.', 'https://en.wikipedia.org/wiki/Golden_Axe_III'),
  ('Q581502', 'Super Fantasy Zone is a 1992 scrolling shooter video game developed and published by Sunsoft for the Mega Drive. Part of Sega''s Fantasy Zone series, it was released only in Japan and Europe. Players control the character Opa-Opa on his quest to defeat Dark Menon, and the game plays similarly to previous Fantasy Zone entries. The game plays similarly to Defender, where the screen scrolls in the direction that Opa-Opa is going. The player shoots at enemies to defeat them, collecting gold coins that are used to purchase temporary upgrades that improve Opa-Opa''s offensive capabilities and speed, among other things.', 'https://en.wikipedia.org/wiki/Super_Fantasy_Zone'),
  ('Q2483310', 'Global Gladiators is a 1992 platform game developed by Virgin Games, originally programmed by David Perry for the Sega Genesis and eventually ported by other Virgin Games teams in Europe to the Master System, Game Gear, and Amiga. The game is based on the McDonald''s fast food chain and has a strong environmentalist message. The game is a spiritual successor to the NES game M.C. Kids, another McDonald''s-themed game that also featured Mick and Mack as its playable characters.', 'https://en.wikipedia.org/wiki/Global_Gladiators'),
  ('Q1143285', 'Streets of Rage is a 1991 beat ''em up video game developed and published by Sega for the Sega Genesis. Players control one of three former police officers turned vigilantes who battle a crime syndicate. It establishes many conventions of the Streets of Rage series, such as two-player cooperative play and an acclaimed techno soundtrack from composer Yuzo Koshiro. It was ported for the Game Gear, Sega CD and Master System and has been rereleased as part of various compilations and on download services.', 'https://en.wikipedia.org/wiki/Streets_of_Rage_(video_game)'),
  ('Q593781', 'Flicky is a platform game developed by Sega and released as an arcade video game in May 1984. It was licensed to Bally Midway for distribution in the United States. In Flicky, the player controls the eponymous blue bird and must gather all the small birds called Chirps in each round and bring them safely to the exit. There are cat and lizard enemies which can disperse the Chirps and kill the player, but Flicky can use items on the playing field to protect herself and the Chirps from danger.

The idea for Flicky came from Sega senior leadership, who wanted to exceed the success of Namco''s Mappy (1983). Yoji Ishii and Yoshiki Kawasaki developed Flicky at Sega over one year. Originally, the game simply had the player catch ambiguous dots in a maze. Taking inspiration from a popular song in a Japanese variety show, Kawasaki gave the game an urban theme and bird characters. The game was originally titled "Busty", then "Flippy", before finally settling on "Flicky".', 'https://en.wikipedia.org/wiki/Flicky'),
  ('Q1142287', 'Out Run is a 1986 racing video game developed and published by Sega for arcades. It is known for its pioneering hardware and graphics, nonlinear gameplay, a selectable soundtrack with music composed by Hiroshi Kawaguchi, and the hydraulic motion simulator deluxe arcade cabinet. The goal is to avoid traffic and reach one of five destinations before time runs out.

Out Run was designed by Yu Suzuki, who traveled to Europe to gain inspiration for the stages. Suzuki''s original concept was to base it on the 1981 American film The Cannonball Run, of which he was a fan. He disliked racing games in which cars exploded on impact, and wanted gamers to enjoy the experience of driving and to feel "superior".', 'https://en.wikipedia.org/wiki/Out_Run'),
  ('Q2903387', 'Bill Walsh College Football ''95 is a video game of the sports genre released in 1994 by EA Sports, and a follow-up to Bill Walsh College Football.', 'https://en.wikipedia.org/wiki/Bill_Walsh_College_Football_%2795'),
  ('Q2495930', 'TaleSpin is a platform game for the Sega Genesis and Game Gear. It is based on the Disney animated series of the same name. Sega released the game on the Sega Mega Drive/Genesis in 1992 and Game Gear in 1993.', 'https://en.wikipedia.org/wiki/TaleSpin_(Sega_video_game)'),
  ('Q3005986', 'Crystal''s Pony Tale is a children''s action-adventure game developed by Artech Studios and published by Sega for the Sega Genesis in 1994. The game features the adventures of protagonist Crystal Pony, who journeys to rescue her friends and stop an evil witch. It was created in hopes to attract little girls to the platform.', 'https://en.wikipedia.org/wiki/Crystal%27s_Pony_Tale'),
  ('Q3006380', 'Crüe Ball is a 1992 pinball video game developed by American studio NuFX and published by Electronic Arts for the Sega Genesis. Themed to glam metal band Mötley Crüe, it features three of their songs: "Dr. Feelgood," "Live Wire," and "Home Sweet Home."

The game''s prototype name was Twisted Flipper. The producer of the game, Richard Robbins, initially pursued the name Headbangers Ball, but MTV balked at a license and Mötley Crüe was added relatively late in development.

This game was designed by Mark Sprenger (artist for Space Shuttle, High Speed, and Diner) and Brian L. Schmidt (composer for Space Station and Black Knight 2000). The game was awarded the Sega Seal of Quality Award for Best Sound at the Consumer Electronics Show.', 'https://en.wikipedia.org/wiki/Cr%C3%BCe_Ball'),
  ('Q3007948', 'Cutie Suzuki no Ringside Angel is a 1990 Japan-exclusive Sega Mega Drive video game about female professional wrestling. It features the famous female Japanese wrestler Cutie Suzuki.

As the first video game based on women''s professional wrestling for the Sega Mega Drive, it played a pivotal role in establishing women as protagonists in 16-bit video games, predating Alisia Dragoon by two years.', 'https://en.wikipedia.org/wiki/Cutie_Suzuki_no_Ringside_Angel'),
  ('Q2333387', 'Hard Drivin'' is a sim racing arcade video game developed by Atari Games in 1989. The player test drives a sports car on courses that emphasize stunts and speed. It features one of the first 3D polygon driving environments via a simulator cabinet with a haptic vibrating steering wheel and a custom rendering architecture.', 'https://en.wikipedia.org/wiki/Hard_Drivin%27'),
  ('Q2610664', 'Sword of Sodan is a hack and slash video game released for the Amiga in 1988 by Discovery Software, which also commissioned a port for the Apple IIGS (but not made public until 2018). A scaled-down version for the Sega Genesis was released in 1990 by Electronic Arts, and in 1993 it was released for the Apple Macintosh System 7 by Bethesda Softworks.', 'https://en.wikipedia.org/wiki/Sword_of_Sodan'),
  ('Q2567511', 'Turbo OutRun is a 1989 racing game developed and published by Sega for arcades. A follow-up to 1986''s Out Run, it was released as a dedicated game, as well as an upgrade kit for the original Out Run board. Like its predecessor, Turbo OutRun has players driving a Ferrari, this time a Ferrari F40. Players traverse a set route across the continental United States from New York City to Los Angeles. In addition to a time limit, Turbo OutRun also adds a computer-controlled opponent driving a Porsche 959. The "Turbo" in the title plays a factor as players can press a button to receive a brief turbo boost of speed. Various power-ups which increase the vehicle''s attributes can be chosen at various stages of the game.', 'https://en.wikipedia.org/wiki/Turbo_OutRun'),
  ('Q2527624', 'Mercs, released as Senjō no Ōkami II in Japan, is a 1990 run and gun video game developed and published by Capcom for arcades. It is a sequel to the 1985 arcade video game Commando (Senjō no Ōkami in Japan). While not as successful as its predecessor, Mercs was well received by critics and was a moderate commercial success. It was followed by Wolf of the Battlefield: Commando 3 in 2008, a downloadable game.', 'https://en.wikipedia.org/wiki/Mercs'),
  ('Q2906989', 'Bloodshot, also released as Battle Frenzy in Germany and North America, is a 1995 first-person shooter video game developed and published by Domark for the Mega Drive and Mega-CD in Europe. A North American Genesis release was planned and even reviewed in gaming magazines, but was only released through the Sega Channel service.', 'https://en.wikipedia.org/wiki/Bloodshot_(1995_video_game)'),
  ('Q2585545', 'Art Alive! is a paint video game released by Sega for the Sega Genesis in 1991.', 'https://en.wikipedia.org/wiki/Art_Alive!'),
  ('Q2266449', 'Cadash is a 1990 action role-playing platform video game developed and published by Taito for arcades. It was then ported to the TurboGrafx-16 in 1991 and the Sega Genesis in 1992. It is included in Taito Memories Volume 2 released for the PlayStation 2 in 2005 and the Xbox and Microsoft Windows versions of Taito Legends 2 released in 2007. Hamster Corporation released the arcade version as part of their Arcade Archives series for the Nintendo Switch and PlayStation 4 on August 31, 2023.', 'https://en.wikipedia.org/wiki/Cadash'),
  ('Q2333479', 'Splatterhouse 2, known in Japan as Splatterhouse Part 2, is a 1992 beat ''em up video game developed by Now Production and published by Namco for the Sega Genesis. It is the sequel to the 1988 arcade game Splatterhouse, and the third installment in the Splatterhouse series, following Splatterhouse: Wanpaku Graffiti.

On August 4, 2008, the game was released on the Wii Virtual Console in North America. It is the first and the only ESRB M-rated game to be released for the Virtual Console. The game was included as an unlockable extra in the 2010 remake. It was included on the Sega Genesis Mini 2 in October 2022.', 'https://en.wikipedia.org/wiki/Splatterhouse_2'),
  ('Q2239210', 'Sonic Spinball, also known as Sonic the Hedgehog Spinball, is a 1993 pinball video game developed by Sega Technical Institute and published by Sega for the Sega Genesis. It is a spin-off of the Sonic the Hedgehog series. Players control Sonic the Hedgehog, who must stop Doctor Robotnik from enslaving the population in a giant pinball-like mechanism. The game is set in a series of pinball machine-like environments with Sonic acting as the pinball.

It was developed by the American staff of Sega Technical Institute, as the Japanese staff was occupied with developing Sonic the Hedgehog 3 and Sonic & Knuckles. When Sega management realized that Sonic 3 would not be completed in time for the 1993 holiday shopping season, they commissioned another Sonic game. After a hasty nine-month development, Sonic Spinball was released for the Sega Genesis in November 1993, with ports for the Game Gear and Master System releasing in 1994 and 1995 respectively.', 'https://en.wikipedia.org/wiki/Sonic_Spinball'),
  ('Q2735577', 'Ghostbusters is a 1990 platform shoot ''em up video game developed by Sega and Compile for the Sega Genesis. It features an original story based on the Ghostbusters films, and is unrelated to the 1984 Ghostbusters game by Activision. The game was released in the United States in August 1990, and was released in the United Kingdom later that year. A Brazilian version by Tec Toy was released for the console in 1991.', 'https://en.wikipedia.org/wiki/Ghostbusters_(1990_video_game)'),
  ('Q3007341', 'Time Killers is a 1992 weapon-based fighting arcade game developed by Incredible Technologies and published by Strata. Along with Allumer''s Blandia, Time Killers is one of the earliest weapon-based fighting games modeled after Capcom''s Street Fighter II (1991). It was later overshadowed by the success of SNK''s 1993 weapon-based fighting game, Samurai Shodown. In Time Killers, eight warriors from different periods in history face off with each other, and then Death, for a chance at immortality.

A home port for the Sega Genesis was released four years after the arcade version, after having been delayed and even cancelled for a time. It was met with overwhelmingly negative reviews. A port was released in 2021 for the iiRcade home arcade console by BASH Gaming Studio.', 'https://en.wikipedia.org/wiki/Time_Killers'),
  ('Q2040765', 'Red Zone is a 1994 scrolling shooter video game developed by Zyrinx and published by Time Warner Interactive for the Sega Genesis. The player switches between piloting a helicopter and walking around on foot, both can be played from a top-down and first-person point of view. The game is notable for its use of several technologies that were not prevalent at the time on the Genesis, such as full-screen rotation, 3D vectors, real-time zoom, and full-motion video.

Zyrinx released a beta version of the game into the public domain, which is believed to have been done out of respect for their roots as a demogroup.', 'https://en.wikipedia.org/wiki/Red_Zone_(1994_video_game)'),
  ('Q2562085', 'The Ooze is a video game developed by Sega Technical Institute and released in 1995 for the Genesis. In the game, players take the role of a slimy puddle of liquid and face off against various enemies and obstacles.', 'https://en.wikipedia.org/wiki/The_Ooze'),
  ('Q2599190', 'OutRunners is a 1992 racing video game developed by Sega AM1 and published by Sega for arcades. It is the third game in the arcade OutRun series after Turbo OutRun (1989), and was ported to the Sega Genesis in 1994.', 'https://en.wikipedia.org/wiki/OutRunners'),
  ('Q2288749', 'Atomic Runner Chelnov is an arcade side-scrolling shooter platform video game developed and published by Data East in 1988.

In the game, the player takes the role of Chelnov, a coal miner who miraculously survives the malfunction and explosion of a nuclear power plant. Chelnov''s body gains superhuman abilities due to the massive amount of radiation given off by the explosion, and a secret organization seeks to harness those abilities for its own evil purposes. Chelnov must battle and defeat the secret organization using his newfound abilities.

It was ported with a different theme to the Sega Genesis in 1992 by Data East and faithfully to the X68000 in 1993 by Dempa.', 'https://en.wikipedia.org/wiki/Atomic_Runner_Chelnov'),
  ('Q2713256', 'Road Rash II is a 1992 racing and vehicular combat video game developed and published by Electronic Arts (EA) for the Sega Genesis. The game is centered around a series of motorcycle races throughout the United States that the player must win to advance to higher-difficulty races, while engaging in unarmed and armed combat to hinder the other racers. It is the second installment in the Road Rash series and introduces a split-screen two-player mode for competing human players, nitrous oxide charges on certain bikes, and chains as offensive weapons.

EA began development of Road Rash II before the end of the 1991 Christmas season, and the game was released before the end of the 1992 Christmas season. Road Rash II met with critical acclaim and commercial success, with reviewers appreciating the visuals and addition of the multiplayer mode while pointing out the lack of innovation in the fundamental gameplay. A conversion for the Game Boy Color was developed by 3d6 Games and released under the title Road Rash in 2000. The game saw additional releases on the PlayStation Portable compilation title EA Replay in 2006 and on the Sega Genesis Mini in 2019.', 'https://en.wikipedia.org/wiki/Road_Rash_II'),
  ('Q3028458', 'Dinosaurs for Hire is a 1993 platform shoot ''em up video game developed and published by Sega for the Sega Genesis. The game is based on the Dinosaurs for Hire comic book series by Malibu Comics. The gameplay sees the player using guns to take down enemies and bosses in a variety of levels as one of three playable characters.', 'https://en.wikipedia.org/wiki/Dinosaurs_for_Hire_(video_game)'),
  ('Q2628345', 'Shining in the Darkness is a 1991 role-playing video game developed by Climax Entertainment and published by Sega for the Sega Genesis. It is the first game in the Shining series.

In 2007, the game was re-released on the Wii Virtual Console. The game also appears in Sonic''s Ultimate Genesis Collection for Xbox 360 and PlayStation 3, as well as Sega Mega Drive and Genesis Classics on PC.', 'https://en.wikipedia.org/wiki/Shining_in_the_Darkness'),
  ('Q2624299', 'Contra: Hard Corps, released as Contra: The Hard Corps in Japan and Probotector in Europe and Australia, is a 1994 run and gun game developed and published by Konami for the Sega Genesis, making it the first game in the Contra series released for a Sega platform.

Set five years after the events of Contra III: The Alien Wars, a terrorist group led by the renegade Colonel Bahamut has stolen an alien cell recovered from the war and now intends to use it to produce weapons. A new task force, known as the titular "Hard Corps", are sent to deal with the situation. The game features a branching storyline with multiple possible endings.', 'https://en.wikipedia.org/wiki/Contra:_Hard_Corps'),
  ('Q2656891', 'Dynamite Headdy is a 1994 platform video game developed by Treasure and published by Sega for the Sega Genesis. The game follows a puppet named Headdy in his efforts to stop an evil puppet king from taking over his world. Headdy can throw his head at enemies to defeat them and use it to pull himself to various areas and move objects. The player can find a wide variety of "heads" which act as power-ups that provide different effects and alter gameplay.

Dynamite Headdy received positive reviews from critics, who highlighted the game''s originality and creativity in distinguishing it among other games in the platform genre. They also commended Treasure for demonstrating their technical expertise with impressive graphical effects and building on the success of their earlier game Gunstar Heroes (1993). Dynamite Headdy has been cited as one of the best games on the Genesis, and has since been included in multiple compilations of Genesis games. An 8-bit port was released for Game Gear, which itself served as the basis for a Master System port released in Brazil.', 'https://en.wikipedia.org/wiki/Dynamite_Headdy'),
  ('Q2670750', 'Truxton is a 1988 vertically scrolling shooter video game developed by Toaplan and published by Taito for Japanese and European arcades; in North America, it was distributed by Midway. It is set in a future where the Gidans alien race, led by Dogurava, have invaded the fictional planet Borogo. Players assume the role of fighter pilot Tatsuo taking control of the Super Fighter ship on a last-ditch effort to overthrow the alien invaders.

Truxton was conceived by Masahiro Yuge, who wanted to create a scrolling shooter where memorization was its main focus. The game inherited previously established ideas from Slap Fight, and was developed in conjunction with Hellfire, although work on the project had already started privately during production of Twin Cobra.', 'https://en.wikipedia.org/wiki/Truxton_(video_game)'),
  ('Q2660069', 'Sword of Vermilion is a 1989 action role-playing game developed and published by Sega for the Sega Genesis. The player controls an unnamed prince character as they attempt to save the realm of Vermilion by collecting a series of rings through navigating the overworld, dungeons, and battles against enemies and bosses.

Sword of Vermilion is the first console exclusive game developed by Sega''s AM2 division.

Sword of Vermilion is part of the Sega Genesis Collection for the PlayStation 2 and PlayStation Portable, and was available on the Wii''s Virtual Console. In December 2021, it was added to the Nintendo Classics service.', 'https://en.wikipedia.org/wiki/Sword_of_Vermilion'),
  ('Q2666939', 'Tiny Toon Adventures: Buster''s Hidden Treasure is the first Tiny Toon Adventures-based game released on the Sega Genesis. It was released in 1993 and developed and published by Konami. The game was not released in Japan, but was released in South Korea, where it was simply called Tiny Toons Adventures.', 'https://en.wikipedia.org/wiki/Tiny_Toon_Adventures:_Buster%27s_Hidden_Treasure'),
  ('Q3011972', 'Dahna: Megami Tanjō is a 1991 platform action game developed by and published by IGS for the Mega Drive exclusively in Japan and South Korea. The player controls the warrior woman title character who struggles against the powers of an evil sorceress raiding her village. The story is told through cutscenes as Dahna is helped along the way by various mythical beasts.', 'https://en.wikipedia.org/wiki/Dahna:_Megami_Tanj%C5%8D'),
  ('Q3016622', 'SRD: Super Real Darwin is a 1987 vertical scrolling shooter video game developed and published by Data East for arcades. It is the sequel to Data East''s 1986 arcade game Darwin 4078.', 'https://en.wikipedia.org/wiki/SRD:_Super_Real_Darwin'),
  ('Q2353508', 'Splatterhouse 3 (stylized as SPLATTERHOUSE • 3), known in Japan as Splatterhouse Part 3, is a 1993 beat ''em up video game developed by Now Production and published by Namco for the Sega Genesis. It is the sequel to Splatterhouse 2 and was one of the first games to be given a rating by Sega''s own Videogame Rating Council. In North America the game was given an MA-13 rating by the council for its graphic violence and gore. Unlike its predecessors, it was not originally released in Europe. The game was included as an unlockable extra in the 2010 remake, with new artwork replacing the digitized photographs for legal reasons.', 'https://en.wikipedia.org/wiki/Splatterhouse_3'),
  ('Q615251', 'Nakajima Satoru Kanshū F1 Super License is a 1992 racing video game for the Sega Mega Drive that allows for either single season or exhibition modes of play. The object of the game is to acquire the championship for the 1992 Formula One season. There is an official FOCA license and uses a top-down view.', 'https://en.wikipedia.org/wiki/Nakajima_Satoru_Kansh%C5%AB_F1_Super_License'),
  ('Q2712153', 'Dragon Ball Z: Buyū Retsuden is a 1994 fighting video game developed and published by Bandai and Ecofilmes for the Sega Mega Drive. Based upon Akira Toriyama''s Dragon Ball franchise, it is the only game in the series released for the Mega Drive, following the Frieza and Cell sagas. Its gameplay has been described as a combination of the original Super Butōden and Super Butōden 2, consisting of one-on-one fights using a three-button configuration, featuring special moves and two playable modes.

With the popularity of the Dragon Ball franchise in European regions and the positive reception of the first Super Butōden entry on Super Famicom, Bandai decided developing Dragon Ball Z: Buyū Retsuden for the Mega Drive but its creation process lasted longer than the Super Butōden sub-series. Buyū Retsuden proved popular among players and garnered generally positive reception from critics; Some reviewers praised the addition of characters not featured in the previous Super NES games, split-screen mechanic, audiovisual presentation and gameplay, but other stated it was not on par with both Street Fighter II: The World Warrior and Mortal Kombat, criticizing certain design choices and slow pacing.', 'https://en.wikipedia.org/wiki/Dragon_Ball_Z:_Buy%C5%AB_Retsuden'),
  ('Q3020713', 'Death Duel is a first person perspective scrolling shooter published by RazorSoft for the Sega Genesis in 1992. In it, players have to strategically shoot nine alien enemies one at a time using all the weapons they can afford.', 'https://en.wikipedia.org/wiki/Death_Duel_(video_game)'),
  ('Q2982966', 'College Football''s National Championship II is a video game developed by BlueSky Software and published by Sega for the Sega Genesis.', 'https://en.wikipedia.org/wiki/College_Football%27s_National_Championship_II'),
  ('Q2982967', 'College Football''s National Championship is a 1994 American football video game that was released exclusively for the North American Sega Genesis video game system. A sequel, College Football''s National Championship II, was released in 1995.', 'https://en.wikipedia.org/wiki/College_Football%27s_National_Championship'),
  ('Q3041336', 'Dungeons & Dragons: Warriors of the Eternal Sun is a role-playing video game developed for the Sega Genesis in 1992 by Westwood Associates. The game tells the story of a party of adventurers who have been transported to an unknown world and must survive against its hostile inhabitants while learning about their new home and seeking allies. It is based on the Dungeons & Dragons (D&D) game rules, and uses creatures and themes from the D&D Hollow World campaign setting, such as Blacklore elves, the Azcans, beastmen, Malpheggi lizardmen, and dinosaurs.', 'https://en.wikipedia.org/wiki/Dungeons_%26_Dragons:_Warriors_of_the_Eternal_Sun'),
  ('Q721001', 'Phantasy Star II is a science fantasy role-playing video game developed and published by Sega for the Sega Genesis. It was released in Japan in 1989 and North America and Europe in 1990. It was later ported to a variety of different platforms. An updated remake, Phantasy Star Generation 2, was released for the PlayStation 2 in 2005 in Japan.

Phantasy Star II is the second installment in Sega''s acclaimed Phantasy Star series and serves as a sequel to the original Phantasy Star for the Master System. Phantasy Star II takes place 1,000 years after the events of its predecessor and follows the journey of a government agent named Rolf and his friends, who are on a mission to discover why the protector of the planet Mota, Mother Brain, has started malfunctioning.', 'https://en.wikipedia.org/wiki/Phantasy_Star_II'),
  ('Q3008217', 'Appaloosa Interactive (formerly Novotrade International) was a corporation, founded in 1982 in Hungary, that produced video games, computer programs and television commercials during the 1980s and 1990s.', 'https://en.wikipedia.org/wiki/Appaloosa_Interactive'),
  ('Q3016739', 'Dashin'' Desperadoes is a platform game by Data East for the Sega Genesis released in 1993. In the game players control one of two cowboys, Will or Rick, who run and negotiate various obstacles to reach the maiden Jenny.

It is the first Genesis game from Data East since Captain America and The Avengers released the year before. Playing the game on Japanese hardware yields an alternate title, Rumble Kids, despite being never released in Japan. In 1993, Data East also released a Neo-Geo exclusive game titled Spinmaster featuring main characters similar to the ones in Dashin'' Desperadoes.', 'https://en.wikipedia.org/wiki/Dashin%27_Desperadoes'),
  ('Q616512', 'Battle Squadron is a vertically scrolling shooter developed by Cope-Com and published in 1989 by Innerprise Software for the Amiga. It is a sequel to Hybris. Electronic Arts released a version for the Mega Drive in 1990. Conversions were later published for iOS (2011), Android (2012), and in 2013, AmigaOS 4, Windows, OS X, and MorphOS.', 'https://en.wikipedia.org/wiki/Battle_Squadron'),
  ('Q856562', 'Sonic the Hedgehog 3 is a 1994 platform game developed by Sega Technical Institute and published by Sega for the Sega Genesis. Like previous Sonic games, players traverse side-scrolling levels while collecting rings and defeating enemies. They control Sonic and Tails, who attempt to retrieve the Chaos Emeralds to stop Doctor Robotnik from relaunching his space station, the Death Egg, after it crash-lands on a mysterious floating island. Sonic 3 introduces Knuckles the Echidna, the island guardian, who lays traps for Sonic and Tails.

Development began in January 1993 by Sega Technical Institute in California, shortly after the release of Sonic the Hedgehog 2. It was initially developed as an isometric game, similar to what became Sonic 3D Blast (1996), but became a conventional 2D platformer due to time constraints. The pop musician Michael Jackson composed portions of the soundtrack but left the project and went uncredited; sources vary on how much of his work was retained, and many tracks were replaced in rereleases.', 'https://en.wikipedia.org/wiki/Sonic_the_Hedgehog_3'),
  ('Q599426', 'Risky Woods is a fantasy-themed, side-scrolling platform game developed by Dinamic Software and Zeus Software and published by Electronic Arts in 1992. It was released as Jashin Draxos in Japan.', 'https://en.wikipedia.org/wiki/Risky_Woods'),
  ('Q2693436', 'Lakers versus Celtics and the NBA Playoffs is a basketball video game developed and released by Electronic Arts. It was first released in 1989 for MS-DOS-compatible PCs and for the Sega Genesis in 1990. The game was highly successful; it was the first game endorsed by the NBA and was the first to contain multiple NBA stars and teams in one game. The game''s title alludes to the 1980s rivalry between the Boston Celtics and Los Angeles Lakers. It is the first game in the NBA Playoffs series of games.

The game would be the first team basketball video game to acquire full players names and rights without actually relying on the NBA Players Association. Established stars in the game include Larry Bird, Kareem Abdul-Jabbar (DOS version only), Magic Johnson, Michael Jordan, and Patrick Ewing.', 'https://en.wikipedia.org/wiki/Lakers_versus_Celtics_and_the_NBA_Playoffs'),
  ('Q2358082', 'Zany Golf, also known as Will Harvey''s Zany Golf, is a fantasy take on miniature golf developed by Sandcastle Productions and published by Electronic Arts in 1988. The game was originally written for the Apple IIGS and subsequently ported to the Amiga, Atari ST, and MS-DOS compatible operating systems. In 1990, a port was released for the Sega Genesis. The game was developed by Will Harvey, Ian Gooding, Jim Nitchals, and Douglas Fulton. Harvey was pursuing his advanced degrees at Stanford University at the time.

The game is played in a 3D isometric viewpoint and allows up to 4 players. Zany Golf consists of half a golf course – nine holes, plus a bonus hole.', 'https://en.wikipedia.org/wiki/Zany_Golf'),
  ('Q690479', 'Ball Jacks is a 1993 action video game developed and published by Namco for the Mega Drive in Japan and Europe.', 'https://en.wikipedia.org/wiki/Ball_Jacks'),
  ('Q2356527', 'Sub-Terrania is a 1994 multidirectional shooter developed by Danish studio Zyrinx and published by Sega for the Mega Drive/Genesis. The game takes place in the future, where a deep-space mining colony has been invaded by an unknown alien race. The player assumes the role of a lone pilot who must defeat the alien forces and rescue the trapped miners. During the course of the game, the player controls a rotatable craft with thrusters that is constantly subject to gravity and the craft''s inertia. Using the ship''s "rotate-and-thrust" capabilities, the players must aim, shoot, dodge, and carefully maneuver their way through the hazardous landscape while constantly taking gravity and refueling needs into account.', 'https://en.wikipedia.org/wiki/Sub-Terrania'),
  ('Q1134672', 'Alien Soldier is a 1995 run and gun video game developed by Treasure and published by Sega for the Mega Drive. Retail copies were released in Japan and PAL territories while in North America it was only available exclusively via the Sega Channel cable service. The story follows a powerful being named Epsilon-Eagle, who after being nearly killed becomes determined to avenge his near death and save his planet. The character has a variety of weapons and moves that the player must master to complete the game. Many gameplay ideas are borrowed from Treasure''s earlier Mega Drive release, Gunstar Heroes (1993). However, Alien Soldier puts an emphasis on challenging boss fights with short and easy levels serving as downtime in-between.', 'https://en.wikipedia.org/wiki/Alien_Soldier'),
  ('Q1275724', 'Beyond Oasis is a 1994 action-adventure game developed by Ancient and published by Sega for the Sega Genesis. The game has also been re-released in various emulated collections. A prequel to the game, The Legend of Oasis, was released for the Sega Saturn in 1996.', 'https://en.wikipedia.org/wiki/Beyond_Oasis'),
  ('Q2742272', 'Mystic Defender is a two-dimensional action run and gun video game released for the Sega Genesis. Initially titled Kujaku Ō 2: Gen''eijō in Japan and based on the anime/manga Kujaku Ō, it is the sequel to SpellCaster for the Master System.', 'https://en.wikipedia.org/wiki/Mystic_Defender'),
  ('Q3028397', 'Dino Land is a 1991 pinball video game developed by Wolf Team for the Sega Genesis and X68000 home computer.', 'https://en.wikipedia.org/wiki/Dino_Land'),
  ('Q2982278', 'Devil''s Crush is a pinball video game developed by Compile for the TurboGrafx-16 and released in 1990. The second installment in the Crush Pinball series after Alien Crush, the game has an eerie occult theme with skulls, skeletons, and demons. It was later followed by Jaki Crush and Alien Crush Returns.

The game was ported to the Mega Drive/Genesis as Dragon''s Fury (Devil Crash MD in Japan) by developer Technosoft. Both North American TurboGrafx-16 and Genesis versions are censored: all pentagrams have been changed to generic stars, and coffins with crucifixes on them in one bonus stage have been changed to vases. Devil''s Crush was later released on the Wii''s Virtual Console, with the European release reverting to its original title; however, the pentagram symbols were removed and replaced with an 8-sided star. It also saw release on the Wii U eShop in 2017.', 'https://en.wikipedia.org/wiki/Devil%27s_Crush'),
  ('Q2742747', 'Crack Down is a run and gun arcade game released by Sega in 1989 and ported to the Sega Mega Drive/Genesis in 1990 in Japan and 1991 in North America and Europe by Sage''s Creation and Sega respectively. It was also ported and released to a number of home computer platforms by U.S. Gold.

The Mega Drive version of Crack Down was re-released in 2007 on the Wii Virtual Console in Japan on August 7, and in PAL regions on September 7. It was also released on Steam on June 1, 2010.', 'https://en.wikipedia.org/wiki/Crack_Down'),
  ('Q3011278', 'DJ Boy is a 1989 beat ''em up arcade video game developed and published in Japan by Kaneko and in North America by Sammy. DJ Boy, also known as DJ Kid, was partially based on the hip hop culture of the U.S. cities. Many of the characters ride around on roller skates rather than walking or running.', 'https://en.wikipedia.org/wiki/DJ_Boy'),
  ('Q3013534', 'Dangerous Seed is a 1989 vertically scrolling shooter video game developed and published by Namco for arcades. Controlling one of three different starships, the player is tasked with destroying an alien race known as the Danger Seed before they wipe out all of mankind. Each ship has their own set of weapons and abilities, such as shots that dissolve enemies and target-seeking projectiles, and can sustain multiple hits before being destroyed. The player''s ships can also combine into a new ship, the Moon Diver, featuring a stronger shield and additional weapons.

The game was designed by Yuichiro Shinozaki, a character artist for Namco''s own Babylonian Castle Saga franchise, with music composed by Yoshinori Nagumo. Early versions of the game were known as Kristallkern, which remains in-game during the end credits. A conversion for the Sega Mega Drive was released a year later in 1990, which included new features such as additional stages and an arranged soundtrack.', 'https://en.wikipedia.org/wiki/Dangerous_Seed'),
  ('Q2362073', 'Dr. Robotnik''s Mean Bean Machine is a falling block puzzle video game developed by Compile and published by Sega. It was released for the Sega Genesis and Game Gear in 1993 and ported to the Master System in 1994.

The game is a Westernized version of Compile''s Puyo Puyo (1991), replacing almost all of its characters with those from the Sonic the Hedgehog franchise, specifically the Adventures of Sonic the Hedgehog animated series. The Puyo Puyo character Carbuncle appears under the name "Has Bean" and makes different animations depending on how the player plays the game. The gameplay is similar to puzzle games such as Tetris, in which the player organises coloured shapes as they descend a board. The plot sees Sonic antagonist Doctor Robotnik kidnapping residents from Beanville and turning them into robots. The game received generally positive reviews, with critics praising the gameplay but criticising the difficulty.', 'https://en.wikipedia.org/wiki/Dr._Robotnik%27s_Mean_Bean_Machine'),
  ('Q853541', 'Sonic 3D Blast, known in regions outside North America as Sonic 3D: Flickies'' Island, is a 1996 platform game in the Sonic the Hedgehog series for the Sega Genesis and Sega Saturn. As Sonic the Hedgehog, the player embarks on a journey to save the Flickies, birds enslaved by Doctor Robotnik. The player must guide Sonic through a series of themed levels to collect Flickies and defeat Robotnik. Though it retains game mechanics from prior Sonic games, Sonic 3D Blast is differentiated by its 2D isometric perspective, with pre-rendered 3D models converted into sprites.

The concept for Sonic 3D Blast originated during the development of Sonic the Hedgehog 3 (1994). Most of the programming was outsourced to the British studio Traveller''s Tales, as the Japanese Sonic Team staff was preoccupied with Nights into Dreams (1996). Development lasted eight months, and the team drew inspiration from Donkey Kong Country (1994) and Sonic Labyrinth (1995). Sonic 3D Blast was developed alongside the Saturn game Sonic X-treme. When X-treme was canceled, Sega commissioned a port of 3D Blast featuring improved graphics for the Saturn.', 'https://en.wikipedia.org/wiki/Sonic_3D_Blast'),
  ('Q3011826', 'Daffy Duck in Hollywood is a video game published by Sega and released in 1994 for the Sega Mega Drive, Master System and Game Gear.', 'https://en.wikipedia.org/wiki/Daffy_Duck_in_Hollywood_(video_game)'),
  ('Q3018711', 'David Robinson Supreme Court (known in Japan as David Robinson Basketball) is a basketball video game released by Sega exclusively for the Sega Genesis in 1992. The game was endorsed by NBA player David Robinson but does not feature an NBA license and instead features four different fictional American teams.

Robinson would later be featured in Sega''s NBA Action games.', 'https://en.wikipedia.org/wiki/David_Robinson%27s_Supreme_Court'),
  ('Q3038687', 'Dragon''s Revenge is a pinball video game by Tengen, released for Sega Genesis in 1993. It is a follow-up to Devil''s Crush (Dragon''s Fury), a pinball game set in sword and sorcery scenario, wherein the player has to defeat a dragon and a witch. The game was released to generally positive reviews.', 'https://en.wikipedia.org/wiki/Dragon%27s_Revenge'),
  ('Q2742792', 'Blaster Master 2 is a 1993 run and gun video game developed by Software Creations and published by Sunsoft for the Sega Genesis. The game is a sequel to the original Blaster Master for the Nintendo Entertainment System (NES), and was released specifically for the North American market following the first game''s success in that region. The staff of the original Japanese version of Blaster Master, titled Chô Wakusei Senki Metafight, had nothing to do with Blaster Master 2, and Sunsoft Japan did not release the game in Japan. It was reported as being in development for the Super NES in the March 1992 issue of Nintendo Power. The game was also mentioned in August 1992 issue of Nintendo Power, but they stated that it was not close to completion.', 'https://en.wikipedia.org/wiki/Blaster_Master_2'),
  ('Q3020979', 'Decap Attack is a 1991 platform game developed by Vic Tokai and published by Sega for the Genesis. The game is a westernized version of the 1990 Japanese Mega Drive game Magical Hat no Buttobi Tābo! Daibōken, with the art, plot, music, and level designs all being changed. Both are updates of the late 1980s games Kid Kool and Psycho Fox. The game has also been released as part of several emulated compilations.', 'https://en.wikipedia.org/wiki/Decap_Attack'),
  ('Q2993566', 'Tūnshí Tiāndì III is a console role-playing video game that is exclusive to the Sega Mega Drive.

The game itself was released in two versions. One version of the game is the traditional Chinese version intended for players in Hong Kong and Taiwan. The other version uses the simplified version of the Chinese language and is intended for audiences in mainland China. Despite this minor difference, the story line of these two versions are identical. The ultimate goal of the game is to conquer all of ancient China (referred to in the game as the world) by defeating bandits and local rulers. Because it was an unlicensed game from Taiwan, it was never physically distributed outside of Asia. The player control the three warriors: Liu Bei, Guan Yu, and Zhang Fei. These legends of 2nd century China have the ability to cast magical spells on enemies like tigers, barbarians, and various kinds of bosses. There are no random encounters and all encounters are visible like in EarthBound, Chrono Trigger, and Secret of Mana.', 'https://en.wikipedia.org/wiki/T%C5%ABnsh%C3%AD_Ti%C4%81nd%C3%AC_III'),
  ('Q3087268', 'Mega Twins, known as Chiki Chiki Boys in Japan and Europe is a 1990 platform video game developed and published by Capcom for arcades.', 'https://en.wikipedia.org/wiki/Mega_Twins'),
  ('Q3091076', 'World Championship Soccer is a soccer game running on Sega''s Mega-Tech arcade cabinet system and was released as one of the first games for the Sega Genesis system in North America in September 1989.

The European Mega Drive release, World Cup Italia ''90, was published jointly with Olivetti and Virgin Mastertronic and was an officially licensed franchise game of the 1990 FIFA World Cup with the official logo and mascot. After the World Cup licence expired the game was renamed to Sega Soccer on the Mega 6 compilation cartridge on the Mega Drive, removing the Virgin Mastertronic credit. A different game was also released as World Cup Italia ''90 for the Master System in 1990 but this is not connected to World Championship Soccer.', 'https://en.wikipedia.org/wiki/World_Championship_Soccer'),
  ('Q3107412', 'ToeJam & Earl is a 1991 action video game developed by Johnson Voorsanger Productions and published by Sega for the Genesis console. It centers on ToeJam and Earl—alien rappers who have crash-landed on Earth—as they attempt to escape the planet, players assume the role of either character and collect pieces of their wrecked spacecraft. It references and parodies 1980s and early-''90s urban culture and is set to a funk soundtrack. ToeJam & Earl''s design was heavily influenced by the role-playing video game Rogue (1980) and derived various features from the game, such as the random generation of levels and items. As such, ToeJam & Earl is often considered to be an early example of a roguelike game.', 'https://en.wikipedia.org/wiki/ToeJam_%26_Earl'),
  ('Q2742161', 'Jurassic Park is a 1993 action-adventure game developed by BlueSky Software and published by Sega for the Sega Genesis. It was released as a tie-in with the 1993 film of the same name, and features elements from Michael Crichton''s 1990 novel on which the film is based.

In 1994, after the financial success of the film and its merchandise, Sega released a sequel video game titled Jurassic Park: Rampage Edition. Both games were re-released in 2023 as part of Jurassic Park: Classic Games Collection.', 'https://en.wikipedia.org/wiki/Jurassic_Park_(Genesis_video_game)'),
  ('Q3100490', 'General Chaos is a video game developed by Game Refuge for the Sega Genesis and published by Electronic Arts in 1993. General Chaos is a satirical action/strategy game.', 'https://en.wikipedia.org/wiki/General_Chaos'),
  ('Q3093019', 'G-LOC: Air Battle is a 1990 combat flight simulator video game developed and published by Sega for arcades. It is a spin-off of the company''s After Burner series. The title refers to "G-force induced Loss Of Consciousness". The game is known for its use of the R360 motion simulator arcade cabinet. The arcade game was a commercial and critical success upon release, and was followed by ports for Sega''s Game Gear, Master System, and Mega Drive/Genesis consoles, as well as for various home computers.', 'https://en.wikipedia.org/wiki/G-LOC:_Air_Battle'),
  ('Q3092703', 'Férias Frustradas do Pica-Pau (Woody Woodpecker''s Frustrated Vacations) is a platform video game developed and published by Tec Toy for the Mega Drive, and the Master System, it was released in October 1996 for Brazil only. This video game was based on the animated short film series created by Walter Lantz, and the title and some of the game art makes references to the Brazilian release of National Lampoon''s Vacation under the name Frustrated Vacations.', 'https://en.wikipedia.org/wiki/F%C3%A9rias_Frustradas_do_Pica-Pau'),
  ('Q3108064', 'X-Men is a home console video game produced by Sega for Sega Genesis in 1993, based on the adventures of the Marvel Comics superhero team, the X-Men. One or two players can play as any of four pre-chosen X-Men. X-Men was released in 1993 and was followed up by X-Men 2: Clone Wars.', 'https://en.wikipedia.org/wiki/X-Men_(1993_video_game)'),
  ('Q3098365', 'Gargoyles is a platform game developed by Disney Interactive and published by Buena Vista Interactive for the Sega Genesis in 1995 exclusively in North America. It is an adaptation of the Disney animated series of the same title.', 'https://en.wikipedia.org/wiki/Gargoyles_(video_game)'),
  ('Q3094225', 'Gadget Twins is a video game developed by Imagitec Design for the Sega Genesis and published by GameTek in 1992. Gadget Twins is a horizontal side scroller action game that supports both single and two-player gameplay.', 'https://en.wikipedia.org/wiki/Gadget_Twins'),
  ('Q2740256', 'World of Illusion Starring Mickey Mouse and Donald Duck is a platform game developed and published by Sega for the Sega Genesis. The game was released in December 1992, and is part of Sega''s Illusion series of Mickey Mouse games. The game was included on the Sega Genesis Mini.', 'https://en.wikipedia.org/wiki/World_of_Illusion'),
  ('Q3107409', 'Pulseman is a 1994 Japanese platform game developed by Game Freak and published by Sega for the Sega Mega Drive. It was released in North America for the Sega Channel in 1995. It was re-released on the Virtual Console for the Wii in 2007 and 2009, and the Nintendo Classics service in 2023.', 'https://en.wikipedia.org/wiki/Pulseman'),
  ('Q3094357', 'Gaiares is a horizontally scrolling shooter developed by Telenet Japan and published by Renovation for the Sega Genesis in 1990. It was one of the first 8Mb cartridge games on the Genesis. Its title combined Gaia (Mother Earth) and the suffix "less" (Res), as the Earth has been lost to pollution in the far future according to the game''s plot (thus making mankind "Earthless").', 'https://en.wikipedia.org/wiki/Gaiares'),
  ('Q3084448', 'Phantasy Star III: Generations of Doom, known in Japan as Successors of Time: Phantasy Star III, is a 1990 role-playing video game developed and published by Sega for the Sega Genesis. The third main installment in the Phantasy Star series, it is the first title to not be developed with the involvement of series co-creator Yuji Naka. The game''s plot spans three generations, following the journey of the prince Rhys and his descendants as they attempt to resolve an escalating conflict between two warring factions. Much of the gameplay elements from its predecessors, derived from traditional Japanese role-playing game tropes such as random encounters, are either retained or altered with additional changes such as an icon-based menuing system.', 'https://en.wikipedia.org/wiki/Phantasy_Star_III'),
  ('Q3099452', 'Gauntlet IV is a 1993 action video game developed by M2 and published by Tengen for the Sega Genesis. It includes a four player port of the original Gauntlet, as well other exclusive modes such as a new RPG Quest Mode and head to head battle mode, it was well received by critics.', 'https://en.wikipedia.org/wiki/Gauntlet_IV'),
  ('Q3026640', 'Dick Vitale''s "Awesome, Baby!" College Hoops is a 1994 college basketball sports game developed and published by Time Warner Interactive. It was released for the Sega Genesis in 1994. Directed by Richard Seaborne, the game features the voice and likeness of the basketball sportscaster Dick Vitale and prominently features his quotes and catchphrases. Players play as multiple college basketball teams from the United States in a 3D court that automatically rotates to fit to the player''s position, which was a major selling point for the game.

Dick Vitale''s "Awesome, Baby!" College Hoops received generally positive reviews from critics. The game''s graphics and self-rotating court was praised, with GameFan calling the game a "technical marvel". Critics were more negative towards the game''s soundtrack and sound effects; GamePro called the soundtrack "terrible" and stated that players would either "love" or "hate" Vitale''s commentary.', 'https://en.wikipedia.org/wiki/Dick_Vitale%27s_%22Awesome,_Baby!%22_College_Hoops'),
  ('Q3077302', 'Forgotten Worlds, originally titled Lost Worlds, is a 1988 horizontally scrolling shooter video game developed and published by Capcom for arcades. It is notable for being the first title released by Capcom for their CP System arcade game hardware.', 'https://en.wikipedia.org/wiki/Forgotten_Worlds'),
  ('Q2742036', 'Air Diver: F-119 Stealth Fighter Simulation is a combat flight simulator video game released by Asmik in Japan, and by Seismic in North America in 1990 for the Sega Genesis/Mega Drive console. It is notable as being one of the two first third party published titles for the console in North America. A follow-up, Super Air Diver was released exclusively for the Super Nintendo Entertainment System years later.', 'https://en.wikipedia.org/wiki/Air_Diver'),
  ('Q2742131', 'Abrams Battle Tank is a video game developed by Dynamix and published by Electronic Arts in 1988 for MS-DOS. Designed by Damon Slye, the game is a 3D vehicle simulation of the M1 Abrams tank. The 1991 Sega Genesis port by Realtime Games Software was renamed to M-1 Abrams Battle Tank.', 'https://en.wikipedia.org/wiki/Abrams_Battle_Tank'),
  ('Q2741890', 'Zoom! is a puzzle video game by developed and published by Discovery Software. Amiga, Commodore 64, and MS-DOS versions were released in 1988, followed-by a port by Sega for the Genesis in 1990. The game has a 3D-like board the player moves around on. Up to two players may play simultaneously.', 'https://en.wikipedia.org/wiki/Zoom!'),
  ('Q2738582', 'Shining Force II is a 1993 tactical role-playing game developed by Sonic! Software Planning and published by Sega for the Sega Genesis. Its storyline is not directly connected to the original Shining Force, although the Game Gear title Shining Force Gaiden: Final Conflict links the two games'' plots. The game is much longer than Shining Force, and contains more free roaming. There is no chapter system, so the player can return to previously visited parts of the world. There are also two different ways of promoting certain characters.

Shining Force II was met with positive reviews and acclaim during its initial release, with critics citing it as superior to its predecessor for its straightforward storyline and charming characters. Amongst critics, the game is often regarded as one of the best RPGs of all time, and a highlighted title for the Sega Genesis. After the game''s initial release, Shining Force II saw re-releases and remasters on consoles and PCs. It was released on the Wii Virtual Console in Europe on October 3, 2008, and in North America on October 6, 2008, and on the Nintendo Classics service on April 21, 2022. The game was also released for iOS and Android devices in October 2018, and for Microsoft Windows in 2011. It also appears in several game compilations, including Sonic''s Ultimate Genesis Collection for Xbox 360 and PlayStation 3 and Sega Genesis Classics for the Nintendo Switch, PlayStation 4, and Xbox One.', 'https://en.wikipedia.org/wiki/Shining_Force_II'),
  ('Q3061334', 'Evander Holyfield''s "Real Deal" Boxing is a boxing video game that was developed by Acme Interactive and published by Sega in 1992, released for the Mega Drive/Genesis and Game Gear consoles. It was followed by a sequel in 1993, Greatest Heavyweights, which featured a number of improvements.', 'https://en.wikipedia.org/wiki/Evander_Holyfield%27s_Real_Deal_Boxing'),
  ('Q842155', 'Pat Riley Basketball is a basketball video game which was released for the Sega Genesis, for the Mega Drive in Japan on March 2, 1990 under the title Super Real Basketball and Europe under the same title as Japan. It was released in August 1990 in the United States. It was also developed for the Master System, but was never released. Pat Riley was the coach of the Los Angeles Lakers at the time of the game''s release. There are two modes and eight different teams to choose from.', 'https://en.wikipedia.org/wiki/Pat_Riley_Basketball'),
  ('Q3116131', 'Greendog: The Beached Surfer Dude! is a platform game developed by Interactive Designs for the Sega Genesis console, and was published by Sega in 1992. A port to the handheld Game Gear was released a year later.', 'https://en.wikipedia.org/wiki/Greendog:_The_Beached_Surfer_Dude!'),
  ('Q787462', 'Golden Axe II is a 1991 beat ''em up video game developed and published by Sega for the Sega Genesis. It is a sequel to 1989''s Golden Axe, and the second installment of the Golden Axe series. The player controls one of three warriors as they attempt to recover the Golden Axe by slaying Dark Guld and his loyal followers. Much like its predecessor, the gameplay is based around side-scrolling levels where the player fights enemies by using their melee weapon, while riding a beast, or utilizing elemental magic. The game revamps and introduces various gameplay mechanics from its contemporary including the ability to select the level of magic used and an attack that hits all around the player’s character.', 'https://en.wikipedia.org/wiki/Golden_Axe_II'),
  ('Q768115', 'Trouble Shooter, originally released in Japan as Battle Mania, is a horizontally scrolling shooter developed and published by Vic Tokai for the Mega Drive/Genesis. It was released in November 1991 in North America and March 6, 1992 in Japan. It was directed by designer Fujito "Takayan" Takada, who at first was primarily responsible for every aspect of the game''s development due to a lack of support from Vic Tokai. Over time, however, more people joined the project, and he took on a supervisory role for much of the game''s design.

The game was given a very distinct theme of self-parody between the enemies, story, and dialogue. A sequel titled Battle Mania Daiginjō was also released for the Mega Drive in Japan and Korea only.', 'https://en.wikipedia.org/wiki/Trouble_Shooter'),
  ('Q3062056', 'Exosquad is a Sega Genesis video game based on the animated television series under the same title and developed by Novotrade.', 'https://en.wikipedia.org/wiki/Exosquad_(video_game)'),
  ('Q3116747', 'Grind Stormer is a 1993 vertically scrolling shooter arcade video game originally developed and published by Toaplan in Japan and North America. It is considered to be the spiritual successor to Slap Fight. Based around a video game within a video game concept, players assume the role of a young secret agent assigned by the government taking control of the NA-00 space fighter craft in an attempt to defeat the titular virtual reality simulator, rescue the abducted players who lost against it and unveil its true purpose.', 'https://en.wikipedia.org/wiki/Grind_Stormer'),
  ('Q3066546', 'Fantasia is a 1991 platform game developed by Infogrames and published by Sega for the Genesis. It was loosely based on the 1940 animated film Fantasia and inspired by the success of the 1990 video game Castle of Illusion Starring Mickey Mouse.', 'https://en.wikipedia.org/wiki/Fantasia_(video_game)'),
  ('Q2313010', 'Alex Kidd in the Enchanted Castle is a 1989 platform game developed and published by Sega for the Genesis. It is the only 16-bit platform game starring Alex Kidd, and the fifth game in the Alex Kidd series.

Alex Kidd in the Enchanted Castle follows Alex as he fights his way through the fictional planet Paperock in search of his long-lost father, King Thor. Alex has access to several items and vehicles that help him complete his quest, including a motorbike, a pedicopter and a pogo stick, which each give him unique abilities. While traveling through eleven worlds, Alex must defeat several opponents in rock paper scissors matches before finally finding King Thor.', 'https://en.wikipedia.org/wiki/Alex_Kidd_in_the_Enchanted_Castle'),
  ('Q3051005', 'Eliminate Down is a scrolling shooter developed by Aprinet and published by Soft Vision for the Mega Drive/Genesis. It was released in Japan on June 25, 1993. Eliminate Down gives players immediate access to three directional-based weapons that can all be powered up as they fight strange alien enemies through eight levels.', 'https://en.wikipedia.org/wiki/Eliminate_Down'),
  ('Q3067167', 'Fatal Labyrinth, titled Shi no Meikyuu: Labyrinth of Death in Japan, is a 1990 roguelike role-playing video game developed and published by Sega for the Sega Genesis. Originally available on the Sega Meganet multiplayer gaming service in Japan, it was later released physically in 1991. The game is similar to and shares assets with Dragon Crystal, which was released around that time.

The game appears in Sonic''s Ultimate Genesis Collection for Xbox 360 and PlayStation 3, and was later included in Sega Genesis Classics for PlayStation 4, Xbox One, and Nintendo Switch.', 'https://en.wikipedia.org/wiki/Fatal_Labyrinth'),
  ('Q3162094', 'Jantei Story is a 1990 video game. It combines both adventure game and mahjong gameplay into a story about a detective looking for a lost girl. The game progresses as the player does rounds of mahjong against various female opponents to progress the story.

The game was released in Japan for the PC Engine on October 9, 1990 and the Sega Mega Drive on March 29, 1991. It led to a series of Jantei Monogatari games that lasted until 1993.

Critics in the Japanese video game magazines Gekkan PC Engine , Marukatsu PC Engine  and Famicom Tsūshin have complimented the games graphics and animation. Reviews in these magazines were split on the quality of the game as a mahjong title or how the table tops game meshed with an adventure game.', 'https://en.wikipedia.org/wiki/Jantei_Story'),
  ('Q1315653', 'Ghouls ''n Ghosts, known as Dai Makaimura in Japan, is a 1988 platform game developed and published by Capcom for arcades. It is the sequel to 1985''s Ghosts ''n Goblins, and the second game in the Ghosts ''n Goblins series.

It was a commercial success, becoming the eighth highest-grossing arcade game of 1989 in Japan. It was also critically acclaimed, with the Sega Genesis version winning four awards from Electronic Gaming Monthly in 1989, including Best Game of the Year.', 'https://en.wikipedia.org/wiki/Ghouls_%27n_Ghosts'),
  ('Q3042010', 'Dynamite Duke is a 1989 action arcade game developed and published by Seibu Kaihatsu. It was later ported to the Mega Drive/Genesis, Master System, and X68000. Being a Cabal-based shooter, it can be considered a follow-up to Seibu''s Empire City: 1931 and Dead Angle.', 'https://en.wikipedia.org/wiki/Dynamite_Duke'),
  ('Q1382986', 'Rocket Knight Adventures is a 1993 platform game developed and published by Konami for the Sega Genesis. The player controls Sparkster, an opossum knight who wields a rocket pack and sword, who battles the evil Devotindos Empire.

Rocket Knight Adventures was designed by Nobuya Nakazato, designer of Contra games such as The Alien Wars, Hard Corps, and Shattered Soldier. It received positive reviews.', 'https://en.wikipedia.org/wiki/Rocket_Knight_Adventures'),
  ('Q843485', 'Dark Castle is a 1986 platform game for Macintosh, originally published by Silicon Beach Software. The game was designed and animated by Mark Pierce and programmed by Jonathan Gay, with Real Sound provided by Eric Zocher. In Dark Castle, a young hero named Duncan attempts to reach the evil Black Knight while dodging various objects and solving occasional puzzles.

A sequel, Beyond Dark Castle, was released in 1987. A second sequel, Return to Dark Castle, was developed by Super Happy Fun Fun, Inc. and released on the Mac App Store on March 14, 2008.

Ports to other platforms were also published by Three-Sixty Pacific and Electronic Arts for the SEGA Genesis. The series has sold over 1 million copies.', 'https://en.wikipedia.org/wiki/Dark_Castle'),
  ('Q3050673', 'Elemental Master is a top down scrolling shooter developed by Technosoft for the Sega Genesis and released in 1990 in Japan and in 1993 in North America by Renovation Products.', 'https://en.wikipedia.org/wiki/Elemental_Master'),
  ('Q3152918', 'Instruments of Chaos starring Young Indiana Jones is a 1994 action game developed by Brian A. Rice, Inc. and published by Sega for the Sega Genesis. It is based on the television series, The Young Indiana Jones Chronicles. The game was in development as of August 1992, with the title Young Indiana Jones. A Sega CD version had been planned for release in July 1993, but it was never published.', 'https://en.wikipedia.org/wiki/Instruments_of_Chaos_starring_Young_Indiana_Jones'),
  ('Q3046450', 'Earth Defense, showm as The Earth Defend on the title screen, is a vertically scrolling shooter for the Mega Drive/Genesis. The game is unlicensed; it was developed by AV Artisan and published by Realtec in both North America and Taiwan without a license from Sega.

The cartridge and box shapes as well as quality in graphics and box art are identical to AV Artisan''s previous games Funny World & Balloon Boy and Mallet Legend''s Whac-a-Critter, both published by Realtec. The player takes on the role of a jet pilot assigned to liberate five world continents from a technologically advanced army. Earth Defense allows two-player simultaneous multiplayer.', 'https://en.wikipedia.org/wiki/Earth_Defense'),
  ('Q3067127', 'Fastest 1 is a Sega Mega Drive racing game video game released in 1991 exclusively in Japan. During the release of this video game, other Formula One video games like Super Monaco GP had caused a general increase of demand for Formula One video games. While most of those games were poor simulations of the races, Fastest One proved to be the most realistic of the era.

The game was based on Formula One racing and featured team and driver names similar to the real life namesakes. A choice of up to 18 playable vehicles could be used in every mode provided. Six vehicles in the game used Ford engines, displaying American ingenuity during the 1990 Formula One season. The language of the game was English.', 'https://en.wikipedia.org/wiki/Fastest_1'),
  ('Q884654', 'Blockout is a 1989 puzzle video game developed by Logical Design Works and P.Z.Karen and published by California Dreams. It was developed in Poland by Aleksander Ustaszewski and Mirosław Zabłocki. It is a 3D puzzle game similar to Tetris. Technōs Japan developed an arcade port titled Block Out.', 'https://en.wikipedia.org/wiki/Blockout'),
  ('Q3179162', 'Jimmy White''s ''Whirlwind'' Snooker is a video game designed and produced by Archer Maclean, released by Virgin Games in 1991 for the Amiga, Atari ST, and IBM PC compatibles (later for the Mega Drive). A port for the Atari Lynx was planned but never released. ''Whirlwind'' Snooker is a realistic snooker simulator.

Although the game was not the first to simulate snooker (or pool) in 3D, it used the processing power and graphics capabilities of 16-bit home computers and was praised for its then ground-breaking realism and easy-to-use interface. ACE said that the game was the closest thing to being on a real snooker table which existed at the time, and it could be used by a player to refine real-life snooker skills.', 'https://en.wikipedia.org/wiki/Jimmy_White%27s_%27Whirlwind%27_Snooker'),
  ('Q2329383', 'Spider-Man vs. The Kingpin (originally released as Spider-Man) is a 1991 action-platform video game based on the Marvel Comics character Spider-Man. The game was originally developed by Technopop and Recreational Brainware and published by Sega for the Sega Genesis, before being ported by Sega to the Master System and Game Gear, with the latter version published by Acclaim Entertainment through its Flying Edge division. An updated version for the Sega CD, also developed by Sega, was released under the name The Amazing Spider-Man vs. The Kingpin.

The player controls Spider-Man as he battles various supervillains (Doctor Octopus, Sandman, the Lizard, Hobgoblin, Vulture, Mysterio, Electro, and Venom) in order to obtain the keys needed to disarm a nuclear bomb that the Kingpin has not only framed Spider-Man for stealing, but plans to detonate within 24 hours. In the middle of the game, Spider-Man''s wife Mary Jane Watson is also kidnapped by Venom.', 'https://en.wikipedia.org/wiki/Spider-Man_vs._The_Kingpin'),
  ('Q3072346', 'Final Blow is a 1989 boxing video game developed and released by Taito in arcades. It was released in Japan in April 1989 and in North America in June 1989 by Romstar.

In 1990, Sega released a port for the Sega Genesis titled James ''Buster'' Douglas Knockout Boxing, which features American boxer James "Buster" Douglas immediately after his upset victory over Mike Tyson, who signed with Nintendo to appear in Punch-Out!! for the Nintendo Entertainment System years earlier. (The Master System game released under the Knockout Boxing title in North America is a distinct game developed by Sanritsu Denki; it was released in Europe under the title Heavyweight Champ, taken from a previous Sega arcade boxing game.)', 'https://en.wikipedia.org/wiki/Final_Blow'),
  ('Q3062915', 'F-117 Night Storm is a Sega Genesis-exclusive video game that was released in 1993 by Electronic Arts.', 'https://en.wikipedia.org/wiki/F-117_Night_Storm'),
  ('Q3072379', 'Final Zone (known in Japan as FZ Senki Axis) is a 1990 isometric scrolling shooter developed and published by Wolf Team. Players take on the role of a mecha operator outfitted in the NAP suit. The NAP suit can carry 14 weapons out of the 20 available weapons and it is up to the player to use them to their maximum benefit. It is the third game released in the Final Zone series, following Final Zone Wolf and Final Zone II. On May 9, 2025 the game got ported to modern consoles as a re-release from Ratalaika Games.', 'https://en.wikipedia.org/wiki/Final_Zone'),
  ('Q3062974', 'F1 Circus is a series of Formula One-based racing video games developed and published by Nichibutsu starting on the PC Engine in 1990.', 'https://en.wikipedia.org/wiki/F1_Circus'),
  ('Q3062977', 'Nakajima Satoru Kanshū F1 Grand Prix is a 1991 Sega Mega Drive Formula One video game based on the career of Satoru Nakajima, who was the first full-time Japanese racer in the history of Formula One. This is the third video game collaboration between Nakajima and Varie, following Nakajima Satoru F-1 Hero and Nakajima Satoru F-1 Hero 2 for the Famicom. The entire 1991 Formula One season can be re-enacted with any of the notable contenders from the prestigious Formula One racing organization.', 'https://en.wikipedia.org/wiki/Nakajima_Satoru_Kansh%C5%AB_F1_Grand_Prix'),
  ('Q3060763', 'European Club Soccer (known as World Trophy Soccer in North America and J-League Champion Soccer in Japan) is a 1992 association football video game developed by Krisalis Software and published by Virgin Games (Game Arts in Japan) for the Mega Drive/Genesis. Based on Manchester United Europe, it focuses on the European Champions Cup. The game was a best-seller in the UK charts for three months.', 'https://en.wikipedia.org/wiki/European_Club_Soccer'),
  ('Q3146722', 'IMG International Tour Tennis is a sports video game developed by High Score Productions and published by EA Sports for the Sega Genesis.', 'https://en.wikipedia.org/wiki/IMG_International_Tour_Tennis'),
  ('Q3063006', 'Pier Solar and the Great Architects is an indie role-playing video game developed and published by WaterMelon for the Sega Mega Drive. The game was released worldwide on December 20, 2010. The game optionally utilizes the Mega CD expansion device to enhance its audio capabilities.', 'https://en.wikipedia.org/wiki/Pier_Solar_and_the_Great_Architects'),
  ('Q3153299', 'International Rugby Challenge (also known simply as International Rugby) is a rugby game on Mega Drive (Genesis) and the Amiga.', 'https://en.wikipedia.org/wiki/International_Rugby_Challenge'),
  ('Q3059230', 'Eternal Champions is a 1993 fighting game developed and published by Sega for the Sega Genesis. It features fighters pulled from different time periods competing in a tournament to win the chance to avert their deaths.

Sega released Eternal Champions following the success of Street Fighter II (1991) and Mortal Kombat (1992). The game tried to set itself apart with features such as a heavier emphasis on its story, unique gameplay mechanics, and elaborate finishing moves called "Overkills".

A second entry in the series, Eternal Champions: Challenge from the Dark Side (1995), was released for the Sega CD. The game also spawned two spin-off games, Chicago Syndicate (1995) and X-Perts (1996).', 'https://en.wikipedia.org/wiki/Eternal_Champions'),
  ('Q3180138', 'NFL ''95 is the sixth video game in the Joe Montana Football/NFL series. It is the last Sega football game to feature Joe Montana. Its sequel, Prime Time NFL Football, featured Deion Sanders.', 'https://en.wikipedia.org/wiki/NFL_%2795'),
  ('Q3286545', 'Powerball is a 1991 competitive sports video game developed and published for the Sega Genesis by Namco. It was re-released for the Wii''s Virtual Console in Japan on February 19, 2008, and in North America on March 24, 2008, at a cost of 800 Wii Points. This version is virtually identical to the original version. An enhanced remake of it was remade for Namco Anthology 1 for the PlayStation exclusive to Japan.', 'https://en.wikipedia.org/wiki/Powerball_(video_game)'),
  ('Q3276923', 'Magical★Taruruto-kun is a 1992 Japanese platform game developed by Game Freak and published by Sega for the Mega Drive. Based on Tatsuya Egawa''s manga and anime of the same name, it is the fifth game in the series and the only one to be released on the Mega Drive. This game would later be included in the lineup for the Japanese version of the Mega Drive Mini 2 in 2022 and would receive an unofficial English translation patch the following year.', 'https://en.wikipedia.org/wiki/Magical_Taruruto-kun_(Mega_Drive_video_game)'),
  ('Q1892615', 'Last Battle: Legend of the Final Hero is a side-scrolling martial arts beat ''em up released for the Mega Drive/Genesis in 1989 by Sega. It was one of the six games that were available as part of the Genesis launch lineup in the U.S. The Japanese version, titled Hokuto no Ken: Shinseikimatsu Kyūseishu Densetsu, is based on the manga and anime series Fist of the North Star (Hokuto no Ken in Japanese). Since the international version did not retain the Hokuto no Ken license, the graphics and characters'' names were altered. It was the second Hokuto no Ken game released by Sega, following the Mark III original, released internationally as Black Belt. Versions for the Commodore 64 and Amiga based upon Last Battle were developed and released by Elite in Europe in 1991.', 'https://en.wikipedia.org/wiki/Last_Battle_(video_game)'),
  ('Q1421541', 'The Killing Game Show is a run and gun video game developed by Raising Hell Software for the Amiga and Atari ST. It was published in 1990 by Psygnosis, then re-released later under the name Fatal Rewind for the Sega Genesis by Electronic Arts.', 'https://en.wikipedia.org/wiki/The_Killing_Game_Show'),
  ('Q1849822', 'Virtua Racing (V.R.) is a 1992 Formula One racing video game developed by Sega AM2 and published by Sega for arcades. It was initially a proof-of-concept application for exercising the "Model 1", a new 3D graphics platform then under development. The results were so encouraging that Virtua Racing was fully developed into a standalone arcade title.

Virtua Racing was among the highest-grossing arcade games of 1992 in Japan and North America, 1993 in Europe, Australia and worldwide. It successfully received the award for Most Innovative New Technology from the Amusement & Music Operators Association (AMOA). Virtua Racing is regarded as one of the most influential video games of all time, for laying the foundations for subsequent 3D racing games and for popularizing 3D polygon graphics among a wider audience. It was later ported to home consoles, starting with the Mega Drive/Genesis in 1994.', 'https://en.wikipedia.org/wiki/Virtua_Racing'),
  ('Q3276282', 'Madō Monogatari I is a 1996 role-playing video game developed and published by Compile for the Mega Drive. It is the last official Mega Drive game released in Japan. The game is part of the long-running Madō Monogatari series.

It is a later revision to the Game Gear version, Madō Monogatari I: Mittsu no Madō-kyū, which is based on the original MSX and PC98 versions, and borrows heavily from the PC Engine version, Madō Monogatari I: Honō no Sotsuenji.', 'https://en.wikipedia.org/wiki/Mad%C5%8D_Monogatari_I'),
  ('Q1891535', 'The Games: Winter Challenge is a sports video game developed by Canadian developer MindSpan and published by Accolade for MS-DOS compatible operating systems in 1991 and as Winter Challenge for the Sega Genesis/Mega Drive in Europe in 1991 and the United States in 1992. The game portrays eight winter sports events that are competed in during the Winter Olympics. The game is unlicensed and not endorsed by the International Olympic Committee or similar organisations. Upon release, Winter Challenge received praise from several publications, with attention directed to the game''s variety of events and visual presentation, with some criticism towards the inconsistency and difficulty of events. A sequel to the game based on the Summer Olympics, The Games: Summer Challenge, was released by Accolade in 1992.', 'https://en.wikipedia.org/wiki/The_Games:_Winter_Challenge'),
  ('Q3228640', 'Leander is a video game for the Amiga developed by Traveller''s Tales and published by Psygnosis in 1991. It was the first game developed by Traveller''s Tales. The game was developed on the Amiga, then converted to the Atari ST by Philipp Wyatt for W.J.S Design. A year later it was published for the Sega Mega Drive as Galahad by Electronic Arts.', 'https://en.wikipedia.org/wiki/Leander_(video_game)'),
  ('Q3206049', 'LHX Attack Chopper is a combat helicopter simulation game published by Electronic Arts in 1990. Development was led by Brent Iverson, who later designed Chuck Yeager''s Air Combat. The game was released for MS-DOS and ported to the Mega Drive/Genesis.

LHX is acronym from Light Helicopter Experimental.', 'https://en.wikipedia.org/wiki/LHX_Attack_Chopper'),
  ('Q3272979', 'MiG-29: Fighter Pilot (alternatively titled MiG-29: Fulcrum) is a 1993 video game developed by PanelComp and The Kremlin and published by Domark for the Sega Genesis. The game is a combat flight simulation game for the Mikoyan MiG-29, and was marketed as the first flight simulator for the console. Upon release, the game received mixed reviews, with critics praising the game''s depth and visual fidelity, and critiquing its controls, handling, and gameplay.', 'https://en.wikipedia.org/wiki/MiG-29:_Fighter_Pilot'),
  ('Q1584992', 'Wonder Boy in Monster World, known in Japan as Wonder Boy V: Monster World III, is a side-scrolling action role-playing game originally developed by Westone and published by Sega for the Mega Drive/Genesis in 1991. It is the fifth game in the Wonder Boy series and the third game in the Monster World sub-series, following Wonder Boy in Monster Land (Super Wonder Boy: Monster World on the Japanese Sega Mark III) and Wonder Boy III: The Dragon''s Trap (Monster World II: Dragon no Wana on the Japanese Game Gear).

Versions for other platforms were also made. In 1993, Sega released a Master System version of the game specifically for the European market, while in 1994, Hudson Soft remade the game for the TurboDuo under the title of The Dynastic Hero, featuring an all-new theme and cast of characters. In 2007, the Turbo Duo and Mega Drive versions were re-released on the Wii Virtual Console download service.', 'https://en.wikipedia.org/wiki/Wonder_Boy_in_Monster_World'),
  ('Q1617751', 'Marvel Land is a 1990 platform video game developed and published by Namco for arcades. It was released in January 1990 in Japan only. The game was ported to the Mega Drive in 1991, with the European version renamed Talmit''s Adventure. The game shares its name with the fictitious kingdom where the 1986 Japan-only Famicom game Valkyrie no Bōken: Toki no Kagi Densetsu takes place, but has no connections with it otherwise. Hamster Corporation released the game as part of their Arcade Archives series for the Nintendo Switch and PlayStation 4 in December 2022; it was only released in Japan due to licensing issues with Marvel Entertainment.', 'https://en.wikipedia.org/wiki/Marvel_Land'),
  ('Q3304202', 'MegaPanel is a 1990 puzzle video game developed and published by Namco for the Mega Drive in Japan.', 'https://en.wikipedia.org/wiki/Megapanel'),
  ('Q1635057', 'Gynoug, known in North America as Wings of Wor, is a 1991 scrolling shooter video game developed by NCS Corporation and published by Masaya for the Sega Genesis. The game was released in North America and Europe in 1991 and in Japan on January 25, 1991, and re-released on the Wii Virtual Console exclusively in Japan on May 20, 2008, and was re-released for the Nintendo Switch, PlayStation 4 and Xbox One on November 12, 2021.', 'https://en.wikipedia.org/wiki/Gynoug'),
  ('Q1648994', 'Bugs Bunny in Double Trouble is a Looney Tunes video game for the Sega Genesis and Game Gear, released in 1996. The game stars Bugs Bunny and features pre-rendered 3D graphics.', 'https://en.wikipedia.org/wiki/Bugs_Bunny_in_Double_Trouble'),
  ('Q2743846', 'Phelios is a 1989 vertically scrolling shooter video game developed and published by Namco for arcades. It was released only in Japan in February 1989. It later received a port for the Sega Genesis, which was released in Japan and North America in 1990 and Europe in 1991 by Sega. The Genesis version was released on the Wii''s Virtual Console in 2009. Hamster Corporation released the arcade version as part of their Arcade Archives series for the Nintendo Switch and PlayStation 4 in February 2023.', 'https://en.wikipedia.org/wiki/Phelios'),
  ('Q2743917', 'Mystical Fighter, originally released in Japan as Maō Renjishi is a beat ''em up game for the Sega Genesis.

The story, designs and characters are based on Japanese mythology.', 'https://en.wikipedia.org/wiki/Mystical_Fighter_(video_game)'),
  ('Q3303131', 'Mazin Saga: Mutant Fighter is a 1993 hybrid beat ''em up/fighting video game developed by Almanic Corporation, in conjunction with ALU and Team "Saga", and published by Sega for the Sega Genesis/Mega Drive in Japan and Europe and later in North America by Vic Tokai. Based upon Go Nagai''s MazinSaga mecha manga, which is considered a combination of Nagai''s Mazinger and Devilman franchises, players assume the role of Koji Kabuto wielding the Mazinger Z armor to fight against powerful ''Bio Beasts'' led by God Kaiser Hell. Co-directed by Satsuki Mizuno, Takashi Yoneda and "Tommy Bon Bon", the title was created by most of the same team that worked on previous projects at Almanic such as E.V.O.: Search for Eden. It was met with mostly positive reception from critics since its release.', 'https://en.wikipedia.org/wiki/Mazin_Saga:_Mutant_Fighter'),
  ('Q3297871', 'Master of Weapon is a 1989 vertically scrolling shooter video game developed and published by Taito for arcades. It was released in Japan in May 1989. A port to the Sega Mega Drive was released in 1991 exclusively in Japan.

Hamster Corporation released the game as part of their Arcade Archives series for the Nintendo Switch and PlayStation 4 in February 2024.', 'https://en.wikipedia.org/wiki/Master_of_Weapon'),
  ('Q3303623', 'McDonald''s Treasure Land Adventure is a 1993 platform game developed by Treasure and published by Sega for the Sega Genesis. Based on the McDonald''s fast food restaurant chain, specifically its McDonaldland marketing campaign, players control Ronald McDonald in his efforts to retrieve the missing pieces of a map that lead to the location of a buried treasure from a group of villains. Ronald can defeat enemies by using a magic attack and can latch onto hooks with his scarf to reach higher platforms.

Treasure Land Adventure was developed by Treasure in conjunction with the run and gun video game Gunstar Heroes (1993). Sega commissioned Treasure to design a McDonald''s game after the company was ineligible to receive a publishing contract to develop games for the Genesis. Treasure president and project programmer Masato Maegawa mandated that the game had to be faithful and respectful to the McDonald''s licensing and characters during production.', 'https://en.wikipedia.org/wiki/McDonald%27s_Treasure_Land_Adventure'),
  ('Q3295079', 'Marsupilami is a 1995 video game based on the comic book series of the same name developed by British studio Apache Software and published by Sega for the Genesis in 1995–1996.', 'https://en.wikipedia.org/wiki/Marsupilami_(video_game)'),
  ('Q3293344', 'Mario Andretti Racing is a video game that was released in 1994 on the Sega Genesis/Mega Drive. It was an early title in the newly created EA Sports line, and was developed by Stormfront Studios and High Score Productions. The game was produced by famed sports game developer Scott Orr as part of his collaboration with Richard Hilleman in the creation of EA Sports. Race driver Mario Andretti personally guided the development of the AI used by the non-player drivers in stock cars, Indy style open wheel racing, and dirt track racing.

The game uses different physics and AI for three kinds of racing.', 'https://en.wikipedia.org/wiki/Mario_Andretti_Racing'),
  ('Q2742954', 'NHL Hockey is an ice hockey video game developed by Park Place Productions and published by Electronic Arts. Released in the summer of 1991 exclusively for the Sega Genesis/Mega Drive, the game allows one to two players to play action-oriented hockey matches that include events such as fighting, power plays, and penalties. Officially licensed by the National Hockey League, NHL Hockey features the teams from the 1990–91 NHL season. It was released in Europe as EA Hockey and in Japan as Professional Hockey, with country-based teams due to the lack of a worldwide league license.

As part of Electronic Arts'' push to release console games for the Sega Genesis, the development team included several members of the group who created the 1990 game John Madden Football. The team aimed to replicate the general concepts that made their football game successful. While they did not have access to the NHL players'' likeness, the developers based the virtual players on real life players'' skills and identified them by their respective jersey numbers.', 'https://en.wikipedia.org/wiki/NHL_Hockey'),
  ('Q3341425', 'Nightmare Circus is a platform video game developed by Funcom and published by Tec Toy for the Sega Mega Drive. The game was first released in April 1996 on the Sega Channel in North America by Sega, and physically released on cartridge in Brazil sometime that same year. It was also released on the Sega Channel in Europe the following year.', 'https://en.wikipedia.org/wiki/Nightmare_Circus'),
  ('Q3330920', 'Mutant League Football is a video game that was originally released in 1993 for the Sega Genesis. The game was designed using an engine designed specifically for it, and features a different take on gridiron football, where it resembles a war as much as a sporting competition.

A year later, the same team applied similar concepts to the sport of ice hockey to create Mutant League Hockey. An animated TV series based around the games, Mutant League, aired from July 1994 to February 1996, while a spiritual successor, Mutant Football League was released in 2017.', 'https://en.wikipedia.org/wiki/Mutant_League_Football'),
  ('Q3315545', 'Minnesota Fats: Pool Legend is a 1995 pool (pocket billiards) video game for the Sega Genesis and Sega Saturn. It was also released in Japan for the Saturn under the alternative title Side Pocket 2: Legend of Hustler. The game features fictional pool hustler Minnesota Fats. It was released as a sequel to Data East''s earlier success Side Pocket.', 'https://en.wikipedia.org/wiki/Minnesota_Fats:_Pool_Legend'),
  ('Q3313279', 'Mike Ditka Ultimate Football is a 1991 video game published by Accolade.', 'https://en.wikipedia.org/wiki/Mike_Ditka_Ultimate_Football'),
  ('Q3330921', 'Mutant League Hockey is an ice hockey video game that was released in 1994 for the Sega Genesis. It is the follow up to Mutant League Football (1993).', 'https://en.wikipedia.org/wiki/Mutant_League_Hockey'),
  ('Q3334216', 'NBA Action ''95: Starring David Robinson is a sports video game developed by American studio Double Diamond Sports and published by Sega for the Sega Genesis in 1995.', 'https://en.wikipedia.org/wiki/NBA_Action_%2795'),
  ('Q3334364', 'NFL Sports Talk Football ''93 Starring Joe Montana is an American football-themed video game featuring Joe Montana, released in 1992. It is the third in the series, and the first to be licensed by the National Football League (NFL).', 'https://en.wikipedia.org/wiki/NFL_Sports_Talk_Football_%2793_Starring_Joe_Montana'),
  ('Q3334363', 'NFL Football ''94 Starring Joe Montana, released as simply NFL Football ''94 in Japan, is a 1993 American football video game developed by BlueSky Software and published by Sega for the Sega Genesis. It features realistic running commentary while the player engages in exhibition, regular season, or playoff action. It is fifth in the Joe Montana Football series and the fourth to be developed by BlueSky Software. Unlike the earlier Joe Montana Football, this game had both NFL and NFLPA licenses, and as such, contains all of the league''s (then) 28 NFL teams, as well as its players and their attributes for the 1993 season.', 'https://en.wikipedia.org/wiki/NFL_Football_%2794_Starring_Joe_Montana'),
  ('Q3357305', 'Osomatsu-kun: Hachamecha Gekijō is a platform video game by Sega, which was released in 1988 for the Sega Mega Drive. An early Mega Drive title, it never saw a release outside of Japan. The game was based on the manga Osomatsu-kun by Fujio Akatsuka, and acts as a promotion for the anime adaptation that premiered the same year. The player controlled the title character and encountered many of the series'' characters in a strange, comical world.', 'https://en.wikipedia.org/wiki/Osomatsu-kun:_Hachamecha_Gekij%C5%8D'),
  ('Q3351654', 'Olympic Gold is a 1992 sports video game developed by Tiertex Design Studios and published by U.S. Gold for the Sega Mega Drive/Genesis, Master System and Game Gear. Based on the 1992 Summer Olympics in Barcelona, Spain, it was the first officially licensed Olympic video game, receiving approval from the International Olympic Committee.

The game features seven Olympic sporting events, including athletics, swimming, diving and archery. Players can compete against computer-controlled opponents or participate in multiplayer competitions, with three difficulty settings available. Gameplay primarily involves rapid button pressing and timing-based controls.', 'https://en.wikipedia.org/wiki/Olympic_Gold_(video_game)'),
  ('Q3359668', 'PGA Tour Golf II is a golf video game developed by American studio Polygames and published by EA Sports for Sega Genesis in 1993 and Time Warner Interactive for Game Gear in 1995.', 'https://en.wikipedia.org/wiki/PGA_Tour_Golf_II'),
  ('Q3352809', 'Onslaught is a video game that was released by Hewson in 1989 for the Amiga and subsequently ported to the Atari ST, MS-DOS, and Mega Drive. The game is a fantasy-themed platform game with an eerie soundtrack and graphic violence.

Onslaught was re-released for iOS in December 2008 and for the Xbox 360 in January 2009 for the Xbox 360 via Xbox Live.', 'https://en.wikipedia.org/wiki/Onslaught_(1989_video_game)'),
  ('Q3359671', 'PGA Tour Golf III is a sports video game developed by Polygames and High Score Productions and published by EA Sports for Sega Genesis in 1994 as the third mainline entry in the PGA Tour series. A Macintosh version co-developed by Manley & Associates was released in 1995. Ports were also announced for the Super NES, Game Boy, and Game Gear as part of 1995 publishing deal between Electronic Arts and THQ. None were released under the title PGA Tour Golf III. However, the next game in the series, PGA Tour 96, did show up on those consoles that year.', 'https://en.wikipedia.org/wiki/PGA_Tour_Golf_III'),
  ('Q3114577', 'Jennifer Capriati Tennis (known as GrandSlam: The Tennis Tournament ''92 in Japan and in PAL regions as GrandSlam: The Tennis Tournament) is a Sega Genesis video game developed by System Sacom and released in 1992. The game is named after Jennifer Capriati, one of the world''s top-ranked female tennis players at the WTA Tour during the time of the game''s release.', 'https://en.wikipedia.org/wiki/Jennifer_Capriati_Tennis'),
  ('Q3046920', 'Ecco Jr. is a video game in the Ecco the Dolphin series, released by Sega in 1995. It has the controls and basic gameplay of the other two Mega Drive/Genesis titles, but is geared towards younger players, lacking the high difficulty of Ecco the Dolphin and Ecco: The Tides of Time.', 'https://en.wikipedia.org/wiki/Ecco_Jr.'),
  ('Q783493', 'Panorama Cotton is a 1994 rail shooter video game developed by Success and published by Sunsoft for the Mega Drive exclusively in Japan on August 12, 1994. Panorama Cotton is the third entry in the Cotton series and made a major departure from the original gameplay formula of prior Cotton entries; instead of being a side-scrolling shooter like the others, it is a pseudo-3D shooter in the style of Sega''s Space Harrier.', 'https://en.wikipedia.org/wiki/Panorama_Cotton'),
  ('Q3073740', 'Flink (full name: The Misadventures of Flink according to the title screen) is a 1994 platform video game developed by former members of Thalion and published by Psygnosis.', 'https://en.wikipedia.org/wiki/Flink'),
  ('Q770439', 'Double Dribble: The Playoff Edition, originally released in Japan as Hyper Dunk: The Playoff Edition, and later released in Europe as HyperDunk, is a basketball video game developed and published by Konami for the Sega Genesis. It is the follow-up to the Double Dribble, originally released for the arcade in 1986 and various home computer systems and consoles.', 'https://en.wikipedia.org/wiki/Double_Dribble:_The_Playoff_Edition'),
  ('Q1837963', 'Vectorman 2 is a 1996 action-platform video game developed by BlueSky Software and published by Sega for the Sega Genesis. Released a year after the original Vectorman, the game retains the game''s core gameplay while expanding its mechanics. Multiple attempts to create a Vectorman 3 were proposed to Sega, with none of them coming to fruition.', 'https://en.wikipedia.org/wiki/Vectorman_2'),
  ('Q764390', 'Desert Demolition Starring Road Runner and Wile E. Coyote is a platform video game developed by BlueSky Software and published by Sega for the Sega Genesis. The game was released in North America in February 1995 and in Europe on April 21, 1995. The game is based around Wile E. Coyote and the Road Runner, who are the game''s player characters and are tasked with playing through a series of levels as they respectively pursue and evade the other. The game was re-released as part of the Sega Mega Hits range in September 1997.', 'https://en.wikipedia.org/wiki/Desert_Demolition'),
  ('Q3046442', 'Earnest Evans is a 1991 platform game by Wolf Team. It was self-published in Japan for the Sega Mega-CD and the Sega Genesis in North America by Renovation Products three months later. As with Sol-Feace, the Mega-CD release has a Mixed Mode CD soundtrack along with animated cutscenes created by Madhouse.

Earnest Evans is the second game (but first chronologically) of a trilogy which also includes El Viento (1991) and Annet Returns (1993). All three games were re-released in Japan in December 2025 as part of the Earnest Evans Collection. A western localization of the collection was later released in January 2026.', 'https://en.wikipedia.org/wiki/Earnest_Evans'),
  ('Q3046535', 'Ayrton Senna''s Super Monaco GP II is an arcade-style Formula One racing video game developed and manufactured by Sega for the Genesis, Master System, and Game Gear in 1992. It is a follow-up to Super Monaco GP. The game was also endorsed by, and had technical input from, the then-Formula One champion Ayrton Senna. Gameplay includes a World Championship season featuring recreations of the tracks in the 1991 Formula One World Championship, along with a three-race "Senna GP" mode set on fictional tracks.

The game was initially suggested by Sega''s distributor in Brazil, Tec Toy, but developed by Sega in Japan. The game''s development was also assisted by Senna, who personally supplied his own advice about the tracks featured in the game. Reception to Ayrton Senna''s Super Monaco GP II was mixed to positive, with reviewers praising the gameplay and the graphics but criticizing too few changes from Super Monaco GP.', 'https://en.wikipedia.org/wiki/Ayrton_Senna%27s_Super_Monaco_GP_II'),
  ('Q3108852', 'Gley Lancer is a 1992 scrolling shooter video game originally developed by NCS Corporation, published in Japan by Masaya and in South Korea by Samsung for the Sega Mega Drive/Genesis. It was re-released in 2019 by Japanese publisher Columbus Circle. It follows Lucia Cabrock, daughter of Earth Federation Navy admiral Ken, who disappeared while fighting in a war between humans and an unknown alien race that possess the ability to teleport, joined by her friend Teim on a journey to save her father by stealing a starfighter. Controlling the titular fighter ship, the player must fight waves of enemies and bosses, while avoiding collision with their projectiles and other obstacles. The Gley Lancer ship is equipped with two satellites options, whose positions and formations are determined by the player.', 'https://en.wikipedia.org/wiki/Gley_Lancer'),
  ('Q851032', 'Gain Ground is a 1988 action arcade video game developed and published by Sega. It is set within a supercomputer''s simulation of war, and follows up to three players traversing through a series of forty levels themed after select periods of human history. The goal of each level, depending on the player''s choice, is either to guide at least one player character safely to an exit point or to destroy all enemies, either of which must be completed within a time limit.

It was later ported to the Master System, Mega Drive/Genesis, and TurboGrafx-CD.', 'https://en.wikipedia.org/wiki/Gain_Ground'),
  ('Q1848971', 'Shadowrun is an action role-playing game for the Sega Genesis, released in 1994 in North America and Asia only. It was adapted from the cyberpunk role-playing game Shadowrun by FASA, and was developed by BlueSky Software. The game is the second video game adapted from Shadowrun, and has a more open ended style of gameplay than its 1993 Super NES counterpart, Shadowrun by Beam Software.', 'https://en.wikipedia.org/wiki/Shadowrun_(1994_video_game)'),
  ('Q3113414', 'Granada is a shooter video game developed and originally published by Wolf Team exclusively for the X68000 in Japan on 20 April 1990. The ninth title to be created and released by Wolf Team for the X68000 platform, the game is set in a futuristic Africa in 2016 where a war erupted over mining rights towards rare metals and has quickly escalated due to newly introduced weapons called Maneuver Cepters. Players assume the role of mercenary Leon Todo piloting the titular Maneuver Cepter tank unit in an attempt to stop the conflict once and for all. Its gameplay mainly consists of action and shooting mixed with mission-based exploration using a main two-button configuration.', 'https://en.wikipedia.org/wiki/Granada_(video_game)'),
  ('Q3053294', 'Steel Empire (originally released as Koutetsu Teikoku in Japan, and otherwise known in various English materials as The Steel Empire or Empire of Steel) is a horizontally scrolling shooter released on the Sega Genesis in 1992. Versions for the Game Boy Advance and Nintendo 3DS were released in 2004 and 2014, respectively. The game was released on the Nintendo Switch at the end of July 2025.

Steel Empire is notable among shoot ''em ups for its unique aesthetic designs. Mostly low-tech in nature, with it being set in a late-19th century alternate world, the game''s aircraft, weaponry, power-ups, environments, enemies and bosses are heavily stylized. Their design added strong steampunk elements to the style, themes and visuals of the game. Steam power, propeller-based aircraft, biplanes, dirigibles and heavily-armored steam trains with giant cannons play large roles as the game''s protagonists and opponents.', 'https://en.wikipedia.org/wiki/Steel_Empire'),
  ('Q3116002', 'Greatest Heavyweights is a boxing video game that was published by Sega in 1993 for the Sega Genesis console. It is a follow-up to Evander Holyfield''s Real Deal Boxing and is virtually identical in many ways, apart from a number of significant improvements.', 'https://en.wikipedia.org/wiki/Greatest_Heavyweights'),
  ('Q3178819', 'Volfied is a 1989 puzzle video game developed and published by Taito for arcades. It was released only in Japan in July 1989. It is a successor to Qix, with extra features and a futuristic science fiction aesthetic, rather than Qix''s abstract geometry style; the player pilots a small spaceship named "Monotros" instead of a marker, and the enemies come in the form of various aliens.', 'https://en.wikipedia.org/wiki/Volfied'),
  ('Q3180136', 'Joe Montana Football is a 1990 American football video game published by Sega. While the game does feature Joe Montana as a playable character, Sega did not obtain licenses from either the National Football League or the National Football League Players Association (NFLPA), meaning no other players, nor any official team names, are used. It was the first of many Sega-published football games of the 1990s prior to moving into the NFL 2K branding in the 2000s.', 'https://en.wikipedia.org/wiki/Joe_Montana_Football'),
  ('Q781306', 'Battle Master is a 1990 fantasy action adventure game designed by Mike Simpson and Simon Jones for PSS and published by Mirrorsoft. The game is a fantasy adventure in which the player controls a champion who must battle evil forces to conquer four kingdoms, uniting the four kings'' crowns and presenting them to the Watcher in order to restore the world to peace.', 'https://en.wikipedia.org/wiki/Battle_Master'),
  ('Q1929072', 'Shining Force: The Legacy of Great Intention, commonly referred to as Shining Force, is a 1992 turn-based tactical role-playing game developed by Climax Entertainment and Sonic! Software Planning and published by Sega for the Sega Genesis. It is the second entry of the Shining series, following 1991''s Shining in the Darkness. While primarily a traditional fantasy-themed game, it contains some science fiction elements.

The game has been re-released for various platforms: in Sega Smash Pack Volume 1 for the Dreamcast and Sega Smash Pack 2 for Microsoft Windows, in Sonic''s Ultimate Genesis Collection for Xbox 360 and PlayStation 3, and as a standalone game for the Wii Virtual Console and Windows via Steam. Additionally, a remake was released for the Game Boy Advance in 2004 under the title Shining Force: Resurrection of the Dark Dragon. In 2010, the game was released for iOS but was discontinued in 2015. It was re-released again on the Nintendo Classics service in 2021.', 'https://en.wikipedia.org/wiki/Shining_Force'),
  ('Q2367099', 'Combat Cars is a racing vehicular combat game developed by Scangames and published by Accolade, and released for the Sega Genesis in 1994.', 'https://en.wikipedia.org/wiki/Combat_Cars'),
  ('Q1922754', 'Puggsy is a 1993 puzzle-platform game developed by Traveller''s Tales and published by Psygnosis. It was released for the Mega Drive and Mega-CD consoles, as well as the Amiga home computer, on October 1993 in Europe and in North America on January 6, 1994. The game was to be released for the Super Nintendo Entertainment System, but the version was cancelled. The game revolves around the titular character Puggsy, an orange space hopper–like alien who landed his spaceship on The Planet, intending to return home until his spaceship was stolen by the raccoon natives of the planet.', 'https://en.wikipedia.org/wiki/Puggsy'),
  ('Q1937111', 'Back to the Future Part III (or Back to the Future III) is a video game based on the film of the same name. The game is different from LJN''s Back to the Future Part II & III video game released for the NES. The game was released in 1991 for the Genesis, Amiga, Amstrad CPC, Atari ST, Commodore 64, MS-DOS, Master System, and the ZX Spectrum. Each version of the game is more or less identical and all are loosely based on the popular film of the same name. The game was developed by Probe Software and published by Image Works and Arena Entertainment (for Sega).', 'https://en.wikipedia.org/wiki/Back_to_the_Future_Part_III_(video_game)'),
  ('Q1923897', 'Teenage Mutant Ninja Turtles: The Hyperstone Heist, released in Europe as Teenage Mutant Hero Turtles: The Hyperstone Heist and in Japan as Teenage Mutant Ninja Turtles: Return of the Shredder, is a 1992 beat ''em up game developed and published by Konami for the Sega Genesis, based on the Teenage Mutant Ninja Turtles comic book characters. It was Konami''s debut title for the Genesis. The game was re-released as part of Teenage Mutant Ninja Turtles: The Cowabunga Collection in 2022.', 'https://en.wikipedia.org/wiki/Teenage_Mutant_Ninja_Turtles:_The_Hyperstone_Heist'),
  ('Q1462499', 'Starflight is a space exploration, combat, and trading role-playing video game created by Binary Systems and published by Electronic Arts in 1986. Originally developed for IBM PC compatibles, it was later ported to the Amiga, Atari ST, Mac, and Commodore 64. A fully revamped version of the game was released for the Genesis in 1991.

Set in the year 4620, the game puts players in the role of a starship captain sent to explore the galaxy. There is no set path, allowing players to switch freely between mining, ship-to-ship combat, and alien diplomacy. The broader plot of the game emerges slowly, as the player discovers that an ancient race of beings is causing stars to flare and destroy all living creatures.', 'https://en.wikipedia.org/wiki/Starflight'),
  ('Q1481597', 'Shadow of the Beast is a platform game developed by Reflections and published in 1989 by Psygnosis for the Amiga. It was ported to several other systems. The game was known for its graphics, with many colours on screen and up to twelve levels of parallax scrolling backdrops, and for its atmospheric score composed by David Whittaker that used high-quality instrument samples.

It was followed by two sequels, Shadow of the Beast II in 1990 and Shadow of the Beast III in 1992. The series was acquired by Sony Interactive Entertainment through Psygnosis, with Heavy Spectrum Entertainment Labs developing a remake, which was released for the PlayStation 4 in May 2016.', 'https://en.wikipedia.org/wiki/Shadow_of_the_Beast_(1989_video_game)'),
  ('Q3201028', 'Kyūkai Dōchūki is a baseball arcade game that was released by Namco in 1990 in Japan; it runs on Namco System 2 hardware, and is a spin-off of Yokai Dochuki. The gameplay is similar to Namco''s own World Stadium series, except that both players have a total of thirty-six different teams to choose from in the Japanese, Arabic, German, Humbaba, American, Russian, and Chinese leagues. The Japan League has five stadiums, and if the player selects one team from it, the game will randomly decide which stadium the match will take place in, but the other leagues only have one stadium. This game also features a cameo re-appearance, from Valkyrie (as in no Densetsu), who appears to report the final outcome of a match once it has finished. Namco''s signature character Pac-Man can also be seen on two of the television screens in a studio wearing a purple bow tie (in his Pac-Land-style anthropomorphized form, as opposed to his "original" one).', 'https://en.wikipedia.org/wiki/Ky%C5%ABkai_D%C5%8Dch%C5%ABki'),
  ('Q3197030', 'King Salmon: The Big Catch is a 1992 Sega Genesis/Mega Drive fishing video game that was developed by Hot-B and was released by Vic Tokai in North America. It was due for release in Europe by July, but the plan was cancelled.', 'https://en.wikipedia.org/wiki/King_Salmon_(video_game)'),
  ('Q1760261', 'Landstalker: The Treasures of King Nole is a 1992 action role-playing video game developed by Climax Entertainment and published by Sega for the Sega Genesis. The player takes on the role of the treasure hunter Nigel as they navigate a three-dimensional world through an isometric viewpoint, solving puzzles and fighting enemies.

The game was a critical and commercial success. A spinoff called Lady Stalker: Challenge from the Past was released in Japan for the Super NES in 1995. A sequel was in the planning stages but was cancelled. Dark Savior and Alundra are considered spiritual successors. Nigel is a playable character in Time Stalkers.', 'https://en.wikipedia.org/wiki/Landstalker'),
  ('Q1742178', 'King''s Bounty is a turn-based fantasy video game designed by Jon Van Caneghem and published by New World Computing in 1990. The game follows the player''s character, a hero of King Maximus, appointed with the job of retrieving the Sceptre of Order from the forces of chaos, led by Arech Dragonbreath. King''s Bounty is notably considered the forerunner of the Heroes of Might and Magic series of games.

A Sega Genesis port was developed and released in North America on February 21, 1991, with a multitude of graphical changes. The gameplay was also modified to incorporate real time overworld exploration.', 'https://en.wikipedia.org/wiki/King%27s_Bounty');

insert into import_summary (wikidata_id, summary, source) values
  ('Q3181983', 'John Madden Football ''92, released as Pro Football in Japan, is a 1991 American football video game developed by Park Place Productions and published by Electronic Arts for the Sega Genesis. It was the second Madden title released for the console, following the original John Madden Football from the previous year, starting the tradition of annual installments.

New aspects of this version include instant replay, two-player cooperative play, quarterback injuries, highlights, and more audibles. There are also new play modes, such as pre-season games, regular season games, playoffs, and sudden death, which was a way to simulate overtime in NFL games. Quarter lengths have been adjusted in this version to be set at 5, 10, or 15 minutes. As in previous versions of the video game, there are no NFL or NFLPA licenses for authentic teams, player names, and stadiums. Teams are organized by city name and colors.', 'https://en.wikipedia.org/wiki/John_Madden_Football_%2792'),
  ('Q3129867', 'Hellfire is a 1989 horizontally scrolling shooter video game developed by Toaplan and published by Taito for Japanese arcades; in North America, it was distributed by U.S.A. Games. The first horizontal shoot ''em up title to be created by Toaplan, the game takes place in the year 2998, where a space matter known as Black Nebula, created by robot dictator Super Mech, spreads and threatens to engulf human-controlled galaxies. Players assume the role of Space Federation member Captain Lancer, taking control of the CNCS1 spacecraft in a surprise attack to overthrow the enemies using the spacecraft''s titular weapon.', 'https://en.wikipedia.org/wiki/Hellfire_(video_game)'),
  ('Q3129155', 'Heavy Unit is a horizontally scrolling shooter arcade video game developed by Kaneko and published by Taito in 1988. A version for the PC Engine was released on December 22, 1989. There was also a Mega Drive conversion by Toho entitled "Heavy Unit: Mega Drive Special" released on December 26, 1990. The player takes control of a star ship that can transform into a mecha by obtaining a specific type of power up.', 'https://en.wikipedia.org/wiki/Heavy_Unit'),
  ('Q3129151', 'Heavy Nova is a 1991 video game developed and published by Micronet for the Sega CD, Sega Genesis, and X68000 that combines elements of fighting games with platform games and mission elements. Players assume the role of a robot operator destined to earn the highest operator rank. To do so, the robot – known in the game as a Heavy DOLL – must complete a combat training camp which prompts the 2D Platformer stages. The player then must combat other Heavy DOLLs as the end-level bosses which prompts the 2D fighting elements. A sequel, Black Hole Assault, was released in 1992; it is a fighting game unlike its predecessor.', 'https://en.wikipedia.org/wiki/Heavy_Nova_(video_game)'),
  ('Q3128710', 'High Seas Havoc, known in Japan as Captain Lang and in Europe as simply Havoc, is a 1994 platform video game developed and published by Data East for the Sega Mega Drive/Genesis. It was also released in the arcades running on a Sega Mega Drive/Genesis-based arcade cabinet.', 'https://en.wikipedia.org/wiki/High_Seas_Havoc'),
  ('Q3374580', 'Pelé! is a 1993 sports video game developed by Radical Entertainment and published by Accolade for the Sega Genesis. The game is based on the sport of association football and puts the player in control of a football team in modes of play such as exhibitions, tournaments, and seasons. It is named after and endorsed by former Brazilian footballer Pelé, who also provided input on the game''s design.

Pelé! received mixed reviews from critics, who commended the graphics and amount of options, but criticized the controls and difficulty. A sequel, Pelé II: World Tournament Soccer, was released in 1994.', 'https://en.wikipedia.org/wiki/Pel%C3%A9!'),
  ('Q3374584', 'Pelé! is a 1993 sports video game developed by Radical Entertainment and published by Accolade for the Sega Genesis. The game is based on the sport of association football and puts the player in control of a football team in modes of play such as exhibitions, tournaments, and seasons. It is named after and endorsed by former Brazilian footballer Pelé, who also provided input on the game''s design.

Pelé! received mixed reviews from critics, who commended the graphics and amount of options, but criticized the controls and difficulty. A sequel, Pelé II: World Tournament Soccer, was released in 1994.', 'https://en.wikipedia.org/wiki/Pel%C3%A9!'),
  ('Q3376406', 'Pete Sampras Tennis is a sports video game published by Codemasters for the Sega Genesis and Game Gear in 1994. A Master System version was cancelled in development. It was followed by Sampras Tennis 96 for the Genesis and Pete Sampras Tennis ''97.', 'https://en.wikipedia.org/wiki/Pete_Sampras_Tennis'),
  ('Q3401632', 'Premier Manager is a football management simulation video game for the Amiga, Atari ST, Acorn Archimedes, and MS-DOS. It was released in 1992 by Gremlin Interactive. A Mega Drive conversion was published in 1995. While the Amiga, Atari, and MS-DOS versions are similar, the Mega Drive version more closely resembles Premier Manager 2. The objective of the game is to manage a football club successfully within the top five divisions of the English league system. Premier Manager is the first game in the Premier Manager series.', 'https://en.wikipedia.org/wiki/Premier_Manager_(video_game)'),
  ('Q3388331', 'Pigskin 621 A.D. is an arcade game released in 1990 by Midway Manufacturing under the "Bally Midway" label. One player can battle the computer, or two players can battle head-to-head. Two teams compete to score as many touchdowns as possible in the tradition of American football, but actual play is more similar to rugby football.

A version for the Sega Genesis, retitled Jerry Glanville''s Pigskin Footbrawl and endorsed by coach Jerry Glanville, was released by RazorSoft on December 18, 1992.', 'https://en.wikipedia.org/wiki/Pigskin_621_A.D.'),
  ('Q3401627', 'Premier Manager 97 is a football management simulator video game developed by Gremlin Interactive and published by Sega for the Mega Drive in 1996. A PC Windows version was released in 1997. It is the fourth game in the Premier Manager series.', 'https://en.wikipedia.org/wiki/Premier_Manager_97'),
  ('Q3440538', 'Rolo to the Rescue is a video game developed by British studio Vectordean and published by Electronic Arts for the Sega Mega Drive/Genesis, released in 1993. The game is a two-dimensional action game with platforming elements, starring Rolo the elephant. Several other animal characters are playable once Rolo rescues them.', 'https://en.wikipedia.org/wiki/Rolo_to_the_Rescue'),
  ('Q3440505', 'Rolling Thunder 3 is a 1993 run and gun video game published by Namco released for the Sega Genesis. It is the third and final game in the Rolling Thunder series after Rolling Thunder and Rolling Thunder 2.

The game was made specifically for the Genesis, unlike the previous two games in the series. Also unlike its predecessors, Rolling Thunder 3 was released only in North America.', 'https://en.wikipedia.org/wiki/Rolling_Thunder_3'),
  ('Q3464074', 'Saint Sword is a hack-and-slash action game developed by Cyclone Systems and published by Taito for the Sega Genesis/Mega Drive in 1991.', 'https://en.wikipedia.org/wiki/Saint_Sword'),
  ('Q3477018', 'Second Samurai is a video game released for the Amiga in 1993. It is the sequel to the 1991 game First Samurai. A Mega Drive version was later released in 1994 which features different graphics, sound and level design to the Amiga version.', 'https://en.wikipedia.org/wiki/Second_Samurai'),
  ('Q3470929', 'Sampras Tennis 96 is a 1995 tennis video game for the Sega Mega Drive developed by Codemasters. It is the sequel to Pete Sampras Tennis. Like its predecessor, it was one of the few titles released on the J-Cart format, which provides two additional controller ports for multiplayer games. The game was followed by Pete Sampras Tennis ''97, which was released for the PlayStation and personal computers.', 'https://en.wikipedia.org/wiki/Sampras_Tennis_96'),
  ('Q3434076', 'Road Rash 3 is a 1995 racing and vehicular combat video game originally published by Electronic Arts (EA) for the Sega Genesis. It is the fourth installment in the Road Rash series and the last to be released for the Genesis. The game is centered around a worldwide series of motorcycle races that the player must win to advance to higher-difficulty races, while engaging in unarmed and armed combat to hinder the other racers.

Development of Road Rash 3 began after series programmer Dan Geisler experienced frustration working on Michael Jordan: Chaos in the Windy City and offered to make a new Road Rash title instead. The game''s worldwide settings were influenced by the need for a significant new feature despite the Genesis''s technology having been pushed to its limit. The game was positively received by critics and commercially successful; critics appreciated the refined gameplay and visuals, but pointed out a lack of innovation, and had mixed reactions to the audio.', 'https://en.wikipedia.org/wiki/Road_Rash_3'),
  ('Q3425578', 'Rent a Hero is an action role-playing video game series released by Sega for the Mega Drive console in 1991 with a large emphasis on humor. The game features the same graphic engine previously used in the development of Sword of Vermilion. However, Rent a Hero has an unusual innovation for the genre. Instead of using standard turn-based battles, fights are in a similar format to 2D fighting games.', 'https://en.wikipedia.org/wiki/Rent_a_Hero'),
  ('Q3431195', 'Richard Scarry''s Busytown is a 1993 educational video game developed by Novotrade for preschool children. It was released for MS-DOS, Classic Mac OS, and Sega Genesis. This game was based on the Best...Ever! series of VHSes distributed by Random House''s home video division, which preceded the TV series''s The Busy World of Richard Scarry that was produced by CINAR and Paramount Television.

A remake was published in 1999 by Pearson Software for Windows and Classic Mac OS (System 7.5.1 and later), with the visuals and animation updated to resemble that of The Busy World of Richard Scarry, and the dialogue re-recorded with Boston actors.', 'https://en.wikipedia.org/wiki/Richard_Scarry%27s_Busytown'),
  ('Q3412560', 'Four Trax is a 1989 racing video game developed and published by Namco for arcades. It was released in North America by Atari Games. It was ported to the Mega Drive/Genesis in 1991 as Quad Challenge.', 'https://en.wikipedia.org/wiki/Four_Trax'),
  ('Q3422429', 'Bahamut Senki is a tactical role-playing game developed by Sega for the Sega Mega Drive in 1991. It was only released in Japan.

The game offers a unique soundtrack for each of the many playable "races" in the game, and has various levels of gameplay that ranged from arcade Archon-style creature-on-creature combat to strategy similar to Koei''s strategy games like Gemfire and Nobunaga''s Ambition. Two-player games are also an option, given the variety that the game offered with the occasional arcade action battle to break up the quiet strategy and planning.', 'https://en.wikipedia.org/wiki/Bahamut_Senki'),
  ('Q3410052', 'Psycho Pinball is a 1994 pinball video game published and developed by Codemasters, released for Mega Drive in the United Kingdom and MS-DOS in the United States and Europe.', 'https://en.wikipedia.org/wiki/Psycho_Pinball'),
  ('Q3414929', 'R.B.I. Baseball 3 is the second sequel to the R.B.I. Baseball video game. It was published by Tengen for the Genesis and Nintendo Entertainment System in 1991.', 'https://en.wikipedia.org/wiki/R.B.I._Baseball_3'),
  ('Q3419958', 'Rastan Saga II, released in Europe as Nastar and in North America as Nastar Warrior, is a 1989 hack and slash platform video game developed and published by Taito for arcades. It is the sequel to Rastan Saga. It was ported to the PC Engine only in Japan as well as the Sega Genesis.

Hamster Corporation re-released the game as part of the Arcade Archives series for the Nintendo Switch and PlayStation 4 in June 2024.', 'https://en.wikipedia.org/wiki/Rastan_Saga_II'),
  ('Q3491156', 'Sorcerer''s Kingdom is a tactical RPG developed by Technical Wave and released for the Sega Genesis in 1992. It was localized for North America by Treco.', 'https://en.wikipedia.org/wiki/Sorcerer%27s_Kingdom'),
  ('Q3488724', 'Socket is a 1993 platform video game developed and published by Vic Tokai for the Sega Genesis. Players control the android duck Socket in his efforts to stop the Time Dominator from stealing treasures from the past and messing with the flow of time.', 'https://en.wikipedia.org/wiki/Socket_(video_game)'),
  ('Q3482637', 'Water Margin, also called Outlaws of the Marsh or All Men Are Brothers, is a Chinese novel from the Ming dynasty, attributed to Shi Nai''an. Regarded as one of the greatest Chinese novels, the novel is among the first works of Chinese fiction written entirely in vernacular Chinese. It is considered a masterpiece of Chinese literature, as well as a book of heroism and transgression.

Set during the Northern Song dynasty (twelfth century), the story follows a group of 108 outlaws that gathers at Mount Liang (also known as Liangshan Marsh) to rebel against the government. Later they are granted amnesty and enlisted by the government to resist the nomadic conquest of the Liao dynasty and other rebels. The original title of the novel was Water Margin for Loyalty and Justice. A wealth of bibliographical and other evidence names Shi Nai''an, Luo Guanzhong (fl. 1330–1400), or both of them, as the novel''s principal compiler, responsible for its original compilation. Through a complex textual evolution, a printed revision based on previous editions was published during the reign of Emperor Shizong (1522–1566) of the Ming dynasty, becoming the ancestral edition to a series of the most widely circulated versions. Dealing with social critique, the novel explores themes of morality, justice, authority and loyalty, and has been banned many times in its history.', 'https://en.wikipedia.org/wiki/Water_Margin'),
  ('Q3486219', 'Skeleton Krew is a 1995 video game developed by Core Design for the Sega Mega Drive, Amiga A1200 and Amiga CD32.', 'https://en.wikipedia.org/wiki/Skeleton_Krew'),
  ('Q3486326', 'Skitchin'' is a 1994 racing video game developed and published by Electronic Arts (EA) for the Sega Genesis. The game puts the player in control of an inline skater who must win races in a tournament while engaging in unarmed and armed combat with other skaters and partaking in skitching, the act of clutching onto a moving vehicle''s bumper to gain momentum.

Skitchin'' was developed by EA''s Canadian division, who repurposed the engine of the Road Rash series to capitalize on its success. The creation of the game''s visuals involved rotoscoping an experienced skater and recruiting the services of teen-aged graffiti artists. The prominence of skitching in the game prompted EA to include a disclaimer warning of the activity''s dangerous nature.', 'https://en.wikipedia.org/wiki/Skitchin%27'),
  ('Q3492578', 'Space Harrier II is a 1988 rail shooter video game developed and published by Sega. The sequel to 1985''s Space Harrier, it was one of the original launch titles released for the Mega Drive in Japan and one of the six Sega Genesis launch titles in the United States the following year. It was later released on the Wii''s Virtual Console in December 2006, and also on the Nintendo Classics service in April 2022. Like Altered Beast, another launch title for the Mega Drive, Space Harrier II features digitized voice recordings during gameplay, and is also an example of some of the Mega Drive''s early sound, with music composed by Tokuhiko Uwabo (credited as "Bo"). A graphically enhanced version included with the Sega Genesis Mini 2 was released in October 2022.', 'https://en.wikipedia.org/wiki/Space_Harrier_II'),
  ('Q3481159', 'Shadow Blasters is a platform game developed by Sigma Pro-Tech for the Sega Genesis in 1990. It was released in Japan and in North America in a localized form.', 'https://en.wikipedia.org/wiki/Shadow_Blasters'),
  ('Q3496955', 'Star Cruiser is a role-playing first-person shooter video game developed by Arsys Software and released in Japan for the PC-8801 and X1 home computers in 1988. The game was released for the PC-9801 and X68000 computers in 1989, and then ported by Masaya (NCS) to the Mega Drive in 1990.

The game is an early example of an action role-playing game with fully 3D polygon graphics, combined with first-person shooter gameplay and space flight simulation when exploring the open-ended outer space with six degrees of freedom. All backgrounds, objects, and opponents in the game are rendered in 3D polygons, years before the technique was widely adopted. The game emphasized storytelling, with plot twists and extensive character dialogues, taking place in a futuristic science fiction setting.', 'https://en.wikipedia.org/wiki/Star_Cruiser_(1988_video_game)'),
  ('Q3494169', 'Sports Talk Baseball, released in Japan as Pro Yakyū Super League ''91, is a Mega Drive/Genesis baseball video game which features an official MLBPA license as well as most rules and aspects followed by Major League Baseball.', 'https://en.wikipedia.org/wiki/Sports_Talk_Baseball'),
  ('Q3492607', 'Uzu Keobukseon (우주거북선) (Space Turtle Ship) is a vertical scrolling shooter video game developed by Samsung in 1993 for the Sega Mega Drive, released only in Korea (the entire menu and dialogue was written in Korean). Players controlled the title ship, a purple and gold space-age battle cruiser designed as a turtle ship, complete with sails and oars, in eight various stages.', 'https://en.wikipedia.org/wiki/Uzu_Keobukseon'),
  ('Q3515684', 'Target Earth, released in Japan as Assault Suit Leynos is a run and gun video game developed by NCS in 1990 for the Sega Genesis. It was re-released on the Wii’s Virtual Console, and on the Nintendo Switch''s Nintendo Classics. It is the first game in the Assault Suits series.', 'https://en.wikipedia.org/wiki/Target_Earth_(video_game)'),
  ('Q3515950', 'Task Force Harrier is a 1989 vertical scrolling shooter video game developed by NMK and published by UPL for arcades. It was released in Japan in October 1989 and in North America by Sammy in November 1989. It was ported to the Sega Genesis by Jorudan and Treco as Task Force Harrier EX on December 20, 1991 in Japan and North America in May 1992. Hamster Corporation released the game as part of their Arcade Archives series for the Nintendo Switch and PlayStation 4 in May 2021.', 'https://en.wikipedia.org/wiki/Task_Force_Harrier'),
  ('Q3516725', 'Team USA Basketball is a 1992 sports video game released on the Sega Genesis. The game is a spinoff following the success of the Bulls vs Lakers video game as well as the popularity explosion of the 1992 United States men''s Olympic basketball team, also known as the "Dream Team". It is the third game in the NBA Playoffs series of games.

A three-card set was bundled with each copy of the game. Put together, the cards showed the entire roster against a sky background with the words, "BARCELONA ''92" in red and white.', 'https://en.wikipedia.org/wiki/Team_USA_Basketball_(video_game)'),
  ('Q3504318', 'Super Volleyball, released as Super Volley Ball in Japan, is a 1989 volleyball video game developed and published by Video System for arcades. It was released in Japan in August 1989 and in North America by Data East in September 1989. It was ported to the TurboGrafx-16 in 1990 and Sega Genesis in 1991. A sequel, Power Spikes, was released in 1991; another sequel, Power Spikes II, was released in 1994.

Hamster Corporation acquired the rights to the game alongside Video System''s portfolio, releasing it as part of their Oretachi Gēsen Zoku series for the PlayStation 2 in 2005, as well as their Arcade Archives series for the Nintendo Switch and PlayStation 4 in August 2022.', 'https://en.wikipedia.org/wiki/Super_Volleyball'),
  ('Q3512249', 'TNN Outdoors Bass Tournament ''96 is a sequel to the fishing video game TNN Bass Tournament of Champions. It was released exclusively in North America in 1996.', 'https://en.wikipedia.org/wiki/TNN_Outdoors_Bass_Tournament_%2796'),
  ('Q3516984', 'Tecmo Super Hockey is a professional hockey video game that was developed by Malibu Interactive and published by Tecmo''s American division, and released in 1995 for the Sega Genesis. An SNES version was planned, but cancelled. It was not licensed by the NHL, but did have a license from the NHLPA.

The game received mixed reviews from critics, who called the game overly simplistic.', 'https://en.wikipedia.org/wiki/Tecmo_Super_Hockey'),
  ('Q3504211', 'Tommy Lasorda Baseball is a 1989 baseball video game developed and published by Sega as one of the six launch titles for the Sega Genesis in North America and for the Sega Mega-Tech arcade system. It is a follow-up to the arcade game Super League (1987). It prominently features former MLB player Tommy Lasorda, who was manager of the Los Angeles Dodgers at the time. In the game, players compete with either AI-controlled opponents or against other players across single exhibitions, open matches, or a 30-game season.

Tommy Lasorda Baseball was part of a marketing campaign to build a library of titles using recognizable names and likenesses of celebrities and athletes to emphasize the arcade experience available on Sega Genesis. The game garnered mixed to positive reception from critics since its release; praise was given to the addition of season play, use of multiple perspectives, sound, two-player component, and gameplay, but criticism was geared towards this aspect being luck-based and having difficult AI, while others felt mixed in regards to the graphical quality and recommended similar titles instead.', 'https://en.wikipedia.org/wiki/Tommy_Lasorda_Baseball'),
  ('Q3499848', 'Stormlord is a platform game developed and published by Hewson Consultants in 1989. It was released for the ZX Spectrum, Commodore 64, Amiga, Atari ST, Amstrad CPC, and MS-DOS. It was ported to the Sega Genesis by Punk Development for RazorSoft and published in 1990.

It was followed by a sequel, Deliverance: Stormlord II.', 'https://en.wikipedia.org/wiki/Stormlord'),
  ('Q3500405', 'Journey from Darkness: Strider Returns (known as Strider II in PAL region) is a 1990 action-platform game published by U.S. Gold (under license from Capcom) and originally released for various computer platforms. It is a British-developed sequel to Capcom''s arcade video game Strider, which U.S. Gold previously ported to home computers in Europe.

Capcom later developed their own sequel in 1999, titled Strider 2 for the arcades and PlayStation, which ignores U.S. Gold''s version of Strider Returns.', 'https://en.wikipedia.org/wiki/Strider_II_(1990_video_game)'),
  ('Q3504284', 'Super Skidmarks is a racing video game developed by Acid Software and released in 1995. The game is the sequel to Skidmarks and as such was also termed Skidmarks 2 and Super Skidmarks 2 by commentators. The game features "minimally realistic" action viewed from an isometric perspective as well as novelty vehicles such as wheeled cows and caravans. Various methods such as joypad adapters and link systems are employed to allow multiple players to compete, up to a maximum of 8. The game was critically acclaimed and a best-seller in the UK. Several upgrades to the Amiga original were released as well as conversions for the Amiga CD32 and Sega Mega Drive, the latter published by Codemasters.', 'https://en.wikipedia.org/wiki/Super_Skidmarks'),
  ('Q3517243', 'Tel-Tel Stadium is a Sega Mega Drive baseball video game released in 1990. Along with Tel-Tel Mahjong it is a part of the Tel-Tel series and the game allowed the players to play an online multiplayer through the Sega MegaModem and the Sega Net Work System, as well to play against computer opponents.', 'https://en.wikipedia.org/wiki/Tel-Tel_Stadium'),
  ('Q3517241', 'Tel-Tel Mahjong is a Sega Mega Drive Mahjong video game that was released exclusively in Japan in 1990. Part of the Tel-Tel series that included Tel-Tel Stadium, it was one of the few games that used the Mega Modem, allowing for two-player games via the Sega Net Work System. Up to three players could play the "host" player in addition to play against computer opponents.', 'https://en.wikipedia.org/wiki/Tel-Tel_Mahjong'),
  ('Q3522969', 'The Terminator is a 1992 video game developed by Probe Software and published by Virgin Games for the Sega Genesis, Master System, and Game Gear. It is based on the 1984 film of the same name. The Terminator was praised for its graphics and sound, but criticized for its gameplay.', 'https://en.wikipedia.org/wiki/The_Terminator_(Sega_video_game)'),
  ('Q3521350', 'The Hybrid Front is a turn-based strategy video game, released in Japan on July 22, 1994, for the Mega Drive. It was re-released for the Virtual Console on May 29, 2007.', 'https://en.wikipedia.org/wiki/The_Hybrid_Front'),
  ('Q3519926', 'The Berenstain Bears is a children''s literature franchise created by Stan and Jan Berenstain and continued by their son, Mike Berenstain. The books feature a family of anthropomorphic grizzly bears who generally learn a moral or safety-related lesson in the course of each story.

Since the 1962 debut of the first Berenstain Bears book, The Big Honey Hunt, the series has grown to over 400 titles, which have sold approximately 260 million copies in 23 languages. The Berenstain Bears franchise has also expanded well beyond the books, encompassing television series and a wide variety of other products and licenses. While enjoying decades of popularity and receiving numerous awards, the series has been criticized for its perceived saccharine tone and formulaic storytelling.', 'https://en.wikipedia.org/wiki/Berenstain_Bears'),
  ('Q3529555', 'Sylvester and Tweety in Cagey Capers is a 2D platform game featuring the Looney Tunes characters Sylvester and Tweety. It was released for the Genesis/Mega Drive console in 1994 and was the first video game to star Sylvester and Tweety.', 'https://en.wikipedia.org/wiki/Sylvester_and_Tweety_in_Cagey_Capers'),
  ('Q3530239', 'Todd''s Adventures in Slime World is a 1990 Metroidvania video game developed by Epyx and published by Atari Corporation for the Atari Lynx. The Sega Genesis and PC Engine Super CD-ROM² versions followed in 1992, both of which were released by Micro World.', 'https://en.wikipedia.org/wiki/Todd%27s_Adventures_in_Slime_World'),
  ('Q3526055', 'Thunder Pro Wrestling Retsuden is a Japan-exclusive Sega Mega Drive professional wrestling video game. This is the only game in the Fire Pro Wrestling series to be released for that system.

The game features an "Exciting" mode that allows players to take on each other, an elimination mode where ten chosen wrestlers compete to win, and a handicap mode where one wrestler must take on two opponents.

A North American release under the name Jesse "The Body" Ventura Wrestling Superstars was planned by DreamWorks, but was never released for unknown reasons.', 'https://en.wikipedia.org/wiki/Thunder_Pro_Wrestling_Retsuden'),
  ('Q3526052', 'Thunder Force II is a scrolling shooter developed by Technosoft. It was first released in Japan on October 15, 1988 for the X68000 computer. A year later, it was ported to the Sega Mega Drive/Genesis game console and released in Japan (under the name Thunder Force II MD), Europe, and the United States. Thunder Force II was one of the six launch titles for the U.S. Genesis release. The Genesis port was later included in Thunder Force Gold Pack Volume 1 for the Sega Saturn. It was also re-released via the Nintendo Classics service on December 16, 2021. It is the second chapter of the Thunder Force series.', 'https://en.wikipedia.org/wiki/Thunder_Force_II'),
  ('Q3532854', 'Tōgi Ō: King Colossus is a 1992 action-RPG video game developed and published by Sega for the Mega Drive. The game was never localized outside Japan, with an English fan translation patch releasing in 2006.', 'https://en.wikipedia.org/wiki/T%C5%8Dgi_%C5%8C:_King_Colossus'),
  ('Q3530319', 'ToeJam & Earl in Panic on Funkotron is a 1993 platform video game developed by Johnson Voorsanger Productions and published by Sega for the Sega Genesis. It is the sequel to cult video game ToeJam & Earl, released in 1991. The game concerns two alien protagonists, ToeJam and Earl, both of whom have escaped from Earth, where they had crash landed. After returning to their home planet of Funkotron, the duo discover a number of antagonistic Earthlings have stowed away on the spacecraft and are wreaking havoc across the planet. The player must hunt down these Earthlings and imprison them in jars before sending them back to Earth.', 'https://en.wikipedia.org/wiki/ToeJam_%26_Earl_in_Panic_on_Funkotron'),
  ('Q3537024', 'Trampoline Terror! is an overhead view action video game with strategy elements developed by NCS and published by DreamWorks in 1990 for the Genesis exclusively in North America. A Japanese release under the name Explode Star was planned, but was cancelled.', 'https://en.wikipedia.org/wiki/Trampoline_Terror!'),
  ('Q3539500', 'Triple Play 96 is a sports video game developed by Canadian studio Extended Play Productions and published by EA Sports for the Sega Genesis. An updated version titled Triple Play: Gold Edition was released exclusively for the Sega Genesis the following year and added updated 1996 rosters and a new "Professional Mode".', 'https://en.wikipedia.org/wiki/Triple_Play_96'),
  ('Q3532675', 'Total Football is a football (soccer) videogame developed for the Sega Mega Drive and Amiga programmed and published by Domark in 1995.', 'https://en.wikipedia.org/wiki/Total_Football_(video_game)'),
  ('Q3538255', 'Traysia (known as Minato no Traysia in Japan) is a traditional role-playing video game that was released in 1992 for the Sega Genesis. The player controls a young man named Roy who is dropped off in the Kingdom of Salon by his uncle, a traveling merchant, and is joined by three other characters to begin a journey that leads them against a shadowy group of wizards from the north.', 'https://en.wikipedia.org/wiki/Traysia'),
  ('Q3542394', 'Mega Turrican is a run and gun video game developed by Factor 5 in 1993 and published by Data East in 1994. Part of the Turrican series, it was released for the Mega Drive/Genesis, and later followed by an Amiga port converted by Kaiko and Neon Studios under the title of Turrican 3: Payment Day. Despite not being the original, the Amiga version was the one that was first commercially released in 1993, published by Rainbow Arts in Germany and Renegade in the rest of Europe. The Mega Drive version did not have a publisher and stayed unreleased from spring 1993 until 1994, when Data East took over its worldwide distribution. Data East itself released the game in North America, and contracted Sony Imagesoft for the game''s distribution in Europe.', 'https://en.wikipedia.org/wiki/Mega_Turrican'),
  ('Q3542597', 'Two Crude, released in Japan as Crude Buster, is a 1990 beat ''em up video game developed and published by Data East for arcades. It was a follow-up to Bad Dudes Vs. DragonNinja (1988). The game was later ported to the Mega Drive/Genesis in 1992. Outside Japan, the port was released under the name Two Crude Dudes.

In the game, players control Biff and Spike, two mercenaries hired by the American government to stop the terrorist organization "Big Valley". Their objective is to retake control of a ruined New York City from Big Valley after a nuclear explosion the group caused.', 'https://en.wikipedia.org/wiki/Two_Crude'),
  ('Q3548017', 'Ultimate Soccer is a 1993 soccer video game by Rage Software released for the Mega Drive, Master System, and Game Gear by request of Sega which even allowed their mascot, Sonic, to be featured in the game menus. It was followed by Striker also for the Mega Drive, Striker ''96, released for MS-DOS, Sega Saturn, and PlayStation, and Striker Pro 2000, released for PlayStation and the Dreamcast. While never published to the Super Nintendo Entertainment System, Rage developed other games for the Nintendo console, including Elite Soccer, Manchester United Championship Soccer (also had version named after Eric Cantona and Lothar Matthäus) and World Soccer 94 – Road to Glory.', 'https://en.wikipedia.org/wiki/Ultimate_Soccer'),
  ('Q3542541', 'Twin Hawk is a 1989 vertically scrolling shooter video game developed by Toaplan and published by Taito for arcades. Taking place at the end of an alternative World War II setting, where general Giovanni and his army plots to take over the fictional country Gorongo, players assume the role of a wing commander from the Daisenpū squadron taking control of a Flying Fortress fighter aircraft (known as the A6M Zero) in an effort to overthrow the enemy.

Created by Yuichirō Nozawa, Twin Hawk was developed as a commission for Taito by most of the same team that previously worked on several projects at Toaplan and made use of the former''s Taito X System board. The game was later ported to consoles including the Sega Mega Drive, PC Engine and PC Engine CD-ROM², with each one featuring several changes and additions compared to the original version.', 'https://en.wikipedia.org/wiki/Twin_Hawk'),
  ('Q3542550', 'Twinkle Tale is a run and gun video game developed by ZAP Corporation and published by Wonder Amusement Studio exclusively for the Sega Mega Drive in Japan on 24 July 1992. It was both the last project created by ZAP, as well as the only title to be released by Wonder Amusement Studio, which was a subsidiary of Japanese record label company Toyo Recording.

Taking place in the fantasy world of Alpherion, the players take control of young apprentice magician Saria on a journey to rescue the great wizards of her land from their captivity and recover the powerful gemstones from the dark sorcerer Gadou and his followers before the demonic king of darkness, Kaiser Demon, is summoned and brings chaos to both the land of Alpherion and the world. Its gameplay mainly consists of run and gun action mixed with minimal exploration elements, using a main three-button configuration.', 'https://en.wikipedia.org/wiki/Twinkle_Tale'),
  ('Q3549239', 'Undeadline is a 1989 vertically scrolling shooter video game developed and originally published by T&E Soft for the MSX2 home computers. It was later ported to the X68000 and Mega Drive, published by Palsoft, followed by digital re-releases for Microsoft Windows. Both the MSX2 and X68000 versions also received physical re-releases by Japanese retailer BEEP. It follows a group of characters in rescue of queen Althea from Zidane, a kingdom surrounded by barriers connected with the demon world, whose monsters have overflowed it. Controlling either a fighter, wizard, or ninja, the player can choose from six stages and play them in any order, fighting against waves of enemies and bosses, while defending or avoiding collision with their projectiles and other obstacles.', 'https://en.wikipedia.org/wiki/Undeadline'),
  ('Q3556308', 'Verytex is a vertically scrolling shooter video game developed by Opera House, with the assistance of ISCO, and published by Asmik Ace Entertainment exclusively for the Mega Drive in Japan on 5 April 1991. Taking place on the colonized fictional planet of Syracuse in a futuristic sci-fi setting, where its military force initiated a violent coup d''état against the inhabitants for unknown reasons, players take control of the titular space fighter craft in an attempt to overthrow the enemies, protect civilization and discover the true cause for the rebellion.

Headed by Air Diver producer Toshiyuki Futamura, Verytex was created by most of the same team that previously worked on several projects such as the Mega Drive conversion of Master of Monsters. Despite being exclusive to Japan, the game has received mixed reviews from critics and from reviewers that reviewed it as an import title, who felt divided in regards to several areas of the title such as the presentation, graphics, sound design, controls and gameplay, although the music was noted by some people as a positive point.', 'https://en.wikipedia.org/wiki/Verytex'),
  ('Q3553824', 'Valis III is a 1990 action-platform video game originally developed by Laser Soft, published by Telenet Japan and NEC for the TurboGrafx-CD. A Sega Genesis version was released in 1991. It is the third entry in the Valis series. It stars Yuko Asou, a Japanese teenage schoolgirl chosen as the Valis warrior and wielder of the mystical Valis sword after the events of Valis II. King Glames, wielder of the sword Leethus, leads denizens of the dark world to conquer both Vecanti and Earth, seeking refuge for his people amid the destruction of their planet. Together with the demon warrior-maiden Cham and her sister Valna, Yuko must prevent Glames from destroying both worlds. Through the journey, the player explores and searches for items and power-ups while fighting enemies and defeating bosses.', 'https://en.wikipedia.org/wiki/Valis_III'),
  ('Q3553006', 'VR Troopers is a 1995 fighting game based on the American syndicated television series VR Troopers that itself used elements from several different Japanese tokusatsu shows from the Metal Hero Series. It was developed by Syrox Developments and published by Sega. The game was released on the Sega Genesis and the Sega Game Gear.', 'https://en.wikipedia.org/wiki/VR_Troopers_(video_game)'),
  ('Q3551915', 'Unnecessary Roughness ''95 is an American football sports video game released for the Genesis and MS-DOS in 1994. Other entries in the series are Unnecessary Roughness (1993) and Unnecessary Roughness ''96 (1996).', 'https://en.wikipedia.org/wiki/Unnecessary_Roughness_%2795'),
  ('Q3560850', 'Virtual Pinball is a follow-up to EA''s 1983 Pinball Construction Set from the same author, Bill Budge, released 10 years later for the Sega Genesis. One to four players can choose from either 29 premade tables or design one using in-game editor tools. Designing options include ten different backgrounds and six themes, and a player can choose where objects are placed, the style of music, and the ball speed. Virtual Pinball lacks the unlimited floppy disc storage used by the original, and the ability to create self-booting disks that can be played without the construction set software.', 'https://en.wikipedia.org/wiki/Virtual_Pinball'),
  ('Q3566430', 'Warrior of Rome, also known as Caesar no Yabou, is a real-time strategy video game developed and published by Micronet for the Mega Drive/Genesis. The game is a fictional story about the adventures of Julius Caesar and the Roman army during his reign as general in the year 48 BCE. The game had a sequel, Warrior of Rome II.', 'https://en.wikipedia.org/wiki/Warrior_of_Rome'),
  ('Q3566433', 'Warrior of Rome II, also known as Caesar no Yabou II is a real-time strategy video game developed and published by Micronet in 1992 for the Sega Mega Drive/Genesis as a sequel to Warrior of Rome.', 'https://en.wikipedia.org/wiki/Warrior_of_Rome_II'),
  ('Q3567743', 'Whip Rush is a space-themed, horizontally and vertically scrolling shooter released in 1990 for the Mega Drive and later that year in North America for the Sega Genesis.', 'https://en.wikipedia.org/wiki/Whip_Rush'),
  ('Q3561681', 'Vixen 357 is a war video game developed by NCS Corporation and published by Masaya Games, and released in 1992 for the Mega Drive. An English-translated production run was scheduled for a 2019 release by Super Fighter Team, but was ultimately cancelled. In 2026 Shinyuden released an English and Spanish translation of the game on Steam and a physical cartridge production run. Ratalaika Games published the game on Xbox Series, Playstation 5 and Nintendo Switch.

Taking place in the late 25th century, many of the characters provided to the player provide character development and losing them could mean losing the game, resulting in a game over. The game uses a battery save to help players regain lost characters in case one of them die in a tactical mistake.', 'https://en.wikipedia.org/wiki/Vixen_357'),
  ('Q3569531', 'Wiz ''n'' Liz: The Frantic Wabbit Wescue is a platform game developed by Raising Hell Software for the Sega Mega Drive and published by Psygnosis in 1993. An Amiga port was developed by Lunatic Software. It is a humorous, cutesy platform game. With the exception of some end-of-level bosses, the game contains no enemies.', 'https://en.wikipedia.org/wiki/Wiz_%27n%27_Liz'),
  ('Q3570003', 'World Series Baseball ''96 is a 1996 baseball video game developed by BlueSky Software and published by Sega for the Sega Genesis.', 'https://en.wikipedia.org/wiki/World_Series_Baseball_%2796'),
  ('Q3569784', 'Wonder Boy III: Monster Lair is a 1988 platform game developed by Westone and published by Sega for arcades. It is the third game in the Wonder Boy series and the last one released for arcades. A console adaptation was made by Hudson Soft and released in 1989 in Japan for the PC Engine CD-ROM² System; the subsequent North American release on the TurboGrafx-CD dropped the Wonder Boy III title. It was also converted and released by Sega for the Mega Drive in Japan in 1990 and Europe in 1991. Both the TurboGrafx-CD and Mega Drive versions were later re-released for the Wii Virtual Console.', 'https://en.wikipedia.org/wiki/Wonder_Boy_III:_Monster_Lair'),
  ('Q3569949', 'World Championship Soccer 2 is an association football video game released for the Sega Genesis/Mega Drive systems in 1994, as a sequel to World Championship Soccer.', 'https://en.wikipedia.org/wiki/World_Championship_Soccer_2'),
  ('Q3570350', 'XDR (short for "X-Dazedly-Ray") is a horizontally scrolling shooter released in Japan in 1990 for the Mega Drive. It contains six levels.', 'https://en.wikipedia.org/wiki/XDR_(video_game)'),
  ('Q3570006', 'World Series Baseball is a 1993 baseball video game released by Sega for the Game Gear and Sega Genesis. It is the first game in the World Series Baseball series, and was followed by World Series Baseball ''95 in 1994.

The game was a major advancement in Sega baseball games, in that it included licensed MLB players and teams (the first baseball video game to have both such licenses [previous baseball video games only had one license]; they are based on the rosters for the 1993 and 1994 MLB seasons), and relatively accurate gameplay.

The series concluded with World Series Baseball 2K3 on the PlayStation 2 and the Xbox. After that, Sega contracted with 2K Games to take over their sports game contracts, and the line continued as the Major League Baseball 2K franchise.', 'https://en.wikipedia.org/wiki/World_Series_Baseball_(1993_video_game)'),
  ('Q3570005', 'World Series Baseball ''95 is a 1994 baseball video game released by Sega for the Game Gear and Sega Genesis. A version for the 32X was released in 1996 under the name World Series Baseball Starring Deion Sanders.', 'https://en.wikipedia.org/wiki/World_Series_Baseball_%2795'),
  ('Q3570004', 'World Series Baseball ''98 is a 1997 baseball video game published by Sega for the Sega Saturn and Sega Genesis. A sequel to World Series Baseball II, it was first released in Japan as Pro Yakyū Greatest Nine ''97, featuring teams and players from Nippon Professional Baseball. The North American version features Major League Baseball teams and players, while the Saturn version introduced three-dimensional polygonal graphics and a batting and pitching system based on selecting areas of the strike zone.

The Saturn version received generally positive reviews, particularly for its gameplay mechanics and transition to three-dimensional graphics, although critics identified shortcomings in its presentation and certain gameplay features. The Japanese version sold more than 182,000 copies, while the American release charted on the US charts.', 'https://en.wikipedia.org/wiki/World_Series_Baseball_%2798'),
  ('Q3570110', 'Wrestle War is a video game developed and published by Sega which was released in arcades in 1989, and later ported to the Sega Mega Drive console in 1991 in Japan, Australia, and Europe. Despite being released the same year as World Championship Wrestling''s WrestleWar pay-per-view event, it is not associated with any wrestling promotion. The original Japanese game cover featured a Hulk Hogan look-alike, but this was changed for the international release.

The Mega Drive version of Wrestle War was included as part of the Sega Smash Pack compilation for the Dreamcast in 2001. In 2022, the original arcade version was included as part of the Sega Astro City Mini V, a vertically oriented variant of the Sega Astro City mini console.', 'https://en.wikipedia.org/wiki/Wrestle_War_(video_game)'),
  ('Q3570305', 'X-Perts is a side-scrolling beat-''em-up video game produced by Sega and released only in North America for the Sega Genesis in 1996. It is a spin-off of Eternal Champions starring the assassin Shadow Yamoto, who is depicted in her design from Eternal Champions: Challenge from the Dark Side. One of the most high profile of the last wave of Genesis games, it was heavily panned by critics as having dull gameplay and poor control.', 'https://en.wikipedia.org/wiki/X-Perts'),
  ('Q3910072', 'Predator 2 is a 1992 second video game adaptation of the film of the same title, developed by Perfect 10 Productions and Teeny Weeny Games and published by Acclaim Entertainment. It was released for the Sega Genesis, Game Gear, and Master System.', 'https://en.wikipedia.org/wiki/Predator_2_(1992_video_game)'),
  ('Q3837535', 'Lotus III: The Ultimate Challenge is the third and final game in the Lotus racing series.', 'https://en.wikipedia.org/wiki/Lotus_III:_The_Ultimate_Challenge'),
  ('Q3574298', 'Yu Yu Hakusho Makyō Tōitsusen is a 1994 fighting game developed by Treasure and published by Sega for the Mega Drive. It is based on the manga series Yu Yu Hakusho by Yoshihiro Togashi. The plot follows the protagonist Yusuke Urameshi, who is tasked by the ruler of the afterlife with solving detective-style cases involving both humans and demons threatening the living world. The story begins to focus heavily on martial arts battles as it progresses.

The game features 11 playable characters from the manga and traditional 2D fighting gameplay. Opponents compete in rounds, attempting to deplete each other''s health by utilizing short and long-range attacks and special combos. It also integrates other mechanics, such as allowing up to four players to compete simultaneously and letting fighters alternate between horizontal planes in the foreground and background. A number of multiplayer options are available that include battle royales, tag team matches, and tournament modes.', 'https://en.wikipedia.org/wiki/Yu_Yu_Hakusho_Maky%C5%8D_T%C5%8Ditsusen'),
  ('Q5299678', 'Double Clutch is a racing video game developed by BGS Development for the Mega Drive. It was published by Sega in the PAL region in 1993.', 'https://en.wikipedia.org/wiki/Double_Clutch_(video_game)'),
  ('Q4037828', 'ESWAT: City Under Siege, released in Japan as Cyber Police ESWAT, is a 1990 action-platform video game developed and published by Sega for the Sega Genesis and Master System. It is based on the arcade game Cyber Police ESWAT, released a year earlier in 1989. The console game maintains the main characters, plot and some of its enemies from the arcade game, but features some different levels, weapons, and bonuses.

Backbone Entertainment pitched a new ESWAT game to Sega, but the project was never greenlit. Artwork and screenshots of the game were later leaked.', 'https://en.wikipedia.org/wiki/ESWAT:_City_Under_Siege'),
  ('Q5137586', 'Coach K College Basketball is the first college basketball video game published by EA Sports spun off from their NBA Live engine. Coach K College Basketball was released in 1995 for Sega Genesis.', 'https://en.wikipedia.org/wiki/Coach_K_College_Basketball'),
  ('Q6314905', 'Jurassic Park: Rampage Edition is a 1994 action platformer video game developed by BlueSky Software and published by Sega for the Sega Genesis. It is the sequel to Sega''s previous Jurassic Park video game, based on the 1993 film of the same name and also released for the Genesis. Rampage Edition is a revamped version of its predecessor, featuring similar gameplay with several changes, and a new story that continues from where the previous game ended.', 'https://en.wikipedia.org/wiki/Jurassic_Park:_Rampage_Edition'),
  ('Q6517780', 'Legend of Wukong, originally known as Wucom Legend, is a Taiwanese role-playing adventure game for the Sega Mega Drive/Genesis developed by Gamtec. It was originally released in 1996 in Chinese only. The game''s story is loosely based on the novel Journey to the West.

An English translation of the game was done by the North American company Super Fighter Team, and began shipping to pre-order customers on December 3, 2008, at the price of US$40 per copy. Legend of Wukong was the second game for the Sega Genesis to be commercially released in the United States since 1998.

The game is 16-megabits (2 megabytes) in size. Players could record their progress to any of the three available save slots. The game shipped in a plastic clamshell case along with a glossy, full-color 16 page instruction manual. The game''s unique cartridge hardware was designed by Kim Biu Wong, head of Tototek, and Super Fighter Team president Brandon Cobb. All pieces were manufactured in China.', 'https://en.wikipedia.org/wiki/Legend_of_Wukong'),
  ('Q5985049', 'Columns III: Revenge of Columns is a puzzle arcade game published by Sega in Japan in 1993 and by Vic Tokai in North America in 1994 as a sequel to Columns II: The Voyage Through Time.', 'https://en.wikipedia.org/wiki/Columns_III'),
  ('Q6953737', 'NFL ''98 is a sports video game released for the Sega Genesis in 1997. Future Sega football titles would fall under the NFL 2K branding.

Like Sega''s previous two NFL releases (NFL ''95 and NFL ''97), NFL ''98 was released exclusively for the North American market. It was not only the last American football video game for the Sega Genesis, but it was one of the last sports games released for a 16-bit console. The game runs under a modified engine of Prime Time NFL with updated 96-97 rosters.

In July 1997, Joe Montana filed a $5 million lawsuit against Sega, claiming that Sega breached his license agreement in regard to the game.', 'https://en.wikipedia.org/wiki/NFL_%2798'),
  ('Q9293417', 'Beauty and the Beast is a Disney media franchise comprising a film series and additional merchandise. The success of the original 1991 American animated feature, Beauty and the Beast, directed by Gary Trousdale and Kirk Wise, led to three direct-to-video follow-up films, a live-action spin-off television series, a Disney World stage show, a Disney World restaurant, a trackless dark ride, several video games, merchandise, and the 10th longest-running musical in Broadway history, which was nominated for nine Tony Awards, winning for Best Costume Design. In March 2017, Disney released a live-action remake of the film.', 'https://en.wikipedia.org/wiki/Beauty_and_the_Beast_(franchise)'),
  ('Q8065990', 'Zan: Yasha Enbukyoku is a 1990 strategy video game by Wolf Team. Set in Feudal Japan, it follows yaksha warriors fighting against demons. Units must be deployed for both protection and attack.', 'https://en.wikipedia.org/wiki/Zan:_Yasha_Enbukyoku'),
  ('Q7886525', 'Disney''s Ariel the Little Mermaid, usually shorted to simply Ariel the Little Mermaid, is a 1992 action-adventure video game developed by BlueSky Software and published by Sega for the Sega Genesis, Game Gear, and Master System. It is based on the 1989 Disney film The Little Mermaid.

Critically, Ariel the Little Mermaid was poorly received for its low difficulty and completion time, and was negatively compared to Ecco the Dolphin. A Master System version was released exclusively in Brazil by Tec Toy.', 'https://en.wikipedia.org/wiki/Ariel_the_Little_Mermaid'),
  ('Q7888614', 'Shadow of the Beast II is a platform game developed by Reflections and published by Psygnosis in 1990. It is the sequel to the earlier Shadow of the Beast.', 'https://en.wikipedia.org/wiki/Shadow_of_the_Beast_II'),
  ('Q7643829', 'Superman (known in Europe as Superman: The Man of Steel) is a video game released by Sunsoft for the Mega Drive/Genesis in 1992. It is based on the DC Comics character of the same name. It is a traditional single-player side-scrolling arcade game where the player controls Superman through various levels in an effort to defeat the evil supervillain named Brainiac. Other super villains, as bosses, include The Prankster, Metallo and Mister Mxyzptlk.

This game was planned to be released on the Super Nintendo Entertainment System, but was cancelled before it was completed. Versions of the game for the Master System and Game Gear were developed by Graftgold and published by Virgin Games in Europe as Superman: The Man of Steel, which was also the title received by the European Mega Drive version published by Virgin.', 'https://en.wikipedia.org/wiki/Superman_(1992_video_game)'),
  ('Q7692446', 'Technoclash is an action game with RPG elements published by Electronic Arts in 1993 for the Genesis.', 'https://en.wikipedia.org/wiki/Technoclash'),
  ('Q16258794', 'The Lost World: Jurassic Park is an action-adventure video game developed by Appaloosa Interactive and published by Sega for the Sega Genesis. It was released on September 16, 1997 in North America. By this time the Genesis was near the end of its commercial lifespan, and months went by between new software releases for the console.

The Lost World: Jurassic Park is based on the film of the same name, which in turn is based on the novel by Michael Crichton.', 'https://en.wikipedia.org/wiki/The_Lost_World:_Jurassic_Park_(Genesis_video_game)'),
  ('Q20707146', 'The Flintstones is a platform game for the Sega Genesis, based on the Hanna-Barbera animated television series The Flintstones. The game was published in 1993 by Taito in North America and Japan while Sega published the game in Europe.', 'https://en.wikipedia.org/wiki/The_Flintstones_(1993_video_game)'),
  ('Q21028849', 'Bonkers is a 1994 action video game developed by Sega Interactive Development Division and published by Sega for the Sega Genesis. It is based on the animated television series Bonkers, and was criticized for its gameplay.', 'https://en.wikipedia.org/wiki/Bonkers_(Genesis_video_game)'),
  ('Q16259348', 'Super Thunder Blade is a 1988 rail shooter game developed and published by Sega for the Sega Genesis. It sees players controlling a helicopter as they gun down military vehicles in various different environments. The sequel to the 1987 arcade game Thunder Blade, the gameplay of Super Thunder Blade follows the structure set by its arcade predecessor, with every stage featuring traditional rail shooting segment ending off with a vertically scrolling shoot ''em up boss battle.

The game was later released for the Virtual Console on September 17, 2007, and on the Nintendo Classics service on April 11, 2025. It was also included in the Sega Genesis Collection for PlayStation 2 and PlayStation Portable in 2006 and in Sonic''s Ultimate Genesis Collection for Xbox 360 and PlayStation 3 in 2009.', 'https://en.wikipedia.org/wiki/Super_Thunder_Blade'),
  ('Q22019762', 'Mamono Hunter Yōko: Dai 7 no Keishō is a platform game developed by Klon and published by NCS Masaya for the Sega Mega Drive in 1991 exclusively in Japan. It is an adaptation of the manga and anime series Devil Hunter Yohko.', 'https://en.wikipedia.org/wiki/Mamono_Hunter_Y%C5%8Dko:_Dai_7_no_Keish%C5%8D'),
  ('Q56275990', 'Prime Time NFL is a video game developed by Spectacular Games and published by Sega for the Sega Genesis. A Sega Saturn version was also planned but cancelled.', 'https://en.wikipedia.org/wiki/Prime_Time_NFL'),
  ('Q61829252', 'Ultracore (originally known as Hardcore) is a run and gun video game developed by DICE. Originally due to be released for Amiga, Genesis, and Sega CD platforms, the game was canceled by its publisher, Psygnosis, in 1994 after it had been almost finished.

The game was salvaged by publisher Strictly Limited Games and released together with the Mega Sg aftermarket console in March 2019. A version compatible with original Sega Genesis systems was released in Japan in October 2019. Ports for Nintendo Switch, PlayStation 4, and PlayStation Vita were released in 2020; ports for Xbox One and Xbox Series X/S were released in December 2023.', 'https://en.wikipedia.org/wiki/Ultracore'),
  ('Q55999414', 'College Football USA 96 is a sports video game released in 1995 by EA Sports. It is the follow-up to Bill Walsh College Football ''95 and part of EA''s NCAA Football series of games. College Football USA 96 is the first game in the series that included all of the Division l-A teams (there were 108 teams at the time) and was also the first to include actual bowl games (the Orange Bowl, Sugar Bowl, Fiesta Bowl, and Rose Bowl). With Bill Walsh''s retirement from coaching after the 1994 season, the game no longer carried an endorsement.

The game received praise for the large number of available teams and for being an accurate simulation of the sport.', 'https://en.wikipedia.org/wiki/College_Football_USA_96'),
  ('Q77965042', 'Crazy Bus (styled on the title screen as CRAZYBUS) is a 2004 unlicensed vehicle simulation game where the player drives a bus. Originally created as a tech demo, it was subsequently put on a ROM cartridge and published by an unauthorized 3rd party for the Sega Genesis. The game was developed by Venezuelan Tom Maneiro under the alias "Tom Scripts".', 'https://en.wikipedia.org/wiki/Crazy_Bus'),
  ('Q35627', 'Sonic the Hedgehog 2 is a 1992 platform game developed by Sega Technical Institute (STI) for the Sega Genesis. Players control Sonic as he attempts to stop Doctor Robotnik from stealing the Chaos Emeralds to power his space station, the Death Egg. Like the first Sonic the Hedgehog (1991), players traverse side-scrolling levels at high speeds while collecting rings, defeating enemies, and fighting bosses. Sonic 2 introduces Sonic''s sidekick Miles "Tails" Prower and features faster gameplay, larger levels, a multiplayer mode, and special stages featuring pre-rendered 3D graphics.

After Sonic the Hedgehog greatly increased the popularity of the Genesis in North America, Sega directed STI''s founder, Mark Cerny, to start Sonic 2 in November 1991. Members of Sonic Team—including the programmer Yuji Naka and the designer Hirokazu Yasuhara—moved from Japan to California to join the project. Sonic 2 was intended to be faster and more ambitious than the first game. The development suffered setbacks, including cultural differences between the Japanese and American staff, and numerous levels were cut due to time constraints and quality concerns. As with the first game, Masato Nakamura, a member of the J-pop band Dreams Come True, composed the soundtrack.', 'https://en.wikipedia.org/wiki/Sonic_the_Hedgehog_2'),
  ('Q37123', 'Sonic the Hedgehog is a 1991 platform game developed by Sonic Team and published by Sega for the Sega Genesis. It was released in North America and PAL regions in June and in Japan the following month. The player controls Sonic, a hedgehog who can run at supersonic speeds. The story follows Sonic as he aims to foil the mad scientist Doctor Robotnik''s plans to seek the powerful Chaos Emeralds. The gameplay involves collecting rings as a form of health, and a simple control scheme, with jumping and attacking controlled by a single button.

Development began in 1990 when Sega ordered its developers to create a game featuring a mascot for the company. The developers chose a blue hedgehog designed by Naoto Ohshima of Sega R&D9 after he won an internal character design contest, and named themselves Sonic Team to match their character. It uses a novel technique that allows Sonic''s sprite to roll along curved scenery which was based on a concept by Oshima from 1989. Sonic the Hedgehog, designed for fast gameplay, was influenced by games by the Mario creator, Shigeru Miyamoto. The music was composed by Masato Nakamura, bassist of the J-pop band Dreams Come True.', 'https://en.wikipedia.org/wiki/Sonic_the_Hedgehog_(1991_video_game)'),
  ('Q40177', 'Sonic & Knuckles is a 1994 platform game developed by Sega Technical Institute and published by Sega for the Sega Genesis. Players control Sonic the Hedgehog or Knuckles the Echidna in their quests to save Angel Island; Sonic tries to stop Doctor Robotnik from re-launching his orbital weapon, the Death Egg, while Knuckles scuffles with Robotnik''s minion, EggRobo. Like previous Sonic games, players traverse side-scrolling levels at high speeds while collecting rings and defeating enemies.

Sega Technical Institute developed Sonic & Knuckles simultaneously alongside its predecessor, Sonic the Hedgehog 3 (1994); they were planned as a single game until time constraints and cartridge costs forced the developers to split it. The Sonic & Knuckles cartridge features an adapter that allows players to connect the Sonic the Hedgehog 3 cartridge, creating a combined game, Sonic 3 & Knuckles. Sonic the Hedgehog 2 (1992) can also be attached, allowing players to control Knuckles in Sonic 2 stages. Attaching the original Sonic the Hedgehog or any other Genesis game released prior to this will unlock the "Blue Sphere" minigame.', 'https://en.wikipedia.org/wiki/Sonic_%26_Knuckles'),
  ('Q55607', 'Bonanza Bros. (sometimes written Bonanza Brothers) is a side-scrolling stealth action game developed and released by Sega in 1990. It is one of the earliest arcade games powered by the Sega System 24 arcade system board. It was ported to various home systems, including the Mega Drive/Genesis, Master System, PC-Engine/TurboGrafx-CD, and several home computers.

Bonanza Bros. received praise for its graphics, soundtrack, and character dialogue. It has been remastered and rereleased several times.', 'https://en.wikipedia.org/wiki/Bonanza_Bros.'),
  ('Q107676088', 'Paprium is a side-scrolling beat ''em up video game for the Mega Drive developed by studio WaterMelon and released in 2020. It was announced as part of a crowd-funding pitch in 2012. Development took eight years, with little to no communication with game''s backers or the press, and the game was widely considered to be vaporware.', 'https://en.wikipedia.org/wiki/Paprium'),
  ('Q102426517', 'Tänzer is a 2019 hack and slash action-platform video game developed by Mikael Tillander and originally published by Mega Cat Studios for the Sega Genesis. In the game, players assume the role of a ballerina whose body was transformed to fight against enemies in a post-apocalyptic setting. The title was crowdfunded through Kickstarter, being first released in 2019 for the Mega Drive and has since been re-released as part of the Mega Cat Studios – Collection 1 compilation for Evercade in 2020.', 'https://en.wikipedia.org/wiki/T%C3%A4nzer_(video_game)'),
  ('Q113451506', 'Street Fighter II: Champion Edition, released as Street Fighter II Dash (stylized as Street Fighter II′ with a prime symbol) in Japan, is a 1992 fighting game developed and published by Capcom for arcades. It is the first of several updated versions of Street Fighter II: The World Warrior (1991), and part of the Street Fighter series. The main changes are the addition of the four grand masters (the final four computer-controlled opponents in the single-player mode) as playable characters and mirror matches. The fighting techniques of the eight main characters from the original game were further balanced for competitive play.', 'https://en.wikipedia.org/wiki/Street_Fighter_II:_Champion_Edition'),
  ('Q2416324', 'The Menacer is a light gun peripheral released by Sega in 1992 for its Sega Genesis and Sega CD video game consoles. It was created in response to Nintendo''s Super Scope and as Sega''s successor to the Master System Light Phaser. The gun is built from three detachable parts (pistol, shoulder stock, sights), and communicates with the television via an infrared sensor. The Menacer was announced at the May 1992 Consumer Electronics Show in Chicago and was released later that year. The gun was bundled with a pack-in six-game cartridge of mostly shooting gallery games. Sega also released a Menacer bundle with T2: The Arcade Game.', 'https://en.wikipedia.org/wiki/Menacer'),
  ('Q3482566', 'Shove It! The Warehouse Game is a 1990 sokoban puzzle video game developed by NCS in Japan. A port of the game was later released in North America by DreamWorks. The game was showcased by DreamWorks at the Sega booth of the Winter 1990 Consumer Electronics Show. Upon release in North America, the game received mixed reviews, with some critics finding the gameplay challenging and addictive, and others faulting the game''s graphics, sound, and lack of features.', 'https://en.wikipedia.org/wiki/Shove_It!_The_Warehouse_Game'),
  ('Q4785073', 'Arcade Classics is a Genesis/Mega Drive compilation of three Atari, Inc. arcade video games: Pong (1972), Missile Command (1980), and Centipede (1981), plus a revised version of each one. It was published in 1996 by Sega. A version was also released for the Game Gear, with Ultrapong replacing Pong.', 'https://en.wikipedia.org/wiki/Arcade_Classics'),
  ('Q2742505', 'Chuck Rock II: Son of Chuck is a slapstick side-scrolling platform game developed by Core Design in 1993 for the Amiga, CD32, Game Gear, Sega CD, Master System, and Mega Drive/Genesis.', 'https://en.wikipedia.org/wiki/Chuck_Rock_II:_Son_of_Chuck'),
  ('Q3547313', 'USAAF Mustang is a horizontally scrolling shooter video game developed by NMK and published by UPL for arcades. It was ported to the Mega Drive by Taito, while being renamed Fire Mustang. Hamster Corporation released the game outside Japan for the first time as part of the Arcade Archives series for the Nintendo Switch and PlayStation 4 in September 2021.', 'https://en.wikipedia.org/wiki/USAAF_Mustang'),
  ('Q3949411', 'HardBall IV is a video game developed by MindSpan and published by Accolade for the Sega Genesis as HardBall ''94 and later for DOS.', 'https://en.wikipedia.org/wiki/HardBall_IV'),
  ('Q63049667', 'Jack Nicklaus Golf & Course Design: Signature Edition is a 1992 golf video game developed by Sculptured Software and published by Accolade for MS-DOS. It is part of a series of games named after golfer Jack Nicklaus, and follows Jack Nicklaus'' Unlimited Golf & Course Design (1990). Like its predecessor, the game includes a golf course designer that allows the player to create customized courses. Two add-on disks provide additional courses. In 1995, both disks were re-released along with Signature Edition as a compilation titled Jack Nicklaus: The Tour Collection.

Jack Nicklaus'' Power Challenge Golf, a scaled-down version of Signature Edition that lacks a course designer, was released for the Sega Genesis in July 1993. Both versions were praised for their graphics. The game was followed by Jack Nicklaus 4 (1997).', 'https://en.wikipedia.org/wiki/Jack_Nicklaus_Golf_%26_Course_Design:_Signature_Edition'),
  ('Q6311685', 'Cue Brick is a puzzle video game developed and published by Konami for arcades. It was released only in Japan in July 1989. A port to the X68000 titled Cueb Runner was released in 1990. Micronet developed ports of the game for the Sega Genesis and Game Gear under the title Junction; these versions were released outside Japan in 1990. Hamster Corporation released the arcade version outside Japan for the first time as part of their Arcade Archives series for the Nintendo Switch and PlayStation 4 in May 2024.', 'https://en.wikipedia.org/wiki/Cue_Brick'),
  ('Q3905597', 'Pirates! Gold is a 1993 remake of the 1987 Sid Meier''s Pirates! video game published by MicroProse.', 'https://en.wikipedia.org/wiki/Pirates!_Gold'),
  ('Q11286752', 'Puzzle & Action: Ichidant-R is a puzzle video game developed and released by Sega in 1994 for the Sega System C-2. It is the sequel to Puzzle & Action: Tant-R and is the second of the Puzzle & Action series. Gameplay is similar to Tant-R: the player must complete a series of mini-games, although its crime theme is replaced with a medieval theme. The detectives from the first game return and play the role of knights in a theatre play. An English version of the game exists, which replaces the Japanese voices with English voices. The Korean version also uses the English voices. The game was ported to the Game Gear in 1994, Mega Drive in 1995, and released on the Sega Ages Rouka ni Ichidant-R compilation for the Sega Saturn. The game was released for the Wii Virtual Console in 2007. All console versions except for the Switch version are Japanese exclusives. The third and final game in the series, Puzzle & Action: Treasure Hunt, was released in 1995.', 'https://en.wikipedia.org/wiki/Puzzle_%26_Action:_Ichidant-R'),
  ('Q11278009', 'Puzzle & Action: Tant-R, is a puzzle video game developed and published by Sega in 1993 for the Sega System C in Japan. The first instalment in the Puzzle & Action trilogy, it is a spin-off of Bonanza Bros.. The characters from Bonanza Bros., Robo and Mobo, are featured as protagonists, functioning as detectives. A prison escapee is chased, and his henchmen interfere. A series of timed mini-games must be completed to defeat the henchmen. The game features references to western culture.

The game was ported to the Sega Mega Drive and Game Gear in 1994, to the Saturn as part of the Sega Ages Shukudai ga Tant R compilation in 1996, and released on the Wii Virtual Console in 2007. An updated version was released for the PlayStation 2 as part of the Sega Ages 2500 Vol. 6 compilation in Japan in 2004 (re-released on the PlayStation Store in 2013), and the Sega Classics Collection, the only English localisation, in 2005. In 2002, a service allowing games to be downloaded to a mobile phone was launched. Reception was mixed: although the graphics and gameplay were praised, some reviewers criticised the mini-games themselves. Puzzle & Action: Tant-R was followed by two sequels: Puzzle & Action: Ichidant-R, featuring a medieval theme, in 1994, and Puzzle & Action: Treasure Hunt, featuring a treasure-hunting theme, in 1995.', 'https://en.wikipedia.org/wiki/Puzzle_%26_Action:_Tant-R'),
  ('Q30612284', 'Risk is a turn-based strategy video game based on the board game of the same name.', 'https://en.wikipedia.org/wiki/Risk_(1988_video_game)'),
  ('Q55632087', 'Rugby World Cup ''95 is a sports video game developed by Electronic Arts and published by EA Sports for the Sega Genesis in 1994. It is based on the sporting event of the same name. An MS-DOS version was developed by Creative Assembly and released in 1995.', 'https://en.wikipedia.org/wiki/Rugby_World_Cup_%2795'),
  ('Q7460497', 'Shadow Dancer: The Secret of Shinobi, also known simply as Shadow Dancer, is a side-scrolling action game developed and published by Sega for the Sega Genesis in 1990. It is the second game in the Shinobi series released for the Mega Drive, following The Revenge of Shinobi. However, it is not a continuation of the previous game, but rather a loose adaptation of the 1989 arcade game Shadow Dancer. Like in the original arcade game, the player controls a ninja followed by a canine companion. The Secret of Shinobi was well received by critics.', 'https://en.wikipedia.org/wiki/Shadow_Dancer:_The_Secret_of_Shinobi'),
  ('Q3531553', 'Tongue of the Fatman (or simply Fatman for the Japan release) is a 1989 fighting game developed by Brian A. Rice, Inc. and published by Activision, originally released for MS-DOS and later ported to the Commodore 64 and Sega Genesis.

The game is also known as Mondu''s Fight Palace on the Commodore 64, and Slaughter Sport in its Sega Genesis iteration. The working title for the game was ''Red Belt''. In single-player mode, the player selects from a roster of alien and fantastical races and progresses through a series of matches, ultimately facing the game''s antagonist, Mondu the Fat. Matches incorporate an in-game economy allowing players to wager currency and purchase items between fights. A crowd-favor mechanic penalizes repeated use of the same attack, discouraging exploitative tactics.', 'https://en.wikipedia.org/wiki/Tongue_of_the_Fatman'),
  ('Q7622931', 'Street Smart is a 1989 fighting game developed and published by SNK for arcades. It was released in Japan in July 1989 and in North America in September 1989. A port to the Sega Genesis was released in 1991.

Hamster Corporation released the game as part of their Arcade Archives series for the Nintendo Switch and PlayStation 4, as well as their Arcade Archives 2 series for the Nintendo Switch 2, PlayStation 5, and Xbox Series X/S in April 2026.', 'https://en.wikipedia.org/wiki/Street_Smart_(video_game)'),
  ('Q2069574', 'Super Hang-On is a 1987 racing video game developed and published by Sega for arcades. It is the sequel to 1985''s Hang-On, and uses a simulated motorcycle arcade cabinet, like the original game. An updated version was released for arcades as Limited Edition Hang-On in 1991.', 'https://en.wikipedia.org/wiki/Super_Hang-On'),
  ('Q3516906', 'Techno Cop is a 1988 video game for the Amiga, Amstrad CPC, Apple II, Atari ST, Commodore 64, MS-DOS, and ZX Spectrum. It was subsequently ported to the Genesis in 1990. The gameplay combines pseudo-3D driving in the graphical style of Out Run with side-scrolling action as the player controls a police officer driving to and then moving through various seedy locations in a one-man war against crime. The game was the first game on the Genesis to have a warning label due to its violent content.

The game was panned by critics for its simplistic graphics, sound, and the fact that many of the levels looked too similar. A Sega Genesis sequel, Techno Cop: The Final Mission, was planned but never released.', 'https://en.wikipedia.org/wiki/Techno_Cop'),
  ('Q28746165', 'World Class Leader Board is a 1987 golf video game published by Access Software. It is part of the Leader Board series.', 'https://en.wikipedia.org/wiki/World_Class_Leader_Board'),
  ('Q659990', 'Switchblade is a 1989 action-platform video game developed by Core Design and published by Gremlin Graphics for the Atari ST. The first installment in the eponymous two-part series, the game is set in a dystopian future where players assume the role of Hiro from the Blade Knights as he embarks on a journey to defeat Havok, the main antagonist who broke free from his imprisonment after the sacred Fireblade was shattered into several pieces. Its gameplay consists of run and gun action mixed with platforming and exploration elements, with a main single-button configuration.

Heavily drawing inspiration from both Japanese and Western pop culture as well as various games, Switchblade was solely created by Core Design co-founder and Rick Dangerous designer Simon Phipps in his spare time, who took a year and a half to complete it while working alongside on other projects at the company. Initially released for the Atari ST platform, the title was later ported to other microcomputers and consoles including the Amiga, Amstrad CPC, GX4000, Commodore 64 and ZX Spectrum, each with several changes and additions from the original version.', 'https://en.wikipedia.org/wiki/Switchblade_(video_game)'),
  ('Q614831', 'Star Control: Famous Battles of the Ur-Quan Conflict, Volume IV is an action-strategy video game developed by Toys for Bob and published by Accolade. It was originally released for MS-DOS and Amiga in 1990, followed by ports for the Sega Genesis and additional platforms in 1991. The story is set during an interstellar war between two space alien factions, with humanity joining the Alliance of Free Stars to defeat the invading Ur-Quan Hierarchy. Players can choose to play as either faction, each with seven different alien starships which are used during the game''s combat and strategy sections.

The game was created by designer-artist Paul Reiche III and programmer-engineer Fred Ford. Initially, the concept was based on the space combat seen in Spacewar! (1962), combined with the action-strategy gameplay seen in Archon: The Light and the Dark (1983). The alternate title, StarCon, was a play on words referring to Reiche''s prior work on Archon, adapted into a science fiction setting. After developing the core space combat system, Reiche and Ford created an assortment of ships, abilities, and character designs. The project was completed with additional artwork from Greg Johnson and Erol Otus.', 'https://en.wikipedia.org/wiki/Star_Control'),
  ('Q56277138', 'Tanglewood is a 2018 puzzle platform video game developed and published by Big Evil Corporation for the Sega Genesis/Mega Drive. It was crowdfunded through Kickstarter and released on 14 August 2018, with emulated versions available for Windows, Mac, and Linux on Steam and a dual-game cartridge for the Evercade along with Xeno Crisis.

The game was released on physical carts playable on Mega Drive systems. A director''s cut for the Nintendo Switch, titled Tanglewood: Definitive Edition, was released on 16 December 2025. A scheduled Dreamcast port was put on hiatus as of May 2019.', 'https://en.wikipedia.org/wiki/Tanglewood_(2018_video_game)'),
  ('Q104586761', 'Xeno Crisis is a 2019 multidirectional shooter video game developed and published by Bitmap Bureau. It is well known for its homebrew releases on a plethora of retro consoles, in addition to official releases on personal computers and current home consoles. The premise takes place in Outpost 88, a scientific research facility overrun by aliens. The facility sent a distress signal, leading Commander Darius dispatching space marines John Marsh and Sarah Ridley to confront the aliens. Gameplay revolves around players defeating enemies, rescuing survivors, collecting in-game currency for upgrades, and facing against bosses.', 'https://en.wikipedia.org/wiki/Xeno_Crisis');

update public.game g
set summary_en = i.summary, summary_en_source = i.source
from import_summary i
where g.wikidata_id = i.wikidata_id
  and g.summary_en is null;

drop table import_summary;
